// ============================================================
//  SheetJS (XLSX) — un solo caricamento, da un solo posto
// ------------------------------------------------------------
//  Prima la stessa libreria veniva scaricata da TRE domini diversi e in tre
//  versioni diverse: cdn.jsdelivr.net (ESM), cdn.sheetjs.com (ESM) e
//  cdnjs.cloudflare.com (UMD). Nessuno l'aveva deciso: si era stratificato.
//  Ora il file e' nostro (js/xlsx.full.min.js) e il caricamento e' UNO.
//  Resta su richiesta: 862 KB non vanno imposti a chi apre la home. Parte solo
//  quando l'utente esporta o importa davvero qualcosa.
// ============================================================
let _xlsxPromise = null;
function loadXLSX() {
  if (typeof XLSX !== 'undefined') return Promise.resolve(XLSX);
  if (_xlsxPromise) return _xlsxPromise; // gia' in corso: non lo si scarica due volte
  _xlsxPromise = new Promise((res, rej) => {
    const s = document.createElement('script');
    s.src = 'js/xlsx.full.min.js?v=' + JS_VERSION.replace('v', '');
    s.onload = () => res(window.XLSX);
    s.onerror = () => { _xlsxPromise = null; rej(new Error('XLSX non caricato')); };
    document.head.appendChild(s);
  });
  return _xlsxPromise;
}

// Bandiere self-hostate (cartella flags/): 56 PNG 40x30, 26 KB in tutto.
// Prima venivano da flagcdn.com, che riceveva cosi' l'IP di ogni visitatore —
// anche anonimo, perche' la bandierina del selettore lingua sta nella barra in
// alto e si carica sempre.
function flagUrl(code) {
  const c = (code || '').toLowerCase();
  // window._FLAGS esiste SOLO nella preview a file unico, che non ha cartelle e
  // porta le bandiere incorporate. Sul sito vero e' undefined e si usa il file.
  return (window._FLAGS && window._FLAGS[c]) || `flags/${c}.png`;
}

// v6.006 (Franco) - RETRO BIANCO. Una figurina puo' non avere un vero retro: il suo
// dietro e' bianco e basta. Non e' la stessa cosa di "retro non ancora collegato" ne' di
// "retro collegato ma senza foto" - quei due sono stati temporanei del censimento e
// spariranno, questo e' un dato permanente della figurina.
// Il bianco e' un'immagine finta generata qui: cosi' entra nei layout fronte+retro senza
// che nessuno dei cinque debba sapere che e' un caso speciale. cloudinaryUrl() lascia
// passare intatto tutto cio' che non e' un URL Cloudinary, quindi il data-URI arriva a
// destinazione com'e'.
const RETRO_BIANCO_IMG = 'data:image/svg+xml;utf8,' + encodeURIComponent(
  '<svg xmlns="http://www.w3.org/2000/svg" width="320" height="200"><rect width="320" height="200" fill="#ffffff"/></svg>');
function cloudinaryUrl(url, opts = 'w_300,h_300,c_fit,q_auto,f_auto') {
  if (!url || !url.includes('cloudinary.com')) return url;
  // Insert transformation parameters after /upload/
  return url.replace('/upload/', `/upload/${opts}/`);
}

function filterNationalities() {
  const q = _perRicerca(document.getElementById('reg-nationality-search').value.trim()); // v6.093 — Perù si trova anche scrivendo Peru
  const dd = document.getElementById('nationality-dropdown');
  if (!q) { dd.style.display = 'none'; return; }
  const filtered = COUNTRIES.filter(([code, name]) => _perRicerca(name).includes(q));
  if (!filtered.length) { dd.style.display = 'none'; return; }
  dd.style.display = '';
  dd.innerHTML = filtered.map(([code, name]) =>
    `<div onclick="selectNationality('${code}','${name}')" style="display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer;transition:background 0.15s;" onmouseover="this.style.background='var(--bg3)'" onmouseout="this.style.background=''">
      <img src="${flagUrl(code)}" style="width:24px;height:16px;object-fit:cover;border-radius:2px;">
      <span style="font-size:0.9rem;">${name}</span>
    </div>`
  ).join('');
}

function selectNationality(code, name) {
  document.getElementById('reg-nationality-code').value = code;
  document.getElementById('reg-nationality-name').value = name;
  document.getElementById('reg-nationality-search').value = name;
  document.getElementById('nationality-dropdown').style.display = 'none';
  const preview = document.getElementById('reg-nationality-preview');
  preview.style.display = 'flex';
  preview.innerHTML = `<img src="${flagUrl(code)}" style="width:24px;height:16px;object-fit:cover;border-radius:2px;"> ${name}`;
}



async function initFirebase() {
  const { initializeApp } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js');
  // v6.176 - `getDocsFromServer` in piu': e' la differenza fra "non ho i dati" e "il database e'
  // vuoto". Vedi `fsGetAllDalServer`.
  const { getFirestore, collection, doc, getDocs, getDocsFromServer, getDoc, setDoc, addDoc, deleteDoc, updateDoc, onSnapshot, query, orderBy, where, deleteField, arrayUnion, arrayRemove, increment } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js');
  const { getAuth, createUserWithEmailAndPassword, signInWithEmailAndPassword, signOut, GoogleAuthProvider, signInWithPopup, sendPasswordResetEmail, onAuthStateChanged, EmailAuthProvider, reauthenticateWithCredential, deleteUser: fbDeleteAuthUser, reauthenticateWithPopup, updatePassword } = await import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js');
  fbApp = initializeApp(FIREBASE_CONFIG);
  db = getFirestore(fbApp);
  fbAuth = getAuth(fbApp);
  window._fb = { collection, doc, getDocs, getDocsFromServer, getDoc, setDoc, addDoc, deleteDoc, updateDoc, onSnapshot, query, orderBy, where, deleteField, arrayUnion, arrayRemove, increment };
  window._fbAuth = { createUserWithEmailAndPassword, signInWithEmailAndPassword, signOut, GoogleAuthProvider, signInWithPopup, sendPasswordResetEmail, EmailAuthProvider, reauthenticateWithCredential, fbDeleteAuthUser, reauthenticateWithPopup, updatePassword };
  console.log('Firebase ready');

  // Verifica che il currentUser eventualmente salvato in localStorage
  // corrisponda a una sessione Firebase Auth realmente attiva in questo
  // browser. Senza questo controllo, un currentUser rimasto in cache (es.
  // sessione scaduta, browser condiviso, logout non completato) mostrerebbe
  // l'interfaccia da loggato/admin anche senza un accesso davvero valido.
  await new Promise((resolve) => {
    const unsubscribe = onAuthStateChanged(fbAuth, async (fbUser) => {
      unsubscribe();
      try {
        if (!fbUser) {
          if (currentUser) { currentUser = null; LOCAL.set('currentUser', null); }
        } else if (!currentUser || currentUser.authUid !== fbUser.uid) {
          const user = await _findUserByAuthUid(fbUser.uid);
          if (user) { currentUser = user; LOCAL.set('currentUser', user); }
          else { currentUser = null; LOCAL.set('currentUser', null); }
        }
      } catch(e) { console.error('Verifica sessione Firebase Auth fallita', e); }
      resolve();
    });
  });

  await loadAllData();

  // Consenso newsletter per chi rientra con la SESSIONE GIÀ ATTIVA.
  // Il prompt era agganciato solo agli eventi di login espliciti (doLogin,
  // signInWithGoogle) — ma la sessione si ripristina qui sopra, da localStorage
  // più onAuthStateChanged, senza passare da nessuno dei due. Chi riapriva
  // semplicemente il sito non lo vedeva MAI. E siccome la sessione persiste,
  // "mai" non era l'eccezione: era il caso normale. Tutto il meccanismo di
  // raccolta del consenso rischiava quindi di non attivarsi quasi su nessuno
  // degli utenti già registrati, che sono proprio quelli per cui era stato
  // costruito.
  // Le condizioni (non admin, non impersonificazione, consenso mai espresso)
  // sono già dentro maybeAskNewsletterConsent: qui non serve ripeterle. Se
  // l'utente non è loggato, currentUser è null e la funzione esce subito.
  // Il ritardo lascia chiudere l'overlay di caricamento e completare il primo
  // render, così il modal non spunta sotto la schermata di attesa.
  // Link profondo di disiscrizione (?unsubscribe=1). Ha la precedenza sul prompt
  // del consenso: chi arriva da li il consenso l'ha gia dato, quindi
  // maybeAskNewsletterConsent uscirebbe comunque subito -- ma l'ordine conta se
  // un domani si aggiungessero altri intenti in sospeso.
  checkUnsubscribeLink();
  setTimeout(maybeAskNewsletterConsent, 1200);
}

// ============================================================
//  CACHE (in-memory, replaces localStorage for shared data)
// ============================================================
let _cache = {
  series: [],
  figurines: [],
  posts: [],
  users: [],
  contact_messages: []
};

// Local-only (per-user) data still uses localStorage
const LOCAL = {
  get(k) { try { return JSON.parse(localStorage.getItem('sgorbions_' + k)) || null; } catch { return null; } },
  set(k,v) { localStorage.setItem('sgorbions_' + k, JSON.stringify(v)); }
};

// v6.080 (Franco) - FIGURINE INVISIBILI: col campo `invisibile` un oggetto lo vede solo l'admin.
// Il filtro sta QUI e non nei punti che disegnano, ed e' la decisione che conta: una figurina
// compare in griglia, nella vista tabellare, nella ricerca globale, in tre caroselli, nei contatori
// della serie, negli specchietti, nell'hub prodotti, negli export delle mancoliste. Sono oltre
// centoventi i punti che leggono l'elenco: filtrarli uno per uno significa dimenticarne uno, e
// l'oggetto resterebbe visibile proprio li'. Da qui invece sparisce ovunque in un colpo solo.
// L'admin riceve l'elenco intero, sempre: e' lui che deve poterle vedere e rimetterle a posto.
// Il memo non e' un vezzo: getData('figurines') viene chiamata anche DENTRO dei cicli, e filtrare
// 3300 oggetti a ogni chiamata renderebbe quadratico del codice che oggi e' lineare. Si riusa il
// risultato finche' l'array in cache e' lo stesso oggetto - e quando cambia, cambia identita'.
let _memoVisibili = { src: null, out: null };
function _figurineVisibili(tutte) {
  if (currentUser?.isAdmin) return tutte;
  if (_memoVisibili.src === tutte) return _memoVisibili.out;
  const out = tutte.filter(f => !f.invisibile);
  _memoVisibili = { src: tutte, out };
  return out;
}
function getData(k, def) {
  if (k.startsWith('owned_') || k === 'currentUser' || k === 'lang') {
    return LOCAL.get(k) || def;
  }
  if (k === 'figurines' && Array.isArray(_cache[k])) return _figurineVisibili(_cache[k]);
  return _cache[k] !== undefined ? _cache[k] : def;
}
function setData(k, v) {
  if (k.startsWith('owned_') || k === 'currentUser' || k === 'lang') {
    LOCAL.set(k, v);
    return;
  }
  _cache[k] = v;
}

// ============================================================
//  FIRESTORE HELPERS
// ============================================================
// ============================================================
// v6.176 (Franco) — «Firestore ha risposto, ma senza nessuna serie» DICEVA IL FALSO.
// ------------------------------------------------------------
// Il 15 agosto la preview si e' fermata su quel messaggio, e in console c'era la spiegazione vera,
// scritta dall'SDK due righe sopra:
//   "Could not reach Cloud Firestore backend. Backend didn't respond within 10 seconds. ...
//    The client will operate in offline mode until it is able to successfully connect."
// Cioe': Firestore NON aveva risposto. Aveva risposto la sua CACHE LOCALE, che era vuota. E
// `getDocs`, quando il client e' offline, **risolve** con quello che ha invece di rifiutare.
//
// ⚠️ DA QUI DISCENDONO TRE COSE, e la terza e' un errore mio da segnare.
//  1. Il nostro messaggio descriveva un database vuoto — un problema di DATI — mentre il problema
//     era di RETE. Indirizzava dalla parte sbagliata chiunque lo leggesse.
//  2. Il `Promise.race` di `loadAllData` non poteva intercettare niente: intercetta una promessa
//     che non arriva mai, non una che arriva con dentro il vuoto.
//  3. Per questo la v6.173 (tetto da 4 a 20 secondi) NON risolveva questo guasto, e io l'avevo
//     presentata come se lo facesse. Ho verificato che il numero fosse cambiato, non che il
//     cambiamento avesse un effetto su cio' che stava succedendo: e' la lezione della v6.157,
//     ripetuta su un altro terreno. La v6.173 resta valida per cio' che fa davvero — togliere un
//     numero muto dal codice — ma non e' la cura di questo sintomo.
//
// `getDocsFromServer` RIFIUTA quando il server non si raggiunge, invece di consegnare la cache.
// Cosi' l'offline torna a essere un errore, e un errore si puo' ritentare.
// ============================================================
async function fsGetAllDalServer(collName) {
  if (!db) return [];
  const { collection, getDocsFromServer } = window._fb;
  const snap = await getDocsFromServer(collection(db, collName));   // niente try: il rifiuto DEVE uscire
  const docs = snap.docs.map(d => ({ ...d.data(), id: d.id }));
  _trackReads(docs.length);
  return docs;
}

// Ritenta prima di arrendersi, perche' e' quello che Franco stava facendo A MANO col pulsante
// RIPROVA: "premendo ancora RIPROVA, ha caricato anche la preview". Se il rimedio e' ripetere il
// tentativo, ripeterlo e' compito del sito — un visitatore alla prima schermata di guasto se ne va.
// ⚠️ Le pause crescono (0,8s poi 1,6s) invece di essere fisse: un server che non risponde perche' e'
// carico peggiora se lo si martella a intervallo costante.
async function _leggiSerieRitentando() {
  const TENTATIVI = 3;
  let ultimo;
  for (let i = 1; i <= TENTATIVI; i++) {
    try {
      return await Promise.race([
        fsGetAllDalServer('series'),
        new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), _timeoutCaricamentoMs()))
      ]);
    } catch (e) {
      ultimo = e;
      console.warn('[Sgorbions] lettura serie, tentativo ' + i + ' di ' + TENTATIVI + ' fallito:', e?.message || e);
      if (i < TENTATIVI) await new Promise(r => setTimeout(r, 800 * i));
    }
  }
  throw ultimo;
}

async function fsGetAll(collName) {
  if (!db) return [];
  try {
    const { collection, getDocs } = window._fb;
    const snap = await getDocs(collection(db, collName));
    const docs = snap.docs.map(d => ({ ...d.data(), id: d.id }));
    // Contatore letture giornaliero
    _trackReads(docs.length);
    return docs;
  } catch(e) { console.error('fsGetAll', e); return []; }
}

async function fsGet(collName, id) {
  if (!db) return null;
  try {
    const { doc, getDoc } = window._fb;
    const snap = await getDoc(doc(db, collName, id));
    _trackReads(1);
    if (!snap.exists()) return null;
    return { ...snap.data(), id: snap.id };
  } catch(e) { console.error('fsGet', e); return null; }
}

// ── Contatore letture Firebase ────────────────────────────────
function _getReadCounter() {
  try {
    const raw = localStorage.getItem('sgorbions_reads');
    if (!raw) return { count: 0, date: _ptDate() };
    const data = JSON.parse(raw);
    // Reset se il giorno PT è cambiato: salva nello storico prima
    if (data.date !== _ptDate()) {
      if (data.count > 0) _saveReadHistory(data.date, data.count);
      return { count: 0, date: _ptDate() };
    }
    return data;
  } catch(e) { return { count: 0, date: _ptDate() }; }
}

function _saveReadHistory(date, count) {
  try {
    const raw = localStorage.getItem('sgorbions_reads_history');
    const history = raw ? JSON.parse(raw) : [];
    // Evita duplicati per la stessa data
    const idx = history.findIndex(r => r.date === date);
    if (idx >= 0) { history[idx].count = count; }
    else { history.unshift({ date, count }); }
    // Mantieni solo 30 giorni
    if (history.length > 30) history.splice(30);
    localStorage.setItem('sgorbions_reads_history', JSON.stringify(history));
  } catch(e) {}
}

function getReadHistory() {
  try {
    const raw = localStorage.getItem('sgorbions_reads_history');
    return raw ? JSON.parse(raw) : [];
  } catch(e) { return []; }
}

function _ptDate() {
  // Data corrente in Pacific Time (UTC-7 o UTC-8)
  const now = new Date();
  const pt = new Date(now.toLocaleString('en-US', { timeZone: 'America/Los_Angeles' }));
  return pt.getFullYear() + '-' + String(pt.getMonth()+1).padStart(2,'0') + '-' + String(pt.getDate()).padStart(2,'0');
}

function _trackReads(count) {
  try {
    const data = _getReadCounter();
    data.count += count;
    localStorage.setItem('sgorbions_reads', JSON.stringify(data));
  } catch(e) {}
  _checkReadQuotaWarning();
}

function getReadCount() {
  return _getReadCounter().count;
}

// Mostra un'icona di avviso in navbar (solo admin) quando il contatore
// LOCALE di letture fsGetAll di questo browser supera il 90% del limite
// giornaliero gratuito di Firestore. NOTA: è una misura solo di questo
// browser, non il consumo reale e globale del sito — per quello resta
// necessario controllare la vera Firebase Console.
function _checkReadQuotaWarning() {
  const btn = document.getElementById('nav-quota-warning-btn');
  if (!btn) return;
  if (!currentUser?.isAdmin) { btn.style.display = 'none'; return; }
  const pct = getReadCount() / 50000;
  btn.style.display = pct >= 0.9 ? '' : 'none';
}

// v6.046 (Franco) - RILEGGE LE FIGURINE DA FIRESTORE, senza toccare la pagina.
// Serve alle due procedure di caricamento foto, che costruiscono l'elenco dei candidati da
// _cache.figurines. Quella cache vive in sessionStorage e dura 5 minuti, ED E' PER SCHEDA: un
// oggetto creato in un'altra scheda (o creato prima e ricaricato entro i 5 minuti) semplicemente
// non c'e'. Il caricamento allora scriveva "Nessun oggetto trovato con Nome completo ..." - un
// messaggio che accusa il DATO mentre il problema e' la copia locale, e manda a cercare nel posto
// sbagliato. E' costato tempo a Franco e a me nella stessa serata.
// Una lettura in piu' all'inizio di un caricamento di foto non si sente: sotto ci sono decine di
// upload di immagini. Non uso loadAllData() apposta: quella mostra l'overlay e ridisegna, e qui
// ridisegnare vorrebbe dire perdere i file gia' scelti nella form.
async function _rileggiFigurine() {
  if (!db) return false;
  _invalidateSessionCache();
  const serie = await fsGetAll('series');
  if (!serie || !serie.length) return false;
  _cache.series = serie;
  _cache.figurines = [];
  for (const s of _cache.series) for (const item of (s.items || [])) _cache.figurines.push(item);
  return true;
}

function _invalidateSessionCache() {
  try { sessionStorage.removeItem('sgorbions_session_cache'); } catch(e) {}
}

async function _syncPublicProfile(user) {
  // Mantiene una copia "pubblica" minimale del profilo utente (public_profiles),
  // separata dal documento users che contiene email e altri dati privati.
  // Sovrascrittura completa (non merge) per non lasciare mai trapelare campi privati.
  if (!user || !user.id || !db) return;
  try {
    const { doc, setDoc } = window._fb;
    const publicData = {
      id: user.id,
      authUid: user.authUid || null,
      username: user.username || '',
      avatar: user.avatar || null,
      nationalityCode: user.nationalityCode || '',
      nationalityName: user.nationalityName || '',
      joined: user.joined || null,
      isAnonymous: !!user.isAnonymous
    };
    await setDoc(doc(db, 'public_profiles', user.id), publicData, { merge: true });
  } catch(e) {
    console.warn('public_profiles sync failed:', e.message);
  }
}

// ============================================================
// v6.172 (Franco: "il salvataggio di un record di serie è molto lento") — SCRIVERE UNA SERIE NON
// VUOL DIRE RISPEDIRE LE SUE FIGURINE.
// ------------------------------------------------------------
// Le figurine vivono DENTRO il documento della loro serie, e la cache se le tiene li'
// (`_cache.series[i].items`). Quindi ogni `{ ...serie, campoNuovo }` si porta dietro gli oggetti, e
// `fsSave` li spedisce tutti: per cambiare il nome di una serie partivano 521 KB su Serie 3.
// E' lo stesso meccanismo dell'Indagine 1 — che pero' aveva misurato il salvataggio di una
// FIGURINA. Questo e' il salvataggio della SERIE, e non era mai stato guardato: stava dietro un
// "tanto si fa di rado" che nessuno aveva verificato.
//
// ⚠️ OMETTERE `items` E' SICURO, e il motivo e' preciso: `fsSave` scrive con
// `setDoc(ref, item, { merge: true })`, e merge lascia intatti i campi che NON nomini. Gli oggetti
// restano quelli che ci sono sul server. Se un giorno quella scrittura diventasse un `setDoc`
// secco o un `updateDoc` con sostituzione, questa funzione cancellerebbe l'inventario di una serie
// con un clic — quindi il legame fra le due cose va tenuto in mente: e' scritto qui apposta.
//
// 📌 DOVE SI USA, e dove NO. Su sedici punti che scrivono una serie, TREDICI cambiano davvero gli
// oggetti — `_saveFigurineItem`, `_deleteFigurineItem`, gli import, le procedure di massa,
// `moveFigurinesToSeries` — e li' il documento intero ci vuole. I soli di livello serie sono
// `saveSeries` e `saveSeriesOrder`, ed e' su quei due che si applica.
// (Un terzo, `migratePrintErrors`, tocca solo `retroChangeTypes`: e' una migrazione una tantum,
// lasciata com'era di proposito invece che toccata "gia' che c'ero".)
// ============================================================
function _serieSenzaItems(s) {
  const { items, ...resto } = s;
  return resto;
}

// ============================================================
// v6.190 (Franco: "le form di modifica non terminano mai... chiudo con la x e aveva salvato")
// L'AVVISO DI SCRITTURA LENTA, IN UN POSTO SOLO.
// ------------------------------------------------------------
// COSA SUCCEDE, perche' il rimedio si capisce solo sapendolo. `setDoc` risolve **solo quando il
// server conferma**. Con la rete lenta non rifiuta: Firestore riprova all'infinito. Quindi
// l'`await` resta appeso e tutto cio' che viene dopo non gira mai - la scritta resta su
// "Salvataggio in corso", i pulsanti restano spenti, la finestra non si chiude da se'.
// Intanto pero' la pagina i dati nuovi ce li ha gia': `getData('series')` torna `_cache.series`
// PER RIFERIMENTO, e la riga che scrive `series[idx] = {...}` sta PRIMA dell'await. Ecco perche'
// riaprendo "aveva salvato": si sta guardando la propria modifica locale, che NON dimostra che il
// server l'abbia ricevuta. Per saperlo serve un `Ctrl+Shift+R` (dalla v6.176 la lettura iniziale
// e' `getDocsFromServer`, che la cache la rifiuta).
//
// ⚠️ QUESTA RELEASE NON RENDE IL SALVATAGGIO PIU' VELOCE E NON LO ANNULLA. Non e' un tetto
// d'attesa: e' solo un TESTO che cambia dopo un po'. La scrittura continua per conto suo. Dire
// "salvataggio fallito" allo scadere di un timer sarebbe stato peggio del silenzio di adesso -
// una scrittura che poi arriva verrebbe raccontata come persa, e la prossima volta il messaggio
// non lo crederebbe piu' nessuno. E' la lezione gia' scritta nel CHANGELOG della v6.108: il
// `Promise.race` non annulla niente.
//
// 🔴 E IL PULSANTE RESTA SPENTO, di proposito. La prima stesura lo riaccendeva - sembra gentile ed
// e' un guasto: su una serie NUOVA il salvataggio passa da `addDoc`, quindi un secondo clic mentre
// il primo e' ancora in coda crea un DOPPIONE. Su una modifica sarebbe innocuo (`setDoc` con
// `merge` sullo stesso id), ma il pulsante e' lo stesso nei due casi. Meglio un pulsante fermo con
// scritto cosa sta succedendo che uno vivo che puo' duplicare.
//
// 📌 Il numero sta in una costante e NON nelle Impostazioni generali sito, dove la v6.173 ha
// portato il tetto di attesa della LETTURA. Non e' un'incoerenza: quello decide se il sito si
// arrende, e sbagliarlo cambia il comportamento; questo decide solo dopo quanti secondi compare
// una frase, e sbagliarlo non costa niente. Una manopola in piu' in un pannello e' una cosa in
// piu' da capire per chi ci passa.
const MS_SCRITTURA_LENTA = 8000;

// Arma l'avviso e torna la funzione per DISARMARLO. Chi la chiama deve chiamare il disarmo su
// ogni uscita - riuscita, fallita o anticipata: e' lo stesso motivo per cui `saveFigFromDetail`
// riaccende i pulsanti in un `finally` dalla v6.052.
function _avvisaScritturaLenta(mostra) {
  const id = setTimeout(() => {
    try { mostra(); }
    catch (e) { console.error('avviso scrittura lenta', e); }   // un avviso che rompe il salvataggio sarebbe il colmo
  }, MS_SCRITTURA_LENTA);
  return () => clearTimeout(id);
}

// Il testo, in un posto solo perche' lo dicono due form. Le tre cose che deve dire, in ordine di
// utilita': la modifica non e' persa; puoi chiudere la finestra; NON chiudere il browser - che e'
// l'unica azione che la perde davvero, visto che la cache di Firestore qui e' solo in memoria.
function _TESTO_SCRITTURA_LENTA() {
  return currentLang === 'it'
    ? '\u23F3 Ci sta mettendo pi\u00F9 del solito \u2014 la rete \u00E8 lenta. La modifica \u00E8 IN CODA e parte da s\u00E9: puoi chiudere questa finestra con la X, ma NON chiudere il browser finch\u00E9 non \u00E8 andata.'
    : '\u23F3 Taking longer than usual \u2014 slow network. The change is QUEUED and will go through on its own: you can close this window, but do NOT close the browser yet.';
}

// v6.232 - UNA SCRITTURA CHE NON PUO' SCRIVERE DEVE FALLIRE, NON RESTITUIRE L'OGGETTO.
//
// Fino alla v6.231 `fsSave` cominciava con `if (!db) return item;` e `fsDelete` con
// `if (!db) return;`. Cioe': senza collegamento al database le due funzioni tornavano indietro
// **con l'aria di aver fatto il lavoro**. Chi le chiama non ha modo di accorgersene - riceve
// esattamente cio' che riceverebbe da un salvataggio riuscito - quindi prosegue: compare
// "✅ Serie salvata!", la cache in memoria si aggiorna, e il dato nuovo si vede ovunque. Fino al
// ricaricamento della pagina, quando non c'e' piu'.
//
// 📌 IL PUNTO NON E' LA PERDITA, E' IL SILENZIO. `saveSeries` ha gia' il suo `try/catch` che dice
// "❌ Salvataggio fallito, riprova", e cosi' quasi tutti gli altri chiamanti: l'impianto per
// raccontarlo c'era gia' e non e' mai scattato, perche' sotto non veniva sollevato niente. Un
// controllo spento in silenzio e' peggio di uno che segnala il falso - il secondo lo scopri al
// primo giro, il primo non lo scopri mai.
// E' la stessa famiglia del ripiego muto ai dati demo, tolto nella v6.108 per la stessa ragione.
//
// ⚠️ IL CONTROLLO SI SPOSTA PIU' IN ALTO di dov'era, e non e' un dettaglio: prima le figurine
// passavano da `_saveFigurineItem` **senza mai incontrarlo**, e quella funzione mette l'oggetto
// dentro `series.items` PRIMA di scrivere (vedi il baco della v6.042). Con `db` nullo si sarebbe
// rotta a meta', lasciando in memoria un oggetto che non e' su Firestore. Adesso si ferma prima di
// toccare qualsiasi cosa. Per lo stesso motivo il controllo precede anche
// `_invalidateSessionCache()`: non si butta una cache buona per un'operazione che non parte.
//
// 📌 QUANDO PUO' SUCCEDERE DAVVERO. Se `initFirebase()` fallisce, `_guastoCaricamentoDati` copre
// la pagina e non si arriva a salvare niente: in quel caso `db` nullo non lo vede nessuno. Resta
// la finestra fra il caricamento della pagina e la fine dei due `import()` dinamici di Firebase, e
// qualunque strada futura che chiami una scrittura senza passare dall'avvio. Cioe': **non sappiamo
// di un caso in cui questo ramo sia scattato**, e questa release non va raccontata come la cura di
// un guasto osservato. Toglie una bugia dal codice, che e' un'altra cosa.
//
// ⚠️ COSA PUO' ROMPERE. Tocca OGNI salvataggio e OGNI cancellazione del sito. Il rischio non e'
// che l'errore non compaia: e' che compaia dove prima si passava oltre. Un chiamante che oggi
// ignora l'esito - `fsSave('users', ...)` senza `await` al login, per dirne uno - con `db` nullo
// produrrebbe una promise rifiutata invece di niente. Restano `.catch` dove c'erano.
function _erroreNienteDb(operazione) {
  const it = (typeof currentLang === 'undefined' || currentLang === 'it');
  const e = new Error(it
    ? 'Database non collegato: ' + operazione + ' non eseguito. Ricarica la pagina e riprova.'
    : 'Database not connected: ' + operazione + ' was not performed. Reload the page and try again.');
  e.code = 'sgorbions/no-db';
  console.error('[v6.232] ' + operazione + ' rifiutato: db non inizializzato');
  return e;
}

async function fsSave(collName, item) {
  // v6.232 - PRIMA DI TUTTO IL RESTO: vedi il blocco qui sopra.
  if (!db) throw _erroreNienteDb('salvataggio');
  // Invalida la cache se modifichiamo serie o figurine
  if (collName === 'series' || collName === 'figurines' || collName === 'levels') {
    _invalidateSessionCache();
  }
  // Le figurine non sono più una collezione a parte: vivono dentro il
  // documento della loro serie (vedi _saveFigurineItem). Intercettiamo qui
  // per non dover toccare tutti i punti del codice che chiamano
  // fsSave('figurines', ...) — continuano a funzionare senza saperlo.
  if (collName === 'figurines') {
    return await _saveFigurineItem(item);
  }
  const { collection, doc, setDoc, addDoc } = window._fb;
  if (item.id) {
    const ref = doc(db, collName, item.id);
    const writes = [setDoc(ref, item, { merge: true })];
    if (collName === 'users') writes.push(_syncPublicProfile(item));
    await Promise.all(writes);
    return item;
  } else {
    // Il campo "id" NON viene scritto nel corpo del documento — è ridondante,
    // dato che fsGet()/fsGetAll() lo ricostruiscono già in lettura dal nome
    // del documento stesso. Scriverlo richiederebbe un secondo giro di
    // scrittura sullo stesso documento appena creato, che Firestore
    // classifica come "update" (non più "create") — bloccato dalle regole
    // per gli utenti non-admin su collezioni come eventi/email_log, dove la
    // creazione è pubblica ma l'aggiornamento è riservato all'admin
    const ref = await addDoc(collection(db, collName), item);
    const saved = { ...item, id: ref.id };
    if (collName === 'users') await _syncPublicProfile(saved);
    return saved;
  }
}

async function fsDelete(collName, id) {
  // v6.232 - stessa ragione di fsSave, e anche qui il controllo sale sopra le figurine:
  // `_deleteFigurineItem` toglie l'oggetto da `series.items` PRIMA di scrivere.
  if (!db) throw _erroreNienteDb('cancellazione');
  if (collName === 'figurines') {
    return await _deleteFigurineItem(id);
  }
  const { doc, deleteDoc } = window._fb;
  await deleteDoc(doc(db, collName, id));
}

// ============================================================
//  FIGURINE: salvate DENTRO il documento della loro serie
//  (un documento Firestore per serie, non uno per figurina).
//  Questo riduce le letture del catalogo da ~1 per figurina a 1 per
//  serie: con 2421 figurine e ~15 serie, un caricamento completo passa
//  da ~2421 letture a ~15. Vedi CHANGELOG in cima al file per i dettagli
//  e i compromessi di questa scelta.
// ============================================================
function _generateFigurineId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

// v6.079 (Franco) - LA DATA DI CREAZIONE E' GIA' DENTRO L'ID. La funzione qui sopra costruisce
// l'id come Date.now() in base36 piu' sei caratteri casuali: ogni oggetto creato da quando quella
// funzione esiste si porta dietro il proprio timestamp. Scriverlo anche su un campo del record
// vorrebbe dire tenere lo stesso fatto in due posti, e popolarlo sui vecchi vorrebbe dire 1638
// scritture per non vedere niente di diverso da quello che gia' si legge.
// Le due funzioni stanno attaccate apposta: se un domani cambia il formato degli id, questa va
// riletta insieme a quella.
// NON tutti gli id la contengono: 1704 oggetti su 3342 (misurato il 6 agosto 2026) hanno id
// generati da FIRESTORE, di quando le figurine erano una collezione a se' invece di vivere dentro
// il documento della loro serie. Per quelli la data non esiste da nessuna parte e non e'
// recuperabile - i piu' vecchi leggibili risalgono al 5 luglio 2026.
// Il controllo di plausibilita' non e' un di piu': un id Firestore come "0bP7FLIoGhQCX2zVO6UG" si
// lascia interpretare da parseInt in base36 senza protestare e produce un numero enorme, cioe' una
// data assurda. Meglio "sconosciuta" che una data inventata che sembra vera.
function _dataCreazione(f) {
  const s = String(f?.id || '');
  if (s.length < 9) return null;
  const t = parseInt(s.slice(0, -6), 36);
  if (!Number.isFinite(t) || t < 1600000000000 || t > Date.now() + 86400000) return null;
  return new Date(t);
}
function _dataCreazioneTesto(f) {
  const d = _dataCreazione(f);
  if (!d) return currentLang === 'it' ? 'sconosciuta' : 'unknown';
  return d.toLocaleString(currentLang === 'it' ? 'it-IT' : 'en-GB',
    { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

function _recomputeSeriesCounts(series) {
  const items = series.items || [];
  series.counts = {
    figurines: items.filter(f => f.section === 'figurines' || !f.section).length,
    retros: items.filter(f => f.section === 'retros').length,
    albums: items.filter(f => f.section === 'albums').length,
    extras: items.filter(f => f.section === 'extras').length
  };
}

// v6.043 (Franco, baco) - FIRESTORE RIFIUTA `undefined`, e lo fa con "invalid-argument".
// E' il codice che compariva provando a clonare un retro: un campo che nel record di partenza non
// esiste arriva alla scrittura come undefined, e Firestore butta via l'intero documento - non il
// campo, il documento. Il record non nasce, e (fino alla v6.042) la sessione restava bloccata.
// Qui i campi undefined si tolgono prima di scrivere, e si SCRIVE IN CONSOLE quali erano: toglierli
// in silenzio avrebbe risolto il sintomo lasciando invisibile la causa, che sta a monte, in chi
// costruisce il record. Un campo assente e un campo undefined sono la stessa cosa per Firestore:
// toglierlo non perde niente.
// Nota su cosa NON fa: non tocca i null (Firestore li accetta e significano "vuoto per scelta") e
// non tocca gli array - quelli non si possono annidare dentro arrayUnion, ma nei dati non ce ne
// sono e sarebbe un altro problema, da affrontare quando esistera'.
function _sanificaPerFirestore(obj, percorso, rimossi) {
  percorso = percorso || ''; rimossi = rimossi || [];
  if (Array.isArray(obj)) return { valore: obj.map((v, i) => _sanificaPerFirestore(v, percorso + '[' + i + ']', rimossi).valore), rimossi };
  if (obj && typeof obj === 'object' && !(obj instanceof Date)) {
    const pulito = {};
    Object.keys(obj).forEach(k => {
      const v = obj[k];
      if (v === undefined) { rimossi.push((percorso ? percorso + '.' : '') + k); return; }
      pulito[k] = _sanificaPerFirestore(v, (percorso ? percorso + '.' : '') + k, rimossi).valore;
    });
    return { valore: pulito, rimossi };
  }
  return { valore: obj, rimossi };
}

async function _saveFigurineItem(item) {
  // v6.043 - vedi sopra: via gli undefined, ma detti ad alta voce.
  {
    const r = _sanificaPerFirestore(item);
    if (r.rimossi.length) {
      console.warn('[v6.043] campi undefined tolti prima di scrivere (' + (item && item.id || 'nuovo') + '):', r.rimossi.join(', '));
      item = r.valore;
    }
  }
  const seriesList = getData('series', []);
  const sIdx = seriesList.findIndex(s => s.id === item.seriesId);
  if (sIdx < 0) throw new Error('Serie non trovata per la figurina: ' + item.seriesId);
  const series = seriesList[sIdx];
  series.items = series.items || [];

  if (!item.id) item.id = _generateFigurineId();
  const iIdx = series.items.findIndex(x => x.id === item.id);
  const isNew = iIdx < 0;
  // v6.042 (Franco, baco) - QUESTA MODIFICA IN MEMORIA VA DISFATTA SE LA SCRITTURA FALLISCE.
  // Il difetto, raccontato da Franco in tre righe che sono una diagnosi migliore di qualunque
  // messaggio d'errore: "modifico un retro e va; provo a clonare X e il salvataggio fallisce;
  // provo a modificare lo stesso retro di prima e fallisce".
  // Il perche' e' qui: l'oggetto entra in series.items PRIMA della scrittura. Se la scrittura non
  // riesce, l'oggetto resta li' - e da quel momento ogni modifica successiva di QUELLA serie passa
  // dal ramo "esistente", che riscrive il documento INTERO, quindi si porta dietro l'elemento
  // guasto e fallisce a sua volta. Un errore singolo diventa una sessione bloccata, e l'unico modo
  // per uscirne era ricaricare la pagina - senza che niente lo dicesse.
  // Ora si tiene lo stato di prima e lo si rimette esattamente com'era: chi fallisce fallisce da
  // solo. Non nasconde il problema a monte, gli toglie la capacita' di propagarsi.
  const _primaItem = isNew ? null : series.items[iIdx];
  const _primaCounts = series.counts ? { ...series.counts } : series.counts;
  const _disfa = () => {
    if (isNew) {
      const k = series.items.indexOf(item);
      if (k >= 0) series.items.splice(k, 1);
    } else {
      series.items[iIdx] = _primaItem;
    }
    series.counts = _primaCounts;
  };
  if (isNew) series.items.push(item); else series.items[iIdx] = item;
  _recomputeSeriesCounts(series);

  if (isNew) {
    // Nuovo elemento: arrayUnion invia a Firestore solo il nuovo oggetto,
    // non l'intero array — molto più veloce. La verifica post-scrittura
    // introdotta temporaneamente per un sospetto bug è stata rimossa: il
    // mistero era un refuso nei dati di test di Franco, non un problema
    // del meccanismo, e quella verifica costava un'intera lettura di rete
    // in più ad ogni salvataggio, annullando gran parte del guadagno.
    _invalidateSessionCache();
    try {
      const { doc, updateDoc, arrayUnion } = window._fb;
      await updateDoc(doc(db, 'series', series.id), { items: arrayUnion(item), counts: series.counts });
    } catch(e) {
      console.warn('arrayUnion non riuscito, riscrivo l\u2019intera serie come fallback:', e.message);
      try {
        await fsSave('series', series);
      } catch(e2) {
        _disfa(); // v6.042 - fallito anche il ripiego: la serie in memoria torna com'era
        throw e2;
      }
    }
  } else {
    // Modifica di un elemento esistente: Firestore non permette di
    // sostituire un singolo elemento di un array per contenuto, quindi
    // qui serve riscrivere l'intero documento della serie
    try {
      await fsSave('series', series);
    } catch(e) {
      _disfa(); // v6.042 - vedi sopra: una modifica fallita non deve restare in memoria
      throw e;
    }
  }

  // Aggiorna la cache piatta usata da tutto il resto del codice, che
  // continua a vedere _cache.figurines esattamente come prima
  _cache.figurines = _cache.figurines || [];
  const flatIdx = _cache.figurines.findIndex(x => x.id === item.id);
  if (flatIdx >= 0) _cache.figurines[flatIdx] = item; else _cache.figurines.push(item);

  return item;
}

async function _deleteFigurineItem(id) {
  const seriesList = getData('series', []);
  for (const series of seriesList) {
    const idx = (series.items || []).findIndex(x => x.id === id);
    if (idx >= 0) {
      const itemToRemove = series.items[idx];
      series.items.splice(idx, 1);
      _recomputeSeriesCounts(series);
      _invalidateSessionCache();
      try {
        const { doc, updateDoc, arrayRemove } = window._fb;
        await updateDoc(doc(db, 'series', series.id), { items: arrayRemove(itemToRemove), counts: series.counts });
      } catch(e) {
        console.warn('arrayRemove non riuscito, riscrivo l\u2019intera serie come fallback:', e.message);
        await fsSave('series', series);
      }
      break;
    }
  }
  _cache.figurines = (_cache.figurines || []).filter(x => x.id !== id);
}

// ============================================================
//  MIGRAZIONE UNA TANTUM: figurine dalla vecchia collezione a parte
//  (un documento a figurina) al nuovo formato incorporato nella serie
//  (campo "items"). Da eseguire una sola volta dopo aver caricato questa
//  versione. La vecchia collezione 'figurines' non viene più letta né
//  scritta dal resto del codice dopo questa modifica — resta in Firestore
//  come backup finché non la si cancella manualmente, se lo si desidera.
// ============================================================
// MIGRAZIONE (v5.711): "errore di stampa" da STRINGA a TIPO.
// Fino alla v5.710 un errore di stampa era un Change con changeType scritto a mano.
// Il filtro lo cercava confrontando la stringa — e bastava scriverla al plurale in una
// serie perche' smettesse di trovarlo, IN SILENZIO. Ora e' un flag (isPrintError).
// Questa converte i record esistenti. Va lanciata UNA VOLTA SOLA.
// CONTA PRIMA, e lo dice: ogni record e' una SCRITTURA su Firestore, e Franco contro
// la quota giornaliera ci ha gia' sbattuto (v5.682). Nessuna sorpresa da 400 scritture.
// v5.752 — Ricalcolo dei Nomi completi (fullName) di figurine e retro secondo le regole
// attuali di computeFullName. Riscrive SOLO i record il cui fullName cambia davvero, per
// non sprecare scritture Firestore. Conta prima e chiede conferma.
// v5.904 — Ricalcolo Nomi Completi: ora PRIMA mostra un'anteprima a tabella (Attuale -> Nuovo) dei
// record che cambierebbero; poi si applica col pulsante. Spostato nella sezione Data import.
let _recomputePending = null; // { serieId, daAgg }
function previewRecomputeFullNames() {
  if (!currentUser?.isAdmin) return;
  const it = currentLang === 'it';
  const prog = document.getElementById('recompute-fullnames-progress');
  const show = (t) => { if (prog) { prog.style.display = 'block'; prog.innerHTML = t; } };
  const figs = getData('figurines', []);
  const serieId = document.getElementById('recompute-fullnames-series-select')?.value || '';
  if (!serieId) { show(it ? "Seleziona prima una serie dall'elenco." : 'Select a series first.'); return; }
  const serie = getData('series', []).find(s => s.id === serieId);
  if (!serie) { show(it ? 'Serie non trovata.' : 'Series not found.'); return; }
  const daAgg = [];
  figs.filter(f => f.seriesId === serie.id).forEach(f => {
    const nuovo = computeFullName(f, figs);
    if ((f.fullName || '') !== (nuovo || '')) daAgg.push({ f, nuovo });
  });
  if (!daAgg.length) { _recomputePending = null; show('Serie "' + esc(serie.name) + '": ' + (it ? 'tutti i Nomi completi sono già aggiornati. Nessuna modifica.' : 'all full names already up to date. No changes.')); return; }
  _recomputePending = { serieId, daAgg };
  const secLbl = { figurines: it ? 'Figurine' : 'Stickers', retros: 'Retro', albums: it ? 'Album' : 'Albums', extras: it ? 'Altri oggetti' : 'Other items', bustine: it ? 'Bustine' : 'Wrappers' };
  // v5.905 — ordina per categoria (Figurine, Retro, Bustine, Album, Altri oggetti), poi Numero, poi Nome.
  const _ord = ['figurines', 'retros', 'bustine', 'albums', 'extras'];
  daAgg.sort((a, b) => (_ord.indexOf(a.f.section || 'figurines') - _ord.indexOf(b.f.section || 'figurines')) || ((a.f.number || 0) - (b.f.number || 0)) || (a.f.name || '').localeCompare(b.f.name || '', 'it'));
  const rows = daAgg.map(({ f, nuovo }) => '<tr>' +
    '<td style="padding:0.35rem 0.6rem;font-size:0.8rem;color:var(--muted);white-space:nowrap;">' + secLbl[f.section || 'figurines'] + '</td>' +
    '<td style="padding:0.35rem 0.6rem;font-size:0.8rem;white-space:nowrap;">' + (f.number || '—') + '</td>' +
    '<td style="padding:0.35rem 0.6rem;font-size:0.8rem;">' + esc(f.name || '') + '</td>' +
    '<td style="padding:0.35rem 0.6rem;font-size:0.8rem;color:var(--muted);">' + esc(f.fullName || '(vuoto)') + '</td>' +
    '<td style="padding:0.35rem 0.6rem;font-size:0.9rem;text-align:center;color:var(--action-admin);">→</td>' +
    '<td style="padding:0.35rem 0.6rem;font-size:0.8rem;color:var(--text);font-weight:600;">' + esc(nuovo || '(vuoto)') + '</td>' +
  '</tr>').join('');
  show('<div style="margin-bottom:0.75rem;">Serie "<b>' + esc(serie.name) + '</b>": <b>' + daAgg.length + '</b> ' + (it ? 'Nomi completi da aggiornare' : 'full names to update') + ' (' + (it ? 'ognuno è una scrittura su Firestore' : 'each is a Firestore write') + ').</div>' +
    '<div style="overflow:auto;max-height:440px;border:1px solid var(--border2);border-radius:8px;"><table class="data-table" style="border-spacing:0;width:100%;"><thead><tr>' +
    // 🆕 v6.238 (Franco) - "TIPO DI ARTICOLO". La v6.237 aveva lasciato qui "Tipo" apposta, perche'
    // questa cella porta `secLbl[f.section]` — l'ARTICOLO (Figurine, Retro, Album...), non la
    // versione — e chiamarla "Versione" per uniformita' avrebbe messo l'etichetta sbagliata su un
    // dato giusto. Ora ha il nome che dice cosa contiene davvero.
    // 📌 "Item type" non e' una traduzione nuova: e' la stessa che il codice usa gia' nei messaggi
    // dei tipi di articolo (vedi i toast di creazione/eliminazione). Inventarne una seconda avrebbe
    // dato due parole inglesi per la stessa cosa.
    '<th style="padding:0.4rem 0.6rem;text-align:left;">' + (it ? 'Tipo di articolo' : 'Item type') + '</th><th style="padding:0.4rem 0.6rem;text-align:left;">N.</th>' +
    '<th style="padding:0.4rem 0.6rem;text-align:left;">' + (it ? 'Nome' : 'Name') + '</th>' +
    '<th style="padding:0.4rem 0.6rem;text-align:left;">' + (it ? 'Nome completo ATTUALE' : 'Current full name') + '</th><th></th>' +
    '<th style="padding:0.4rem 0.6rem;text-align:left;">' + (it ? 'NUOVO' : 'New') + '</th>' +
    '</tr></thead><tbody>' + rows + '</tbody></table></div>' +
    '<button class="btn-primary btn-admin" onclick="applyRecomputeFullNames()" id="recompute-apply-btn" style="margin-top:0.9rem;">✅ ' + (it ? ('Applica le ' + daAgg.length + ' modifiche') : ('Apply ' + daAgg.length + ' changes')) + '</button>');
}
async function applyRecomputeFullNames() {
  if (!currentUser?.isAdmin || !_recomputePending) return;
  const it = currentLang === 'it';
  const prog = document.getElementById('recompute-fullnames-progress');
  const show = (t) => { if (prog) { prog.style.display = 'block'; prog.innerHTML = t; } };
  const applyBtn = document.getElementById('recompute-apply-btn');
  if (applyBtn) applyBtn.disabled = true;
  const figs = getData('figurines', []);
  const { daAgg } = _recomputePending;
  let fatti = 0, falliti = 0;
  const aggiornati = [];
  // v6.117 - UNA SCRITTURA PER SERIE, non una per record (vedi `_salvaFigurineInBlocco`).
  // Prima ogni giro riscriveva l'INTERO documento della serie: su Serie 3 sono 521 KB a record.
  const daScrivere = daAgg.map(({ f, nuovo }) => ({ ...f, fullName: nuovo }));
  show(it ? 'Scrittura in corso…' : 'Writing…');
  try {
    await _salvaFigurineInBlocco(daScrivere);
    daScrivere.forEach((rec, k) => {
      const idx = figs.findIndex(x => x.id === rec.id);
      if (idx >= 0) figs[idx] = rec;
      aggiornati.push({ vecchio: daAgg[k].f.fullName || '', nuovo: daAgg[k].nuovo || '' });
    });
    fatti = daScrivere.length;
  } catch (e) { console.error('applyRecomputeFullNames', e); falliti = daScrivere.length; }
  show((it ? 'Aggiornati ' : 'Updated ') + fatti + ' / ' + daAgg.length + (falliti ? (' — ' + falliti + (it ? ' FALLITI' : ' FAILED')) : ''));
  _cache.figurines = figs;
  _recomputePending = null;
  const listaHTML = aggiornati.map(({ vecchio, nuovo }) =>
    '<div style="font-family:monospace;font-size:0.76rem;line-height:1.5;"><span style="color:var(--muted);">' + esc(vecchio || '(vuoto)') + '</span> → <span style="color:var(--text);">' + esc(nuovo || '(vuoto)') + '</span></div>').join('');
  show('<b>' + (it ? 'Fatto' : 'Done') + ': ' + fatti + (it ? ' aggiornati' : ' updated') + '</b>' + (falliti ? (', ' + falliti + (it ? ' falliti' : ' failed')) : '') + '.' +
    (aggiornati.length ? ('<div style="margin-top:0.6rem;max-height:320px;overflow:auto;border-top:1px solid var(--border2);padding-top:0.5rem;">' + listaHTML + '</div>') : ''));
  try { renderItems(); } catch (e) {}
}

async function migratePrintErrors() {
  if (!currentUser?.isAdmin) return;
  const btn = document.getElementById('migrate-printerrors-btn');
  const prog = document.getElementById('migrate-printerrors-progress');
  const mostra = (t) => { if (prog) { prog.style.display = 'block'; prog.innerHTML = t; } };

  const figs = getData('figurines', []);
  // il riconoscimento per stringa, l'ULTIMA volta che lo usiamo: serve proprio a
  // liberarcene. tollerante su maiuscole e spazi, come faceva il vecchio filtro.
  const daMigrare = figs.filter(f =>
    f.isChange && (f.changeType || '').toLowerCase().trim() === 'errore di stampa' && !f.isPrintError);

  if (!daMigrare.length) {
    mostra('Nessun record da migrare. (Se ti aspettavi di trovarne, controlla in console i changeType realmente in uso: potrebbero essere scritti diversamente.)');
    return;
  }

  const perSez = {};
  daMigrare.forEach(f => { perSez[f.section] = (perSez[f.section] || 0) + 1; });
  const dettaglio = Object.entries(perSez).map(([k, v]) => `${k}: ${v}`).join(', ');

  if (!confirm(
    `Trovati ${daMigrare.length} record da convertire in "Errore di stampa" (${dettaglio}).\n\n` +
    `Diventeranno: isPrintError = true, isChange = false, changeType = vuoto.\n\n` +
    `Sono ${daMigrare.length} SCRITTURE su Firestore. Procedo?`
  )) return;

  if (btn) btn.disabled = true;
  let fatti = 0, falliti = 0;
  const daScrivere = [];
  for (const f of daMigrare) {
    const nuovo = { ...f, isPrintError: true, isChange: false, changeType: '' };
    daScrivere.push(nuovo);
  }
  // v6.117 - una scrittura per SERIE. La migrazione avvisava "sono N SCRITTURE su Firestore":
  // ora sono N record in poche scritture, una per ogni serie toccata.
  mostra('Conversione in corso…');
  try {
    await _salvaFigurineInBlocco(daScrivere);
    daScrivere.forEach(nuovo => {
      const idx = figs.findIndex(x => x.id === nuovo.id);
      if (idx >= 0) figs[idx] = nuovo;
    });
    fatti = daScrivere.length;
  } catch (e) { console.error('migratePrintErrors', e); falliti = daScrivere.length; }
  mostra(`Convertiti ${fatti} / ${daMigrare.length}` + (falliti ? ` — ${falliti} FALLITI` : ''));

  // un fallimento silenzioso qui lascerebbe meta' dei dati nel vecchio modello e meta'
  // nel nuovo, senza che nessuno lo sappia: la peggiore delle due verita' (v5.682).
  // ...e ripulisce anche la LISTA delle serie: se "Errore di stampa" restasse fra i
  // "Tipi di change", il menu tornerebbe a offrirlo e finirebbe sui record NUOVI —
  // rifacendo, un pezzo alla volta, il modello che stiamo smontando.
  let serieRipulite = 0;
  try {
    for (const sr of getData('series', [])) {
      const lista = sr.retroChangeTypes || [];
      const pulita = lista.filter(t => !/^error[ei]\s+di\s+stampa$/i.test((t || '').trim()));
      if (pulita.length !== lista.length) {
        await fsSave('series', { ...sr, retroChangeTypes: pulita });
        sr.retroChangeTypes = pulita;
        serieRipulite++;
      }
    }
  } catch (e) { console.error('pulizia retroChangeTypes', e); }
  const coda = serieRipulite ? ` Tolto "errore di stampa" dai Tipi di change di ${serieRipulite} serie.` : '';

  mostra(falliti
    ? `⚠️ Migrazione INCOMPLETA: ${fatti} riusciti, ${falliti} falliti. Rilancia il pulsante: riprendera' solo quelli rimasti.`
    : `\u2713 Migrazione completata: ${fatti} record convertiti.${coda} Ricarica la pagina.`);
  if (btn) btn.disabled = false;
  try { renderItems(); refreshSeriesMeta(); } catch (e) {}
}

async function migrateFigurinesIntoSeries() {
  if (!confirm('Migrare tutte le figurine nel nuovo formato per-serie? Operazione da fare una volta sola.')) return;
  const btn = document.getElementById('migrate-figurines-btn');
  const progressEl = document.getElementById('migrate-figurines-progress');
  if (btn) btn.disabled = true;
  if (progressEl) { progressEl.style.display = ''; progressEl.textContent = 'Lettura della vecchia collezione figurines...'; }

  try {
    const oldFigurines = await fsGetAll('figurines'); // vecchio formato, un documento a figurina
    const seriesList = getData('series', []);
    const bySeriesId = {};
    for (const f of oldFigurines) {
      if (!bySeriesId[f.seriesId]) bySeriesId[f.seriesId] = [];
      bySeriesId[f.seriesId].push(f);
    }

    let done = 0;
    for (const series of seriesList) {
      series.items = bySeriesId[series.id] || [];
      _recomputeSeriesCounts(series);
      await fsSave('series', series);
      done++;
      if (progressEl) progressEl.textContent = 'Migrate ' + done + ' / ' + seriesList.length + ' serie...';
    }

    const matchedSeriesIds = new Set(seriesList.map(s => s.id));
    const orphanFigs = oldFigurines.filter(f => !matchedSeriesIds.has(f.seriesId));

    // Ricostruisce la cache piatta usata da tutto il resto del codice
    _cache.figurines = [];
    for (const s of seriesList) for (const item of (s.items || [])) _cache.figurines.push(item);
    _invalidateSessionCache();

    const summary = 'Completato: ' + oldFigurines.length + ' figurine spostate in ' + done + ' serie.' +
      (orphanFigs.length ? ' ⚠️ ' + orphanFigs.length + ' figurine con una serie non trovata (seriesId non valido) — ignorate, controllale manualmente.' : '');
    if (progressEl) progressEl.textContent = summary;
    toast(oldFigurines.length + ' figurine migrate con successo' + (orphanFigs.length ? ' (' + orphanFigs.length + ' orfane, vedi log)' : ''), orphanFigs.length ? 'error' : 'success');
    renderCatalog(); renderHomeSeries(); renderHomeStats(); renderAdminSeries();
  } catch(e) {
    console.error('migrateFigurinesIntoSeries', e);
    toast('Errore durante la migrazione: ' + e.message, 'error');
    if (progressEl) progressEl.textContent = '❌ Errore: ' + e.message;
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function loadAllData() {
  showLoadingOverlay(true);

  // (Il rilevamento della lingua del browser è stato spostato alla prima
  // assegnazione di currentLang — qui non veniva mai eseguito: vedi la nota
  // su _detectBrowserLang.)

  // Cache in sessionStorage per ridurre le letture Firebase
  // Le collection che cambiano raramente vengono cachate per la sessione corrente
  const SESSION_KEY = 'sgorbions_session_cache';
  const CACHE_TTL = 5 * 60 * 1000; // 5 minuti
  let sessionCache = null;
  try {
    const raw = sessionStorage.getItem(SESSION_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Date.now() - parsed.ts < CACHE_TTL) sessionCache = parsed;
    }
  } catch(e) {}

  try {
    if (sessionCache) {
      // Usa la cache per i dati statici
      _cache.series = sessionCache.series || [];
      _cache.figurines = sessionCache.figurines || [];
      _cache.levels = sessionCache.levels || [];
      // Le serie in sessionStorage sono salvate SENZA il campo "items" (per
      // non duplicare gli stessi dati anche nell'array piatto figurines,
      // risparmiando spazio nel browser) — le riattacchiamo qui
      const figsBySeriesId = {};
      for (const f of _cache.figurines) {
        if (!figsBySeriesId[f.seriesId]) figsBySeriesId[f.seriesId] = [];
        figsBySeriesId[f.seriesId].push(f);
      }
      for (const s of _cache.series) s.items = figsBySeriesId[s.id] || [];
      // Ricarica solo i dati dinamici
      _cache.posts = await fsGetAll('posts');
      _cache.public_profiles = await fsGetAll('public_profiles');
      if (currentUser?.isAdmin) await _loadAdminOnlyData();
    } else {
      // Prima volta o cache scaduta: carica tutto
      // v6.176 - si legge DAL SERVER e si ritenta tre volte. Il tetto della v6.173 e' dentro
      // `_leggiSerieRitentando`, e vale per ogni tentativo.
      _cache.series = await _leggiSerieRitentando();
      // Le figurine vivono dentro il documento della loro serie (campo
      // "items"): le "spacchettiamo" qui in un unico array piatto, così
      // tutto il resto del codice continua a usare _cache.figurines
      // esattamente come prima, senza saperlo
      _cache.figurines = [];
      for (const s of _cache.series) {
        for (const item of (s.items || [])) _cache.figurines.push(item);
      }
      _cache.posts = await fsGetAll('posts');
      _cache.public_profiles = await fsGetAll('public_profiles');
      if (currentUser?.isAdmin) await _loadAdminOnlyData();
      _cache.levels = await fsGetAll('levels');
      // Salva in sessionStorage (le serie senza "items": sono già presenti
      // per intero in figurines, non serve duplicarle e sprecare spazio)
      try {
        const seriesLight = _cache.series.map(s => { const { items, ...rest } = s; return rest; });
        sessionStorage.setItem(SESSION_KEY, JSON.stringify({
          ts: Date.now(),
          series: seriesLight,
          figurines: _cache.figurines,
          levels: _cache.levels
        }));
      } catch(e) {}
    }
    await loadAllOwnedFromFirebase();
    _cache.users = _cache.users || [];
    // seed admin if not present (solo quando l'intera lista utenti è caricata, cioè per l'admin)
    if (currentUser?.isAdmin && !_cache.users.find(u => u.username === 'admin')) {
      const adminUser = { id: 'admin', username: 'admin', email: 'admin@sgorbions.it', password: 'admin123', isAdmin: true, joined: new Date().toISOString() };
      await fsSave('users', adminUser);
      _cache.users.push(adminUser);
    }
  } catch(e) {
    // v6.108 - qui ci finisce anche il TIMEOUT del `Promise.race` qui sopra, che e' il sospettato
    // principale dell'Indagine 3: le serie pesano ~1,4 MB e crescono. Se il messaggio che compare a
    // schermo dice `timeout`, e' quello.
    // v6.173 - e ora il numero da cambiare NON si cambia piu' qui: sta in Impostazioni -> Impostazioni
    // generali sito. Il valore di partenza e la sua taratura stanno accanto a
    // TIMEOUT_CARICAMENTO_DEFAULT_MS.
    _guastoCaricamentoDati(e.message || e);
    return;
  }
  showLoadingOverlay(false);
  // v6.173 - si aggiorna il tetto per il PROSSIMO caricamento, adesso che i dati ci sono. Senza
  // `await` di proposito: e' una rifinitura per il giro dopo, non deve rallentare questo.
  _aggiornaTimeoutDaConfigurazione();
  // v6.233 - la semina delle versioni per articolo, una volta sola e solo da admin. Come sopra,
  // senza `await`: non deve rallentare il primo disegno della pagina.
  _seminaVersioniArticolo();
  // v6.235 - la verifica delle partenze sui dati veri, una volta per sessione e solo da admin.
  // Non blocca niente: stampa. Si rilancia a mano con `verificaPartenzeSuiDati()`.
  if (currentUser?.isAdmin && !_partenzeVerificate) { _partenzeVerificate = true; try { verificaPartenzeSuiDati(false); } catch (e) { console.error('verificaPartenzeSuiDati', e); } }
  // v6.108 - Firestore ha risposto, e ha risposto SENZA SERIE. Non e' lo stesso guasto di sopra ed
  // e' bene che non dica la stessa cosa: li' la lettura non e' arrivata in fondo, qui e' arrivata e
  // non conteneva niente. Prima entrambi i casi finivano nei dati demo, indistinguibili.
  // 🔴 v6.176 - IL TESTO E' CAMBIATO PERCHE' QUELLO DI PRIMA DICEVA IL FALSO.
  // Diceva "Firestore ha risposto, ma senza nessuna serie" anche quando Firestore NON aveva
  // risposto affatto: con `getDocs` un client offline riceve la cache locale vuota, e la promessa
  // si RISOLVE. Il messaggio descriveva un database vuoto — un problema di dati — mentre il
  // problema era di rete, e mandava a cercare dalla parte sbagliata.
  // Ora la lettura passa da `getDocsFromServer` (vedi `fsGetAllDalServer`), che offline RIFIUTA:
  // se si arriva fin qui, il server ha risposto sul serio e la collezione e' davvero vuota.
  // Il testo puo' quindi dire quel che dice, ed e' vero.
  if (!_cache.series.length) { _guastoCaricamentoDati('Il server ha risposto, e la collezione delle serie e\' vuota'); return; }

  // Se l'utente ha una sessione già salvata (login automatico), aggiorna
  // lastLogin: senza questo, chi resta loggato senza rifare login esplicito
  // non avrebbe mai una data di ultimo accesso registrata su Firebase.
  if (currentUser) {
    const freshUser = (_cache.users || []).find(u => u.id === currentUser.id);
    if (freshUser) {
      freshUser.lastLogin = new Date().toISOString();
      currentUser = freshUser;
      LOCAL.set('currentUser', freshUser);
      await fsSave('users', freshUser);
    }
  }

  renderAll();
  updateNavUser();
}

function showLoadingOverlay(show) {
  let ov = document.getElementById('loading-overlay');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'loading-overlay';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(14,10,26,0.92);z-index:9998;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1rem;';
    ov.innerHTML = '<div style="font-family:var(--font-display);font-size:2rem;color:var(--accent);text-shadow:0 0 30px rgba(181,255,46,0.5);">SGORBIONS</div><div style="font-family:var(--font-ui);color:var(--muted);font-size:1rem;">Caricamento dati...</div><div style="width:200px;height:4px;background:var(--card2);border-radius:2px;overflow:hidden;"><div style="height:100%;background:linear-gradient(90deg,var(--accent3),var(--accent));animation:progress-anim 1.5s ease-in-out infinite;border-radius:2px;"></div></div><style>@keyframes progress-anim{0%{width:0%;margin-left:0}50%{width:70%;margin-left:0}100%{width:0%;margin-left:100%}}</style>';
    document.body.appendChild(ov);
  }
  ov.style.display = show ? 'flex' : 'none';
}

// v6.108 (Franco) - IL CARICAMENTO E' FALLITO, E LO SI DICE.
//
// Al posto di `loadDemoData()`. Il ripiego ai dati demo era nato per un caso che oggi non esiste
// piu': un sito SENZA database, che mostrava tre serie finte per far vedere com'e' fatto.
// `FIREBASE_CONFIG` e' scritto dentro l'app e non manca mai, quindi da tempo quel ripiego non
// scattava piu' per "Firebase non c'e'": scattava su un GUASTO PASSEGGERO - una lettura lenta, la
// rete che fa i capricci - e sostituiva dati finti a dati veri **senza dirlo**, con un `console.warn`
// che nessuno guarda.
// Il costo lo ha pagato Franco piu' volte: "la preview carica i dati della sandbox, e ricaricare non
// serve". Non serviva perche' non c'era niente in cache da buttare - si rifaceva lo stesso tentativo.
// E cercare la causa richiedeva di avere la console aperta al momento giusto.
//
// Adesso il sito si ferma e scrive **la causa vera**. Un pannello che copre, non una fascetta:
// proseguire con il catalogo vuoto racconterebbe un'altra bugia, cioe' che di oggetti non ce ne
// sono. Meglio una schermata che dice "i dati non sono arrivati" di un sito che sembra a posto e non
// lo e'.
function _guastoCaricamentoDati(causa) {
  console.error('[Sgorbions] caricamento dati fallito:', causa);
  showLoadingOverlay(false);
  const it = (typeof currentLang === 'undefined' || currentLang === 'it');
  let ov = document.getElementById('sg-guasto-dati');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'sg-guasto-dati';
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(14,10,26,0.96);z-index:9999;display:flex;'
      + 'flex-direction:column;align-items:center;justify-content:center;gap:1rem;padding:1.5rem;text-align:center;';
    document.body.appendChild(ov);
  }
  // v6.109 (Franco) - DUE SCHERMATE, E IL TESTO LO HA DECISO FRANCO.
  //
  //   ADMIN   -> la sola causa vera, piu' RIPROVA. Niente prosa: a chi puo' farci qualcosa serve la
  //              stringa, il resto e' rumore.
  //   UTENTE  -> "SITO MOMENTANEAMENTE NON DISPONIBILE." piu' RIPROVA. La causa NON si mostra: non
  //              la scriviamo noi, arriva dall'SDK di Firebase, e a un visitatore direbbe cose come
  //              `Missing or insufficient permissions` - per lui rumore, e intanto un pezzo di come
  //              e' fatto il sito dentro. Resta comunque nella `console.error` qui sopra.
  //
  // Il "RIPROVARE PIU' TARDI" della prima stesura e' stato tolto (Franco: "per lo user tieni solo il
  // pulsante RIPROVA"): con un guasto che spesso e' passeggero, "piu' tardi" manderebbe via qualcuno
  // che con un click sarebbe entrato. A invitare all'azione basta il pulsante, che dice gia' cosa
  // fare e lo fa subito.
  //
  // Nota di lessico, ed era un errore: la prima stesura diceva "i dati del CATALOGO". Qui dentro non
  // c'e' nessun catalogo, c'e' un INVENTARIO - e' il nome della sezione. Le parole del sito si
  // copiano dal sito, non si inventano.
  //
  // `currentUser` c'e' anche durante il guasto perche' viene da localStorage e non da Firebase: e'
  // l'unico motivo per cui questa distinzione si puo' fare proprio nel momento in cui Firebase non
  // risponde.
  const admin = !!currentUser?.isAdmin;
  const pulsante = '<button onclick="location.reload()" style="font-family:var(--font-ui);font-size:0.9rem;'
    + 'font-weight:600;padding:0.55rem 1.4rem;border-radius:8px;border:none;background:var(--accent);'
    + 'color:var(--bg);cursor:pointer;">' + (it ? 'RIPROVA' : 'RETRY') + '</button>';
  ov.innerHTML = admin
    ? '<code style="font-family:ui-monospace,monospace;font-size:0.9rem;color:var(--warn);background:var(--card2);'
      + 'border:1px solid var(--border);border-radius:8px;padding:0.7rem 1rem;max-width:40rem;word-break:break-word;">'
      + String(causa || (it ? 'causa non riportata' : 'cause not reported')) + '</code>'
      + pulsante
    // Il marchio resta all'utente e non all'admin: su una pagina pubblica dice che il guasto e' del
    // sito e non del browser, cioe' fa sembrare la schermata voluta invece che rotta.
    // v6.110 (Franco) - il nome per esteso, com'e' scritto nella barra degli indirizzi: chi arriva
    // qui deve riconoscere il sito che stava cercando, e "SGORBIONS" da solo non e' quello che ha
    // digitato. La misura e' a `clamp` e non fissa perche' la scritta e' lunga il doppio della
    // precedente: a 1.8rem su un telefono stretto sarebbe uscita dallo schermo.
    : '<div style="font-family:var(--font-display);font-size:clamp(1rem,5.5vw,1.6rem);color:var(--accent);'
      + 'max-width:100%;word-break:break-word;">FIGURINESGORBIONS.IT</div>'
      + '<div style="font-family:var(--font-ui);color:var(--text);font-size:1rem;letter-spacing:0.03em;max-width:34rem;">'
      + (it ? 'SITO MOMENTANEAMENTE NON DISPONIBILE.' : 'THE SITE IS TEMPORARILY UNAVAILABLE.') + '</div>'
      + pulsante;
  ov.style.display = 'flex';
}

// ============================================================
//  CLOUDINARY UPLOAD
// ============================================================
async function uploadToCloudinary(file) {
  const formData = new FormData();
  formData.append('file', file);
  formData.append('upload_preset', CLOUDINARY_PRESET);
  const res = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD}/image/upload`, {
    method: 'POST', body: formData
  });
  const data = await res.json();
  if (data.secure_url) {
    _trackCloudinaryUpload();
    return data.secure_url;
  }
  throw new Error('Upload failed');
}

// ── Contatore upload Cloudinary ───────────────────────────────
function _getMonthKey() {
  const now = new Date();
  return now.getFullYear() + '-' + String(now.getMonth()+1).padStart(2,'0');
}

function _getCloudinaryCounter() {
  try {
    const raw = localStorage.getItem('sgorbions_cloudinary');
    if (!raw) return { count: 0, month: _getMonthKey() };
    const data = JSON.parse(raw);
    if (data.month !== _getMonthKey()) return { count: 0, month: _getMonthKey() };
    return data;
  } catch(e) { return { count: 0, month: _getMonthKey() }; }
}

function _trackCloudinaryUpload() {
  try {
    const data = _getCloudinaryCounter();
    data.count += 1;
    localStorage.setItem('sgorbions_cloudinary', JSON.stringify(data));
  } catch(e) {}
}

function getCloudinaryUploadCount() {
  return _getCloudinaryCounter().count;
}

