// Lingua del browser (navigator.language: informazione già presente nel
// browser, nessuna richiesta di rete verso terzi — vedi Privacy Policy).
// Se il browser non dichiara nulla, il default è l'italiano.
function _detectBrowserLang() {
  const b = (navigator.language || navigator.userLanguage || '').toLowerCase();
  if (!b) return 'it';
  return b.startsWith('it') ? 'it' : 'en';
}

// ATTENZIONE all'ordine: il rilevamento va fatto QUI, alla prima assegnazione.
// Farlo più tardi (com'era in loadAllData) è inutile — setLang(), chiamato nel
// blocco INIT prima di initFirebase(), scrive già LOCAL('lang'), quindi il
// controllo "!LOCAL.get('lang')" là in fondo risultava sempre falso e il
// rilevamento non veniva MAI eseguito.
let currentLang = LOCAL.get('lang') || _detectBrowserLang();

function t(key) { return (i18n[currentLang] || i18n.en)[key] || (i18n.en)[key] || key; }

// v5.939 (Franco) — TITOLO E SEGNAPOSTO DELLA RICERCA, che non si traducevano.
// Sono gli unici due testi della pagina costruiti a mano ("Imposta la tua ricerca di figurine",
// "Cerca figurine...") perché contengono il nome della sezione, quindi non possono stare in un
// data-i18n fisso: venivano scritti una volta sola all'apertura della sezione e restavano nella
// lingua di quel momento. Ora sono in una funzione, chiamata sia lì sia ad ogni cambio lingua.
function aggiornaTestiRicercaSezione() {
  if (!currentSection) return;
  const it = (currentLang === 'it');
  const nome = (getSectionLabel(currentSection) || (it ? 'oggetti' : 'items')).toLowerCase();
  const si = document.getElementById('items-search');
  if (si) si.placeholder = (it ? 'Cerca ' : 'Search ') + nome + '...';
  const st = document.getElementById('items-search-title');
  if (st) st.textContent = (it ? 'Imposta la tua ricerca di ' : 'Set your search for ') + nome;
}

function applyI18n() {
  document.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.dataset.i18n);
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    el.innerHTML = t(el.dataset.i18nHtml);
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    el.placeholder = t(el.dataset.i18nPlaceholder);
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    el.title = t(el.dataset.i18nTitle);
  });
  // v5.939 — i due testi della ricerca che contengono il nome della sezione
  try { aggiornaTestiRicercaSezione(); } catch (e) { console.error('aggiornaTestiRicercaSezione', e); }
  // e le etichette dei box filtri, anch'esse costruite a mano con il nome della sezione
  try { if (currentSection) renderItemTypeFilters(); } catch (e) { console.error('renderItemTypeFilters (i18n)', e); }
}

function setLang(lang, byUser = false) {
  currentLang = lang;
  LOCAL.set('lang', lang);
  if (byUser && currentUser) {
    LOCAL.set('lang_set_by_user_' + currentUser.id, true);
    // Persistiamo la scelta anche sul documento utente: localStorage vive solo su
    // questo dispositivo, ma per scrivergli un'e-mail nella sua lingua il dato
    // deve stare nel database. Scrittura non bloccante: cambiare lingua a mano è
    // un gesto raro, e se fallisce non c'è nulla da interrompere.
    if (currentUser.lang !== lang) {
      currentUser.lang = lang;
      LOCAL.set('currentUser', currentUser);
      fsSave('users', currentUser).catch(e => console.warn('Lingua utente non salvata', e.message));
    }
  }
  // Update flag button
  const btn = document.getElementById('lang-current-btn');
  if (btn) {
    const flags = { en: 'gb', it: 'it' };
    btn.src = flagUrl(flags[lang] || 'gb');
  }
  document.querySelectorAll('.lang-btn').forEach(b => {
    b.classList.toggle('active', (lang === 'en' && b.textContent === '🇬🇧') || (lang === 'it' && b.textContent === '🇮🇹'));
  });
  const eyebrow = document.getElementById('classifica-eyebrow');
  if (eyebrow) eyebrow.textContent = lang === 'it' ? 'Migliori Collezionisti' : 'Top Collectors';
  // Blocchi di contenuto lungo (es. Privacy Policy) troppo estesi per il
  // dizionario data-i18n: due versioni statiche, mostriamo solo quella giusta
  document.querySelectorAll('.lang-block-it').forEach(el => el.style.display = lang === 'it' ? '' : 'none');
  document.querySelectorAll('.lang-block-en').forEach(el => el.style.display = lang === 'en' ? '' : 'none');
  applyI18n();
  renderAll();
}

// ============================================================
//  APP STATE
// ============================================================
let currentUser = LOCAL.get('currentUser') || null;
let _realAdmin = null; // traccia l'admin originale durante l'impersonificazione (vedi isImpersonating)
let currentSeriesId = null;
// v6.054 (Franco) - UN VALORE SOLO per i due filtri sulla foto: null | 'senza' | 'con'.
// Due booleani separati potrebbero essere accesi entrambi, e "senza foto E con foto" e' un elenco
// vuoto che nessuno ha chiesto: con un valore solo quella combinazione non e' rappresentabile.
// "Con foto" e' riservato all'admin: a un utente non serve chiedere di vedere le figurine che una
// foto ce l'hanno - sono la normalita'. All'admin serve, per lavorare sul gia' fatto.
// v6.095 - quattro stati: null | 'senza' | 'con' | 'nonDisp'. Tutti e tre gli interruttori sono
// da ADMIN e vivono nel riquadro "Filtri aggiuntivi admin".
let _fotoFilter = null;
let _noteFilter = false;   // v6.113 - "Con note", solo admin
// Il filtro sul TIPO di oggetto (set base, variazioni, change...) risponde alla
// domanda "che cosa e' questo?". Non rispondeva a quella che un collezionista si fa
// davvero: "cosa mi manca?". Da qui il secondo filtro, che e' una DIMENSIONE
// INDIPENDENTE: "variazione ufficiale" e "mi manca" non sono alternative, si
// COMBINANO ("le variazioni ufficiali che mi mancano"). Per questo vive in una
// variabile propria e in una riga propria, e non fra le opzioni del tipo.
let _ownedFilter = 'all'; // 'all' | 'owned' (ce l'ho) | 'missing' (mi manca)
let _wishlistFilter = false; // v5.908 — filtro "Ciò che cerco": se acceso, mostra solo la wishlist dell'utente
let _itemTypeFilter = 'base'; // 'base' | 'variation' | 'unofficialVariation' | 'change' | 'all' — sempre uno solo attivo
// v6.048 (Franco) - da ADMIN si riparte sempre da "tutti". Il valore qui sopra vale solo prima che
// si entri in una sezione: chi decide davvero e' _tipoIniziale(), chiamata a ogni apertura, perche'
// al caricamento del file currentUser non esiste ancora.
// Il perche' della differenza: un utente arriva per guardare la collezione, e "set base" gli mostra
// la serie come la si ricorda, senza le varianti; un admin arriva per LAVORARCI, e un filtro acceso
// che non ha scelto lui gli nasconde meta' degli oggetti - compresi quelli che sta cercando perche'
// hanno qualcosa che non va.
function _tipoIniziale() { return currentUser?.isAdmin ? 'all' : 'base'; }
// v6.140 (Franco) - DA CHI DISCENDE un change o un errore di stampa: dalla figurina BASE o da una
// VARIAZIONE. Sono sotto-filtri del rispettivo selettore, non filtri a se': valgono solo mentre
// quel selettore e' acceso, e si spengono con lui (vedi `_sciogliRaggruppamentiEstranei`).
// '' = tutti | 'base' = discende da una base | 'variation' = discende da una variazione.
let _changeParentFilter = '';
let _printErrorParentFilter = '';
let _ebayFilter = false; // indipendente da _itemTypeFilter: si combina in AND, non è esclusivo con "Solo base"/ecc.
let _noOfficialVariationFilter = false; // indipendente da _itemTypeFilter come _ebayFilter, ma impone SEMPRE anche "solo base" (non solo AND con il filtro tipo scelto) — mostra solo figurine base senza nessuna Variazione ufficiale collegata
let _retroViewMode = 'destra-piena'; // 'sotto' | 'destra' | 'dinamico' | 'fronte-grande' | 'destra-piena' — come viene mostrato il Retro rispetto al fronte nella griglia Figurine, visibile a tutti

// v5.827 — ETICHETTA DELLE CARD FIGURINA, SOLO SU TELEFONO.
// 'number' = sulla card compare il solo numero; 'full' = numero e nome (com'e' sul desktop).
// Vale ESCLUSIVAMENTE sotto la soglia mobile: _figLabelOnlyNumber() ha la guardia di viewport,
// quindi il desktop rende sempre numero+nome qualunque cosa ci sia salvato. La scelta e'
// ricordata dal browser (localStorage), a differenza di _retroViewMode che non si salva.
let _figLabelMode = 'full';   // v5.848 — default: nomi MOSTRATI (prima 'number')
try { const _m = localStorage.getItem('sgorbions_fig_label_mode'); if (_m === 'number' || _m === 'full') _figLabelMode = _m; } catch(e) {}
function _isMobileViewport() { return window.matchMedia('(max-width: 860px)').matches; }
function _figLabelOnlyNumber() { return _isMobileViewport() && _figLabelMode === 'number'; }

// v6.020 — "MOSTRA RETRO" quando su telefono il filtro "Figurine set base" li nasconde.
// Dalla v5.853 con quel filtro attivo la card mostra il solo fronte: sono tutte figurine base,
// affiancare il retro dimezzava il fronte senza distinguere niente. Resta vero come DEFAULT, ma
// da qui in poi e' una scelta dell'utente e non piu' un fatto: l'interruttore sta accanto a
// "Mostra nomi" e compare SOLO nella situazione in cui i retro sarebbero nascosti.
// NON si salva in localStorage (scelta di Franco): ogni apertura del sito riparte spenta, come
// _retroViewMode e a differenza di _figLabelMode. Dentro la sessione invece regge, cosi'
// cambiare filtro e tornare su "base" non fa perdere la scelta appena fatta.
let _mostraRetroSoloBase = false;

// LA condizione "su telefono si vede il solo fronte". Prima della v6.020 stava scritta due volte,
// in renderItems e in _itemHasWidePair, e il commento di quest'ultima diceva apertamente che
// erano "due copie della stessa verita' e l'unica difesa e' che questo commento lo dica".
// Con l'aggiunta di _mostraRetroSoloBase le copie sarebbero diventate tre: qui diventa una.
// Chi la chiama da _itemHasWidePair guarda currentSection e non f.section, ma quella funzione
// esce gia' prima se f.section !== 'figurines', e viene chiamata solo mentre si impagina la
// sezione corrente: le due letture coincidono.
function _soloFronteMobile() {
  return _isMobileViewport()
      && currentSection === 'figurines'
      && _itemTypeFilter === 'base'
      && !_mostraRetroSoloBase;
}
// L'interruttore ha senso solo dove c'e' qualcosa da riaccendere: stessa condizione, ma senza
// l'ultimo pezzo — altrimenti accendendolo sparirebbe il comando per rispegnerlo.
function _mostraRetroToggleVisibile() {
  return _isMobileViewport() && currentSection === 'figurines' && _itemTypeFilter === 'base';
}
function toggleMostraRetroSoloBase() {
  _mostraRetroSoloBase = !_mostraRetroSoloBase;
  currentItemPage = 1; // le card cambiano larghezza: la paginazione calcolata prima non vale piu'
  try { renderItems(); } catch(e) { console.error('renderItems (toggleMostraRetroSoloBase)', e); }
}

// v5.856 — descrizione della serie richiudibile, solo su telefono.
function _setupSeriesDescToggle(desc) {
  const p = document.getElementById('detail-desc');
  const btn = document.getElementById('detail-desc-toggle');
  if (!p || !btn) return;
  const lunga = _isMobileViewport() && (desc || '').trim().length > 140;
  if (!lunga) {
    p.classList.remove('desc-collapsed');
    btn.style.display = 'none';
    return;
  }
  p.classList.add('desc-collapsed');
  btn.style.display = '';
  btn.textContent = currentLang === 'it' ? 'Mostra tutto' : 'Show more';
}
function toggleSeriesDesc() {
  const p = document.getElementById('detail-desc');
  const btn = document.getElementById('detail-desc-toggle');
  if (!p || !btn) return;
  const chiusa = p.classList.toggle('desc-collapsed');
  btn.textContent = chiusa
    ? (currentLang === 'it' ? 'Mostra tutto' : 'Show more')
    : (currentLang === 'it' ? 'Mostra meno' : 'Show less');
}
function setFigLabelMode(mode) {
  _figLabelMode = (mode === 'full') ? 'full' : 'number';
  try { localStorage.setItem('sgorbions_fig_label_mode', _figLabelMode); } catch(e) {}
  try { renderItems(); } catch(e) { console.error('renderItems (setFigLabelMode)', e); }
}
function toggleFigLabelMode() { setFigLabelMode(_figLabelMode === 'number' ? 'full' : 'number'); }
// v6.077 (Franco) - IL NUMERO ESISTE SOLO DOVE SI PUO' SCRIVERE. Le due form lo mostrano nelle sole
// FIGURINE, e non nei tipi che lo ereditano dalla base: in album, bustine e altri oggetti il campo
// non c'e' proprio. Card, titolo della scheda e ordinamento lo stampavano lo stesso, pescandolo da
// un valore che nessuno poteva correggere - e infatti si era guastato in silenzio: due album
// numerati 1, due "altri oggetti" numerati 1, e tre album con la foto della figurina dello stesso
// numero, presa da un vecchio caricamento massivo (visto il 6 agosto 2026).
// La regola e' una: figurine, e solo se la serie i numeri li usa davvero.
// NB: i numeri restano SCRITTI sui record. Qui si smette solo di leggerli, quindi non si perde
// niente e tornare indietro e' una riga.
function _haNumero(f) {
  if (!f || f.section !== 'figurines' || f.noNumber) return false;
  const s = getData('series', []).find(x => x.id === f.seriesId);
  return !(s && s.noNumbers);
}
// v6.077 - lo stesso campo, due mestieri. Nelle FIGURINE e' il Numero (e sparisce nei tipi che lo
// ereditano dalla base); in album, bustine e altri oggetti e' l'ORDINAMENTO, cioe' l'unica leva per
// decidere in che ordine stanno in griglia. Nei RETRO non c'e': loro un ordine vero ce l'hanno gia'
// (categoria, sottocategoria, nome), e una leva inerte e' un comando che mente.
// Tre punti la interrogavano con tre condizioni diverse, e una delle tre (il toggle della scheda)
// non guardava nemmeno la sezione: bastava spuntare e togliere una casella su un retro per far
// comparire un campo che li' non deve esserci.
// v6.214 - anche qui la domanda passa dal descrittore, e i tre casi diventano leggibili: un
// articolo senza numero non mostra il campo; uno col numero d'INVENTARIO lo nasconde quando il tipo
// e' ereditato (li' il numero viene dalla base); uno con l'ORDINAMENTO lo mostra sempre, perche'
// una posizione in elenco non si eredita da nessuno.
function _mostraCampoNumero(sezione, tipoEreditato) {
  if (!sezione) return false;
  const n = _art(sezione).numero;
  if (n === 'nessuno') return false;
  if (n === 'inventario') return !tipoEreditato;
  return true;
}
// v6.214 - la domanda non elenca piu' le sezioni: la fa al descrittore. Prima diceva "tutto cio'
// che non e' figurines ne' retros", che e' un elenco per esclusione - e un elenco per esclusione
// accoglie in silenzio ogni sezione futura, giusta o sbagliata che sia. Con la sesta e' successo:
// `attaccare` ci e' caduta dentro senza che nessuno l'avesse deciso.
function _numeroEOrdinamento(sezione) {
  return !!sezione && _art(sezione).numero === 'ordinamento';
}
// v6.077 - l'etichetta del campo nella FINESTRA "Aggiungi/Modifica". Va scritta da JS perche'
// dipende dalla sezione, e mentre dice "Ordinamento" il `data-i18n` va TOLTO: applyI18n() riscrive
// tutto cio' che ce l'ha, quindi al primo cambio lingua l'etichetta sarebbe tornata "Numero" da
// sola - la trappola descritta nel §5 del documento, che costa una release ogni volta.
// Nella scheda non serve: li' l'etichetta la genera gia' switchToEditMode() a ogni apertura.
// La serie ha i numeri? Flag "Non ha numeri" della scheda serie (s.noNumbers).
function _serieHaNumeri() {
  const s = getData('series', []).find(x => x.id === currentSeriesId);
  return !(s && s.noNumbers);
}
// Specchietti "Retro per categoria" (v5.762): stato apertura (chiusi al caricamento) e filtro
let _retroCatResultsOpen = false;  // riquadro risultati: chiuso di default
// 🆕 v6.269 - UN INSIEME, non piu' un valore solo. Insieme vuoto = spento, come per i tre
