// Admin seeding is handled in loadAllData() after Firebase is ready

// ============================================================
//  NAVIGATION
// ============================================================
function showAdminTab(tab) {
  // Show page-profile but hide profile content, show only admin panel
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  const profilePage = document.getElementById('page-profile');
  if (profilePage) profilePage.classList.add('active');
  const sd = document.getElementById('series-detail');
  if (sd) sd.style.display = 'none';
  // Hide profile content, show admin panel
  const profileContent = document.getElementById('profile-content');
  if (profileContent) profileContent.style.display = 'none';
  const panel = document.getElementById('admin-panel');
  if (panel) panel.style.display = 'block';
  window.scrollTo({ top: 0, behavior: 'smooth' });
  adminTab(tab);
}

// v6.011 (Franco) - nella home il logo sparisce dalla navbar, perche' lo stesso logo e' gia' grande
// in mezzo alla pagina: due volte la stessa immagine a un palmo di distanza.
// Fuori dalla home il logo resta: li' e' l'unico posto in cui compare, ed e' anche il modo per
// tornare indietro.
// Lo stato non si passa come parametro ma si LEGGE dal DOM (quale pagina e' attiva, e se la scheda
// serie e' aperta): chi apre una serie non passa da showPage, e un parametro avrebbe richiesto di
// ricordarsene in ogni punto di navigazione.
//
// v6.183 (Franco) - VALE ANCHE SUL DESKTOP: e' caduta la condizione `_isMobileViewport()`.
// ⚠️ La regola non cambia, cambia la RAGIONE per cui vale, e le due non coincidevano.
// Sul telefono il motivo scritto nella v6.011 era lo spazio verticale, "la risorsa scarsa" — un
// argomento che sul desktop non regge, perche' li' lo spazio c'e'. Il motivo che vale su entrambi
// e' l'altro, ed era gia' nella prima riga: **la stessa immagine due volte nella stessa schermata**.
// Toglierla dalla navbar in home non fa guadagnare spazio sul desktop, toglie una ripetizione.
// 📌 Ed e' un pezzo di codice che si SEMPLIFICA crescendo: una condizione in meno, e sparisce
// anche la dipendenza dalla larghezza della finestra — quindi il richiamo al `resize` (in fondo al
// file) resta per gli altri, non piu' per questo.
// v6.183 (Franco) — SU TELEFONO LA FRASE SOTTO IL LOGO E' PIU' CORTA.
// "Il database non ufficiale dedicato alla leggendaria serie italiana degli anni '90." diventa
// "Il database non ufficiale della leggendaria serie italiana anni '90.".
// ⚠️ NON si scrive il testo, si cambia la CHIAVE `data-i18n` (e poi il testo). E' la stessa strada
// di `_aggiornaBivioInventario` per `catalog.sub` e del pulsante del riepilogo nella v6.177: un
// `textContent` scritto a mano verrebbe cancellato dal primo `applyI18n()`, che rilegge
// l'attributo — e succederebbe al primo cambio di lingua, cioe' lontano da qui.
// Si riaggancia al `resize` insieme al logo: ruotare il telefono o cambiare preset nel banco prova
// deve aggiornarla, se no resta giusta solo per la larghezza che c'era al caricamento (v6.012).
function _aggiornaFraseHome() {
  const p = document.getElementById('hero-desc-main');
  if (!p) return;
  const chiave = _isMobileViewport() ? 'hero.descShort' : 'hero.desc';
  if (p.getAttribute('data-i18n') === chiave) return;   // niente da fare: evita di riscrivere a ogni pixel di resize
  p.setAttribute('data-i18n', chiave);
  p.textContent = t(chiave);
}

function _aggiornaLogoNavbar() {
  const logo = document.querySelector('#navbar .nav-logo');
  if (!logo) return;
  const attiva = document.querySelector('.page.active');
  const dettaglioSerie = document.getElementById('series-detail');
  const inHome = !!attiva && attiva.id === 'page-home'
    && (!dettaglioSerie || dettaglioSerie.style.display === 'none');
  logo.style.display = inHome ? 'none' : '';
}

// ============================================================
//  CAROSELLO DELLA HOME (v6.051, Franco)
// ============================================================
// Una vetrina di figurine a caso, fra hero e resto della pagina. Sta fuori dal blocco riservato a
// chi ha fatto login: serve soprattutto a chi arriva senza account e non sa ancora cosa c'e' dentro.
// Scelte, e il perche':
//  - MAX 12 elementi. La home la carica anche chi non e' registrato, e ogni foto e' una richiesta di
//    rete in piu': si chiedono miniature (w_300) e si lascia al browser il caricamento pigro.
//  - A CASO ad ogni apertura della home, non "gli ultimi" o "i migliori": non serve nessun campo
//    nuovo e non c'e' niente da tenere aggiornato a mano.
//  - Scorre DA SOLO, ma si ferma col mouse sopra e quando la scheda del browser non e' in primo
//    piano: un carosello che gira in una scheda che nessuno guarda consuma e basta.
//  - Se il sistema dichiara "riduci le animazioni" (prefers-reduced-motion) NON parte da solo. Le
//    frecce restano, quindi si puo' comunque guardare tutto.
//  - Il timer si spegne uscendo dalla home: e' l'unico modo per essere certi che non ne restino due
//    in giro, che e' come questi caroselli finiscono per accelerare da soli.
// v6.073 - i timer stanno in una MAPPA, uno per carosello. Fino alla v6.072 erano due variabili
// sciolte e _caroselloSpegni() sceglieva quale fermare a colpi di "diverso da": con due caroselli
// funzionava, col terzo no — "diverso da serie" avrebbe spento anche quello nuovo. Una mappa non
// ha questo problema e non va ritoccata quando se ne aggiunge un quarto.
const _caroselloTimers = { home: null, serie: null, prodotto: null };
const CAROSELLO_MAX = 20;                                 // v6.066 (Franco): da 15 a 20
// v6.066: altro +15% sulla velocita'. I fattori restano scritti uno per uno invece del risultato:
// cosi' si legge la storia (4 secondi di partenza, poi -30%, poi -15%) e non un numero magico.
const CAROSELLO_PASSO_MS = Math.round(4000 / 1.3 / 1.15 / 1.55); // 4000 -> 3077 -> 2676 -> 1726 ms
// v6.080 (Franco) - il ritmo provato su telefono e' piaciuto e vale OVUNQUE: un passo solo per
// tutti i caroselli, desktop compreso. Era nato come rimedio a un effetto collaterale - con 3
// schede visibili invece di sei e mezzo la stessa fila di venti figurine ci metteva piu' del doppio
// a scorrere tutta - e si e' rivelato semplicemente il ritmo giusto.
// I fattori restano scritti uno per uno invece del risultato: cosi' si legge la storia (4000 di
// partenza, -30%, -15%, -35%) e non un numero magico che nessuno sa piu' da dove viene.
function _caroselloPasso() { return CAROSELLO_PASSO_MS; }
// Larghezza della card come FRAZIONE del contenitore: con un valore in pixel il numero di schede
// visibili cambierebbe con la finestra, e "6 e mezzo" varrebbe solo sul monitor di chi l'ha
// misurato. La mezza scheda tagliata sul bordo e' voluta: dice che la fila continua.
// Formula: N schede occupano N*(card+gap) meno l'ultimo gap, che non c'e'.
const _caroselloLarghezza = n => 'calc((100% + 0.9rem) / ' + n + ' - 0.9rem)';
const CAROSELLO_LARGHEZZA = _caroselloLarghezza(6.5);        // home
const CAROSELLO_LARGHEZZA_SERIE = _caroselloLarghezza(8.5);  // serie: foto piu' piccole (v6.071)
// Quante schede si vedono su TELEFONO. In un posto solo perche' e' un numero che si prova, si
// guarda e si ricambia: 5 alla prima stesura, poi 4, poi 3 (v6.080).
const CAROSELLO_COLONNE_MOBILE = 3;
// Quante serie per riga nell'hub Prodotti su telefono. Un numero da provare, come quello dei
// caroselli: 3 alla prima stesura, 2 dopo averle viste con le pillole sotto (v6.080).
// L'Inventario per Serie ne ha 3, ma le sue card sono piu' semplici: qui sotto la copertina ci
// sono il titolo e le pillole delle tipologie, che in un terzo di schermo si spezzano.
const HUB_COLONNE_MOBILE = 2;
// v6.080 (Franco) - SU TELEFONO le schede visibili sono poche, non sei e mezzo o otto e mezzo. Con la
// larghezza di un telefono quelle frazioni davano card da una quarantina di pixel: foto minuscole.
// Il numero si sceglie qui e non nelle costanti perche' dipende dalla larghezza dello schermo, che
// al caricamento del file non si sa ancora - le costanti restano come valore del desktop.
function _caroselloLarghezzaHome()  { return _isMobileViewport() ? _caroselloLarghezza(CAROSELLO_COLONNE_MOBILE) : CAROSELLO_LARGHEZZA; }
function _caroselloLarghezzaSerie() { return _isMobileViewport() ? _caroselloLarghezza(CAROSELLO_COLONNE_MOBILE) : CAROSELLO_LARGHEZZA_SERIE; }
// E l'ALTEZZA DELLA FOTO su telefono smette di essere un numero fisso. Era il vero motivo del "box
// allungato tantissimo in verticale": 175px di altezza sopra una card larga 60 fanno un rettangolo
// in piedi, e dentro `object-fit:contain` rimpicciolisce la figurina per farcela stare. Le colonne
// da sole non lo risolvono - allargano la card, ma l'altezza resta quella. Su telefono la foto e'
// quindi QUADRATA rispetto alla card; sul desktop restano i numeri di sempre.
// Vale 0 come "usa il quadrato": _caroselloCard lo legge cosi'.
function _caroselloAltezzaFoto(px) { return _isMobileViewport() ? 0 : px; }

// ---- pezzi comuni ai due caroselli (v6.071) --------------------------------------------------
// Sono due file di figurine con le stesse regole: stessa card, stesso scorrimento, stessa velocita',
// stesse condizioni per fermarsi. Cambiano solo COSA mostrano e QUANTO sono grandi. Tenerli in due
// copie avrebbe voluto dire due comportamenti destinati a divergere alla prima modifica.
function _caroselloScorriBox(box, dir) {
  if (!box) return;
  const primo = box.firstElementChild;
  const passo = primo ? (primo.getBoundingClientRect().width + 14) : 200;
  const fine = box.scrollWidth - box.clientWidth - 4;
  if (dir > 0 && box.scrollLeft >= fine) box.scrollTo({ left: 0 });      // in fondo: si ricomincia
  else if (dir < 0 && box.scrollLeft <= 4) box.scrollTo({ left: fine }); // all'inizio: si va in coda
  else box.scrollBy({ left: passo * dir });
}

// La card: foto, poi Serie, Numero, Nome e Punteggio (a destra), ognuno su una riga di altezza
// FISSA. Nomi di lunghezza diversa darebbero card di altezza diversa, e in una fila che scorre si
// vedrebbe subito. Una figurina senza numero lascia la riga bianca invece di far salire le altre.
// v6.073 - QUALI RIGHE mostra la card, e sta scritto in un punto solo perche' e' una regola sola.
// Le figurine tengono le quattro di sempre (Serie, Numero, Nome, Punteggio). I RETRO no: un retro
// non ha numero — zero su 531, misurato — quindi quella riga sarebbe rimasta bianca per sempre, e
// il Nome da solo non basta a distinguerli. Servono Categoria e Sottocategoria, che sono i campi
// con cui i retro si nominano davvero (§13.1).
// Le righe hanno altezza FISSA e restano vuote invece di sparire: nomi di lunghezza diversa
// darebbero card di altezza diversa, e in una fila che scorre si vedrebbe subito.
function _caroselloRighe(f, nomeSerie, mostraSerie) {
  const serie = esc(nomeSerie.get(f.seriesId) || '');
  // v6.081 (Franco) - LA SERIE SI MOSTRA SOLO SE DISTINGUE. Nel carosello della scheda serie tutte
  // le card vengono per forza dalla stessa serie (il filtro e' f.seriesId === currentSeriesId),
  // quindi quella riga ripeteva il titolo della pagina occupando un'altezza fissa su ogni card.
  // La decisione NON e' "in quale carosello siamo" ma "quante serie ci sono nell'elenco"
  // (_caroselloMostraSerie): cosi' vale da se' anche per un hub prodotto che contenga una serie
  // sola, e un quarto carosello non richiede di aggiungere un caso da nessuna parte.
  // Default: se il parametro non arriva, la riga si mostra - il comportamento di prima.
  // v6.277 (Franco) - il nome della serie in BIANCO. Era `var(--accent)`, il verde lime, e in mezzo
  // al testo di un carosello era l'unico.
  const rigaSerie = dim => (mostraSerie === false ? [] : [{ t: serie, col: 'var(--text)', dim, alt: '1.2em' }]);
  // v6.080 (Franco) - SU TELEFONO una riga sola: il nome. Era il testo, non la foto, a fare il "box
  // allungato tantissimo in verticale": quattro righe per le figurine e CINQUE per i retro, ognuna
  // con un'altezza fissa, fanno circa 6em di testo sotto una card larga sessanta pixel - piu' alto
  // della foto stessa.
  // Cadono serie, numero, categoria, sottocategoria e punteggio: su una card cosi' stretta non si
  // leggono comunque, e la scheda completa e' a un tocco. Il nome resta su UNA riga con i puntini,
  // non su due: due righe rimettono meta' del problema.
  // v6.080 (Franco, seconda passata) - il nome su una riga sola con i puntini non si leggeva: su
  // una card da ottanta pixel ci sta poco piu' di una parola, quindi "GASTONE BUBBONE" diventava
  // "GASTON…". Ora ogni PAROLA va a capo per conto suo. I nomi degli Sgorbions sono quasi sempre
  // due parole, cioe' due righe corte e intere invece di una troncata.
  // Altezza 'auto', non fissa: le righe qui sono una o tre a seconda del nome, e un'altezza fissa
  // le taglierebbe di nuovo. Le card restano alte uguali lo stesso, perche' nella fila si stirano
  // sulla piu' alta.
  // Ordine su telefono, deciso da Franco: SERIE in prima riga, NUMERO in seconda, poi il nome.
  // Restano fuori categoria, sottocategoria e punteggio: sono le righe che gonfiavano il box senza
  // essere leggibili. Il numero si mostra solo dove vuol dire qualcosa (_haNumero, v6.077), quindi
  // sui retro quella riga non c'e' - loro un numero non ce l'hanno.
  if (_isMobileViewport()) {
    const isRetro = (f.section || '') === 'retros';
    // v6.080 (Franco) - I RETRO SU TELEFONO HANNO LE LORO RIGHE: serie, categoria, sottocategoria,
    // nome e punteggio. Sono gli stessi campi del desktop, con una differenza sola e voluta: il
    // NOME va a capo quando finisce lo spazio, senza altezza fissa e senza spezzare le parole.
    // Perche' non parola per parola come le figurine: il nome di una figurina e' un nome di persona
    // (due parole), quello di un retro e' una FRASE - fino a nove parole, "RICERCATO PER ENTRATA
    // CON SCASSO (NELLA BOCCA DI CHIUNQUE)". Spezzarla parola per parola faceva nove righe e la
    // card diventava piu' alta di prima che ci mettessimo mano. Su una card stretta il testo va
    // comunque a capo quasi a ogni parola: la regola speciale non serviva, serviva solo togliere
    // il troncamento a una riga che c'era prima.
    if (isRetro) {
      // v6.080 (Franco) - quando il NOME e' piu' lungo del SOTTONOME, in etichetta va il sottonome.
      // Il caso tipico e' la categoria RICERCATO: il nome e' il capo d'imputazione per esteso
      // ("RICERCATA PER CRUDELTA' MENTALE E NON") e il sottonome e' chi lo ha commesso
      // ("INFERMIERA DELLA SCUOLA") - su una card di un carosello serve il secondo.
      // NON e' "se c'e' il sottonome mostralo": misurato sui dati veri, in OFFERTA SPECIALE
      // (46 retro) il sottonome e' sempre PIU' LUNGO del nome, e la regola secca avrebbe
      // sostituito un'etichetta corta con una lunga. Il confronto di lunghezze evita proprio
      // quello, ed e' il motivo per cui la regola e' scritta cosi' e non nel modo piu' breve.
      // Riguarda 45 retro base su 728: 36 RICERCATO, 9 sparsi fra le altre categorie. I 609 senza
      // sottonome non cambiano, e restano lunghi quelli che un sottonome non ce l'hanno.
      const _nomeR = (f.name || '').trim();
      const _sottoR = (f.subname || '').trim();
      const _etichettaR = (_sottoR && _nomeR.length > _sottoR.length) ? _sottoR : _nomeR;
      return [
        ...rigaSerie('0.62rem'),
        // v6.080 (Franco) - la CATEGORIA va a capo se non ci sta, invece di essere troncata coi
        // puntini: su una card da un centinaio di pixel "SGORBIONS HORRIBLE HOROSCOPES" su una
        // riga sola diventa "SGORBIONS HO…", che non dice piu' di quale categoria si tratti.
        // Altezza libera come il nome: e' il modo che questa funzione ha per dire "quante righe
        // servono", e le card restano comunque alte uguali perche' nella fila si stirano.
        // v6.279 (Franco) - gli stessi colori delle card del retro. La sottocategoria resta grigia:
        // non era fra le due nominate. Vedi il CHANGELOG.
        { t: esc(f.category || ''),    col: COL_CATEGORIA,   dim: '0.64rem', alt: 'auto' },
        // v6.281 (Franco) - l'arancione delle card. Qui la categoria era gia' 'auto', quindi andava
        // a capo da se': il troncamento che si vedeva era quello del ramo non-telefono.
        { t: esc(f.subcategory || ''), col: COL_SOTTOCAT,    dim: '0.64rem', alt: '1.2em' },
        { t: esc(_etichettaR),         col: COL_IDENTITA,    dim: '0.7rem',  alt: 'auto' },
        { t: f.score > 0 ? '&#11088; ' + esc(String(f.score)) : '', col: 'var(--success)', dim: '0.66rem', alt: '1.2em', dx: 'right' }
      ];
    }
    // Le figurine restano come deciso prima: serie, numero, e il nome parola per parola - li' sono
    // due parole e la spezzatura le rende leggibili invece che troncate.
    const parole = String(f.name || '').trim().split(/\s+/).filter(Boolean).map(esc).join('<br>');
    const righe = rigaSerie('0.62rem');
    // v6.277 (Franco) - numero e nome in azzurro, come sulle card.
    if (_haNumero(f) && f.number) righe.push({ t: esc(String(f.number)), col: COL_IDENTITA, dim: '0.66rem', alt: '1.2em' });
    righe.push({ t: parole, col: COL_IDENTITA, dim: '0.72rem', alt: 'auto' });
    return righe;
  }
  if ((f.section || '') === 'retros') {
    return [
      ...rigaSerie('0.66rem'),
      // v6.279 (Franco) - come sopra, e per la stessa ragione.
      // v6.281 (Franco) - la categoria su DUE righe invece di una troncata: e' l'altezza a decidere
      // se una riga va a capo (vedi `_caroselloCard`), quindi si cambia quella. Fissa e non 'auto',
      // altrimenti una categoria lunga alzerebbe la sua card e sfalserebbe la fila.
      { t: esc(f.category || ''),    col: COL_CATEGORIA,    dim: '0.68rem', alt: '2.5em' },
      { t: esc(f.subcategory || ''), col: COL_SOTTOCAT,     dim: '0.68rem', alt: '1.2em' },
      { t: esc(f.name || ''),        col: COL_IDENTITA,     dim: '0.74rem', alt: '2.5em' },
      { t: f.score > 0 ? '&#11088; ' + esc(String(f.score)) : '', col: 'var(--success)', dim: '0.7rem', alt: '1.2em', dx: 'right' }
    ];
  }
  return [
    ...rigaSerie('0.66rem'),
    // v6.277 (Franco) - numero e nome in azzurro, come sulle card.
    { t: f.number ? esc(String(f.number)) : '', col: COL_IDENTITA,    dim: '0.7rem',  alt: '1.2em' }, // v6.080 - senza cancelletto
    { t: esc(f.name || ''),                     col: COL_IDENTITA,    dim: '0.74rem', alt: '2.5em' },
    { t: f.score > 0 ? '&#11088; ' + esc(String(f.score)) : '', col: 'var(--success)', dim: '0.7rem', alt: '1.2em', dx: 'right' }
  ];
}

// La card: foto, poi le righe di cui sopra. Il titolo del passaggio del mouse usa il NOME COMPLETO
// per i retro (_retroNomeCompleto, la stessa regola della ricerca dalla v6.049/050): col solo nome
// due card diverse potevano avere la stessa identica etichetta.
// v6.081 (Franco) - La regola sta QUI e in nessun altro posto: la riga della serie serve solo se
// l'elenco ne contiene piu' d'una. Con una sola serie quella riga e' costante su tutte le card,
// cioe' non distingue niente - e nel carosello di una scheda serie ripete pure il titolo della
// pagina che la contiene. Si guarda l'elenco gia' filtrato, non il contesto, perche' e' l'elenco
// a saperlo: chi lo ha costruito puo' cambiare idea sui filtri senza che questa riga se ne accorga.
function _caroselloMostraSerie(elenco) {
  return new Set((elenco || []).map(f => f.seriesId)).size > 1;
}

function _caroselloCard(f, nomeSerie, altezzaFoto, larghezza, mostraSerie) {
  const etichetta = ((f.section || '') === 'retros')
    ? _retroNomeCompleto(f)
    : (f.number ? f.number + ' ' : '') + (f.name || '');
  // v6.080 - alt 'auto' vuol dire "niente altezza fissa": serve alle righe che possono essere una o
  // tre (il nome spezzato parola per parola su telefono). Le altre continuano ad avere la loro
  // misura, che e' cio' che tiene allineate le card fra loro sul desktop.
  const righe = _caroselloRighe(f, nomeSerie, mostraSerie).map((r, i) =>
    '<div style="font-size:' + r.dim + ';color:' + r.col + ';line-height:1.25;' + (r.alt === 'auto' ? '' : 'height:' + r.alt + ';overflow:hidden;') +
      (i === 0 ? 'margin-top:0.4rem;' : '') +
      (r.alt === '1.2em' ? 'white-space:nowrap;text-overflow:ellipsis;' : '') +
      (r.dx ? 'text-align:' + r.dx + ';' : '') +
    '">' + (r.t || '&nbsp;') + '</div>'
  ).join('');
  return '<div onclick="_caroselloApri(\'' + f.id + '\',\'' + f.seriesId + '\')" ' +
    'title="' + esc(etichetta) + '" ' +
    'style="flex:0 0 auto;width:' + larghezza + ';scroll-snap-align:start;cursor:pointer;background:var(--card2);border:1px solid var(--border);border-radius:var(--radius);padding:0.5rem;">' +
    // v6.080 - altezzaFoto 0 vuol dire "quadrata rispetto alla card" (telefono): niente altezza
    // fissa sotto una card stretta, che e' cio' che allungava il box in verticale.
    '<img src="' + cloudinaryUrl(f.img, 'w_400,h_400,c_fit,q_auto,f_auto') + '" loading="lazy" alt="" ' +
      'style="width:100%;' + (altezzaFoto ? 'height:' + altezzaFoto + 'px;' : 'aspect-ratio:1;height:auto;') + 'object-fit:contain;border-radius:6px;background:var(--card);">' +
    righe +
  '</div>';
}

// v6.072 (Franco) - il clic su una card. Da NON loggato la scheda non si apre: si dice perche' e si
// offre la porta d'ingresso. Prima si apriva comunque, e per un visitatore era un vicolo cieco -
// vedeva una scheda che il sito, per il resto, non gli lascia raggiungere.
// Il controllo sta QUI e non nei due caroselli: e' una regola sola, e la card e' gia' una sola.
function _caroselloApri(figId, seriesId) {
  if (!currentUser) {
    toast(currentLang === 'it'
      ? 'Accedi per vedere la scheda della figurina'
      : 'Sign in to open the sticker details', 'error');
    try { openAuth('login'); } catch(e) { console.error('openAuth', e); }
    return;
  }
  openFigFromSearch(figId, seriesId, 'figurines');
}

// Accende il movimento automatico di una fila. `vivo()` dice se ha ancora senso scorrere: se
// risponde di no il timer si spegne da solo, cosi' non ne restano in giro quando si cambia pagina.
function _caroselloAvviaBox(box, quale, vivo) {
  _caroselloSpegni(quale);
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return; // "riduci animazioni"
  const t = setInterval(() => {
    if (document.hidden) return;          // scheda del browser in secondo piano
    if (!vivo()) { _caroselloSpegni(quale); return; }
    _caroselloScorriBox(box, 1);
  }, _caroselloPasso());
  _caroselloTimers[quale] = t;
}
function _caroselloSpegni(quale) {
  if (_caroselloTimers[quale]) { clearInterval(_caroselloTimers[quale]); _caroselloTimers[quale] = null; }
}
function _caroselloStop() { _caroselloSpegni('home'); }

// ---- CAROSELLO DELLA HOME (v6.051) ------------------------------------------------------------
// Vetrina di figurine A CASO, fuori dal blocco riservato a chi ha fatto login: serve soprattutto a
// chi arriva senza account. Miniature e caricamento pigro perche' la home la scarica anche lui.
function renderCarosello() {
  const sez = document.getElementById('home-carosello-sez');
  const box = document.getElementById('home-carosello');
  if (!sez || !box) return;
  _caroselloSpegni('home');
  const disponibili = getData('figurines', []).filter(f => (f.section || 'figurines') === 'figurines' && f.img);
  if (disponibili.length < 2) { sez.style.display = 'none'; box.innerHTML = ''; return; }
  // si mescola una COPIA: ordinare a caso l'elenco vero cambierebbe l'ordine in tutto il sito
  const mazzo = disponibili.slice();
  for (let i = mazzo.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [mazzo[i], mazzo[j]] = [mazzo[j], mazzo[i]];
  }
  const nomeSerie = new Map(getData('series', []).map(x => [x.id, _nomeSerieCard(x)])); // v6.080
  const inFila = mazzo.slice(0, CAROSELLO_MAX); // v6.081 - la serie si guarda sulle card che finiscono davvero in fila
  const mostraSerie = _caroselloMostraSerie(inFila);
  box.innerHTML = inFila.map(f => _caroselloCard(f, nomeSerie, _caroselloAltezzaFoto(175), _caroselloLarghezzaHome(), mostraSerie)).join('');
  sez.style.display = '';
  const prec = document.getElementById('carosello-prec');
  const succ = document.getElementById('carosello-succ');
  if (prec) prec.onclick = () => _caroselloScorriBox(box, -1);
  if (succ) succ.onclick = () => _caroselloScorriBox(box, 1);
  const vivo = () => { const h = document.getElementById('page-home'); return !!h && h.classList.contains('active'); };
  box.onmouseenter = () => _caroselloSpegni('home');
  box.onmouseleave = () => _caroselloAvviaBox(box, 'home', vivo);
  _caroselloAvviaBox(box, 'home', vivo);
}

// ---- CAROSELLO DELLA SCHEDA SERIE (v6.071, Franco) --------------------------------------------
// Prende il posto della descrizione nell'HUB (la vista coi cinque box), e solo li'. Mostra le
// figurine BASE di quella serie IN ORDINE DI NUMERO: qui non si cerca varieta' come nella home, si
// cerca la serie com'e' fatta, e l'ordine numerico e' l'ordine in cui uno se la ricorda.
// Foto un po' piu' piccole (150 invece di 175) e piu' schede in fila: e' un elenco da scorrere, non
// una vetrina da guardare.
function renderCaroselloSerie() {
  const sez = document.getElementById('serie-carosello-sez');
  const box = document.getElementById('serie-carosello');
  if (!sez || !box) return;
  _caroselloSpegni('serie');
  const base = getData('figurines', [])
    .filter(f => f.seriesId === currentSeriesId && (f.section || 'figurines') === 'figurines'
      && !f.isVariation && !f.isUnofficialVariation && !f.isChange && !f.isPrintError && f.img)
    .sort((a, b) => (a.number || 0) - (b.number || 0));
  if (base.length < 2) { sez.style.display = 'none'; box.innerHTML = ''; return; }
  const nomeSerie = new Map(getData('series', []).map(x => [x.id, _nomeSerieCard(x)])); // v6.080
  // v6.081 - qui il filtro e' f.seriesId === currentSeriesId, quindi vale sempre false. Si calcola
  // lo stesso invece di scrivere `false`: se un giorno questo carosello mostrasse anche altro, la
  // riga della serie ricomparirebbe da sola.
  const mostraSerie = _caroselloMostraSerie(base);
  box.innerHTML = base.map(f => _caroselloCard(f, nomeSerie, _caroselloAltezzaFoto(150), _caroselloLarghezzaSerie(), mostraSerie)).join('');
  sez.style.display = '';
  const prec = document.getElementById('serie-carosello-prec');
  const succ = document.getElementById('serie-carosello-succ');
  if (prec) prec.onclick = () => _caroselloScorriBox(box, -1);
  if (succ) succ.onclick = () => _caroselloScorriBox(box, 1);
  // vivo finche' si e' nell'hub: entrando in una sezione il carosello sparisce e il timer con lui
  const vivo = () => !currentSection && document.getElementById('series-detail')?.style.display !== 'none';
  box.onmouseenter = () => _caroselloSpegni('serie');
  box.onmouseleave = () => _caroselloAvviaBox(box, 'serie', vivo);
  _caroselloAvviaBox(box, 'serie', vivo);
}

// ---- CAROSELLO DELL'HUB DI UN PRODOTTO (v6.073, Franco) ---------------------------------------
// Tutti gli oggetti di quel tipo, di TUTTE le serie, in ordine CASUALE. Il caso e' una scelta di
// Franco e ha un motivo: qui non esiste un ordine naturale da rispettare — nell'hub di una serie
// c'e' il numero di figurina, i retro un numero non ce l'hanno — e mescolare fa vedere ogni volta
// un pezzo diverso di un elenco lungo.
// SOLO GLI OGGETTI BASE, la stessa regola del carosello di serie. Non e' un dettaglio: coi campi
// che la card mostra, un Change e la sua base sono INDISTINGUIBILI, perche' Nome, Categoria e
// Sottocategoria il figlio li eredita dalla base (§13.1). Misurato sui retro: con tutti sarebbero
// 175 etichette identiche su 415 card delle 531; con i soli base sono 282 card e zero doppioni.
function renderCaroselloProdotto() {
  const sez = document.getElementById('prodotto-carosello-sez');
  const box = document.getElementById('prodotto-carosello');
  if (!sez || !box) return;
  _caroselloSpegni('prodotto');
  const base = getData('figurines', [])
    .filter(f => (f.section || 'figurines') === _prodottoCorrente
      && !f.isVariation && !f.isUnofficialVariation && !f.isChange && !f.isPrintError && f.img);
  if (base.length < 2) { sez.style.display = 'none'; box.innerHTML = ''; return; }
  const serie = getData('series', []);
  const nomeSerie = new Map(serie.map(x => [x.id, _nomeSerieCard(x)])); // v6.080 - terzo carosello
  // Si lavora sempre su una COPIA: riordinare l'elenco vero cambierebbe l'ordine in tutto il sito.
  const mazzo = base.slice();
  // v6.073 (Franco) — l'ordine dipende dal prodotto, e non e' un capriccio: le BUSTINE sono
  // poche e hanno un ordine naturale (la serie, e dentro la serie il nome), quindi mescolarle non
  // mostrerebbe varieta', mostrerebbe disordine. Gli altri sono elenchi lunghi — 282 retro, 1542
  // figurine — dove il caso fa vedere ogni volta un pezzo diverso di una cosa che non si guarda
  // mai tutta. La regola sta qui, in un punto solo, e si allunga aggiungendo una riga alla mappa.
  const ORDINE = {
    bustine: (a, b) => {
      const oa = serie.find(s => s.id === a.seriesId)?.order ?? 9999;
      const ob = serie.find(s => s.id === b.seriesId)?.order ?? 9999;
      return oa !== ob ? oa - ob : (a.name || '').localeCompare(b.name || '', 'it');
    }
  };
  if (ORDINE[_prodottoCorrente]) {
    mazzo.sort(ORDINE[_prodottoCorrente]);
  } else {
    for (let i = mazzo.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [mazzo[i], mazzo[j]] = [mazzo[j], mazzo[i]];
    }
  }
  const mostraSerie = _caroselloMostraSerie(mazzo); // v6.081 - qui le serie sono di solito piu' d'una, ma non per forza
  box.innerHTML = mazzo.map(f => _caroselloCard(f, nomeSerie, _caroselloAltezzaFoto(150), _caroselloLarghezzaSerie(), mostraSerie)).join('');
  sez.style.display = '';
  const prec = document.getElementById('prodotto-carosello-prec');
  const succ = document.getElementById('prodotto-carosello-succ');
  if (prec) prec.onclick = () => _caroselloScorriBox(box, -1);
  if (succ) succ.onclick = () => _caroselloScorriBox(box, 1);
  // vivo finche' l'hub del prodotto e' a schermo: uscendo, il timer si spegne da solo
  const vivo = () => document.getElementById('prodotto-detail')?.style.display === 'block';
  box.onmouseenter = () => _caroselloSpegni('prodotto');
  box.onmouseleave = () => _caroselloAvviaBox(box, 'prodotto', vivo);
  _caroselloAvviaBox(box, 'prodotto', vivo);
}

function showPage(page) {
  const protectedPages = ['catalog', 'blog', 'classifica', 'wantlist', 'profile', 'newsletter', 'wishlist', 'unsubscribe'];
  if (protectedPages.includes(page) && !currentUser) {
    openAuth('login');
    return;
  }
  // Traccia la pagina da cui si arriva, per poter tornare indietro dal profilo
  // (es. pulsante "← Torna a Inventario") invece di andare sempre alla Home
  const currentActiveEl = document.querySelector('.page.active');
  if (currentActiveEl && currentActiveEl.id !== 'page-' + page) {
    _previousPage = currentActiveEl.id.replace('page-', '');
  }
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('series-detail').style.display = 'none';
  // v6.073 - anche l'hub di un prodotto: non e' una .page, quindi il giro qui sopra non lo tocca
  const _pd = document.getElementById('prodotto-detail');
  if (_pd) _pd.style.display = 'none';
  _caroselloSpegni('prodotto');
  _prodottoCorrente = null;
  _sezioneApertaDaProdotto = null;
  const el = document.getElementById('page-' + page);
  if (el) { el.classList.add('active'); }
  document.querySelectorAll('.nav-links a').forEach(a => {
    a.classList.toggle('active', a.dataset.page === page);
  });
  try { _aggiornaLogoNavbar(); } catch(e) { console.error('_aggiornaLogoNavbar', e); }
  window.scrollTo({ top: 0, behavior: 'smooth' });
  // v6.051 - il carosello si ridisegna (quindi ripesca a caso) entrando nella home, e si ferma
  // uscendone: un timer lasciato acceso e' il modo in cui questi caroselli iniziano ad accelerare.
  if (page === 'home') { try { renderCarosello(); } catch(e) { console.error('renderCarosello', e); } }
  else _caroselloStop();
  if (page === 'catalog') renderCatalog();
  if (page === 'blog') renderBlog();
  if (page === 'profile') {
    const pc = document.getElementById('profile-content');
    if (pc) pc.style.display = '';
    const ap = document.getElementById('admin-panel');
    if (ap) ap.style.display = currentUser?.isAdmin ? 'block' : 'none';
    renderProfile();
  }
  if (page === 'home') { renderHomeStats(); renderHomeSeries(); }
  if (page === 'wantlist') renderWantlist();
  if (page === 'newsletter') { renderNewsletterUsers(); renderEmailLog(); }
  if (page === 'wishlist') renderWishlist();
  if (page === 'unsubscribe') renderUnsubscribePage();
  if (page === 'classifica') renderClassifica();
  if (page === 'admin') adminTab('users');
  if (page === 'contact' && currentUser) {
    const emailInput = document.getElementById('contact-email');
    if (emailInput && !emailInput.value) emailInput.value = currentUser.email;
  }
  initReveal();
}

// ============================================================
//  AUTH
// ============================================================
// openAuth moved to top
async function _findUserByAuthUid(uid) {
  // Prima controlla la cache locale (es. per l'admin, che ha l'intera collezione già in cache)
  const cached = getData('users', []).find(x => x.authUid === uid);
  if (cached) return cached;
  // Query mirata: con le regole di sicurezza attive, un utente può leggere solo
  // il documento il cui campo authUid corrisponde al proprio uid autenticato
  try {
    const { collection, query, where, getDocs } = window._fb;
    const q = query(collection(db, 'users'), where('authUid', '==', uid));
    const snap = await getDocs(q);
    if (snap.empty) return null;
    const docSnap = snap.docs[0];
    const user = { ...docSnap.data(), id: docSnap.id };
    // Aggiorna la cache solo se era già una lista realmente popolata (es. per
    // l'admin). Altrimenti NON creiamo qui una lista con un solo utente: 
    // verrebbe scambiata per l'elenco completo (è successo, ed è un bug
    // fastidioso da scovare). Chi ha bisogno della lista completa la carica
    // esplicitamente con _loadAdminOnlyData().
    if (Array.isArray(_cache.users)) {
      const idx = _cache.users.findIndex(x => x.id === user.id);
      if (idx >= 0) _cache.users[idx] = user; else _cache.users.push(user);
    }
    return user;
  } catch(e) {
    console.error('_findUserByAuthUid query failed', e);
    return null;
  }
}

// Rilegge da Firestore i dati che il pannello admin mostra, e ridisegna.
// SERVIVA: il sito non ha NESSUN ascoltatore in tempo reale (onSnapshot: zero). I
// dati dell'admin si leggono UNA VOLTA SOLA, all'accesso, e poi restano fermi in
// cache. Non e' che "ci mettono un po'" a comparire, come sembrava a Franco: non
// comparivano affatto, finche' non si ricaricava la pagina.
// Rilegge SOLO le quattro raccolte del pannello (users, contact_messages,
// segnalazioni, eventi) tramite _loadAdminOnlyData, che esisteva gia'. Non tocca
// figurine, serie, owned: sono migliaia di documenti, e Franco ha gia' sbattuto
// contro la quota giornaliera di Firestore.
async function refreshAdminData() {
  if (!currentUser?.isAdmin) return;
  const btn = document.getElementById('admin-refresh-btn');
  const info = document.getElementById('admin-refresh-info');
  // il doppio clic raddoppierebbe le letture: il pulsante si spegne mentre lavora
  if (btn?.disabled) return;
  if (btn) btn.disabled = true;
  if (info) info.textContent = currentLang === 'it' ? 'Lettura in corso...' : 'Loading...';
  try {
    await _loadAdminOnlyData();
    // ridisegno tutto cio' che dipende da quelle quattro raccolte
    try { renderAdminUsers(); } catch(e) { console.error('renderAdminUsers', e); }
    try { renderAdminContacts(); } catch(e) {}
    try { renderAdminSegnalazioni(); } catch(e) {}
    try { renderAdminEventi(); } catch(e) {}
    // i badge veri: updateAdminBadges() NON esiste — me l'ero inventata.
    try { updateMsgBadge(); } catch(e) {}
    try { updateBellBadge(); } catch(e) {}
    try { updateWishlistBadge(); } catch(e) {}
    const ora = new Date().toLocaleTimeString(currentLang === 'it' ? 'it-IT' : 'en-US');
    if (info) info.textContent = (currentLang === 'it' ? 'Aggiornato alle ' : 'Updated at ') + ora;
  } catch(e) {
    console.error('refreshAdminData', e);
    // un errore silenzioso qui sarebbe il peggio: l'admin crederebbe di vedere dati
    // freschi mentre guarda quelli vecchi. Stessa lezione della v5.682.
    if (info) info.textContent = currentLang === 'it'
      ? '⚠️ Aggiornamento NON riuscito: stai vedendo i dati di prima.'
      : '⚠️ Refresh FAILED: you are seeing the previous data.';
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function _loadAdminOnlyData() {
  // Dati riservati all'admin, da ricaricare esplicitamente ogni volta che un
  // admin effettua il login dal modulo (non solo al caricamento iniziale
  // della pagina, gestito da loadAllData). In parallelo, non in sequenza,
  // per non sommare i tempi di rete di quattro richieste una dopo l'altra.
  const [users, contactMessages, segnalazioni, eventi] = await Promise.all([
    fsGetAll('users'),
    fsGetAll('contact_messages'),
    fsGetAll('segnalazioni'),
    fsGetAll('eventi')
  ]);
  _cache.users = users;
  _cache.contact_messages = contactMessages;
  _cache.segnalazioni = segnalazioni;
  _cache.eventi = eventi;
  updateMsgBadge();

  // Manutenzione: cancella i messaggi dei non registrati oltre i 6 mesi. Gira qui
  // perche' e' l'unico momento disponibile — il sito e' statico e non ha un
  // processo notturno. Non e' atteso (niente await): se fosse lento non deve
  // rallentare l'apertura del pannello.
  purgeOldContactMessages();
  purgeOldEventi();
  purgeOldSegnalazioni();
}

async function doLogin() {
  const emailInput = document.getElementById('login-email').value.trim();
  const p = document.getElementById('login-password').value;
  const authErr = document.getElementById('auth-error');
  if (authErr) authErr.style.display = 'none';
  const showErr = (msg) => { const ae = document.getElementById('auth-error'); if (ae) { ae.style.display = ''; ae.textContent = msg; } else toast(msg, 'error'); };
  if (!emailInput || !p) { showErr(currentLang === 'it' ? 'Inserisci e-mail e password' : 'Enter e-mail and password'); return; }

  const { signInWithEmailAndPassword } = window._fbAuth;
  let cred;
  try {
    cred = await signInWithEmailAndPassword(fbAuth, emailInput, p);
  } catch(err) {
    console.error('Firebase Auth login', err);
    const networkCodes = ['auth/network-request-failed', 'auth/timeout', 'auth/too-many-requests'];
    if (networkCodes.includes(err.code)) {
      showErr(currentLang === 'it'
        ? '⏳ Connessione lenta o instabile: il login non è riuscito a completarsi in tempo. Non è un problema di password — riprova.'
        : '⏳ Slow or unstable connection: login didn\u2019t complete in time. This is not a password issue — please retry.');
    } else {
      showErr(currentLang === 'it' ? 'E-mail o password errati' : 'Wrong e-mail or password');
    }
    return;
  }

  const user = await _findUserByAuthUid(cred.user.uid);
  if (!user) {
    console.error('Login riuscito su Firebase Auth ma nessun profilo trovato per authUid', cred.user.uid);
    showErr(currentLang === 'it' ? 'Accesso riuscito ma profilo non trovato: contatta l\'amministratore' : 'Signed in but no profile found: please contact the administrator');
    return;
  }

  user.lastLogin = new Date().toISOString();
  currentUser = user;
  LOCAL.set('currentUser', user);
  // Al login la Nazionalità reimposta la lingua, ma solo se: (a) l'utente non ha
  // scelto esplicitamente una lingua cliccando la bandierina, e (b) una
  // nazionalità c'è davvero. Se è vuota si tiene la lingua in uso — prima veniva
  // trattata come "non italiano" e forzava l'inglese.
  if (!LOCAL.get('lang_set_by_user_' + user.id) && user.nationalityCode) {
    setLang(user.nationalityCode === 'it' ? 'it' : 'en');
    applyI18n();
  }
  fsSave('users', user); // lastLogin: non blocca il login, non serve attenderlo
  if (!user.isAdmin) logEvent('login', 'Login effettuato da: ' + bold(user.username), { read: true, authUid: user.authUid || null });
  else await _loadAdminOnlyData();
  await loadAllOwnedFromFirebase();
  closeModal('auth-modal');
  updateNavUser();
  loadWishlist();
  const welcomeEl = document.getElementById('hero-welcome-msg');
  if (welcomeEl) {
    welcomeEl.style.display = '';
    welcomeEl.textContent = (currentLang === 'it' ? 'Bentornato, ' : 'Welcome back, ') + user.username + '! 👾';
    setTimeout(() => { welcomeEl.style.display = 'none'; }, 4000);
  }
  // Chi era arrivato dal link di disiscrizione e ha dovuto accedere viene portato
  // dove voleva andare, invece di essere scaricato sulla Home.
  if (resumePendingUnsubscribe()) return;
  maybeAskNewsletterConsent(); // utenti pre-v5.597: consenso mai chiesto
}
function _generateUniqueUsername(base) {
  const profiles = getData('public_profiles', []);
  let clean = (base || 'collezionista').replace(/[^a-zA-Z0-9_]/g, '').slice(0, 20) || 'collezionista';
  let candidate = clean;
  let n = 1;
  while (profiles.find(x => x.username === candidate)) {
    n++;
    candidate = clean + n;
  }
  return candidate;
}

async function signInWithGoogle() {
  if (!fbAuth || !window._fbAuth) { toast(currentLang === 'it' ? 'Connessione a Firebase in corso, riprova tra poco' : 'Connecting to Firebase, please retry shortly', 'error'); return; }
  const { GoogleAuthProvider, signInWithPopup } = window._fbAuth;
  let cred;
  try {
    cred = await signInWithPopup(fbAuth, new GoogleAuthProvider());
  } catch(err) {
    console.error('signInWithGoogle', err);
    if (err.code === 'auth/popup-closed-by-user' || err.code === 'auth/cancelled-popup-request') return; // l'utente ha chiuso il popup, nessun errore da mostrare
    toast(currentLang === 'it' ? 'Accesso con Google non riuscito, riprova' : 'Google sign-in failed, please retry', 'error');
    return;
  }

  let user = await _findUserByAuthUid(cred.user.uid);

  let isNewUser = false;
  if (user) {
    // Utente già esistente: procedo come un login
    user.lastLogin = new Date().toISOString();
  } else {
    isNewUser = true;
    // Stesso requisito del form di registrazione: conferma di avere
    // almeno 16 anni, obbligatoria anche per chi si registra con Google
    const ageConfirmed = confirm(currentLang === 'it'
      ? 'Per registrarti devi confermare di avere almeno 16 anni. Confermi?'
      : 'To register you must confirm you are at least 16 years old. Do you confirm?');
    if (!ageConfirmed) {
      try { const { fbDeleteAuthUser } = window._fbAuth; await fbDeleteAuthUser(cred.user); } catch(e) { console.warn('cleanup unconfirmed google account failed', e.message); }
      toast(currentLang === 'it' ? 'Registrazione annullata' : 'Registration cancelled', 'error');
      return;
    }
    // Primo accesso con questo account Google: creo un nuovo utente
    const baseName = cred.user.displayName || (cred.user.email || '').split('@')[0];
    const username = _generateUniqueUsername(baseName);
    // nationalityCode è sempre vuoto (Google non la fornisce): la lingua è quindi
    // quella che la persona sta usando in questo momento sul sito.
    const newUser = { id: Date.now().toString(), authUid: cred.user.uid, username, email: cred.user.email || '', isAdmin: false, joined: new Date().toISOString(), lastLogin: new Date().toISOString(), nationalityCode: '', nationalityName: '', ageConfirmed16: true, ageConfirmedAt: new Date().toISOString(), lang: currentLang };
    const saved = await fsSave('users', newUser);
    _cache.users = _cache.users || [];
    _cache.users.push(saved);
    user = saved;
    sendWelcomeEmail(saved);
    logEvent('new_user', 'Nuovo utente registrato con Google: ' + bold(username), { authUid: newUser.authUid || null });
  }

  currentUser = user;
  LOCAL.set('currentUser', user);
  // Stessa regola del login e-mail/password. Nota: un nuovo utente Google ha
  // sempre nationalityCode vuoto (Google non la fornisce), quindi non subisce
  // mai un cambio di lingua alla registrazione — prima invece finiva sempre in
  // inglese, qualunque lingua stesse usando.
  if (!LOCAL.get('lang_set_by_user_' + user.id) && user.nationalityCode) {
    setLang(user.nationalityCode === 'it' ? 'it' : 'en');
    applyI18n();
  }
  if (!isNewUser) fsSave('users', user); // lastLogin: non blocca, non serve attenderlo (per un nuovo utente è già stato salvato sopra)
  if (!isNewUser && !user.isAdmin) logEvent('login', 'Login effettuato da: ' + bold(user.username), { read: true, authUid: user.authUid || null });
  if (!isNewUser && user.isAdmin) await _loadAdminOnlyData();
  await loadAllOwnedFromFirebase();
  closeModal('auth-modal');
  updateNavUser();
  loadWishlist();
  const welcomeEl = document.getElementById('hero-welcome-msg');
  if (welcomeEl) {
    welcomeEl.style.display = '';
    welcomeEl.textContent = (currentLang === 'it' ? 'Bentornato, ' : 'Welcome back, ') + user.username + '! 👾';
    setTimeout(() => { welcomeEl.style.display = 'none'; }, 4000);
  }
  // Nuovo utente Google: chiediamo esplicitamente se vuole personalizzare il nome utente
  // (generato automaticamente da nome e cognome dell'account Google) — molti non
  // scoprirebbero mai da soli che è possibile cambiarlo dal profilo
  if (isNewUser) {
    // Il consenso newsletter non è chiesto qui: il nuovo utente Google non passa
    // dal form di registrazione, quindi il campo resta undefined e il prompt gli
    // viene mostrato subito dopo il modal del nome utente (vedi saveNewUsername).
    // Se chiude quel modal senza salvare, lo vedrà al prossimo accesso: in nessun
    // caso il consenso viene dato per scontato.
    openUsernameModal(true);
  } else {
    if (resumePendingUnsubscribe()) return;
    maybeAskNewsletterConsent();
  }
}

async function doRegister() {
  const u = document.getElementById('reg-username').value.trim();
  const e = document.getElementById('reg-email').value.trim();
  const p = document.getElementById('reg-password').value;
  const regErr = document.getElementById('reg-error');
  if (regErr) regErr.style.display = 'none';
  if (!u || !e || !p) { if (regErr) { regErr.style.display = ''; regErr.textContent = 'Compila tutti i campi'; return; } toast((currentLang === 'it' ? 'Compila tutti i campi' : 'Please fill in all fields'), 'error'); return; }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) { if (regErr) { regErr.style.display = ''; regErr.textContent = 'Inserisci un indirizzo e-mail valido'; return; } toast('Inserisci un indirizzo e-mail valido', 'error'); return; }
  if (p.length < 6) { const re = document.getElementById('reg-error'); if (re) { re.style.display = ''; re.textContent = 'La password deve avere almeno 6 caratteri'; return; } toast('La password deve avere almeno 6 caratteri', 'error'); return; }
  const ageConfirmed = document.getElementById('reg-age-confirm')?.checked;
  if (!ageConfirmed) {
    const msg = currentLang === 'it' ? 'Devi confermare di avere almeno 16 anni per registrarti' : 'You must confirm you are at least 16 years old to register';
    if (regErr) { regErr.style.display = ''; regErr.textContent = msg; } else toast(msg, 'error');
    return;
  }
  // Consenso newsletter: la risposta è obbligatoria (tendina a tre valori, di
  // default "— Seleziona —"), ma il "No" è una risposta perfettamente valida e
  // non impedisce la registrazione. Blocchiamo solo chi non ha risposto affatto.
  const nlChoice = document.getElementById('reg-newsletter-consent')?.value || '';
  if (!nlChoice) {
    const msg = currentLang === 'it'
      ? 'Scegli se vuoi ricevere la newsletter — puoi tranquillamente rispondere "No", la registrazione funziona lo stesso'
      : 'Please choose whether you want the newsletter — you can safely answer "No", registration works anyway';
    if (regErr) { regErr.style.display = ''; regErr.textContent = msg; } else toast(msg, 'error');
    return;
  }
  let profiles = getData('public_profiles', []);
  if (profiles.find(x => x.username === u)) { const msg = currentLang === 'it' ? 'Nome utente già in uso' : 'Username already taken'; const re = document.getElementById('reg-error'); if (re) { re.style.display = ''; re.textContent = msg; return; } toast(msg, 'error'); return; }
  const natCode = document.getElementById('reg-nationality-code')?.value || '';
  const natName = document.getElementById('reg-nationality-name')?.value || '';
  let authUid = null;
  const submitBtn = document.getElementById('reg-submit-btn');
  const waitNotice = document.getElementById('reg-wait-notice');
  if (submitBtn) submitBtn.disabled = true;
  if (waitNotice) waitNotice.style.display = '';
  try {
    const { createUserWithEmailAndPassword } = window._fbAuth;
    const cred = await createUserWithEmailAndPassword(fbAuth, e, p);
    authUid = cred.user.uid;
  } catch(err) {
    console.error('Firebase Auth registration', err);
    let msg = currentLang === 'it' ? 'Registrazione non riuscita, riprova' : 'Registration failed, please retry';
    if (err.code === 'auth/email-already-in-use') msg = currentLang === 'it' ? 'Questa email è già registrata' : 'This email is already registered';
    else if (err.code === 'auth/weak-password') msg = currentLang === 'it' ? 'Password troppo debole (minimo 6 caratteri)' : 'Password too weak (minimum 6 characters)';
    if (regErr) { regErr.style.display = ''; regErr.textContent = msg; } else toast(msg, 'error');
    if (submitBtn) submitBtn.disabled = false;
    if (waitNotice) waitNotice.style.display = 'none';
    return;
  }
  // La scelta è già stata validata sopra: qui è certamente 'yes' o 'no', mai
  // vuota. Registriamo comunque data e origine anche per il "no" — è un rifiuto
  // esplicito e consapevole, e va conservato come tale (non resta undefined,
  // quindi a costui il prompt una-tantum non verrà mai riproposto).
  const nlConsent = (nlChoice === 'yes');
  // Lingua da salvare sull'utente (serve per scrivergli nella SUA lingua, es. il
  // piè di pagina della newsletter). Va calcolata QUI, non presa da currentLang:
  // qualche riga più sotto la Nazionalità, se scelta, sovrascrive la lingua della
  // form (v5.599). Salvare currentLang prima di quell'override memorizzerebbe una
  // lingua che fra un istante non sarà più quella dell'utente.
  const finalLang = natCode ? (natCode === 'it' ? 'it' : 'en') : currentLang;
  const newUser = { id: Date.now().toString(), authUid, username: u, email: e, isAdmin: false, joined: new Date().toISOString(), lastLogin: new Date().toISOString(), nationalityCode: natCode, nationalityName: natName, ageConfirmed16: true, ageConfirmedAt: new Date().toISOString(), lang: finalLang, newsletterConsent: nlConsent, newsletterConsentDate: new Date().toISOString(), newsletterConsentSource: 'registration' };
  const saved = await fsSave('users', newUser);
  _cache.users = _cache.users || [];
  _cache.users.push(saved);
  currentUser = saved;
  LOCAL.set('currentUser', saved);
  if (submitBtn) submitBtn.disabled = false;
  if (waitNotice) waitNotice.style.display = 'none';
  closeModal('auth-modal');
  updateNavUser();
  sendWelcomeEmail(saved);
  const welcomeEl2 = document.getElementById('hero-welcome-msg');
  if (welcomeEl2) {
    welcomeEl2.style.display = '';
    welcomeEl2.textContent = (currentLang === 'it' ? 'Benvenuto nella famiglia Sgorbions, ' : 'Welcome to the Sgorbions family, ') + u + '! 🎉';
    setTimeout(() => { welcomeEl2.style.display = 'none'; }, 4000);
  }
  // Lingua: la Nazionalità, se scelta, vince sulla lingua della form — quella
  // può essere il frutto di un rilevamento automatico (navigator.language),
  // cioè di un'azione non voluta; la nazionalità è invece un gesto deliberato.
  // Ma se la Nazionalità NON è stata scelta non c'è nessun gesto deliberato da
  // far vincere: si tiene la lingua in uso. Prima invece il campo vuoto veniva
  // trattato come "non italiano" e forzava l'inglese — era questo il baco.
  if (finalLang !== currentLang) {
    setLang(finalLang);
    applyI18n();
  }
  logEvent('new_user', 'Nuovo utente registrato: ' + bold(u), { authUid: authUid || null });
}

// ============================================================
//  CHANGE PASSWORD
// ============================================================
function openDemoToggleModal() {
  // v5.956 — la figurina d'esempio (Gastone Bubbone, n. 1 della "Serie 1") NON e' scritta a mano
  // nell'HTML: si cerca nei dati, cosi' se la foto in Inventario cambia cambia anche qui e le due
  // non possono divergere. La serie si cerca per NOME perche' l'id non e' stabile fra ambienti.
  // Si prende la figurina base: senza escludere variazioni e Change, un contrassegno sulla n. 1
  // porterebbe in guida una foto che non e' quella attesa. Se non si trova nulla — dati non
  // ancora caricati, serie rinominata — resta l'emoji dell'HTML, che e' meglio di un riquadro rotto.
  const box = document.getElementById('demo-toggle-img');
  if (box) {
    const serie = getData('series', []).find(s => (s.name || '').trim().toLowerCase() === 'serie 1');
    const fig = serie ? getData('figurines', []).find(f => f.seriesId === serie.id
        && Number(f.number) === 1
        && (f.section || 'figurines') === 'figurines'
        && !f.isVariation && !f.isUnofficialVariation && !f.isChange) : null;
    if (fig && fig.img) {
      box.innerHTML = '<img src="' + cloudinaryUrl(fig.img, 'w_180,h_180,c_fit,q_auto,f_auto') +
                      '" alt="" style="width:100%;height:100%;object-fit:contain;">';
      const nm = document.getElementById('demo-toggle-name');
      const sb = document.getElementById('demo-toggle-sub');
      if (nm && fig.name) nm.textContent = fig.name;
      if (sb) sb.textContent = (serie.name || 'Serie 1') + ' — N. ' + (fig.number != null ? fig.number : 1);
    }
  }
  // Reset demo toggle state
  const btn = document.getElementById('demo-toggle-btn');
  if (btn) {
    btn.classList.remove('on');
    btn._on = false;
    const label = document.getElementById('demo-toggle-label');
    if (label) label.style.color = 'var(--muted)';
  }
  document.getElementById('demo-toggle-modal').classList.remove('hidden');
}

function toggleDemoBtn() {
  const btn = document.getElementById('demo-toggle-btn');
  const label = document.getElementById('demo-toggle-label');
  if (!btn) return;
  btn._on = !btn._on;
  btn.classList.toggle('on', btn._on);
  if (label) label.style.color = btn._on ? 'var(--info)' : 'var(--muted)';
}

function openChangePwdModal() {
  // Seconda guardia: il pulsante e' gia' disabilitato durante l'impersonificazione
  // (renderProfile), ma un pulsante grigiato e' un'indicazione, non una garanzia —
  // la funzione resta richiamabile per altre vie. E qui l'errore sarebbe grave:
  // si cambierebbe la password DELL'ADMIN credendo di cambiare quella dell'utente.
  if (isImpersonating()) {
    toast(currentLang === 'it'
      ? "Non disponibile durante l'impersonificazione: cambieresti la password dell'admin."
      : "Not available while impersonating: you would change the admin's password.", 'error');
    return;
  }
  document.getElementById('change-pwd-current').value = '';
  document.getElementById('change-pwd-new').value = '';
  document.getElementById('change-pwd-confirm').value = '';
  const fb = document.getElementById('change-pwd-feedback');
  fb.style.display = 'none';
  document.getElementById('change-pwd-modal').classList.remove('hidden');
}

// ============================================================
//  AUTOCANCELLAZIONE ACCOUNT (diritto all'oblio, GDPR art. 17)
// ============================================================
function openDeleteAccountModal() {
  if (!currentUser) return;
  if (currentUser.isAdmin || isImpersonating()) return; // mai per l'admin, né durante l'impersonificazione
  const pwdGroup = document.getElementById('delete-account-password-group');
  const confirmBtn = document.getElementById('delete-account-confirm-btn');
  const googleBtn = document.getElementById('delete-account-google-btn');
  const errEl = document.getElementById('delete-account-error');
  const pwdInput = document.getElementById('delete-account-password');
  if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }
  if (pwdInput) pwdInput.value = '';

  const provider = fbAuth?.currentUser?.providerData?.[0]?.providerId;
  if (provider === 'google.com') {
    if (pwdGroup) pwdGroup.style.display = 'none';
    if (confirmBtn) confirmBtn.style.display = 'none';
    if (googleBtn) googleBtn.style.display = '';
  } else {
    if (pwdGroup) pwdGroup.style.display = '';
    if (confirmBtn) confirmBtn.style.display = '';
    if (googleBtn) googleBtn.style.display = 'none';
  }
  document.getElementById('delete-account-modal').classList.remove('hidden');
}

async function confirmDeleteAccount() {
  const pwd = document.getElementById('delete-account-password').value;
  const errEl = document.getElementById('delete-account-error');
  const showErr = (msg) => { if (errEl) { errEl.style.display = ''; errEl.textContent = msg; } };
  if (!pwd) { showErr('Inserisci la tua password.'); return; }

  const { EmailAuthProvider, reauthenticateWithCredential } = window._fbAuth;
  const fbUser = fbAuth.currentUser;
  try {
    const cred = EmailAuthProvider.credential(currentUser.email, pwd);
    await reauthenticateWithCredential(fbUser, cred);
  } catch(e) {
    console.error('reauthenticate error', e);
    showErr(currentLang === 'it' ? 'Password non corretta, riprova.' : 'Wrong password, please retry.');
    return;
  }
  await _performAccountDeletion(fbUser);
}

async function confirmDeleteAccountGoogle() {
  const { GoogleAuthProvider, reauthenticateWithPopup } = window._fbAuth;
  const fbUser = fbAuth.currentUser;
  const errEl = document.getElementById('delete-account-error');
  try {
    await reauthenticateWithPopup(fbUser, new GoogleAuthProvider());
  } catch(e) {
    console.error('reauthenticate google error', e);
    if (errEl) { errEl.style.display = ''; errEl.textContent = currentLang === 'it' ? 'Verifica Google non riuscita, riprova.' : 'Google verification failed, please retry.'; }
    return;
  }
  await _performAccountDeletion(fbUser);
}

// L'autore di un post/commento, tradotto al momento della visualizzazione:
// riconosce sia "Utente eliminato" sia "Deleted user" (qualunque sia stata
// salvata al momento della cancellazione dell'account) e mostra sempre il
// testo giusto per la lingua CORRENTE, invece di restare fissa nella
// lingua di quel momento passato
function displayAuthorName(name) {
  if (name === 'Utente eliminato' || name === 'Deleted user') {
    return currentLang === 'it' ? 'Utente eliminato' : 'Deleted user';
  }
  return name;
}

// ============================================================
//  CANCELLAZIONE ACCOUNT — le tracce nelle tre raccolte residue
// ------------------------------------------------------------
//  Fino alla v5.636 l'auto-eliminazione cancellava users, public_profiles, owned
//  e wishlists, e anonimizzava i post. Lasciava indietro TRE raccolte, in cui
//  restavano l'indirizzo e-mail dell'utente e le parole che aveva scritto:
//    - contact_messages : e-mail + testo dei messaggi inviati
//    - email_log        : e-mail + IL CORPO di ogni e-mail ricevuta da noi
//    - segnalazioni     : nome utente + commento
//  Chi premeva "Elimina il mio account" pensava di essere sparito. Non lo era.
//  E l'informativa, dalla v5.633, gli promette in apertura che puo' cancellare
//  tutto "da solo, con un pulsante": la promessa va mantenuta dal codice, non
//  ammorbidita nel testo.
//
//  SI CANCELLA, NON SI ANONIMIZZA — decisione di Franco, ed e' la piu' solida:
//  svuotare il solo identificativo lascerebbe il TESTO, e nel testo la gente si
//  firma. Un record con l'e-mail cancellata ma il messaggio intatto resta un
//  dato personale, con in piu' l'illusione di essere a posto.
//
//  ATTENZIONE — RICHIEDE UN AGGIORNAMENTO DELLE REGOLE FIRESTORE. Chi cancella
//  il proprio account NON e' l'admin: senza una regola che gli consenta di
//  cancellare le PROPRIE righe, queste chiamate verrebbero rifiutate e
//  fallirebbero in silenzio. Le regole necessarie sono nel file
//  firestore_rules_v5637.txt consegnato insieme a questa versione.
//  Gli errori qui NON interrompono la cancellazione dell'account: se una
//  raccolta non fosse raggiungibile, l'account viene comunque eliminato e
//  l'errore finisce in console. Meglio un residuo segnalato che un utente
//  bloccato a meta' strada, con l'account a pezzi.
// ============================================================
// L'utente BERSAGLIO va passato per intero: la funzione NON deve dedurlo da
// currentUser. Serve infatti anche all'admin che cancella un ALTRO utente, e in
// quel caso currentUser e' l'admin — cercare le segnalazioni con il SUO authUid
// non solo mancherebbe il bersaglio, ma rischierebbe di cancellare le proprie.
async function _deleteUserTraces(user) {
  if (!user) return;
  const { collection: col, query: qf, where: wf, getDocs: gd } = window._fb;
  const mail = (user.email || '').trim();
  const auid = user.authUid;
  const esiti = [];

  // 1. Messaggi dal form Contatti (interrogati per indirizzo, come loadMyContactMessages)
  if (mail) {
    try {
      const snap = await gd(qf(col(db, 'contact_messages'), wf('email', '==', mail)));
      const ids = snap.docs.map(d => d.id);
      for (const id of ids) await fsDelete('contact_messages', id);
      // La CACHE va ripulita, non solo Firestore. Se la si lascia sporca, il
      // pannello continua a mostrare i messaggi di un utente che non esiste piu':
      // il dato e' a posto, ma l'admin vede una bugia — e conclude, comprensibil-
      // mente, che la cancellazione non abbia funzionato.
      if (_cache.contact_messages) {
        _cache.contact_messages = _cache.contact_messages.filter(m => !ids.includes(m.id));
      }
      esiti.push(`contact_messages: ${ids.length}`);
    } catch(e) { console.warn('[cancellazione] contact_messages', e.message); esiti.push('contact_messages: ERRORE'); }
  }

  // 2. Registro e-mail — comprende il CORPO delle e-mail ricevute
  if (mail) {
    try {
      const snap = await gd(qf(col(db, 'email_log'), wf('to', '==', mail)));
      for (const d of snap.docs) await fsDelete('email_log', d.id);
      // email_log non ha cache: le tabelle lo rileggono da Firestore a ogni
      // disegno. E' per questo che, prima di questa correzione, le e-mail
      // sparivano subito dal pannello e messaggi e segnalazioni no.
      esiti.push(`email_log: ${snap.docs.length}`);
    } catch(e) { console.warn('[cancellazione] email_log', e.message); esiti.push('email_log: ERRORE'); }
  }

  // 3. Segnalazioni — cancellate per intero, commento compreso (scelta di Franco).
  // Si interroga per authUid e NON per userId: le regole Firestore confrontano
  // request.auth.uid con un campo del documento, quindi una query su userId
  // verrebbe rifiutata (l'utente non ha il permesso di leggere righe altrui, e
  // Firestore non puo' saperlo in anticipo se il filtro non e' quello giusto).
  // Le segnalazioni si cercano per authUid, perche' le regole Firestore ancorano
  // l'identita' a quello. Ma authUid esiste solo dalla v5.637 in poi: le
  // segnalazioni piu' vecchie ne sono prive, e una ricerca per authUid non le
  // trova — restano li' con dentro nome utente e commento.
  //
  // Fino alla v5.656 questo caso veniva saltato IN SILENZIO: niente errore,
  // niente riga nel riepilogo. L'admin leggeva "contact_messages: 1 · email_log: 1"
  // e non si accorgeva che delle segnalazioni non si era proprio parlato.
  //
  // Se chi cancella e' l'ADMIN, c'e' una seconda strada: le regole gli danno
  // lettura e cancellazione su TUTTE le segnalazioni, quindi puo' cercarle anche
  // per userId (l'id applicativo), che c'e' sempre stato. L'utente che cancella
  // se stesso non puo' farlo — le regole non glielo consentono — ma per lui il
  // problema non si pone: le sue segnalazioni recenti hanno tutte authUid.
  {
    const trovati = new Map(); // id -> doc, per non cancellare due volte lo stesso
    let errore = false;

    if (auid) {
      try {
        const snap = await gd(qf(col(db, 'segnalazioni'), wf('authUid', '==', auid)));
        snap.docs.forEach(d => trovati.set(d.id, true));
      } catch(e) { console.warn('[cancellazione] segnalazioni (authUid)', e.message); errore = true; }
    }

    // Ripiego per le segnalazioni vecchie, praticabile solo dall'admin.
    if (currentUser?.isAdmin && user.id) {
      try {
        const snap2 = await gd(qf(col(db, 'segnalazioni'), wf('userId', '==', String(user.id))));
        const nuove = snap2.docs.filter(d => !trovati.has(d.id)).length;
        snap2.docs.forEach(d => trovati.set(d.id, true));
        if (nuove) console.log(`[cancellazione] ${nuove} segnalazioni senza authUid recuperate per userId (create prima della v5.637)`);
      } catch(e) { console.warn('[cancellazione] segnalazioni (userId)', e.message); errore = true; }
    }

    if (!auid && !currentUser?.isAdmin) {
      // Caso che prima spariva senza dire nulla.
      console.warn('[cancellazione] segnalazioni NON verificate: utente senza authUid');
      esiti.push('segnalazioni: NON VERIFICATE');
    } else {
      const ids = [...trovati.keys()];
      for (const id of ids) {
        try { await fsDelete('segnalazioni', id); }
        catch(e) { console.warn('[cancellazione] segnalazione', id, e.message); errore = true; }
      }
      if (_cache.segnalazioni) {
        _cache.segnalazioni = _cache.segnalazioni.filter(x => !trovati.has(x.id));
      }
      esiti.push(errore ? 'segnalazioni: ERRORE' : `segnalazioni: ${ids.length}`);
    }
  }

  console.log('[cancellazione account] tracce rimosse →', esiti.join(' · '));
}

async function _anonymizeUserContent(userId) {
  // Post e commenti restano visibili (valore per gli altri lettori del
  // blog), ma con il nome sostituito: non è più possibile risalire a chi
  // li ha scritti una volta cancellato l'account
  const anonName = currentLang === 'it' ? 'Utente eliminato' : 'Deleted user';
  const posts = getData('posts', []);
  for (const post of posts) {
    let changed = false;
    if (post.authorId === userId) { post.author = anonName; changed = true; }
    if (post.comments && post.comments.length) {
      for (const c of post.comments) {
        if (c.authorId === userId) { c.author = anonName; changed = true; }
      }
    }
    if (changed) {
      try { await fsSave('posts', post); } catch(e) { console.warn('anonymize post failed', e.message); }
    }
  }
}

async function _performAccountDeletion(fbUser) {
  const { fbDeleteAuthUser } = window._fbAuth;
  const userId = currentUser.id;
  try {
    // L'anonimizzazione va fatta PRIMA di cancellare l'account: le regole
    // di sicurezza richiedono di essere ancora autenticati per modificare
    // i post del blog
    await _anonymizeUserContent(userId);
    // Le tracce vanno rimosse PRIMA di cancellare il documento utente: alcune
    // regole Firestore verificano l'identita' del richiedente contro i suoi dati,
    // e senza il documento utente il permesso potrebbe non essere piu' concedibile.
    await _deleteUserTraces(currentUser);

    // Evento registrato PRIMA di cancellare il documento utente: dopo, il nome
    // utente non esisterebbe piu' e resterebbe solo un id.
    // Il nome c'e' (richiesta di Franco): senza, l'evento direbbe che "qualcuno"
    // se n'e' andato, che non serve a nulla.
    // L'indirizzo e-mail invece NO: e' la persona che ci ha appena chiesto di
    // essere dimenticata, e ricopiarle l'indirizzo in un altro registro sarebbe
    // il contrario di quello che ha chiesto.
    logEvent('account_deleted', "L'utente " + bold(currentUser.username) + " ha eliminato il proprio account");

    await fsDelete('users', userId);
    try { await fsDelete('public_profiles', userId); } catch(e) { console.warn('delete public_profiles', e.message); }
    try { await fsDelete('owned', userId); } catch(e) { console.warn('delete owned', e.message); }
    try { await fsDelete('wishlists', userId); } catch(e) { console.warn('delete wishlists', e.message); }

    // Cancella l'account Firebase Authentication vero e proprio — possibile
    // solo perché l'utente lo sta facendo su se stesso, appena riautenticato
    await fbDeleteAuthUser(fbUser);
  } catch(e) {
    console.error('_performAccountDeletion error', e);
    const errEl = document.getElementById('delete-account-error');
    if (errEl) { errEl.style.display = ''; errEl.textContent = (currentLang === 'it' ? 'Errore durante la cancellazione: ' : 'Error during deletion: ') + e.message; }
    return;
  }

  closeModal('delete-account-modal');
  currentUser = null;
  LOCAL.set('currentUser', null);
  updateNavUser();
  showPage('home');
  document.getElementById('account-deleted-modal')?.classList.remove('hidden');
}

async function doChangePassword() {
  const current = document.getElementById('change-pwd-current').value;
  const newPwd = document.getElementById('change-pwd-new').value;
  const confirm = document.getElementById('change-pwd-confirm').value;
  const fb = document.getElementById('change-pwd-feedback');

  const showError = (msg) => {
    fb.style.cssText = 'display:block;background:rgba(var(--danger-rgb),0.1);border:1px solid rgba(var(--danger-rgb),0.3);color:var(--danger);padding:0.6rem 1rem;border-radius:8px;font-size:0.88rem;';
    fb.textContent = msg;
  };

  if (fbAuth?.currentUser?.providerData?.[0]?.providerId === 'google.com') {
    showError(currentLang === 'it' ? 'Hai fatto accesso con Google: la password si gestisce direttamente dal tuo account Google, non da qui.' : 'You signed in with Google: manage your password directly from your Google account, not here.');
    return;
  }

  if (!current || !newPwd || !confirm) { showError('Compila tutti i campi.'); return; }
  if (newPwd.length < 6) { showError('La nuova password deve essere di almeno 6 caratteri.'); return; }
  if (newPwd !== confirm) { showError('Le due password non corrispondono.'); return; }

  const { EmailAuthProvider, reauthenticateWithCredential, updatePassword } = window._fbAuth;
  const fbUser = fbAuth.currentUser;
  try {
    const cred = EmailAuthProvider.credential(currentUser.email, current);
    await reauthenticateWithCredential(fbUser, cred);
  } catch(e) {
    console.error('reauthenticate error', e);
    showError('La password attuale non è corretta.');
    return;
  }
  try {
    await updatePassword(fbUser, newPwd);
  } catch(e) {
    console.error('updatePassword error', e);
    showError('Errore durante l\u2019aggiornamento: ' + e.message);
    return;
  }

  currentUser.mustChangePassword = false;
  LOCAL.set('currentUser', currentUser);
  await fsSave('users', currentUser);

  fb.style.cssText = 'display:block;background:rgba(181,255,46,0.1);border:1px solid rgba(181,255,46,0.2);color:var(--accent);padding:0.6rem 1rem;border-radius:8px;font-size:0.88rem;';
  fb.textContent = '✅ Password aggiornata con successo!';
  setTimeout(() => closeModal('change-pwd-modal'), 1500);
}

// ============================================================
//  RESET PASSWORD
// ============================================================
function openResetModal() {
  closeModal('auth-modal');
  const loginEmail = document.getElementById('login-email')?.value.trim() || '';
  document.getElementById('reset-email-input').value = loginEmail;
  const fb = document.getElementById('reset-pwd-feedback');
  fb.style.display = 'none';
  document.getElementById('reset-pwd-modal').classList.remove('hidden');
}


// Conta le richieste di reset password, mese per mese — stesso schema del
// contatore e-mail EmailJS. È un conteggio NOSTRO, non quello reale di
// Firebase Auth (che non è consultabile dal sito), ma è affidabile perché
// ogni richiesta passa comunque dal nostro codice
// Registra nel log e-mail (quello di "E-mail inviate") il fatto che
// abbiamo chiesto a Firebase Auth di mandare un'e-mail di reset password
// — non possiamo vederne il contenuto (lo manda Firebase, non noi), ma
// tracciamo comunque che la richiesta è stata fatta. A differenza di
// logEmail(), niente lettura di pulizia: la richiesta può arrivare anche
// da un utente non loggato (dal form di login), che non ha i permessi
// per leggere l'intera collezione email_log
async function logPwdResetEmail(toEmail) {
  try {
    await fsSave('email_log', {
      to: toEmail,
      subject: currentLang === 'it' ? 'Reimposta la tua password' : 'Reset your password',
      source: 'pwdreset',
      body: '',
      status: 'sent',
      date: new Date().toISOString()
    });
  } catch(e) { console.error('logPwdResetEmail error', e); }
}

async function incrementPwdResetCounter() {
  try {
    const now = new Date();
    const monthKey = now.getFullYear() + '-' + String(now.getMonth()+1).padStart(2,'0');
    const { doc, setDoc, increment } = window._fb;
    const ref = doc(db, 'pwd_reset_stats', 'counter');
    // Incremento atomico: non serve leggere prima il valore attuale (cosa
    // che falliva per gli utenti non admin, dato che la lettura di questa
    // collezione è riservata all'admin — causava un azzeramento apparente
    // del contatore ad ogni richiesta da un utente non admin)
    await setDoc(ref, { total: increment(1), months: { [monthKey]: increment(1) } }, { merge: true });
  } catch(e) { console.error('Pwd reset counter error', e); }
}

async function refreshPwdResetCountWidget() {
  const el = document.getElementById('pwd-reset-count-display');
  if (!el) return;
  try {
    const now = new Date();
    const monthKey = now.getFullYear() + '-' + String(now.getMonth()+1).padStart(2,'0');
    const { doc, getDoc } = window._fb;
    const ref = doc(db, 'pwd_reset_stats', 'counter');
    let count = 0;
    try {
      const snap = await getDoc(ref);
      if (snap.exists()) { const data = snap.data(); count = (data.months && data.months[monthKey]) || 0; }
    } catch(e) {}
    el.textContent = count;
  } catch(e) { console.error('Pwd reset widget error', e); }
}

async function doResetPassword() {
  const email = document.getElementById('reset-email-input').value.trim();
  const fb = document.getElementById('reset-pwd-feedback');
  const btn = document.querySelector('#reset-pwd-modal .btn-primary');

  if (!email) { 
    fb.style.cssText = 'display:block;background:rgba(var(--danger-rgb),0.1);border:1px solid rgba(var(--danger-rgb),0.3);color:var(--danger);padding:0.6rem 1rem;border-radius:8px;font-size:0.88rem;';
    fb.textContent = currentLang === 'it' ? 'Inserisci il tuo indirizzo e-mail.' : 'Enter your e-mail address.';
    return; 
  }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    fb.style.cssText = 'display:block;background:rgba(var(--danger-rgb),0.1);border:1px solid rgba(var(--danger-rgb),0.3);color:var(--danger);padding:0.6rem 1rem;border-radius:8px;font-size:0.88rem;';
    fb.textContent = currentLang === 'it' ? 'Inserisci un indirizzo e-mail valido.' : 'Enter a valid e-mail address.';
    return;
  }

  // Sempre lo stesso messaggio, indipendentemente dal fatto che l'indirizzo sia
  // registrato o meno (non riveliamo l'esistenza di un account a chi non è autenticato)
  fb.style.cssText = 'display:block;background:rgba(var(--info-rgb),0.1);border:1px solid rgba(var(--info-rgb),0.3);color:var(--info);padding:0.6rem 1rem;border-radius:8px;font-size:0.88rem;';
  fb.innerHTML = currentLang === 'it'
    ? 'Attendi la e-mail contenente il link per resettare la password.<br><br>ATTENZIONE! Controlla la cartella Spam/Posta indesiderata.<br><br>Se proprio non arriva, scrivici da <a href="#" onclick="closeModal(\'reset-pwd-modal\');showPage(\'contact\');return false;" style="color:var(--info);text-decoration:underline;">Contatti</a> per chiedere un reset manuale.'
    : 'Wait for the e-mail with the link to reset your password.<br><br>ATTENTION! Check your Spam/Junk folder.<br><br>If it really doesn\'t arrive, write to us from <a href="#" onclick="closeModal(\'reset-pwd-modal\');showPage(\'contact\');return false;" style="color:var(--info);text-decoration:underline;">Contacts</a> to request a manual reset.';
  if (btn) btn.disabled = true;

  // Un evento per ogni richiesta (non sappiamo se poi viene davvero
  // completata, ma è comunque un segnale utile: qualcuno ha perso la
  // password — o dice di averla persa)
  logEvent('reset_pwd', (currentLang === 'it' ? 'Richiesto reset password per: ' : 'Password reset requested for: ') + bold(email));

  try {
    const { sendPasswordResetEmail } = window._fbAuth;
    await sendPasswordResetEmail(fbAuth, email);
    incrementPwdResetCounter();
    logPwdResetEmail(email);
  } catch(err) {
    // Non mostriamo l'errore all'utente per non rivelare se l'indirizzo esiste (es. auth/user-not-found)
    console.warn('sendPasswordResetEmail', err.code || err.message);
  }

  setTimeout(() => {
    if (btn) btn.disabled = false;
  }, 3000);
}

async function logout() {
  // Chiude davvero la sessione Firebase Auth: senza questo, il controllo di
  // sessione introdotto in v5.311 troverebbe ancora una sessione valida al
  // prossimo caricamento e rimetterebbe l'utente loggato "da solo"
  try {
    const { signOut } = window._fbAuth || {};
    if (fbAuth && signOut) await signOut(fbAuth);
  } catch(e) { console.error('signOut error', e); }

  currentUser = null;
  LOCAL.set('currentUser', null);
  updateNavUser();
  updateOwnedCounter();
  showPage('home');
  const welcomeEl = document.getElementById('hero-welcome-msg');
  if (welcomeEl) {
    welcomeEl.style.display = '';
    welcomeEl.textContent = currentLang === 'it' ? 'Arrivederci! A presto 👋' : 'Logged out. See you soon! 👋';
    setTimeout(() => { welcomeEl.style.display = 'none'; }, 4000);
  }
}
function updateNavUser() {
  const guestNav = document.getElementById('guest-nav');
  const userNav = document.getElementById('user-nav');
  const addSeriesBtn = document.getElementById('admin-add-series-btn');
  const wantlistLink = document.getElementById('nav-wantlist');
  const btnCollect = document.getElementById('btn-start-collecting');
  if (currentUser) {
    guestNav.style.display = 'none';
    userNav.style.display = 'flex';
    if (wantlistLink) wantlistLink.style.display = '';
    ['nav-catalog','nav-blog','nav-classifica','nav-mialista-link','nav-logout-link'].forEach(id => { const el = document.getElementById(id); if (el) el.style.display = ''; });
    const navBlogEl = document.getElementById('nav-blog');
    if (navBlogEl) navBlogEl.textContent = currentUser.isAdmin ? 'Blog' : t('nav.blog');
    const nwl = document.getElementById('nav-wishlist'); if (nwl) nwl.style.display = currentUser.isAdmin ? 'none' : '';
    const nlBtn = document.getElementById('nav-newsletter-btn');
    if (nlBtn) nlBtn.style.display = currentUser.isAdmin ? '' : 'none';
    if (btnCollect) btnCollect.style.display = 'none';
    const homeContent = document.getElementById('home-logged-in-content');
    if (homeContent) homeContent.style.display = '';
    mostraNumeroniHero(true);   // v5.935 — due colonne, una per lato dell'immagine
    if (document.getElementById('btn-explore-catalog')) document.getElementById('btn-explore-catalog').style.display = '';
    document.getElementById('nav-username').textContent = currentUser.username + (currentUser.isAdmin ? ' 👑' : '');
    const bellBtn = document.getElementById('nav-bell-btn');
    const msgBtn = document.getElementById('nav-msg-btn');
    if (msgBtn) msgBtn.style.display = currentUser?.isAdmin ? '' : 'none';
    const replyBtn = document.getElementById('nav-reply-btn');
    if (replyBtn) replyBtn.style.display = currentUser?.isAdmin ? 'none' : '';
    if (bellBtn) {
      bellBtn.style.display = currentUser.isAdmin ? '' : 'none';
      updateBellBadge();
    }
    if (!currentUser.isAdmin) checkUnreadReplies();
    _checkReadQuotaWarning();
    const jsVerWrap = document.getElementById('nav-js-version-wrap');
    if (jsVerWrap) jsVerWrap.style.display = currentUser.isAdmin ? '' : 'none';
    const navAvatar = document.getElementById('nav-avatar');
    // Always reset first
    navAvatar.style.backgroundImage = '';
    navAvatar.style.backgroundSize = '';
    navAvatar.style.backgroundPosition = '';
    navAvatar.textContent = '';
    if (currentUser.avatar) {
      navAvatar.style.backgroundImage = 'url(' + currentUser.avatar + ')';
      navAvatar.style.backgroundSize = 'cover';
      navAvatar.style.backgroundPosition = 'center';
    } else {
      navAvatar.textContent = currentUser.username[0].toUpperCase();
    }
    if (addSeriesBtn) addSeriesBtn.style.display = currentUser.isAdmin ? '' : 'none';
  } else {
    guestNav.style.display = 'flex';
    userNav.style.display = 'none';
    if (addSeriesBtn) addSeriesBtn.style.display = 'none';
    if (wantlistLink) wantlistLink.style.display = 'none';
    const nlBtn2 = document.getElementById('nav-newsletter-btn');
    if (nlBtn2) nlBtn2.style.display = 'none';
    if (btnCollect) btnCollect.style.display = '';
    const homeContent2 = document.getElementById('home-logged-in-content');
    if (homeContent2) homeContent2.style.display = 'none';
    const bellBtn2 = document.getElementById('nav-bell-btn');
    if (bellBtn2) bellBtn2.style.display = 'none';
    const quotaBtn2 = document.getElementById('nav-quota-warning-btn');
    if (quotaBtn2) quotaBtn2.style.display = 'none';
    ['nav-catalog','nav-blog','nav-classifica','nav-wishlist','nav-mialista-link','nav-logout-link'].forEach(id => { const el = document.getElementById(id); if (el) el.style.display = 'none'; });
    mostraNumeroniHero(false);
    if (document.getElementById('btn-explore-catalog')) document.getElementById('btn-explore-catalog').style.display = 'none';
  }
  // v6.079 - il pallino delle segnalazioni si decide qui, dove si decide tutto il resto della
  // navbar: da non loggato o da utente normale la funzione lo spegne da sola.
  try { aggiornaPallinoErrori(); } catch(e) { console.error('aggiornaPallinoErrori', e); }
}
