// ============================================================
//  SERIES
// ============================================================
// Calcola e mostra i conteggi automatici (var. ufficiali/non ufficiali/Change)
// contando le figurine della serie con i relativi flag a true.
function updateSeriesVariationCounts(seriesId) {
  const figs = seriesId ? getData('figurines', []).filter(f => f.seriesId === seriesId) : [];
  // Ogni conteggio dichiara la SEZIONE in cui il suo tipo vive. Prima nessuno lo
  // faceva: si contava su tutta la serie, mescolando Figurine, Retro, Album e
  // Altri oggetti. Funzionava per caso — ogni contrassegno vive di fatto nella
  // sua sezione — ma bastava che una figurina finisse marcata isChange per errore
  // e sarebbe stata conteggiata li' dentro senza che nessuno se ne accorgesse.
  // Le CHANGE sono varianti del RETRO, non del fronte: nascono con
  // section:'retros' e il selettore Change esiste solo nella sezione Retro.
  // E' l'equivoco in cui e' caduto Franco, leggendo "146 Change" in una serie che
  // di Change (fra le figurine) non ne ha nessuna. Aveva ragione a fidarsi
  // dell'etichetta: era l'etichetta a tacere.
  // "N. di Figurine" era l'UNICO dei quattro contatori scritto a mano dall'admin, e
  // per questo l'unico che poteva mentire: bastava importare figurine e scordarsi
  // di aggiornarlo. Ora e' calcolato come gli altri tre — e con la STESSA
  // definizione del filtro "Solo figurine set base" e del badge 📦 della pagina
  // serie: nessun contrassegno fra Variazione, Variazione non ufficiale e Change.
  // Tre punti, una sola definizione: non possono piu' divergere.
  const c = _conteggiSerie(figs);
  const elBase = document.getElementById('series-count-input');
  const elVar = document.getElementById('series-count-variations-input');
  const elUnoff = document.getElementById('series-count-unofficial-variations-input');
  const elChg = document.getElementById('series-count-change-input');
  const elChgRetro = document.getElementById('series-count-retro-change-input');   // v6.170
  if (elBase) elBase.value = c.base;
  if (elVar) elVar.value = c.variazioni;
  if (elUnoff) elUnoff.value = c.nonUfficiali;
  if (elChg) elChg.value = c.changeFigurine;
  if (elChgRetro) elChgRetro.value = c.changeRetro;
  const elErr = document.getElementById('series-count-print-error-input');   // v6.219
  if (elErr) elErr.value = c.erroriStampa;
  const elOma = document.getElementById('series-count-free-version-input');           // v6.248
  if (elOma) elOma.value = c.omaggiFigurine;
  const elOmaR = document.getElementById('series-count-retro-free-version-input');    // v6.248
  if (elOmaR) elOmaR.value = c.omaggiRetro;
}

// ============================================================
// v6.170 (Franco) — I CINQUE CONTEGGI DI UNA SERIE, IN UN POSTO SOLO.
// ------------------------------------------------------------
// Li leggono DUE punti: la scheda della serie (`updateSeriesVariationCounts`) e la tabella admin
// (`renderAdminSeries`). Estratti invece che ricopiati, per la stessa ragione della v6.143: due
// copie della stessa regola divergono al primo ritocco, e il commento che stava qui sopra prima
// diceva gia' "Tre punti, una sola definizione: non possono piu' divergere". Aggiungere un terzo
// lettore ricopiando avrebbe smentito quella frase nella release che la cita.
//
// ⚠️ CHANGE DI FIGURINA E CHANGE DI RETRO SONO DUE CONTEGGI, NON UNO. Misurato il 15 agosto:
//   Serie 1 -> 0 di figurina, 144 di retro     (per questo la scheda scriveva "N. Change = 0")
//   Serie 2 -> 1 di figurina, 51 di retro
//   Serie 3 -> 115 di figurina, 107 di retro
// Un contatore solo filtrato sulle figurine non mentiva: rispondeva a una domanda diversa da
// quella che l'etichetta faceva credere. E' l'equivoco dei "146 Change" gia' annotato qui sopra.
//
// ⚠️ LA SEZIONE MANCANTE VALE 'figurines', come ovunque nel resto del file (vedi
// `openSeriesEbayModal`, che usa gia' `(f.section || 'figurines')`). Fino alla v6.169 QUESTA
// funzione usava il confronto secco `f.section === 'figurines'`, quindi un record senza `section`
// restava fuori da tutti e quattro i conteggi. Se in preview i numeri della scheda risultano
// diversi da prima, e' questo: vuol dire che dei record senza `section` esistono, e che finora
// erano invisibili ai contatori. Va guardato, non dato per scontato in nessuna delle due
// direzioni.
// ============================================================
function _conteggiSerie(items) {
  const sez = f => (f.section || 'figurines');
  const fig = f => sez(f) === 'figurines';
  return {
    // 🔴 v6.170 - GLI ERRORI DI STAMPA MANCAVANO DALL'ESCLUSIONE, e il conto era gonfio.
    // Trovato da Franco: la tabella diceva 336 per Serie 3, la ricerca col selettore "set base" ne
    // dice 256, e Serie 3 ha 79 errori di stampa fra le figurine.
    // Il commento di `updateSeriesVariationCounts` dichiarava "la STESSA definizione del filtro
    // «Solo figurine set base»" — ed era FALSO: quel filtro esclude QUATTRO contrassegni
    // (`_itemTypeFilter === 'base'`), il contatore ne escludeva tre. Le due definizioni erano
    // divergenti almeno dalla v5.711, quando `isPrintError` ha smesso di essere un sottotipo di
    // Change ed e' diventato un tipo a se': chi aveva scritto i tre non aveva un quarto da
    // escludere, e nessuno e' tornato a riguardarlo.
    // ⚠️ La lezione non e' "mancava un flag": e' che il commento AFFERMAVA l'equivalenza invece di
    // ottenerla. Ora la ottiene, usando `_eBase` — la definizione canonica, gia' letta da quattro
    // punti. Un'equivalenza dichiarata a parole non regge a una release; una condivisa si'.
    base:           items.filter(f => fig(f) && _eBase(f)).length,
    variazioni:     items.filter(f => fig(f) && f.isVariation).length,
    nonUfficiali:   items.filter(f => fig(f) && f.isUnofficialVariation).length,
    changeFigurine: items.filter(f => fig(f) && f.isChange).length,
    changeRetro:    items.filter(f => sez(f) === 'retros' && f.isChange).length,
    // v6.211 (Franco) - i RETRO della serie. ⚠️ Sono i retro BASE, cioe' `_eBase`: senza change
    // ne' errori di stampa. Contarli TUTTI avrebbe fatto un numero che contiene dentro di se' i
    // CHANGE RETRO gia' mostrati nella colonna accanto - due numeri di cui uno comprende l'altro,
    // sulla stessa riga, e nessuno dei due sbagliato: e' il modo piu' rapido di far dubitare di
    // entrambi. E' lo stesso criterio con cui `base` esclude variazioni e change fra le figurine.
    // \uD83D\uDCCC Non serviva ne' un campo sulla serie ne' una procedura di ricalcolo: qui i numeri si
    // calcolano dagli oggetti a ogni disegno, e da questa riga arrivano da soli in tutti i punti che
    // leggono `_conteggiSerie` - il riepilogo utenti, la tabella admin e la scheda della serie.
    retro:          items.filter(f => sez(f) === 'retros' && _eBase(f)).length,
    // 🆕 v6.219 - GLI ERRORI DI STAMPA. ⚠️ E' l'unico conteggio SENZA sezione, e non e' una
    // dimenticanza: gli altri la dichiarano perche' si sa dove vive il loro contrassegno, di
    // questo si sa solo che ce n'e' fra le figurine (79 su Serie 3, misurati nella v6.170) e non
    // e' mai stato guardato se ce ne siano fra i retro. Un filtro su `figurines` avrebbe potuto
    // scrivere "0" a una serie che ne ha - che e' parola per parola l'errore della v6.170.
    erroriStampa:   items.filter(f => f.isPrintError).length,
    // 🆕 v6.248 - GLI OMAGGI, DIVISI COME I CHANGE. La v6.235 ne faceva un conto solo, senza filtro
    // di sezione, perche' non si sapeva dove vivessero. Adesso si sa — Franco: *"nei change ci sono
    // 2 contatori... serve lo stesso per gli omaggio"* — e i due numeri si contano separati.
    // ⚠️ `omaggi` RESTA come somma dei due: e' quello che leggono la colonna HA OMAGGIO della
    // tabella admin, la colonna desktop e la riga di telefono (v6.235/240). Toglierlo avrebbe
    // svuotato tre tabelle senza dare errore — sono lettori di questo oggetto, non di quelle righe.
    omaggiFigurine: items.filter(f => fig(f) && f.isFreeVersion).length,
    omaggiRetro:    items.filter(f => sez(f) === 'retros' && f.isFreeVersion).length,
    omaggi:         items.filter(f => f.isFreeVersion).length
  };
}

function toggleSeriesCountGroups() {
  const hasVar = document.getElementById('series-has-variations-input')?.checked;
  const hasUnoff = document.getElementById('series-has-unofficial-variations-input')?.checked;
  const hasChg = document.getElementById('series-has-change-input')?.checked;
  const hasChgRetro = document.getElementById('series-has-retro-change-input')?.checked;   // v6.170
  const gVar = document.getElementById('series-count-variations-group');
  const gUnoff = document.getElementById('series-count-unofficial-variations-group');
  const gChg = document.getElementById('series-count-change-group');
  const gChgRetro = document.getElementById('series-count-retro-change-group');            // v6.170
  if (gVar) gVar.style.display = hasVar ? '' : 'none';
  if (gUnoff) gUnoff.style.display = hasUnoff ? '' : 'none';
  if (gChg) gChg.style.display = hasChg ? '' : 'none';
  if (gChgRetro) gChgRetro.style.display = hasChgRetro ? '' : 'none';
  // v6.219 - la coppia degli errori di stampa
  const hasErr = document.getElementById('series-has-print-error-input')?.checked;
  const gErr = document.getElementById('series-count-print-error-group');
  if (gErr) gErr.style.display = hasErr ? '' : 'none';
  // v6.248 - le DUE coppie degli omaggi, a specchio dei change
  const hasOma = document.getElementById('series-has-free-version-input')?.checked;
  const gOma = document.getElementById('series-count-free-version-group');
  if (gOma) gOma.style.display = hasOma ? '' : 'none';
  const hasOmaR = document.getElementById('series-has-retro-free-version-input')?.checked;
  const gOmaR = document.getElementById('series-count-retro-free-version-group');
  if (gOmaR) gOmaR.style.display = hasOmaR ? '' : 'none';
}

// Mostra, per la serie attualmente aperta, quanti oggetti di ciascuna
// tipologia (Figurine/Retro/Album/Altri oggetti) sono marcati "Ebay"
function openSeriesEbayModal() {
  const series = getData('series', []).find(s => s.id === currentSeriesId);
  if (!series) return;
  document.getElementById('series-ebay-modal-name').textContent = series.name;
  const figs = getData('figurines', []).filter(f => f.seriesId === currentSeriesId);
  // v5.919 — i contatori occupavano cinque righe a tutta larghezza per dieci numeri: ora sono un
  // riquadro compatto in alto a sinistra (Franco). Stessa informazione, un ventesimo dello spazio.
  const counters = document.getElementById('series-ebay-counters');
  counters.innerHTML = `<div style="display:inline-block;border:1px solid var(--border);border-radius:10px;padding:0.5rem 0.8rem;background:var(--card2);">
    ${EBAY_SECTIONS.map(sec => {
      const total = figs.filter(f => (f.section || 'figurines') === sec).length;
      const forSaleCount = figs.filter(f => (f.section || 'figurines') === sec && f.forSale).length;
      return `<div style="display:flex;justify-content:space-between;gap:1.2rem;font-size:0.78rem;line-height:1.5;">
        <span style="color:var(--muted);">${ebaySectionLabel(sec)}</span>
        <span style="color:var(--text);font-weight:${forSaleCount ? '700' : '400'};white-space:nowrap;">${forSaleCount} / ${total}</span>
      </div>`;
    }).join('')}
  </div>`;

  // Tabella oggetti marcati Ebay, con selettore mercato IT/COM (v5.899). La Descrizione è esclusa
  // apposta (troppo lunga per la tabella; resta nell'export).
  _ebayViewMarket = 'it'; // default a ogni apertura
  renderEbayViewTable();

  document.getElementById('series-ebay-modal').classList.remove('hidden');
}

// v5.918 — ORDINAMENTO CONDIVISO con la vista tabellare (renderBulkEditView). Estratto da lì
// perché la tabella "Titoli eccedenti la taglia ebay" deve elencare gli oggetti nello stesso
// ordine: due copie delle stesse regole sarebbero divergenti al primo ritocco.
// Regole per sezione: Retro → Categoria, Sottocategoria, Nome, Tipo di change; Figurine →
// Sottoserie, Numero (i senza numero in fondo), Nome completo; altre sezioni → Numero.
// v6.079 (Franco) - "Ordina per creazione" nella vista tabellare: dal piu' recente. Non sostituisce
// l'ordinamento normale, lo mette in pausa - si accende e si spegne, e spegnendolo la tabella torna
// esattamente com'era. Vive nella sessione e non si ricorda: e' un modo di guardare la tabella
// adesso ("cosa ho inserito oggi?"), non una preferenza.
// Gli oggetti la cui data non e' leggibile finiscono in fondo, nel loro ordine di sempre: metterli
// in cima o mescolarli direbbe qualcosa che non sappiamo.
let _ordinaPerCreazione = false;
function toggleOrdinaPerCreazione() {
  _ordinaPerCreazione = !_ordinaPerCreazione;
  renderBulkEditView();
}
function cmpPerCreazione(sezione) {
  const normale = cmpVistaTabellare(sezione);
  return (a, b) => {
    const da = _dataCreazione(a), db = _dataCreazione(b);
    if (da && db) return db - da;      // piu' recente prima
    if (da && !db) return -1;
    if (!da && db) return 1;
    return normale(a, b);              // entrambi senza data: l'ordine di sempre
  };
}

function cmpVistaTabellare(sezione) {
  // v6.155 - stesso ordinamento della griglia dentro un box di tipo: due viste degli stessi oggetti
  // che si ordinano diversamente sarebbero due verita' sulla stessa cosa.
  const _cmpTipo = _tipoProdottoCorrente ? _comparatoreTipo(_tipoProdottoCorrente) : null;
  return (a, b) => {
    if (_cmpTipo) return _cmpTipo(a, b);
    if (sezione === 'retros') {
      const catCmp = (a.category||'').localeCompare(b.category||'', 'it');
      if (catCmp !== 0) return catCmp;
      const subcatCmp = (a.subcategory||'').localeCompare(b.subcategory||'', 'it');
      if (subcatCmp !== 0) return subcatCmp;
      const nameCmp = (a.name||'').localeCompare(b.name||'', 'it');
      if (nameCmp !== 0) return nameCmp;
      return (a.changeType||'').localeCompare(b.changeType||'', 'it');
    }
    if (sezione === 'figurines') {
      const subCmp = (a.subseries||'').localeCompare(b.subseries||'', 'it');
      if (subCmp !== 0) return subCmp;
      if (!a.number && !b.number) {
        const nameCmp = (a.name||'').localeCompare(b.name||'', 'it');
        if (nameCmp !== 0) return nameCmp;
      } else if (!a.number) { return 1; }
      else if (!b.number) { return -1; }
      else {
        const numCmp = a.number - b.number;
        if (numCmp !== 0) return numCmp;
      }
      const allFigsForSort2 = getData('figurines', []);
      const fnA = a.fullName || computeFullName(a, allFigsForSort2);
      const fnB = b.fullName || computeFullName(b, allFigsForSort2);
      return fnA.localeCompare(fnB, 'it');
    }
    if (!a.number && !b.number) return (a.subseries||'').localeCompare(b.subseries||'');
    if (!a.number) return 1;
    if (!b.number) return -1;
    return a.number - b.number;
  };
}

// ============================================================
// TITOLO DELL'ANNUNCIO eBAY (v5.918)
// Schema deciso da Franco:
//     Sgorbions <Serie> <Sottoserie> #<Numero> - <Nome completo> - Gpk - Topps
// Le parti mancanti (sottoserie, numero sugli oggetti "senza numero") spariscono senza
// lasciare spazi doppi o trattini penzolanti. Il pezzo centrale è il NOME COMPLETO — quello
// che la vista tabellare mostra nella colonna "Nome Completo" — non il solo Nome: per
// variazioni, Change ed errori di stampa è lì che sta l'informazione che distingue il pezzo.
//
// eBay accetta 80 caratteri e non uno di più, quindi il titolo viene TRONCATO a 80. Non c'è
// nessuna regola automatica su cosa sacrificare (via "Topps", via il retro, ecc.): i pezzi
// troncati vanno guardati e sistemati uno per uno, ed è esattamente ciò che elenca la tabella
// "Titoli eccedenti la taglia ebay" nella Vista Ebay.
// Un eventuale titolo scritto a mano (ebayTitleIt/En) ha comunque la precedenza sul generato.
const EBAY_TITLE_MAX = 80;
// v5.919 — ordine delle sezioni nella Vista Ebay, deciso da Franco: figurine, retro, bustine,
// album, altri oggetti. Una sola definizione per contatori, tabelle e tabella dei titoli lunghi.
const EBAY_SECTIONS = ['figurines', 'retros', 'bustine', 'albums', 'extras'];
function ebaySectionLabel(sec) {
  const it = (currentLang === 'it');
  return ({ figurines: it ? 'Figurine' : 'Stickers', retros: 'Retro', bustine: it ? 'Bustine' : 'Wrappers',
            albums: it ? 'Album' : 'Albums', extras: it ? 'Altri oggetti' : 'Other items' })[sec] || sec;
}
// v5.979 — MARCATORE DELLE VERSIONI SPECIALI (Franco). Fino alla v5.978 il titolo diceva solo
// il Nome completo, e per le varianti quello NON basta: computeFullName() dà "Nome - NomeRetro"
// sia per una variazione UFFICIALE sia per una NON ufficiale, quindi nel titolo le due erano
// indistinguibili. Il marcatore lo mette la composizione, non sta nei dati: nel Nome completo la
// parola "VARIAZIONE" non compare da nessuna parte.
// 🔴 v6.234 - ERA LA TERZA CATENA, col TERZO ordine (variazione non ufficiale per prima). Il
// commento diceva *"se un dato vecchio avesse per errore due flag, meglio la risposta piu'
// precisa"*: il caso era stato immaginato e mai misurato. Ora lo misura
// `_controllaVersioniMultiple`, e l'ordine e' quello di `VERSIONI_ARTICOLO`.
// ⚠️ La stringa resta ITALIANA e maiuscola: a tradurla e' `EBAY_GLOSSARIO`, che tiene Franco. Per
// questo la Versione omaggio ha `marcatoreEbay: null` e non un valore inventato da me: finche'
// Franco non decide la parola, un omaggio esportato non porta marcatore invece di portarne uno
// sbagliato.
function ebayMarcatore(f) {
  if (!f) return '';
  const v = _versioneDiChiave(_chiaveTipo(f));
  return (v && v.marcatoreEbay) || '';
}

// v5.979 — SOTTONOMI DA NON METTERE NEL TITOLO (Franco). Alcuni oggetti hanno, dentro il Nome
// completo, un pezzo in più fra il nome e il Tipo di change / Tipo di errore di stampa:
//   RICERCATO PER FURTO CON SCASSAMENTO - CANE DOMESTICO - OMAGGIO NERO
//                                          ^^^^^^^^^^^^^^ questo
// Nel titolo eBay non ci va. È un ELENCO e non una regola per una ragione precisa: nella stringa
// composta il confine fra nome, sottonome e tipo non esiste più, e per indovinare quale trattino
// sia quello giusto bisognerebbe dedurlo. Un elenco di frasi invece è esatto e si controlla a
// occhio. Lo tiene Franco, come il glossario.
const EBAY_SOTTONOMI = [
  'SORELLINA MINORE',
  'PROFESSORESSA',
  'DOTTORE',
  'PAPÀ',
  'MICROBO UMANO',
  'COCCOLO DELLA MAESTRA',
  'DENTISTA',
  'BUGIARDO SPARABALLE',
  'NEGOZIANTE DI DOLCI',
  'PRESIDE',
  'BARBIERE (DETTO ANCHE MACELLAIO)',
  'MAMMA',
  'SORELLA MAGGIORE',
  'VICINA',
  'NETTEZZA URBANA',
  'FRATELLINO MINORE',
  'AVIDONE',
  'BULLO DELLA CLASSE',
  'INFERMIERA DELLA SCUOLA',
  'MECCANICO',
  'PROFESSORE SUPPLENTE',
  'FRATELLO MAGGIORE',
  'CANE DOMESTICO',
  'IDRAULICO',
  'FUMATORE FOLLE',
  'POSTINO',
  'BIBLIOTECARIO',
  'CRIMINALOIDE',
  'BABY-SITTER',
  'CICCIONE',
  'CUOCO DELLA MENSA SCOLASTICA',
  'POLTRONE',
  'GATTO',
  'MATTACCHIONE',
  'GUIDATORE DI AUTOBUS'
];
const _EBAY_SOTTONOMI = new Set(EBAY_SOTTONOMI.map(x => x.trim().toUpperCase()));
// Si tolgono quando SERVONO PER STARE NEGLI 80 (Franco): se il titolo ci sta anche con loro,
// restano — un'informazione in più non fa male, è lo spazio che manca.
// Il taglio è per SEGMENTO INTERO fra " - ", mai per sottostringa: così non può capitare di
// tagliare in mezzo a una parola né di colpire un pezzo che si chiama quasi come un altro.
// Se togliendoli non restasse niente, si tiene il nome com'era: un titolo senza nome sarebbe
// peggio del problema che stiamo risolvendo.
function ebayTogliSottonomi(nome) {
  if (!nome) return nome || '';
  const pezzi = String(nome).split(' - ');
  const tenuti = pezzi.filter(p => !_EBAY_SOTTONOMI.has(p.trim().toUpperCase()));
  return (tenuti.length ? tenuti : pezzi).join(' - ');
}

// v5.979 — GLOSSARIO IT→EN (Franco). Lo tiene Franco: non si traduce NULLA che non sia qui dentro.
// "CHANGE" non ha voce perché è già inglese.
const EBAY_GLOSSARIO = {
  'VARIAZIONE NON UFFICIALE': 'UNOFFICIAL VARIATION',
  'ERRORE DI STAMPA':         'PRINT ERROR',
  'VARIAZIONE':               'VARIATION',
  'SERIE':                    'SERIES'
};
// Le voci si applicano dalla PIÙ LUNGA alla più corta, e non è teoria: "VARIAZIONE NON UFFICIALE"
// contiene "VARIAZIONE", quindi sostituendo prima la corta non si otterrebbe mai
// "UNOFFICIAL VARIATION" ma sempre "VARIATION NON UFFICIALE".
const _EBAY_GLOSSARIO_ORDINATO = Object.keys(EBAY_GLOSSARIO).sort((a, b) => b.length - a.length);
// Solo PAROLE INTERE: con una voce "ORO → GOLD", sostituendo anche dentro le parole "TESORO"
// diventerebbe "TESGOLD".
// Il caso si conserva: i dati sono quasi tutti in maiuscolo, ma il nome della serie no
// ("Serie 3"), e "Sgorbions SERIES 3" stonerebbe accanto a "Sgorbions Serie 3".
function _ebayApplicaCaso(originale, tradotto) {
  if (originale === originale.toUpperCase()) return tradotto.toUpperCase();
  if (originale === originale.toLowerCase()) return tradotto.toLowerCase();
  if (originale[0] === originale[0].toUpperCase()) {
    return tradotto.charAt(0).toUpperCase() + tradotto.slice(1).toLowerCase();
  }
  return tradotto;
}
function ebayTraduci(testo) {
  if (!testo) return testo || '';
  let out = testo;
  for (const voce of _EBAY_GLOSSARIO_ORDINATO) {
    const cerca = voce.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    out = out.replace(new RegExp('\\b' + cerca + '\\b', 'gi'),
                      m => _ebayApplicaCaso(m, EBAY_GLOSSARIO[voce]));
  }
  return out;
}

// Il CORPO del titolo: l'identità del pezzo, senza la coda commerciale.
// v5.979 — ora dipende dal MERCATO. Il glossario si applica alla testa (serie, sottoserie) e al
// marcatore, MAI al Nome completo: quello è il nome dell'oggetto e non si traduce (regola di
// Franco). Il numero resta dov'era, nella testa: nel Nome completo non c'è mai.
function ebayTitleCorpo(f, mercato, tieniSottonomi) {
  if (!f) return '';
  const en = (mercato === 'com');
  const tr = x => en ? ebayTraduci(x) : (x || '');
  const serie = getData('series', []).find(s => s.id === f.seriesId);
  const testa = ['Sgorbions', tr(serie ? serie.name : ''), tr(f.subseries || ''),
                 (f.noNumber || !f.number) ? '' : ('#' + f.number)].filter(Boolean).join(' ');
  const grezzo = f.fullName || computeFullName(f, getData('figurines', [])) || f.name || '';
  const nome = tieniSottonomi ? grezzo : ebayTogliSottonomi(grezzo);
  const marc = ebayMarcatore(f);
  const centro = [nome, marc ? '(' + tr(marc) + ')' : ''].filter(Boolean).join(' ');
  return [testa, centro].filter(Boolean).join(' - ');
}
function ebayTitleFull(f, mercato) {
  const corpo = ebayTitleCorpo(f, mercato, true); // "intero" = tutto, sottonomi compresi
  return corpo ? corpo + ' - Gpk - Topps' : '';
}

// v5.929 — REGOLE DI TRONCAMENTO date da Franco. La coda "- Gpk - Topps" si sacrifica INTERA,
// mai a metà: un titolo che finisce con "- Gpk - Top" sembra un errore, non un'abbreviazione.
//   1. se per stare negli 80 servirebbe tagliare anche una sola lettera di "Topps" → via " - Topps"
//   2. se anche così non basta e servirebbe tagliare dentro "Gpk" → via anche " - Gpk"
// Quindi si prova, in ordine: titolo intero → senza Topps → senza Gpk → e solo se nemmeno il
// corpo ci sta si taglia di netto, che è l'unico caso davvero da guardare a mano.
// v5.979 — i sottonomi sono il PRIMO sacrificio, prima ancora della coda commerciale: se il
// titolo ci sta anche con loro restano, altrimenti se ne vanno e si riparte dalla scala di prima.
function ebayTitle(f, mercato) {
  const pieno = ebayTitleCorpo(f, mercato, true);
  const magro = ebayTitleCorpo(f, mercato, false);
  for (const c of [pieno + ' - Gpk - Topps',
                   magro + ' - Gpk - Topps',
                   magro + ' - Gpk',
                   magro]) {
    if (c.length <= EBAY_TITLE_MAX) return c;
  }
  return magro.slice(0, EBAY_TITLE_MAX).replace(/[\s-]+$/, '');
}
// "Eccede" ora vuol dire una cosa più precisa e più utile: nemmeno il solo corpo (senza coda)
// entra negli 80, quindi il titolo viene tagliato dentro il nome. Perdere la coda commerciale,
// invece, non è un problema da segnalare: è la regola che funziona.
// v5.979 — senza mercato risponde per ENTRAMBI: le due lingue hanno lunghezze diverse
// ("SERIES" è più lungo di "SERIE", "VARIATION" più corto di "VARIAZIONE"), e un titolo che si
// taglia solo in inglese va guardato lo stesso.
function ebayTitleEccede(f, mercato) {
  if (mercato) return ebayTitleCorpo(f, mercato, false).length > EBAY_TITLE_MAX;
  return ebayTitleCorpo(f, 'it', false).length > EBAY_TITLE_MAX
      || ebayTitleCorpo(f, 'com', false).length > EBAY_TITLE_MAX;
}
// Serve alla tabella: dire COSA è successo a questo titolo.
function ebayTitleStato(f, mercato) {
  const pieno = ebayTitleCorpo(f, mercato, true);
  const magro = ebayTitleCorpo(f, mercato, false);
  if (pieno.length + ' - Gpk - Topps'.length <= EBAY_TITLE_MAX) return 'intero';
  if (magro.length + ' - Gpk - Topps'.length <= EBAY_TITLE_MAX) return 'senzaSottonomi';
  if (magro.length + ' - Gpk'.length <= EBAY_TITLE_MAX) return 'senzaTopps';
  if (magro.length <= EBAY_TITLE_MAX) return 'senzaGpk';
  return 'tagliato';
}

// v5.979 — La forbice: si mostra quando il titolo VISIBILE è il risultato di un taglio dentro
// il nome. Perdere la coda commerciale non è un problema da segnalare (è la regola che funziona);
// perdere pezzi di nome sì. Confrontando col testo mostrato, un titolo riscritto a mano perde la
// forbice da solo, senza che nessuno debba ricordarsi di toglierla.
function ebayForbice(f, mercato, testoMostrato) {
  if (ebayTitleStato(f, mercato) !== 'tagliato') return '';
  if (testoMostrato !== ebayTitle(f, mercato)) return '';
  const it = (currentLang === 'it');
  return ` <span title="${it ? 'Tagliato dentro il nome per stare negli 80 caratteri di eBay' : 'Cut inside the name to fit eBay\'s 80 characters'}" style="color:var(--action-admin);font-weight:700;">✂</span>`;
}

// v5.899 — Vista Ebay: due tabelle (eBay.it / eBay.com) con selettore. Le colonne che cambiano tra i
// due mercati: Prezzo (€/$), Condizione (Nuovo/Usato vs Ungraded/Used), Spedizione.
// v5.918 — il Titolo non è più un segnaposto "—": è generato da ebayTitle() ed è per ora lo stesso
// sui due mercati (i nomi dei personaggi sono italiani e "Gpk - Topps" è già il richiamo che cerca
// il collezionista americano).
// v5.981 — non restano segnaposto: priceUsd ora ha il suo campo nella scheda, ed ebayShipIt/Us
// sono stati rimossi invece di completati (la spedizione sta nella business policy di eBay, non
// sull'oggetto). Al posto della colonna Spedizione c'è lo Stato di pubblicazione.
let _ebayViewMarket = 'it';
function setEbayViewMarket(m) { _ebayViewMarket = m; renderEbayViewTable(); }
// v5.920 — sezioni chiuse nella Vista Ebay (chiave = sezione). Tutte aperte all'inizio: la
// maschera deve mostrare cosa c'è, non nasconderlo; è chi legge a chiudere ciò che ha già visto.
let _ebaySectionCollapsed = {};
function toggleEbaySection(sec) {
  _ebaySectionCollapsed[sec] = !_ebaySectionCollapsed[sec];
  try { renderEbayViewTable(); } catch (e) { console.error('toggleEbaySection', e); }
}

// v5.921 (Franco) — ORDINAMENTO DELLE TABELLE della Vista Ebay. Ogni sezione ha il suo stato
// ({colonna, verso}), perché si lavora su una sezione per volta: ordinare i prezzi delle figurine
// non deve scombinare i retro. Il ciclo del clic è a TRE tempi — crescente → decrescente →
// nessun ordinamento — così si torna sempre all'ordine di partenza (quello della vista tabellare)
// senza dover indovinare come fare. La stessa meccanica vale per la tabella dei titoli eccedenti,
// tenuta a parte perché ha colonne sue (chiave '_oversize').
let _ebaySort = {}; // sezione -> { col, dir } ; assente = ordine della vista tabellare
function setEbaySort(sec, col) {
  const s = _ebaySort[sec];
  if (!s || s.col !== col) _ebaySort[sec] = { col, dir: 1 };
  else if (s.dir === 1) s.dir = -1;
  else delete _ebaySort[sec];
  try { sec === '_oversize' ? renderEbayOversizeTable() : renderEbayViewTable(); }
  catch (e) { console.error('setEbaySort', e); }
}
// Intestazione cliccabile con la freccia dello stato corrente.
function ebayTh(sec, col, label, extra) {
  const s = _ebaySort[sec];
  const freccia = (s && s.col === col) ? (s.dir === 1 ? ' ▲' : ' ▼') : '';
  const attivo = !!freccia;
  // v5.922 — due comandi nella stessa intestazione: il testo ORDINA, la × CHIUDE la colonna.
  // La × ferma la propagazione, altrimenti chiudere una colonna la ordinerebbe anche.
  // v5.923 (Franco) — la × è anche su "Nome completo": nessuna colonna è privilegiata. L'unico
  // limite che resta è l'ultima rimasta — una tabella senza colonne non è una vista, è il nulla —
  // e infatti quando ne resta una sola la × non compare.
  // v5.931 — la ✕ vale solo per le colonne della vista principale: nella tabella dei titoli
  // eccedenti le colonne sono altre (sezione, troncato, intero, caratteri) e chiuderle avrebbe
  // nascosto le omonime dell'altra tabella. Lì le intestazioni ordinano soltanto.
  // v5.979 — vale anche per la tabella di confronto: le sue colonne sono altre (titoloIt,
  // titoloEn) e la ✕ avrebbe chiuso le omonime della vista principale.
  const chiudibile = sec !== '_oversize' && sec !== '_confronto' && EBAY_COLS.filter(ebayColVisibile).length > 1;
  const x = chiudibile
    ? `<span onclick="event.stopPropagation();nascondiEbayCol('${col}')" title="${currentLang === 'it' ? 'Chiudi questa colonna' : 'Hide this column'}"
        style="margin-left:0.45rem;color:var(--muted);font-size:0.85em;cursor:pointer;">✕</span>` : '';
  return `<th onclick="setEbaySort('${sec}','${col}')" title="${currentLang === 'it' ? 'Ordina per questa colonna' : 'Sort by this column'}"
    style="padding:0.4rem 0.6rem;text-align:left;white-space:nowrap;cursor:pointer;user-select:none;${attivo ? 'color:var(--action-admin);' : ''}${extra || ''}">${label}<span style="font-size:0.75em;">${freccia}</span>${x}</th>`;
}

// ============================================================
// SELEZIONE RIGHE E SCRITTURA DEL TITOLO (v5.925, Franco)
// Fin qui il titolo era solo CALCOLATO: bello da guardare, ma non esisteva da nessuna parte.
// Ora si può fissarlo nel database — ebayTitleIt ED ebayTitleEn insieme — e poi correggerlo a
// mano. v5.979: i due non sono più lo stesso testo, ciascuno riceve il titolo del proprio
// mercato (l'inglese passa dal glossario).
// Regola sui titoli lunghi (scelta di Franco): nel campo finisce SOLO ciò che eBay accetta,
// quindi la versione tagliata a 80. Un campo con dentro 126 caratteri sarebbe un annuncio che
// non parte.
// Da qui in poi vale la precedenza di sempre: campo pieno = titolo tuo, il generato non torna più.
// ============================================================
let _ebaySelected = new Set();
// v5.926 — il comando "apri" della riga: una ✎ a fine riga, che porta alla FORM di modifica
// (tab Generale/Ebay), non alla scheda di lettura — dalla Vista Ebay si va a cambiare dati.
// v5.928 — due comandi, due destinazioni diverse: ✎ la FORM di modifica (cambiare dati),
// ↗ la SCHEDA di dettaglio (guardare il pezzo, con foto e frecce ◀▶). Nella v5.926 era rimasta
// solo la form e la scheda era diventata irraggiungibile da qui.
function ebayApriBtn(id) {
  const it = (currentLang === 'it');
  const ic = (comando, simbolo, titolo) => `<span onclick="event.stopPropagation();${comando}" title="${titolo}"
    style="cursor:pointer;color:var(--action-admin);font-size:0.95rem;padding:0 3px;">${simbolo}</span>`;
  return `<span style="white-space:nowrap;">`
    + ic(`apriModificaItem('${id}')`, '✎', it ? 'Modifica: apre la scheda dell\'oggetto' : 'Edit: open the item card')   // v6.105
    + ic(`openFigDetail('${id}')`, '↗', it ? 'Scheda: apre il dettaglio dell\'oggetto' : 'Card: open the item detail')
    + `</span>`;
}
function ebayToggleSel(id, ev) {
  if (ev) ev.stopPropagation();
  _ebaySelected.has(id) ? _ebaySelected.delete(id) : _ebaySelected.add(id);
  try { renderEbayViewTable(); } catch (e) { console.error('ebayToggleSel', e); }
}
// Casella in intestazione: seleziona/deseleziona tutta la sezione (solo le righe che si vedono).
function ebayToggleSelSezione(sec, ev) {
  if (ev) ev.stopPropagation();
  const ids = getData('figurines', [])
    .filter(f => f.seriesId === currentSeriesId && f.forSale && (f.section || 'figurines') === sec)
    .map(f => f.id);
  const tutteGiaSelezionate = ids.length && ids.every(id => _ebaySelected.has(id));
  ids.forEach(id => tutteGiaSelezionate ? _ebaySelected.delete(id) : _ebaySelected.add(id));
  try { renderEbayViewTable(); } catch (e) { console.error('ebayToggleSelSezione', e); }
}
function ebayDeselezionaTutto() {
  _ebaySelected.clear();
  try { renderEbayViewTable(); } catch (e) { console.error('ebayDeselezionaTutto', e); }
}

// Scrive il titolo generato (tagliato a 80) nei due campi, per le righe selezionate.
// v5.979 (Franco) — RIGENERAZIONE COMPLETA. Riscrive ebayTitleIt ed ebayTitleEn di ogni oggetto
// marcato Ebay dell'INTERO catalogo, non della sola serie aperta: serve dopo un cambio delle
// regole di composizione (marcatori, glossario, sottonomi), che altrimenti resterebbe invisibile
// — il valore salvato vince sempre sul generato.
//
// UN SOLO SALVATAGGIO PER SERIE, e non è un dettaglio: le figurine vivono dentro il documento
// della loro serie, quindi fsSave('figurines', ...) riscrive l'INTERA serie ad ogni oggetto.
// Su settecento pezzi sarebbero settecento riscritture complete invece di cinque. Gli oggetti in
// series.items sono gli stessi di _cache.figurines (stessi riferimenti), quindi modificarli una
// volta li aggiorna in tutti e due.
async function ebayRigeneraTitoli() {
  if (!currentUser?.isAdmin) return;
  const it = (currentLang === 'it');
  const serie = getData('series', []);

  const bersagli = [];
  for (const s of serie) for (const item of (s.items || [])) if (item.forSale) bersagli.push({ s, item });
  if (!bersagli.length) { toast(it ? 'Nessun oggetto marcato Ebay nell\u2019Inventario' : 'No items marked Ebay', 'error'); return; }

  const scritti = bersagli.filter(b => (b.item.ebayTitleIt || '').trim() || (b.item.ebayTitleEn || '').trim()).length;
  const domanda = it
    ? ('Rigenerare titolo IT ed EN di ' + bersagli.length + ' oggetti, in tutto l\u2019Inventario?' +
       (scritti ? '\n\nAttenzione: ' + scritti + ' hanno già un titolo salvato, comprese le correzioni fatte a mano. Verranno sovrascritti.' : ''))
    : ('Regenerate IT and EN titles of ' + bersagli.length + ' items across the whole catalogue?' +
       (scritti ? '\n\n' + scritti + ' already have a saved title, including manual fixes. They will be overwritten.' : ''));
  if (!confirm(domanda)) return;

  let cambiati = 0, tagliati = 0;
  const daSalvare = new Set();
  for (const { s, item } of bersagli) {
    const nuovoIt = ebayTitle(item, 'it');
    const nuovoEn = ebayTitle(item, 'com');
    if (item.ebayTitleIt !== nuovoIt || item.ebayTitleEn !== nuovoEn) {
      item.ebayTitleIt = nuovoIt;
      item.ebayTitleEn = nuovoEn;
      cambiati++;
      daSalvare.add(s);
    }
    if (ebayTitleStato(item, 'it') === 'tagliato' || ebayTitleStato(item, 'com') === 'tagliato') tagliati++;
  }

  if (!daSalvare.size) {
    toast(it ? 'Erano già tutti aggiornati: niente da riscrivere' : 'Already up to date: nothing to write');
    return;
  }

  let errori = 0;
  for (const s of daSalvare) {
    try { await fsSave('series', s); } catch (e) { console.error('rigenerazione, serie ' + s.id, e); errori++; }
  }

  const esito = it
    ? (cambiati + ' titoli riscritti in ' + daSalvare.size + (daSalvare.size === 1 ? ' serie' : ' serie') +
       (tagliati ? ' — ' + tagliati + ' con la forbice ✂, da guardare a mano' : '') +
       (errori ? ' (' + errori + ' serie NON salvate, vedi console)' : ''))
    : (cambiati + ' titles rewritten in ' + daSalvare.size + ' series' +
       (tagliati ? ' — ' + tagliati + ' truncated ✂' : '') + (errori ? ' (' + errori + ' failed)' : ''));
  toast(esito, errori ? 'error' : 'success');
  try { renderEbayViewTable(); } catch (e) { console.error('ridisegno dopo rigenerazione', e); }
}

// v5.981 — Mette (o toglie) dalla coda di pubblicazione le righe selezionate.
//
// Il salvataggio parte da series.items e NON da getData('figurines'), e non è pignoleria: le
// figurine vivono dentro il documento della loro serie, quindi si salva una serie per volta
// invece di una serie per oggetto (la lezione di ebayRigeneraTitoli). Ma c'è un secondo motivo,
// meno ovvio: _cache.figurines contiene gli STESSI riferimenti di series.items solo quando i dati
// arrivano da Firestore (righe 10231/10299). Quando arrivano dalla cache di sessione (riga 10272)
// sono copie distinte, uscite da un JSON.parse. Perciò si scrive in serie — che è ciò che si
// salva — e si riallinea a mano _cache.figurines, che è ciò che si disegna.
async function ebayImpostaCoda(valore) {
  if (!currentUser?.isAdmin) return;
  const it = (currentLang === 'it');
  if (!_ebaySelected.size) { toast(it ? 'Nessuna riga selezionata' : 'No rows selected', 'error'); return; }
  const daSalvare = new Set();
  let toccati = 0;
  for (const s of getData('series', [])) {
    for (const item of (s.items || [])) {
      if (!_ebaySelected.has(item.id)) continue;
      if ((item.daPubblicare || false) === valore) continue;   // già come lo si vuole
      item.daPubblicare = valore;
      toccati++;
      daSalvare.add(s);
    }
  }
  if (!daSalvare.size) {
    toast(it ? 'Erano già tutte così: niente da salvare' : 'Already in that state: nothing to save');
    return;
  }
  // il gemello disegnato (vedi sopra): senza questo, a cache di sessione calda la tabella
  // continuerebbe a mostrare lo stato vecchio pur avendo salvato quello nuovo.
  getData('figurines', []).forEach(f => { if (_ebaySelected.has(f.id)) f.daPubblicare = valore; });
  let errori = 0;
  for (const s of daSalvare) {
    try { await fsSave('series', s); } catch (e) { console.error('ebayImpostaCoda, serie ' + s.id, e); errori++; }
  }
  _ebaySelected.clear();
  try { renderEbayViewTable(); } catch (e) { console.error('ebayImpostaCoda, ridisegno', e); }
  const esito = it
    ? (valore ? (toccati + (toccati === 1 ? ' oggetto messo' : ' oggetti messi') + ' in coda') : (toccati + (toccati === 1 ? ' oggetto tolto' : ' oggetti tolti') + ' dalla coda'))
    : (toccati + ' item(s) ' + (valore ? 'queued' : 'removed from the queue'));
  toast(esito + (errori ? (it ? ' (' + errori + ' serie NON salvate, vedi console)' : ' (' + errori + ' series failed)') : ''), errori ? 'error' : 'success');
}

async function ebayApplicaTitoli() {
  if (!currentUser?.isAdmin) return;
  const it = (currentLang === 'it');
  const figs = getData('figurines', []);
  const scelti = figs.filter(f => _ebaySelected.has(f.id));
  if (!scelti.length) { toast(it ? 'Nessuna riga selezionata' : 'No rows selected', 'error'); return; }
  // Sovrascrivere un titolo scritto a mano è la sola cosa irreversibile qui: si chiede prima.
  const giaScritti = scelti.filter(f => (f.ebayTitleIt || '').trim() || (f.ebayTitleEn || '').trim()).length;
  const domanda = it
    ? ('Scrivere il titolo generato su ' + scelti.length + (scelti.length === 1 ? ' oggetto' : ' oggetti') + '?' +
       (giaScritti ? '\n\nAttenzione: ' + giaScritti + (giaScritti === 1 ? ' ha' : ' hanno') + ' già un titolo scritto a mano, che verrà sovrascritto.' : ''))
    : ('Write the generated title on ' + scelti.length + ' item(s)?' + (giaScritti ? '\n\n' + giaScritti + ' already have a manual title that will be overwritten.' : ''));
  if (!confirm(domanda)) return;
  let salvati = 0;
  for (const f of scelti) {
    // v5.979 — i due mercati non hanno più lo stesso titolo: l'inglese passa dal glossario.
    f.ebayTitleIt = ebayTitle(f, 'it');   // già tagliati a 80
    f.ebayTitleEn = ebayTitle(f, 'com');
  }
  // v6.117 - una scrittura per SERIE invece di una per oggetto.
  try {
    await _salvaFigurineInBlocco(scelti);
    salvati = scelti.length;
  } catch (e) {
    console.error('ebayApplicaTitoli', e);
    toast(it ? 'Scrittura fallita: ' + (e?.code || e?.message || 'errore') : 'Write failed: ' + (e?.code || e?.message || 'error'), 'error');
    return;
  }
  _cache.figurines = figs;
  _ebaySelected.clear();
  try { renderEbayViewTable(); } catch (e) { console.error('ebayApplicaTitoli', e); }
  toast(it ? ('Titolo scritto su ' + salvati + (salvati === 1 ? ' oggetto' : ' oggetti')) : ('Title written on ' + salvati + ' item(s)'), 'success');
}

// Modifica in cella: il testo diventa un input, Invio o uscita salvano, Esc annulla.
// Svuotare il campo NON lascia il titolo vuoto: rimette in gioco il generato (è il modo per
// "tornare indietro" senza dover ricopiare il Nome completo).
function ebayEditTitolo(id, ev) {
  if (ev) ev.stopPropagation();
  const cella = document.getElementById('ebay-titolo-' + id);
  if (!cella || cella.querySelector('input')) return;
  const f = getData('figurines', []).find(x => x.id === id);
  if (!f) return;
  const isIt = (_ebayViewMarket === 'it');
  const valore = (isIt ? f.ebayTitleIt : f.ebayTitleEn) || ebayTitle(f);
  // v5.930 — l'input parte col titolo GENERATO quando il campo è vuoto: comodo da correggere, ma
  // vuol dire che uscendo senza toccare niente il valore sarebbe "diverso dal campo salvato" e
  // finirebbe scritto. È così che 47 titoli si sono salvati da soli al primo clic esplorativo.
  // Il confronto ora è col valore INIZIALE dell'input (data-iniziale), non col campo: se non hai
  // scritto nulla, non si salva nulla.
  cella.innerHTML = `<input type="text" value="${(valore || '').replace(/"/g, '&quot;')}" data-iniziale="${(valore || '').replace(/"/g, '&quot;')}"
      onclick="event.stopPropagation();" onkeydown="ebayEditTitoloTasto(event, '${id}')" onblur="ebaySalvaTitolo('${id}', this.value, this.dataset.iniziale)"
      oninput="ebayContaCaratteri(this)"
      style="width:100%;box-sizing:border-box;font-size:0.82rem;padding:3px 6px;border:1px solid var(--action-admin);border-radius:6px;background:var(--card);color:var(--text);">
    <span class="conta" style="font-size:0.7rem;color:var(--muted);"></span>`;
  const input = cella.querySelector('input');
  input.focus(); input.select();
  ebayContaCaratteri(input);
}
function ebayContaCaratteri(input) {
  const c = input.parentNode.querySelector('.conta');
  if (!c) return;
  const n = input.value.length, oltre = n > EBAY_TITLE_MAX;
  c.textContent = n + ' / ' + EBAY_TITLE_MAX;
  c.style.color = oltre ? 'var(--danger, #e5484d)' : 'var(--muted)';
  input.style.borderColor = oltre ? 'var(--danger, #e5484d)' : 'var(--action-admin)';
}
function ebayEditTitoloTasto(ev, id) {
  if (ev.key === 'Enter') { ev.preventDefault(); ev.target.blur(); }
  else if (ev.key === 'Escape') { ev.preventDefault(); ev.target.onblur = null; renderEbayViewTable(); }
}
async function ebaySalvaTitolo(id, valore, iniziale) {
  const figs = getData('figurines', []);
  const f = figs.find(x => x.id === id);
  if (!f) return;
  const isIt = (_ebayViewMarket === 'it');
  const nuovo = (valore || '').trim();
  // v5.930 — si salva solo ciò che è stato DAVVERO modificato rispetto a com'era all'apertura.
  const partenza = (iniziale === undefined ? ((isIt ? f.ebayTitleIt : f.ebayTitleEn) || '') : iniziale).trim();
  if (nuovo === partenza) { try { renderEbayViewTable(); } catch (e) {} return; }
  if (isIt) f.ebayTitleIt = nuovo || null; else f.ebayTitleEn = nuovo || null;
  _cache.figurines = figs;
  try { await fsSave('figurines', f); } catch (e) { console.error('ebaySalvaTitolo', e); toast(currentLang === 'it' ? 'Salvataggio fallito' : 'Save failed', 'error'); }
  try { renderEbayViewTable(); } catch (e) {}
}

// v5.924 — intestazione di una colonna che NON si ordina (il numero di riga): ha solo la ✕.
function ebayThFisso(col, label, extra) {
  // v5.933 — il numero di riga si mostra SEMPRE: niente ✕, e non entra nella riga di ripristino.
  const chiudibile = (col !== 'riga') && EBAY_COLS.filter(ebayColVisibile).length > 1;
  const x = chiudibile
    ? `<span onclick="nascondiEbayCol('${col}')" title="${currentLang === 'it' ? 'Chiudi questa colonna' : 'Hide this column'}"
        style="margin-left:0.4rem;color:var(--muted);font-size:0.85em;cursor:pointer;">✕</span>` : '';
  return `<th style="padding:0.4rem 0.6rem;text-align:left;white-space:nowrap;color:var(--muted);${extra || ''}">${label}${x}</th>`;
}

// v5.922 (Franco) — COLONNE A SCOMPARSA. La tabella è a larghezza piena: appena una colonna esce,
// le altre si riprendono lo spazio da sole, senza toccare le larghezze a mano.
// Lo stato è UNICO per tutte e cinque le sezioni: le tabelle mostrano gli stessi dati, e vederle
// con colonne diverse a seconda della sezione confonderebbe più di quanto aiuti.
let _ebayColHidden = {};
// v5.923 — elenco delle colonne, per sapere quante ne restano aperte (l'ultima non si chiude).
// v5.981 — via 'sped', dentro 'stato'. La spedizione non è più un dato dell'oggetto: con le
// business policy dell'Inventory API sta nella fulfillment policy, e nell'annuncio finisce solo
// l'ID della policy. Una colonna che non può che essere vuota è peggio di una colonna assente.
const EBAY_COLS = ['riga', 'nome', 'titolo', 'prezzo', 'qta', 'cond', 'stato', 'foto'];
function nascondiEbayCol(col) {
  if (EBAY_COLS.filter(ebayColVisibile).length <= 1) return; // mai zero colonne
  _ebayColHidden[col] = true;
  try { renderEbayViewTable(); } catch (e) { console.error('nascondiEbayCol', e); }
}
function mostraEbayCol(col) {
  if (col) delete _ebayColHidden[col]; else _ebayColHidden = {};
  try { renderEbayViewTable(); } catch (e) { console.error('mostraEbayCol', e); }
}
function ebayColVisibile(col) { return !_ebayColHidden[col]; }
// v5.927 — chiude tutto tranne il Titolo, in un colpo. La casella di selezione e la ✎ restano:
// non sono colonne di dati, sono i comandi della riga, e senza di loro la vista sarebbe di sola
// lettura proprio mentre serve per lavorare sui titoli.
function ebaySoloTitolo() {
  _ebayColHidden = {};
  // v5.933 (Franco) — il numero di riga resta: serve a dire "la settima" mentre si parla di una
  // riga, e senza di lui una colonna sola di titoli non si riesce nemmeno a citare.
  EBAY_COLS.forEach(c => { if (c !== 'titolo' && c !== 'riga') _ebayColHidden[c] = true; });
  try { renderEbayViewTable(); } catch (e) { console.error('ebaySoloTitolo', e); }
}
// Riga di ripristino: senza, una colonna chiusa sarebbe una colonna persa.
function ebayColRestoreBar(etichette) {
  const nascoste = Object.keys(_ebayColHidden).filter(c => etichette[c]);
  if (!nascoste.length) return '';
  const it = (currentLang === 'it');
  const chip = c => `<span onclick="mostraEbayCol('${c}')" title="${it ? 'Rimetti questa colonna' : 'Bring this column back'}"
    style="display:inline-flex;align-items:center;gap:0.3rem;border:1px dashed var(--border);border-radius:999px;padding:1px 9px;font-size:0.76rem;color:var(--muted);cursor:pointer;">${etichette[c]} <span style="font-weight:700;">+</span></span>`;
  return `<div style="display:flex;flex-wrap:wrap;align-items:center;gap:0.4rem;margin-bottom:0.75rem;">
    <span style="font-size:0.76rem;color:var(--muted);">${it ? 'Colonne chiuse:' : 'Hidden columns:'}</span>
    ${nascoste.map(chip).join('')}
    ${nascoste.length > 1 ? `<span onclick="mostraEbayCol()" style="font-size:0.76rem;color:var(--action-admin);cursor:pointer;text-decoration:underline;margin-left:0.2rem;">${it ? 'rimettile tutte' : 'restore all'}</span>` : ''}
  </div>`;
}
// Ordina una copia della lista secondo lo stato; senza stato restituisce l'elenco com'è.
// I numeri si confrontano da numeri (3.5 < 12), il testo con le regole italiane; i vuoti
// vanno sempre in fondo, in entrambi i versi: un campo non compilato non è "il più piccolo".
function ebayApplicaSort(items, sec, valori) {
  const s = _ebaySort[sec];
  if (!s || !valori[s.col]) return items;
  const val = valori[s.col];
  const vuoto = v => v === null || v === undefined || v === '';
  return [...items].sort((a, b) => {
    const va = val(a), vb = val(b);
    if (vuoto(va) && vuoto(vb)) return 0;
    if (vuoto(va)) return 1;
    if (vuoto(vb)) return -1;
    const cmp = (typeof va === 'number' && typeof vb === 'number')
      ? va - vb
      : String(va).localeCompare(String(vb), 'it', { numeric: true, sensitivity: 'base' });
    return cmp * s.dir;
  });
}
// v5.981 — quale account si sta guardando nella Vista Ebay. null = il predefinito.
// Come per il mercato, la scelta è di chi guarda e vale finché la maschera resta aperta.
let _ebayViewAccount = null;
function setEbayViewAccount(id) { _ebayViewAccount = id || null; renderEbayViewTable(); }

function renderEbayViewTable() {
  const tableEl = document.getElementById('series-ebay-table');
  if (!tableEl) return;
  const it = (currentLang === 'it');
  const figs = getData('figurines', []).filter(f => f.seriesId === currentSeriesId);
  const market = _ebayViewMarket, isIt = market === 'it', sym = isIt ? '€' : '$';
  // Le impostazioni servono per gli account, ma questa funzione è sincrona (la chiamano una
  // dozzina di punti). Si usa la cache; se non c'è ancora, si disegna lo stesso e si ridisegna
  // una volta sola appena arriva — meglio una tabella completa un istante dopo che una funzione
  // async che costringe a rincorrere tutti i chiamanti.
  const impostazioni = _cache.ebaySettings || {};
  if (_cache.ebaySettings === undefined) {
    getEbaySettings().then(() => renderEbayViewTable()).catch(e => console.error('impostazioni eBay', e));
  }
  const contiEbay = ebayAccounts(impostazioni);
  const accountCorrente = _ebayViewAccount || ebayAccountPredefinito(impostazioni)?.id || null;
  // Bottoni admin = arancioni (var(--action-admin)), non lime.
  const tab = (m, label) => `<button onclick="setEbayViewMarket('${m}')" style="font-size:0.82rem;padding:5px 14px;border-radius:8px;border:1px solid ${market === m ? 'var(--action-admin)' : 'var(--border)'};background:${market === m ? 'var(--action-admin)' : 'transparent'};color:${market === m ? '#ffffff' : 'var(--muted)'};cursor:pointer;font-weight:${market === m ? '700' : '400'};">${label}</button>`;
  // v5.927 (Franco) — "Lascia solo titolo": una scorciatoia per la lavorazione dei titoli, che
  // altrimenti costa sei clic sulle ✕. Il bottone si spegne da solo quando è già in quello stato
  // (niente comando che non fa niente) e la strada del ritorno resta quella di sempre: la riga
  // "Colonne chiuse → rimettile tutte".
  const soloTitolo = EBAY_COLS.every(c => c === 'titolo' ? ebayColVisibile(c) : !ebayColVisibile(c));
  const btnSoloTitolo = `<button onclick="ebaySoloTitolo()" ${soloTitolo ? 'disabled' : ''}
    title="${it ? 'Chiude tutte le colonne tranne il Titolo' : 'Hides every column but the title'}"
    style="font-size:0.8rem;padding:5px 12px;border-radius:8px;border:1px solid var(--border);background:transparent;color:${soloTitolo ? 'var(--border)' : 'var(--muted)'};cursor:${soloTitolo ? 'default' : 'pointer'};">${it ? 'Lascia solo titolo' : 'Title only'}</button>`;
  // v5.979 (Franco) — terzo tab: i due titoli affiancati. Serve perché da quando l'inglese passa
  // dal glossario i due mercati non dicono più la stessa cosa, e alternare fra due schede per
  // confrontarli è il modo peggiore di accorgersi di una differenza.
  // v5.981 — seconda riga di scelta: l'account venditore. Compare solo con almeno due account,
  // perché con uno solo non c'è niente da scegliere e sarebbe una riga di ingombro.
  const _attrA = t => String(t || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
  const tabAcc = a => `<button onclick="setEbayViewAccount('${_attrA(a.id)}')" style="font-size:0.78rem;padding:4px 11px;border-radius:8px;border:1px solid ${accountCorrente === a.id ? 'var(--action-admin)' : 'var(--border)'};background:${accountCorrente === a.id ? 'var(--action-admin)' : 'transparent'};color:${accountCorrente === a.id ? '#ffffff' : 'var(--muted)'};cursor:pointer;font-weight:${accountCorrente === a.id ? '700' : '400'};">${_attrA(a.etichetta)}</button>`;
  const selettoreAccount = (contiEbay.length > 1 && market !== 'confronto')
    ? `<div style="display:flex;gap:0.4rem;margin-bottom:0.75rem;align-items:center;flex-wrap:wrap;">
         <span style="font-size:0.78rem;color:var(--muted);">${it ? 'Account:' : 'Account:'}</span>${contiEbay.map(tabAcc).join('')}</div>`
    : '';
  const selector = `<div style="display:flex;gap:0.5rem;margin-bottom:0.75rem;align-items:center;">${tab('it', '🇮🇹 eBay.it')}${tab('com', '🇺🇸 eBay.com')}${tab('confronto', '⇄ ' + (it ? 'Titoli mercato a confronto' : 'Titles side by side'))}<span style="flex:1;"></span>${market === 'confronto' ? '' : btnSoloTitolo}</div>` + selettoreAccount;
  if (market === 'confronto') { renderEbayConfrontoTitoli(tableEl, selector); renderEbayOversizeTable(); return; }
  if (!figs.some(f => f.forSale)) {
    tableEl.innerHTML = selector + `<p style="color:var(--muted);font-style:italic;font-size:0.88rem;">${it ? 'Nessun oggetto marcato Ebay in questa serie.' : 'No items marked Ebay in this series.'}</p>`;
    renderEbayOversizeTable();
    return;
  }
  const muted = x => `<span style="color:var(--muted);">${x}</span>`;
  const esc = s => (s || '').replace(/</g, '&lt;');
  // v5.918 — titolo generato (troncato a 80); un titolo scritto a mano ha la precedenza.
  const titleOf = f => (isIt ? f.ebayTitleIt : f.ebayTitleEn) || ebayTitle(f, market);
  // la cella segnala il taglio: chi guarda la tabella deve accorgersene senza contare i caratteri
  // v5.925 — la cella è modificabile (clic) e distingue a colpo d'occhio il titolo SCRITTO da
  // quello solo calcolato: il generato resta in grigio, perché finché è grigio non esiste ancora
  // da nessuna parte.
  const titleCell = f => {
    const manuale = (isIt ? f.ebayTitleIt : f.ebayTitleEn) || '';
    const titoloMostrato = titleOf(f);
    const testo = esc(titoloMostrato);
    // v5.979 — la forbice non dipende più dal fatto che il titolo sia salvato o calcolato: dopo
    // una rigenerazione sono TUTTI salvati, e con la vecchia regola sarebbe sparita proprio
    // quando serve. Ora segnala una cosa più precisa: il testo che stai vedendo è esattamente
    // quello che la composizione ha dovuto TAGLIARE DENTRO IL NOME. Se lo riscrivi a mano, la
    // forbice se ne va da sola — perché quel testo non è più il troncato.
    const forbice = ebayForbice(f, market, titoloMostrato);
    const troppoLungo = manuale.length > EBAY_TITLE_MAX
      ? ` <span title="${it ? 'Oltre gli 80 caratteri: eBay lo rifiuta' : 'Over 80 characters: eBay will reject it'}" style="color:var(--danger, #e5484d);font-weight:700;">${manuale.length}</span>` : '';
    return `<span id="ebay-titolo-${f.id}" onclick="ebayEditTitolo('${f.id}', event)" title="${it ? 'Clicca per modificare' : 'Click to edit'}"
      style="display:block;${manuale ? '' : 'color:var(--muted);font-style:italic;'}">${testo}${forbice}${troppoLungo}</span>`;
  };
  // v5.981 — Stato di pubblicazione del mercato che si sta guardando. Sola lettura: questi campi
  // li scrive il programma sul PC, il sito non li tocca mai. Sono due cose sovrapposte in una
  // cella: l'ESITO (cos'è successo l'ultima volta) e la CODA (cosa succederà al prossimo lancio),
  // e servono insieme — "pubblicato" con la coda alzata significa "pubblicato, ma non più
  // aggiornato", che è esattamente il caso che si vuole vedere a colpo d'occhio.
  const statoEbay = f => accountCorrente ? ebayStatoDi(f, accountCorrente, market) : null;
  // Un oggetto che non va su questo account non ha "mai pubblicato" come stato: non ha proprio uno
  // stato, ed e' una cosa diversa. Confonderle vorrebbe dire vedere centinaia di righe che sembrano
  // in attesa di essere pubblicate quando invece non c'entrano niente con questo venditore.
  const riguardaAccount = f => !accountCorrente ||
    ebayAccountsDiOggetto(f, impostazioni).includes(accountCorrente) ||
    ebayAccountConStato(f).includes(accountCorrente);
  const EBAY_STATI = {
    'pubblicato':      { seg: '●', col: 'var(--success, #3fb950)', it: 'pubblicato',      en: 'published' },
    'ritirato':        { seg: '○', col: 'var(--muted)',            it: 'ritirato',        en: 'ended' },
    'errore':          { seg: '▲', col: 'var(--danger, #e5484d)',  it: 'errore',          en: 'error' },
    'mai pubblicato':  { seg: '·', col: 'var(--muted)',            it: 'mai pubblicato',  en: 'never published' },
  };
  const statoCell = f => {
    if (!riguardaAccount(f)) return `<span style="color:var(--border);" title="${it ? 'Questo oggetto non va in vendita su questo account' : 'Not for sale on this account'}">${it ? 'non qui' : 'not here'}</span>`;
    const e = statoEbay(f);
    const inCoda = f.daPubblicare
      ? `<span title="${it ? 'In coda: al prossimo lancio del programma viene creato o aggiornato' : 'Queued for the next run'}">📤</span> ` : '';
    const s = EBAY_STATI[e?.stato] || EBAY_STATI['mai pubblicato'];
    // Il dettaglio (listingId, errore, data) sta nella scheda dell'oggetto: qui ci va nel tooltip,
    // perché una colonna di tabella non è il posto per un messaggio d'errore di eBay.
    const dettaglio = [
      e?.listingId ? (it ? 'Annuncio n. ' : 'Listing no. ') + e.listingId : '',
      e?.ultimoErrore || '',
      e?.aggiornatoIl ? (it ? 'aggiornato il ' : 'updated ') + new Date(e.aggiornatoIl).toLocaleString(it ? 'it-IT' : 'en-GB') : '',
    ].filter(Boolean).join(' — ');
    const etichetta = it ? s.it : s.en;
    // ultimoErrore arriva da eBay e può contenere qualunque cosa, virgolette comprese: qui finisce
    // DENTRO un attributo, dove esc() (che tocca solo "<") non basterebbe a chiudere il buco.
    const attr = t => String(t || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
    return `${inCoda}<span title="${attr(dettaglio || etichetta)}" style="color:${s.col};white-space:nowrap;">${s.seg} ${etichetta}</span>`;
  };
  const priceCell = f => { const v = isIt ? f.price : f.priceUsd; return (v == null || v === '') ? muted('—') : sym + Number(v).toFixed(2); };
  const condOf = f => isIt ? (f.condition === 'used' ? 'Usato' : 'Nuovo') : (f.condition === 'used' ? 'Used' : 'Ungraded');
  const img1 = u => `<img src="${cloudinaryUrl(u, 'w_48,h_48,c_fit,q_auto,f_auto')}" style="width:36px;height:36px;object-fit:contain;border-radius:4px;background:var(--card2);">`;
  // v5.919 (Franco) — nelle FIGURINE accanto alla foto dell'annuncio va anche la miniatura del
  // RETRO associato: su eBay il retro è metà di ciò che il collezionista guarda, e da qui si vede
  // a colpo d'occhio se manca. Le altre sezioni (il retro è già l'oggetto, o non ne hanno) no.
  const thumb = f => {
    const mie = f.ebayImg ? img1(f.ebayImg) : muted('—');
    if ((f.section || 'figurines') !== 'figurines') return mie;
    const retro = f.retroId ? getData('figurines', []).find(x => x.id === f.retroId) : null;
    const suo = retro ? (retro.ebayImg || retro.img) : null;
    const cella = suo ? img1(suo)
      : `<span title="${retro ? (it ? 'Retro associato senza foto' : 'Linked retro has no photo') : (it ? 'Nessun retro associato' : 'No linked retro')}" style="color:var(--muted);font-size:0.75rem;">${retro ? '○' : '—'}</span>`;
    return `<div style="display:flex;gap:0.35rem;align-items:center;justify-content:center;">${mie}${cella}</div>`;
  };
  const td = (c, extra = '') => `<td style="padding:0.4rem 0.6rem;font-size:0.82rem;${extra}">${c}</td>`;
  // (v5.921: le intestazioni le costruisce ebayTh(), che ci mette anche clic e freccia)
  // v5.919 (Franco) — non più un'unica tabella con la colonna "Tipo", ma CINQUE tabelle, una per
  // sezione: le colonne utili cambiano da sezione a sezione e una colonna che ripete la stessa
  // parola per cento righe è spazio buttato. Anche N. e Nome se ne vanno: al loro posto il NOME
  // COMPLETO, che è ciò che finisce nel titolo dell'annuncio.
  // Ordine delle righe: lo stesso della vista tabellare (cmpVistaTabellare).
  const blocchi = EBAY_SECTIONS.map(sec => {
    const items = figs.filter(f => f.forSale && (f.section || 'figurines') === sec).sort(cmpVistaTabellare(sec));
    // v5.920 (Franco) — ogni sezione si chiude: con centinaia di righe, per arrivare alla sezione
    // dopo si scorreva all'infinito. L'intestazione è il comando (tutta, non una freccina da
    // centrare) e lo stato resta in _ebaySectionCollapsed, quindi sopravvive al cambio di mercato
    // IT/COM e a ogni ridisegno finché la maschera è aperta.
    const chiusa = !!_ebaySectionCollapsed[sec];
    const testa = (comando) => `<h3 onclick="${comando}" style="font-size:0.92rem;font-weight:700;color:var(--text);margin:1.5rem 0 0.5rem;${comando ? 'cursor:pointer;user-select:none;' : ''}">
      <span style="display:inline-block;width:1em;color:var(--muted);">${comando ? (chiusa ? '▸' : '▾') : ''}</span>${ebaySectionLabel(sec)} <span style="color:var(--muted);font-weight:400;">(${items.length})</span></h3>`;
    if (!items.length) {
      return testa('') + `<p style="color:var(--muted);font-style:italic;font-size:0.85rem;margin:0;">${it ? 'Nessun oggetto marcato Ebay.' : 'No items marked Ebay.'}</p>`;
    }
    const titolo = testa(`toggleEbaySection('${sec}')`);
    if (chiusa) return titolo;
    // v5.921 — ordinamento per colonna (se attivo su questa sezione). Il valore usato per
    // ordinare è quello VISTO nella cella, mercato compreso: si ordina ciò che si legge.
    const ordinati = ebayApplicaSort(items, sec, {
      nome:   f => f.fullName || f.name || '',
      titolo: f => titleOf(f),
      prezzo: f => { const v = isIt ? f.price : f.priceUsd; return (v == null || v === '') ? null : Number(v); },
      qta:    f => Number(f.quantity || 1),
      cond:   f => condOf(f),
      // v5.981 — ordinando per stato le righe che chiedono attenzione si radunano: prima gli
      // errori, poi la coda, e in fondo quello che è già a posto.
      stato:  f => { if (!riguardaAccount(f)) return 9; const e = statoEbay(f); const ordine = { 'errore': 0, 'mai pubblicato': 2, 'ritirato': 3, 'pubblicato': 4 }; return (ordine[e?.stato] ?? 2) - (f.daPubblicare ? 0.5 : 0); },
      foto:   f => f.ebayImg ? 1 : 0
    });
    // v5.922 — le colonne chiuse non vengono né intestate né riempite (niente celle vuote a
    // reggere lo spazio: la tabella è width:100% e le superstiti si allargano da sole).
    const vis = ebayColVisibile;
    // v5.924 (Franco) — numero di riga come prima colonna. È la POSIZIONE nell'elenco così
    // com'è ora, non un dato del pezzo: riparte da 1 in ogni sezione e si rinumera quando
    // cambi ordinamento. Per questo la sua intestazione non ordina (ordinare per "posizione
    // attuale" non vorrebbe dire nulla); si può però chiudere come le altre.
    // v5.926 (Franco) — la riga NON è più cliccabile tutta: da quando il Titolo si modifica in
    // cella, un clic qualunque sulla riga era un'ambiguità (modifico o apro?). Il comando è ora
    // un punto solo e dichiarato: la ✎ a fine riga, che apre la FORM di modifica dell'oggetto.
    // Chiudendola con la ✕ si torna qui: closeModal nasconde solo la finestra in cima, e la
    // Vista Ebay resta sotto con selezione, ordinamento e colonne intatti.
    const rows = ordinati.map((f, i) => `<tr style="${_ebaySelected.has(f.id) ? 'background:rgba(255,157,61,0.10);' : ''}"
      onmouseover="this.style.background='var(--card2)'" onmouseout="this.style.background='${_ebaySelected.has(f.id) ? 'rgba(255,157,61,0.10)' : ''}'">
      ${td(`<input type="checkbox" ${_ebaySelected.has(f.id) ? 'checked' : ''} onclick="ebayToggleSel('${f.id}', event)" style="cursor:pointer;">`, 'width:1%;text-align:center;')}
      ${vis('riga') ? td(i + 1, 'color:var(--muted);text-align:right;white-space:nowrap;width:1%;') : ''}
      ${vis('nome') ? td(esc(f.fullName || f.name)) : ''}
      ${vis('titolo') ? td(titleCell(f) || muted('—')) : ''}
      ${vis('prezzo') ? td(priceCell(f), 'white-space:nowrap;') : ''}
      ${vis('qta') ? td(f.quantity || 1, 'text-align:center;white-space:nowrap;') : ''}
      ${vis('cond') ? td(condOf(f), 'white-space:nowrap;') : ''}
      ${vis('stato') ? td(statoCell(f), 'white-space:nowrap;') : ''}
      ${vis('foto') ? td(thumb(f), 'text-align:center;') : ''}
      ${td(ebayApriBtn(f.id), 'width:1%;text-align:center;')}
    </tr>`).join('');
    return titolo + `<div style="overflow-x:auto;"><table class="data-table" style="border-spacing:0;width:100%;"><thead><tr>
      <th style="padding:0.4rem 0.6rem;width:1%;text-align:center;"><input type="checkbox" onclick="ebayToggleSelSezione('${sec}', event)" title="${it ? 'Seleziona tutta la sezione' : 'Select the whole section'}" ${items.length && items.every(f => _ebaySelected.has(f.id)) ? 'checked' : ''} style="cursor:pointer;"></th>${vis('riga') ? ebayThFisso('riga', '#', 'text-align:right;') : ''}${vis('nome') ? ebayTh(sec, 'nome', it ? 'Nome completo' : 'Full name') : ''}${vis('titolo') ? ebayTh(sec, 'titolo', 'Titolo ' + (isIt ? 'IT' : 'EN')) : ''}${vis('prezzo') ? ebayTh(sec, 'prezzo', (it ? 'Prezzo' : 'Price') + ' (' + sym + ')') : ''}${vis('qta') ? ebayTh(sec, 'qta', it ? 'Q.tà' : 'Qty') : ''}${vis('cond') ? ebayTh(sec, 'cond', it ? 'Condizione' : 'Condition') : ''}${vis('stato') ? ebayTh(sec, 'stato', (it ? 'Stato' : 'Status') + ' ' + (isIt ? 'IT' : 'US')) : ''}${vis('foto') ? ebayTh(sec, 'foto', it ? 'Foto' : 'Photo') : ''}<th style="width:1%;"></th>
    </tr></thead><tbody>${rows}</tbody></table></div>`;
  }).join('');
  const etichetteCol = {
    nome: it ? 'Nome completo' : 'Full name',
    titolo: 'Titolo', prezzo: it ? 'Prezzo' : 'Price', qta: it ? 'Q.tà' : 'Qty',
    cond: it ? 'Condizione' : 'Condition', stato: it ? 'Stato' : 'Status', foto: it ? 'Foto' : 'Photo'
  };
  // v5.925 — barra delle azioni: compare solo quando c'è una selezione, così a riposo non
  // occupa spazio e quando c'è dice subito su quante righe agirà.
  const n = _ebaySelected.size;
  const barraAzioni = n ? `<div style="display:flex;flex-wrap:wrap;align-items:center;gap:0.6rem;margin-bottom:0.75rem;padding:0.5rem 0.8rem;border:1px solid var(--action-admin);border-radius:10px;background:rgba(255,157,61,0.08);">
    <span style="font-size:0.82rem;color:var(--text);font-weight:600;">${n} ${it ? (n === 1 ? 'riga selezionata' : 'righe selezionate') : (n === 1 ? 'row selected' : 'rows selected')}</span>
    <button class="btn-primary btn-admin" onclick="ebayApplicaTitoli()" style="font-size:0.82rem;padding:0.35rem 0.9rem;"
      title="${it ? 'Scrive il titolo generato dal Nome completo nei campi Titolo IT ed EN (tagliato a 80 caratteri)' : 'Writes the generated title into the IT and EN title fields (cut at 80 chars)'}">${it ? '📝 Applica Nome completo al Titolo' : '📝 Apply full name to title'}</button>
    <button class="btn-primary btn-admin" onclick="ebayImpostaCoda(true)" style="font-size:0.82rem;padding:0.35rem 0.9rem;"
      title="${it ? 'Al prossimo lancio del programma questi annunci vengono creati o aggiornati' : 'These listings will be created or updated the next time the program runs'}">${it ? '📤 Metti in coda' : '📤 Queue'}</button>
    <button class="btn-danger-ghost" onclick="ebayImpostaCoda(false)" style="font-size:0.82rem;padding:0.35rem 0.9rem;cursor:pointer;"
      title="${it ? 'Toglie dalla coda: il programma li ignora. Torneranno in coda da sé alla prossima modifica' : 'Removes from the queue. They will return on their own at the next change'}">${it ? '↩︎ Togli dalla coda' : '↩︎ Unqueue'}</button>
    <span onclick="ebayDeselezionaTutto()" style="font-size:0.78rem;color:var(--muted);cursor:pointer;text-decoration:underline;">${it ? 'deseleziona' : 'clear'}</span>
  </div>` : '';
  tableEl.innerHTML = selector + barraAzioni + ebayColRestoreBar(etichetteCol) + blocchi;
  renderEbayOversizeTable();
}

// v5.979 — "Titoli mercato a confronto" (Franco). Terzo tab della Vista Ebay: una sola tabella
// piatta con i due titoli accanto, non cinque tabelle per sezione. Il senso è il confronto, e per
// confrontare serve vedere le due colonne sulla stessa riga: la sezione di appartenenza, qui, non
// aggiunge niente.
// Ordine: per TITOLO ITALIANO (Franco), non l'ordine della vista tabellare. È l'ordine giusto per
// una lista che si legge come un elenco di annunci, e mette vicine le righe che si somigliano —
// che è dove le differenze fra le due lingue si notano.
// Sola lettura di proposito: la modifica di un titolo ha già il suo posto, la cella cliccabile
// nelle due schede di mercato. Qui non si saprebbe quale dei due si sta modificando.
function renderEbayConfrontoTitoli(tableEl, selector) {
  const it = (currentLang === 'it');
  const figs = getData('figurines', []).filter(f => f.seriesId === currentSeriesId && f.forSale);
  if (!figs.length) {
    tableEl.innerHTML = selector + `<p style="color:var(--muted);font-style:italic;font-size:0.88rem;">${it ? 'Nessun oggetto marcato Ebay in questa serie.' : 'No items marked Ebay in this series.'}</p>`;
    return;
  }
  const esc = s => (s || '').replace(/</g, '&lt;');
  // Un titolo scritto a mano vince su quello generato, come nelle altre tabelle; e come là, il
  // generato resta in grigio corsivo — finché è grigio non esiste ancora da nessuna parte.
  const dati = figs.map(f => {
    const manIt = (f.ebayTitleIt || '').trim(), manEn = (f.ebayTitleEn || '').trim();
    return { f,
      it:  manIt || ebayTitle(f, 'it'),  itManuale: !!manIt,
      en:  manEn || ebayTitle(f, 'com'), enManuale: !!manEn };
  }).sort((a, b) => a.it.localeCompare(b.it, 'it', { numeric: true, sensitivity: 'base' }));

  const ordinati = dati; // ordine fisso: titolo italiano (Franco)

  const td = (c, extra = '') => `<td style="padding:0.35rem 0.6rem;font-size:0.82rem;${extra}">${c}</td>`;
  const testoCella = (testo, manuale, uguale, f, mercato) => {
    // Il generato resta in grigio corsivo, come nelle altre tabelle: finché è grigio non esiste
    // ancora da nessuna parte.
    const stile = manuale ? '' : 'color:var(--muted);font-style:italic;';
    // Due titoli identici non sono un errore — succede quando nel testo non compare nessuna
    // parola del glossario — ma in una tabella che esiste per confrontarli vale la pena vederlo.
    const segno = uguale ? ` <span title="${it ? 'Identico al titolo italiano: nessuna parola da tradurre' : 'Identical to the Italian title: no glossary word here'}" style="color:var(--muted);">=</span>` : '';
    return `<span style="${stile}">${esc(testo)}${ebayForbice(f, mercato, testo)}${segno}</span>`;
  };

  // v5.979 — le due lingue INCOLONNATE, non affiancate (Franco). Due colonne da 80 caratteri non
  // ci stanno nella maschera, ma soprattutto: due titoli quasi uguali si confrontano guardandoli
  // uno sopra l'altro, dove le parti identiche si allineano e la differenza salta all'occhio.
  // Affiancati bisogna cercarla.
  const bordo = 'border-top:1px solid var(--border);';
  const rows = ordinati.map((r, i) => {
    const uguale = (r.it === r.en);
    return `<tr onmouseover="this.style.background='var(--card2)'" onmouseout="this.style.background=''">
      ${td(i + 1, bordo + 'color:var(--muted);text-align:right;white-space:nowrap;width:1%;vertical-align:top;')}
      ${td('🇮🇹', bordo + 'width:1%;white-space:nowrap;')}
      ${td(testoCella(r.it, r.itManuale, false, r.f, 'it'), bordo)}
    </tr>
    <tr onmouseover="this.style.background='var(--card2)'" onmouseout="this.style.background=''">
      ${td('', 'width:1%;')}
      ${td('🇺🇸', 'width:1%;white-space:nowrap;')}
      ${td(testoCella(r.en, r.enManuale, uguale, r.f, 'com'))}
    </tr>`;
  }).join('');

  const identici = ordinati.filter(r => r.it === r.en).length;
  const tagliati = ordinati.filter(r => ebayTitleStato(r.f, 'it') === 'tagliato' || ebayTitleStato(r.f, 'com') === 'tagliato').length;
  const btnRigenera = currentUser?.isAdmin ? `<div style="margin-bottom:0.75rem;">
    <button class="btn-primary btn-admin" onclick="ebayRigeneraTitoli()" style="font-size:0.82rem;padding:0.35rem 0.9rem;"
      title="${it ? 'Riscrive ebayTitleIt ed ebayTitleEn di TUTTI gli oggetti marcati Ebay dell\u2019Inventario' : 'Rewrites the IT and EN titles of EVERY item marked Ebay in the catalogue'}">${it ? '🔁 Rigenera tutti i titoli (tutto l’Inventario)' : '🔁 Regenerate all titles (whole catalogue)'}</button>
  </div>` : '';
  const th = (label, extra = '') => `<th style="padding:0.4rem 0.6rem;text-align:left;white-space:nowrap;color:var(--muted);${extra}">${label}</th>`;
  tableEl.innerHTML = selector + btnRigenera +
    `<p style="color:var(--muted);font-size:0.85rem;margin-bottom:0.75rem;">${it
      ? ordinati.length + (ordinati.length === 1 ? ' oggetto marcato Ebay' : ' oggetti marcati Ebay') + ', ordinati per titolo italiano; per ciascuno le due righe di mercato. ' +
        (tagliati ? tagliati + (tagliati === 1 ? ' porta la forbice ✂ (tagliato dentro il nome). ' : ' portano la forbice ✂ (tagliati dentro il nome). ') : '') +
        (identici ? identici + (identici === 1 ? ' ha' : ' hanno') + ' i due titoli identici (=): in quel testo non compare nessuna parola del glossario.' : 'Nessuna coppia identica.')
      : ordinati.length + ' item(s) marked Ebay, sorted by Italian title; two market rows each. ' +
        (identici ? identici + ' have identical titles (=): no glossary word appears in that text.' : 'No identical pair.')}</p>` +
    `<div style="overflow-x:auto;"><table class="data-table" style="border-spacing:0;width:100%;"><thead><tr>
      ${th('#', 'text-align:right;width:1%;')}${th(it ? 'Mercato' : 'Market', 'width:1%;')}${th(it ? 'Titolo' : 'Title')}
    </tr></thead><tbody>${rows}</tbody></table></div>`;
}

// v5.918 — "Titoli eccedenti la taglia ebay" (Franco). Elenca gli oggetti di questa serie
// MARCATI EBAY il cui titolo generato supera gli 80 caratteri e viene quindi troncato: sono i
// pezzi da guardare uno per uno, perché il taglio automatico non sa quale parte sia sacrificabile.
// Ordine: lo stesso della vista tabellare (cmpVistaTabellare), applicato dentro ciascuna sezione,
// con le sezioni nell'ordine della tabella qui sopra. Mostra titolo intero e titolo troncato
// affiancati: senza vedere cosa si perde, non si può decidere cosa riscrivere.
function renderEbayOversizeTable() {
  const box = document.getElementById('series-ebay-oversize');
  if (!box) return;
  const it = (currentLang === 'it');
  const eccedenti = EBAY_SECTIONS.flatMap(sec =>
    getData('figurines', [])
      .filter(f => f.seriesId === currentSeriesId && f.forSale && (f.section || 'figurines') === sec && ebayTitleEccede(f))
      .sort(cmpVistaTabellare(sec)));

  const titolo = `<h3 style="font-size:0.95rem;font-weight:700;color:var(--text);margin-bottom:0.4rem;">${it ? 'Titoli eccedenti la taglia ebay' : 'Titles over the eBay size limit'}</h3>`;
  if (!eccedenti.length) {
    box.innerHTML = titolo + `<p style="color:var(--muted);font-style:italic;font-size:0.88rem;">${it ? 'Nessun titolo viene tagliato dentro il nome: le regole automatiche bastano a farli stare tutti negli 80 caratteri.' : 'No title is cut inside the name: the automatic rules keep them all within 80 characters.'}</p>`;
    return;
  }
  const esc = s => (s || '').replace(/</g, '&lt;');
  const td = (c, extra = '') => `<td style="padding:0.4rem 0.6rem;font-size:0.82rem;${extra}">${c}</td>`;
  // v5.921 — ordinabile anche questa: qui la colonna che serve davvero è "Caratteri", per
  // partire dai titoli che sforano di più.
  const ordinati = ebayApplicaSort(eccedenti, '_oversize', {
    sezione:  f => ebaySectionLabel(f.section || 'figurines'),
    nome:     f => f.fullName || f.name || '',
    troncato: f => ebayTitle(f),
    intero:   f => ebayTitleFull(f),
    caratteri: f => ebayTitleFull(f).length
  });
  const rows = ordinati.map((f, i) => {
    const intero = ebayTitleFull(f), troncato = ebayTitle(f);
    const perse = intero.length - EBAY_TITLE_MAX;
    // v5.926 — anche qui il comando è la ✎ a fine riga (non la riga intera), e apre la form.
    return `<tr onmouseover="this.style.background='var(--card2)'" onmouseout="this.style.background=''">
      ${td(i + 1, 'color:var(--muted);text-align:right;white-space:nowrap;width:1%;')}
      ${td(ebaySectionLabel(f.section || 'figurines'), 'color:var(--muted);white-space:nowrap;')}
      ${td(esc(f.fullName || f.name))}
      ${td(esc(troncato), 'color:var(--text);')}
      ${td(esc(intero), 'color:var(--muted);')}
      ${td('<strong>' + intero.length + '</strong> <span style="color:var(--action-admin);">(+' + perse + ')</span>', 'white-space:nowrap;text-align:right;')}
      ${td(ebayApriBtn(f.id), 'width:1%;text-align:center;')}
    </tr>`;
  }).join('');
  box.innerHTML = titolo +
    `<p style="color:var(--muted);font-size:0.85rem;margin-bottom:0.75rem;">${it
      ? 'Qui finiscono solo i titoli che non si salvano con le regole automatiche: tolta la coda "- Gpk - Topps" restano comunque oltre gli 80 caratteri, e il taglio cade dentro il nome. ' + eccedenti.length + (eccedenti.length === 1 ? ' oggetto' : ' oggetti') + ' da riscrivere a mano.'
      : 'Only titles the automatic rules cannot save: even without the "- Gpk - Topps" tail they exceed 80 characters, so the cut falls inside the name. ' + eccedenti.length + ' item(s) to rewrite by hand.'}</p>` +
    `<div style="overflow-x:auto;"><table class="data-table" style="border-spacing:0;width:100%;"><thead><tr>
      <th style="padding:0.4rem 0.6rem;text-align:right;white-space:nowrap;color:var(--muted);width:1%;">#</th>${ebayTh('_oversize', 'sezione', it ? 'Sezione' : 'Section')}${ebayTh('_oversize', 'nome', it ? 'Nome completo' : 'Full name')}${ebayTh('_oversize', 'troncato', it ? 'Titolo troncato (80)' : 'Truncated title (80)')}${ebayTh('_oversize', 'intero', it ? 'Titolo intero' : 'Full title')}${ebayTh('_oversize', 'caratteri', it ? 'Caratteri' : 'Chars')}<th style="width:1%;"></th>
    </tr></thead><tbody>${rows}</tbody></table></div>`;
}

// v6.186 (🔴) - IL RIPRISTINO DEI CAMPI DELLA SERIE, IN UN POSTO SOLO.
// `openAddSeriesModal` ha due rami che riusano la STESSA form, e fino alla v6.185 solo uno dei due
// rimetteva a posto le caselle. Il ramo MODIFICA ne ripristinava otto su otto (v6.169 + v6.170);
// il ramo CREAZIONE ne azzerava TRE - `hasUnofficialVariations`, `hasChange`, `noNumbers` - e
// lasciava le altre cinque con il valore dell'ultima serie aperta. Piu' `nomeCorto` (un campo di
// testo che restava pieno) e i controlli sospesi, riempiti solo dal ramo modifica.
// `saveSeries` e' una sola e legge tutto: quindi aprire una serie e poi premere "Aggiungi serie"
// faceva NASCERE la serie nuova con i flag di quella prima, in silenzio.
// E' la stessa forma del guasto della v6.169, nel ramo gemello. Non azzera dati esistenti - li
// crea sbagliati - ma e' altrettanto muto.
// 📌 Il rimedio non e' "aggiungere le cinque righe mancanti nell'else": sarebbero DUE elenchi da
// tenere allineati a mano, cioe' il difetto stesso rimandato alla prossima casella. La v6.162
// aveva gia' risolto identicamente per i campi delle colonne (azzeramento fuori dai due rami), e
// la v6.143 aveva gia' insegnato la forma: si ESTRAE, non si duplica.
// Da qui in avanti una casella nuova sulla serie si aggiunge in UN posto, e i due rami la ereditano.
// v6.216 - l'elenco di un RECORD (non di un id): la usa il ripristino, che ha la serie in mano.
// Stessa regola di `_articoliNascosti`, e il ripiego sui due flag sparira' al passo 3.
function _articoliNascostiDaRecord(s) {
  if (!s) return [];
  if (Array.isArray(s.articoliNascosti)) return s.articoliNascosti;
  const da = [];
  if (s.noAlbums) da.push('albums');
  if (s.noRetro)  da.push('retros');
  return da;
}

function _ripristinaFlagSerie(s) {
  const spunta = (id, v) => { const el = document.getElementById(id); if (el) el.checked = !!v; };
  spunta('series-has-unofficial-variations-input', s && s.hasUnofficialVariations);
  spunta('series-has-change-input',                s && s.hasChange);
  spunta('series-has-retro-change-input',          s && s.hasRetroChange);   // v6.170
  spunta('series-no-numbers-input',                s && s.noNumbers);
  // v6.216 - le due caselle singole sono diventate l'elenco. ⚠️ Con `s` a null (creazione) si
  // spengono tutte: e' la ragione per cui questa funzione esiste dalla v6.186.
  {
    const nascosti = _articoliNascostiDaRecord(s);
    document.querySelectorAll('.series-articolo-nascosto').forEach(x => { x.checked = nascosti.includes(x.value); });
  }
  spunta('series-contenitore-input',               s && s.serieContenitore); // v6.204
  spunta('series-has-subseries-input',             s && s.hasSubseries);     // v6.169
  spunta('series-has-sizes-input',                 s && s.hasSizes);         // v6.169
  spunta('series-has-variations-input',            s && s.hasVariations);    // v6.169
  // 🔴 v6.219 - IL FLAG NUOVO, E QUESTA E' LA RIGA PIU' IMPORTANTE DELLA RELEASE. Senza, la
  // casella si aprirebbe sempre spenta, `saveSeries` la leggerebbe e scriverebbe `false`: il
  // guasto della v6.169 ricreato da capo su un campo appena nato. Nove flag, nove ripristini.
  spunta('series-has-print-error-input',           s && s.hasPrintError);    // v6.219
  // 🔴 v6.235 - il flag nuovo, e vale l'avvertimento della v6.219 qui sopra: senza questa riga la
  // casella si aprirebbe sempre spenta e `saveSeries` scriverebbe `false` a ogni salvataggio.
  // Dieci flag, dieci ripristini.
  spunta('series-has-free-version-input',          s && s.hasFreeVersion);        // v6.235
  spunta('series-has-retro-free-version-input',    s && s.hasRetroFreeVersion);   // v6.248
  const nc = document.getElementById('series-nome-corto-input');
  if (nc) nc.value = (s && s.nomeCorto) || '';                               // v6.080
  renderSeriesBypassCheckboxes(s && s.controlliSospesi);                     // v6.080
  // Dipende da `noRetro`, quindi va DOPO le spunte e non prima: e' il motivo per cui sta qui
  // dentro invece che nei due rami.
  _aggiornaRigaColonneRetro();
}
// \uD83D\uDD34 v6.215 - LA TABELLA DELLE COLONNE NELLA SCHEDA SERIE, GENERATA.
// Fino alla v6.214 era markup scritto a mano nell'index, con CINQUE righe - e gli articoli sono
// SEI dalla v6.195. La riga di "Figurine da attaccare" non c'e' mai stata.
//
// \uD83D\uDCCC E NESSUNO SE N'E' ACCORTO PER VENTI RELEASE, perche' il difetto e' muto per costruzione:
// `openAddSeriesModal` riempie i campi con `Object.keys(COLONNE_DEFAULT).forEach`, e per ogni
// sezione fa `document.getElementById('series-col-' + sez + '-d')`. Per `attaccare` quel campo non
// esiste, `getElementById` torna `null`, e la riga `if (cd)` lo salta. Nessun errore, nessun avviso.
// ⚠️ Al SALVATAGGIO succede lo stesso dall'altra parte: `saveSeries` legge quel campo, non lo
// trova, e scrive il valore di partenza. Quindi la sesta sezione aveva le colonne bloccate sul
// default e non c'era modo di cambiarle - e la tabella non lo diceva, perche' la riga mancava.
//
// \uD83D\uDD34 IL CHANGELOG DELLA v6.195 AFFERMAVA IL CONTRARIO: *"questa riga da' GRATIS la sesta
// coppia di campi nella form della serie: quei campi non sono scritti a mano nell'index, li genera
// Object.keys(COLONNE_DEFAULT)"*. Era falso: quel ciclo RIEMPIE campi che esistono, non li CREA.
// E' il difetto della v6.157 per la quinta volta - **verificato che il codice fosse cambiato, non
// che il cambiamento avesse un effetto** - ed e' stato trovato da Franco guardando, come le altre
// quattro. Il controllo che l'avrebbe preso costava dieci secondi: contare le righe della tabella.
//
// Da qui in avanti la tabella si genera dal descrittore: le righe sono quante sono gli articoli,
// nel loro ordine, e un settimo articolo comparirebbe da se'. Come il pannello Griglie di
// visualizzazione, che infatti le sei righe le mostrava gia' - ed e' l'unico motivo per cui i due
// posti dicevano cose diverse sulla stessa cosa.
// v6.216 - le caselle "articoli che questa serie non ha", generate dal descrittore come la tabella
// delle colonne. Un articolo nuovo porta la sua casella da se'.
// ⚠️ `onchange` su tutte: la riga delle colonne dei Retro si mostra o si nasconde a seconda che
// i Retro ci siano, e quella regola sta in `_aggiornaRigaColonneRetro`. Prima era attaccata alla
// casella "Figurine senza retro", che questa release toglie.
function _caselleArticoliSerie() {
  const box = document.getElementById('series-articoli-nascosti');
  if (!box) return;
  box.innerHTML = PRODOTTI_INVENTARIO.map(sez =>
    '<label style="display:flex;align-items:center;gap:0.4rem;cursor:pointer;font-size:0.85rem;">' +
      '<input type="checkbox" class="series-articolo-nascosto" value="' + sez + '" ' +
        'onchange="_aggiornaRigaColonneRetro()" ' +
        'style="width:15px;height:15px;cursor:pointer;flex-shrink:0;">' +
      // v6.229 (Franco: "lo metterei in bianco") - i nomi degli articoli erano `--muted`, cioe' lo
      // stesso grigio-viola dei SUGGERIMENTI. Ma questi non sono un suggerimento: sono le sei cose
      // fra cui si sceglie, e stavano piu' spente della frase che le spiega.
      '<span style="color:var(--text);">' + esc(getSectionLabel(sez)) + '</span>' +
    '</label>').join('');
}
function _leggiArticoliNascosti() {
  return [...document.querySelectorAll('.series-articolo-nascosto')].filter(x => x.checked).map(x => x.value);
}

function _tabellaColonneSerie() {
  const box = document.getElementById('series-colonne-tabella');
  if (!box) return;
  const cella = 'padding:3px 6px;';
  box.innerHTML =
    '<table style="border-collapse:collapse;margin-top:0.2rem;">' +
    '<tr><td></td>' +
      '<td style="padding:0 6px;font-size:0.76rem;color:var(--muted);">desktop</td>' +
      '<td style="padding:0 6px;font-size:0.76rem;color:var(--muted);">mobile</td></tr>' +
    PRODOTTI_INVENTARIO.map(sez =>
      '<tr><td style="padding:3px 8px 3px 0;font-size:0.84rem;color:var(--text);white-space:nowrap;">' +
        esc(getSectionLabel(sez)) + '</td>' +
      ['d', 'm'].map(q =>
        '<td style="' + cella + '"><input class="form-input" type="number" min="1" max="12" ' +
        'id="series-col-' + sez + '-' + q + '" ' +
        'style="width:70px;padding:0.25rem 0.4rem;font-size:0.85rem;"></td>').join('') +
      '</tr>').join('') +
    '</table>';
}

// v6.217 - I QUATTRO TAB DELLA SCHEDA SERIE. Scritta come `switchLinkedFigTab`, che cicla su
// classe + `data-tab` invece di elencare gli id: con quattro tab (e un quinto sempre possibile)
// elencarli sarebbe stato un altro posto dove ricordarsi di aggiungerli.
// 🔴 `display:none`, MAI un `remove()`: i campi degli altri tre tab devono restare nel DOM, perche'
// `saveSeries` li legge tutti a ogni salvataggio e cio' che non trova lo scrive vuoto o `false`.
function switchSeriesTab(key) {
  document.querySelectorAll('#add-series-modal .series-tab-btn').forEach(btn => {
    const active = btn.getAttribute('data-tab') === key;
    btn.style.borderBottomColor = active ? 'var(--accent)' : 'transparent';
    btn.style.color = active ? 'var(--accent)' : 'var(--muted)';
    btn.style.fontWeight = active ? '600' : '400';
  });
  document.querySelectorAll('#add-series-modal .series-tab-panel').forEach(panel => {
    panel.style.display = panel.getAttribute('data-tab') === key ? '' : 'none';
  });
}

function openAddSeriesModal(seriesId) {
  // v6.215 - la tabella si disegna PRIMA di tutto il resto: le righe qui sotto riempiono campi che
  // devono gia' esistere. Invertire l'ordine riprodurrebbe esattamente il difetto che questa
  // release chiude, e senza dare errore.
  _tabellaColonneSerie();
  _caselleArticoliSerie();   // v6.216 - anche queste PRIMA del ripristino, che le spunta
  if (!currentUser?.isAdmin) { toast((currentLang === 'it' ? 'Solo per admin' : 'Admin only'), 'error'); return; }
  document.getElementById('edit-series-id').value = seriesId || '';
  // v6.162 - la form si riusa fra creazione e modifica: i due campi si azzerano sempre, e in
  // modifica vengono riempiti sotto. Senza, creando una serie dopo averne modificata un'altra si
  // ereditavano le sue colonne senza che nessuno l'avesse chiesto.
  // v6.163 - in CREAZIONE i campi partono dai default, non vuoti: sono obbligatori, e una serie
  // nuova deve nascere con la disposizione di sempre invece che con dieci caselle da riempire.
  Object.keys(COLONNE_DEFAULT).forEach(sez => {
    const cd = document.getElementById('series-col-' + sez + '-d');
    const cm = document.getElementById('series-col-' + sez + '-m');
    if (cd) cd.value = _colonneDefault(sez).d;   // v6.197
    if (cm) cm.value = _colonneDefault(sez).m;   // v6.197
  });
  _aggiornaRigaColonneRetro();   // v6.169 - anche in creazione
  document.getElementById('series-modal-title').textContent = seriesId ? t('modal.series.edit') : t('modal.series.title');
  document.getElementById('series-img-preview').style.display = 'none';
  editingSeriesImg = null;
  // \uD83D\uDD34 v6.189 - QUESTA RIGA MANCAVA, ed era la gemella dimenticata della riga sopra.
  // `editingSeriesImg` (l'URL di quella salvata) veniva azzerata, `editingSeriesImgFile` (il file
  // scelto e non ancora caricato) no. Quindi: apri una serie, scegli una foto nuova, NON salvare,
  // apri un'altra serie o creane una -> quel file e' ancora in canna, e `saveSeries` lo guarda per
  // primo. La foto finiva sulla serie sbagliata, senza che niente lo dicesse.
  // Stessa famiglia della v6.186, e la stessa forma: due variabili che descrivono la stessa cosa,
  // una azzerata e l'altra no. Con la v6.189 morde di piu', perche' ora da qui puo' uscire anche
  // un PNG appena elaborato.
  // Anche il campo file si svuota: se no continua a mostrare il nome del file di prima, e a un
  // `<input type=file>` non si puo' assegnare un valore diverso da ''.
  editingSeriesImgFile = null;
  { const f = document.getElementById('series-img-file'); if (f) f.value = ''; }
  { const b = document.getElementById('series-remove-bg-btn');
    if (b) { b.disabled = false; b.textContent = _ETICHETTA_SFONDO(); } }
  if (seriesId) {
    const s = getData('series', []).find(x => x.id === seriesId);
    // v6.186 - FUORI dal `if (s)`: se la serie non si trovasse, le caselle resterebbero quelle di
    // prima, che e' lo stesso difetto un gradino piu' in la'.
    _ripristinaFlagSerie(s || null);
    if (s) {
      document.getElementById('series-name-input').value = s.name;
      document.getElementById('series-year-input').value = s.year;
      // (series-count-input NON si riempie piu' da s.count: e' calcolato piu' sotto
      //  da updateSeriesVariationCounts. Scrivere qui il valore vecchio significava
      //  mostrarlo per un istante prima di sovrascriverlo — e tenere in vita un campo
      //  che l'admin credeva ancora di controllare.)
      document.getElementById('series-first-number-input').value = s.firstNumber || '';
      document.getElementById('series-last-number-input').value = s.lastNumber || '';
      document.getElementById('series-album-count-input').value = s.albumCount || '';
      // v6.186 - le otto spunte, `nomeCorto` e i controlli sospesi sono passati in
      //          `_ripristinaFlagSerie`, chiamata qui sopra per tutti e due i rami.
      // 🔴 v6.170 — LA CASELLA NUOVA VA RIPRISTINATA QUI, e questa riga e' la piu' importante della
      // release. E' il flag aggiunto oggi: se il ripristino manca, si apre sempre spenta, il
      // salvataggio la legge e scrive `false` — cioe' si ricrea da capo, su un campo nuovo, il
      // guasto che la v6.169 ha appena chiuso. Otto flag, otto ripristini: si contano.

    // 🔴 v6.169 (Franco, sul sintomo: "HA SOTTOSERIE non mostra SI per Sgorbions Holidays, che ha il
    // campo a TRUE") - QUESTE TRE RIGHE MANCAVANO. Quattro flag su sette venivano ripristinati
    // riaprendo una serie, tre no: `hasSubseries`, `hasSizes`, `hasVariations`. Una casella non
    // ripristinata si apre SPENTA, e il salvataggio la legge e scrive `false`.
    // ⚠️ Quindi ogni volta che si apriva una serie e la si salvava — anche solo per cambiare il
    // nome — quei tre flag venivano azzerati in silenzio. Non e' un'ipotesi: misurato sui dati veri
    // il 14 agosto, `hasSubseries`, `hasSizes` e `hasVariations` erano false su TUTTE E 13 le serie,
    // mentre i dati dicono il contrario — tre serie hanno oggetti con la sottoserie, una ha le
    // taglie, Serie 1 ha variazioni vere. I quattro flag ripristinati invece sopravvivono
    // (`hasChange` 1, `noNumbers` 4): la controprova sta nella differenza.
    // 📌 E' esattamente il guasto che il codice descrive altrove e che qui nessuno aveva collegato:
    // "un campo che al salvataggio viene sovrascritto non si mostra modificabile" (v6.038), e la
    // nota di `fe-no-number` — "la casella resta SEMPRE nel DOM: il salvataggio la legge, e se non
    // la trova scrive false. Toglierla avrebbe azzerato il flag in silenzio al primo salvataggio".
    // Qui la casella c'era: a mancare era il ripristino, che produce lo stesso effetto.

    // v6.162 - le colonne della griglia. `?? ''` e non `|| ''`: uno zero salvato per errore deve
    // ricomparire nel campo, se no si corregge un dato che non si vede.
    // v6.163 - precompilati: se la serie ha un valore suo si mostra quello, se no il default, che e'
    // il numero che il sito usa oggi. Un campo obbligatorio non si apre mai vuoto.
    Object.keys(COLONNE_DEFAULT).forEach(sez => {
      const cfg = (s.colonne && s.colonne[sez]) || {};
      const cd = document.getElementById('series-col-' + sez + '-d');
      const cm = document.getElementById('series-col-' + sez + '-m');
      if (cd) cd.value = _colClamp(cfg.d) || _colonneDefault(sez).d;   // v6.197
      if (cm) cm.value = _colClamp(cfg.m) || _colonneDefault(sez).m;   // v6.197
    });

      document.getElementById('series-desc-input').value = s.descIt || s.desc || '';
      const descEnInput = document.getElementById('series-desc-en-input');
      if (descEnInput) descEnInput.value = s.desc || '';
      const rctInput = document.getElementById('series-retro-change-types-input');
      if (rctInput) rctInput.value = (s.retroChangeTypes || []).join('\n');
      // v6.102 (§12.10) - la seconda lista. `|| []` non e' pro forma: le serie salvate prima della
      // v6.102 il campo non ce l'hanno affatto, e senza il ripiego qui finirebbe "undefined"
      // scritto dentro la casella, che al primo salvataggio diventerebbe un tipo di change.
      const fctInput = document.getElementById('series-front-change-types-input');
      if (fctInput) fctInput.value = (s.frontChangeTypes || []).join('\n');
      // v6.241 - i tipi di omaggio. `|| []` per la stessa ragione detta qui sopra: nessuna serie
      // salvata prima di oggi ha questo campo, e senza ripiego finirebbe "undefined" dentro la
      // casella — che al primo salvataggio diventerebbe un tipo di omaggio chiamato "undefined".
      // v6.246 - due caselle. Il ripiego sul campo unico della v6.241 vale solo per la frontale.
      const rfvInput = document.getElementById('series-retro-free-version-types-input');
      if (rfvInput) rfvInput.value = (s.retroFreeVersionTypes || []).join('\n');
      const ffvInput = document.getElementById('series-front-free-version-types-input');
      if (ffvInput) ffvInput.value = (s.frontFreeVersionTypes || s.freeVersionTypes || []).join('\n');

      if (s.img) { const pr = document.getElementById('series-img-preview'); pr.src = s.img; pr.style.display = 'block'; editingSeriesImg = s.img; }
    }
  } else {
    ['series-name-input','series-year-input','series-count-input','series-first-number-input','series-last-number-input','series-album-count-input','series-desc-input','series-desc-en-input'].forEach(id => document.getElementById(id).value = '');
    // 🔴 v6.186 - QUI STAVA IL BUCO: si azzeravano TRE caselle su otto, e le altre cinque
    //             (`hasRetroChange`, `noRetro`, `hasSubseries`, `hasSizes`, `hasVariations`) piu'
    //             `nomeCorto` e i controlli sospesi restavano quelli dell'ultima serie aperta.
    //             `null` vuol dire "nessuna serie": azzera tutto, in un posto solo.
    _ripristinaFlagSerie(null);
    const rctInput = document.getElementById('series-retro-change-types-input');
    if (rctInput) rctInput.value = '';
    // v6.102 (§12.10) - anche la seconda casella va svuotata per una serie NUOVA. La riga sopra
    // esiste per lo stesso motivo: senza, la serie nuova nascerebbe con i tipi di quella aperta
    // prima, e nessuno lo direbbe. Aggiungere una casella e dimenticare questo punto e' il modo
    // in cui il reset resta indietro di un campo per mesi.
    const fctInput = document.getElementById('series-front-change-types-input');
    if (fctInput) fctInput.value = '';
    // v6.241 - la terza casella. Il commento qui sopra dice perche' esistono queste righe:
    // dimenticarne una fa nascere la serie nuova con l'elenco di quella aperta prima, e nessuno
    // lo segnala. E' il punto in cui "aggiungere una casella" resta indietro per mesi.
    const rfvInput = document.getElementById('series-retro-free-version-types-input');
    if (rfvInput) rfvInput.value = '';
    const ffvInput = document.getElementById('series-front-free-version-types-input');
    if (ffvInput) ffvInput.value = '';
  }
  updateSeriesVariationCounts(seriesId || null);
  toggleSeriesCountGroups();
  _aggiornaPulsanteEliminaSerie(seriesId || null);   // v6.171
  // Flag visibili solo per admin (ora dentro label in griglia 2 colonne)
  const hasSizesGroup = document.getElementById('series-has-sizes-input')?.closest('.form-group');
  if (hasSizesGroup) hasSizesGroup.style.display = currentUser?.isAdmin ? '' : 'none';
  const hasSubseriesGroup = document.getElementById('series-has-subseries-group');
  if (hasSubseriesGroup) hasSubseriesGroup.style.display = currentUser?.isAdmin ? '' : 'none';
  const hasVariationsGroup = document.getElementById('series-has-variations-input')?.closest('.form-group');
  if (hasVariationsGroup) hasVariationsGroup.style.display = currentUser?.isAdmin ? '' : 'none';
  // v6.217 - si apre SEMPRE sul primo tab. Nella scheda oggetto il tab resta dov'eri passando a
  // Modifica, ed e' giusto li': e' lo stesso oggetto guardato in due modi. Qui ogni apertura e'
  // un'altra serie, e non c'e' nessun passaggio lettura/modifica da cui tornare.
  switchSeriesTab('serie');
  document.getElementById('add-series-modal').classList.remove('hidden');
}
function handleSeriesImg(e) {
  const file = e.target.files[0]; if (!file) return;
  editingSeriesImgFile = file;
  const reader = new FileReader();
  reader.onload = ev => {
    const pr = document.getElementById('series-img-preview');
    pr.src = ev.target.result; pr.style.display = 'block';
  };
  reader.readAsDataURL(file);
}
let editingSeriesImgFile = null;
async function saveSeries() {
  const name = document.getElementById('series-name-input').value.trim();
  const year = document.getElementById('series-year-input').value;
  const hasSizes = document.getElementById('series-has-sizes-input').checked;
  // v6.162 - le colonne della griglia. Vuoto -> `null`, che e' "non deciso": zero direbbe "nessuna
  // colonna", ed e' un'altra cosa.
  // v6.163 - dieci campi (cinque sezioni x due) in un oggetto solo. Dove il campo e' vuoto o storto
  // si rimette il DEFAULT invece di `null`: i campi sono obbligatori, e "vuoto" non e' uno stato
  // ammesso — se lo fosse, la griglia tornerebbe al CSS senza che nessuno l'abbia chiesto.
  const colonne = {};
  Object.keys(COLONNE_DEFAULT).forEach(sez => {
    const d = _colClamp(document.getElementById('series-col-' + sez + '-d')?.value);
    const m = _colClamp(document.getElementById('series-col-' + sez + '-m')?.value);
    colonne[sez] = { d: d || _colonneDefault(sez).d, m: m || _colonneDefault(sez).m };   // v6.197
  });
  const hasSubseries = document.getElementById('series-has-subseries-input').checked;
  const hasVariations = document.getElementById('series-has-variations-input')?.checked || false;
  const hasUnofficialVariations = document.getElementById('series-has-unofficial-variations-input')?.checked || false;
  const hasChange = document.getElementById('series-has-change-input')?.checked || false;
  const hasRetroChange = document.getElementById('series-has-retro-change-input')?.checked || false;   // v6.170
  const hasPrintError = document.getElementById('series-has-print-error-input')?.checked || false;     // v6.219
  const hasFreeVersion = document.getElementById('series-has-free-version-input')?.checked || false;            // v6.235
  const hasRetroFreeVersion = document.getElementById('series-has-retro-free-version-input')?.checked || false;  // v6.248
  const noNumbers = document.getElementById('series-no-numbers-input')?.checked || false;
  // \uD83D\uDD34 v6.216 - PASSO 1: si scrive l'elenco E si tengono ALLINEATI i due vecchi flag. Non e'
  // ridondanza: fra la migrazione (passo 2) e lo spostamento dei lettori (passo 3) i lettori
  // guardano ancora i vecchi, e se restassero indietro mostrerebbero la cosa sbagliata. Queste due
  // righe spariscono al passo 3, e i campi al passo 4.
  const articoliNascosti = _leggiArticoliNascosti();
  const noRetro = articoliNascosti.includes('retros');
  const noAlbums = articoliNascosti.includes('albums');

  const serieContenitore = document.getElementById('series-contenitore-input')?.checked || false; // v6.204
  const controlliSospesi = _leggiControlliSospesi(); // v6.080
  const nomeCorto = (document.getElementById('series-nome-corto-input')?.value || '').trim(); // v6.080
  const countVariations = parseInt(document.getElementById('series-count-variations-input').value) || null;
  const countUnofficialVariations = parseInt(document.getElementById('series-count-unofficial-variations-input').value) || null;
  const countChange = parseInt(document.getElementById('series-count-change-input').value) || null;
  const countRetroChange = parseInt(document.getElementById('series-count-retro-change-input')?.value) || null;   // v6.170
  const countPrintError = parseInt(document.getElementById('series-count-print-error-input')?.value) || null;     // v6.219
  const countFreeVersion = parseInt(document.getElementById('series-count-free-version-input')?.value) || null;             // v6.235
  const countRetroFreeVersion = parseInt(document.getElementById('series-count-retro-free-version-input')?.value) || null;   // v6.248
  const count = document.getElementById('series-count-input').value;
  const firstNumber = parseInt(document.getElementById('series-first-number-input').value) || null;
  const lastNumber = parseInt(document.getElementById('series-last-number-input').value) || null;
  const albumCount = parseInt(document.getElementById('series-album-count-input').value) || null;
  const descIt = document.getElementById('series-desc-input').value.trim();
  const desc = document.getElementById('series-desc-en-input').value.trim();
  // v6.246 - i tipi di omaggio, DUE liste come i change: uno per riga.
  const retroFreeVersionTypes = (document.getElementById('series-retro-free-version-types-input')?.value || '')
    .split('\n').map(v => v.trim()).filter(Boolean);
  const frontFreeVersionTypes = (document.getElementById('series-front-free-version-types-input')?.value || '')
    .split('\n').map(v => v.trim()).filter(Boolean);
  let retroChangeTypes = (document.getElementById('series-retro-change-types-input')?.value || '')
    .split('\n').map(v => v.trim()).filter(Boolean);
  // "Errore di stampa" NON puo' piu' stare qui (v5.713): dalla v5.711 e' un TIPO a se'
  // (isPrintError), non un sottotipo di Change. Se restasse fra i "Tipi di change", lo
  // stesso concetto sarebbe rappresentabile in DUE modi — ed e' esattamente la doppia
  // verita' che la v5.711 aveva chiuso. Lo tolgo, e LO DICO: toglierlo in silenzio
  // farebbe pensare a Franco di averlo scritto male.
  if (retroChangeTypes.some(t => /^error[ei]\s+di\s+stampa$/i.test(t))) {
    retroChangeTypes = retroChangeTypes.filter(t => !/^error[ei]\s+di\s+stampa$/i.test(t));
    toast(currentLang === 'it'
      ? '"Errore di stampa" non \u00e8 pi\u00f9 un tipo di change: ora \u00e8 un tipo di oggetto a s\u00e9. L\u2019ho tolto dalla lista.'
      : '"Print error" is no longer a change type: it is now an object type of its own. Removed from the list.',
      'info');
  }
  // v6.102 (§12.10) - la seconda lista: i tipi di change che riguardano il FRONTE.
  const frontChangeTypes = (document.getElementById('series-front-change-types-input')?.value || '')
    .split('\n').map(v => v.trim()).filter(Boolean);
  // Lo stesso tipo in tutte e due le liste e' una contraddizione: non si puo' sapere da che lato
  // sta un change di quel tipo, che e' esattamente il problema che questa release chiude.
  // Si BLOCCA e si dice quali sono, invece di scegliere una lista al posto di Franco: davanti a due
  // dati che si contraddicono un programma non ne sceglie uno, li fa vedere tutti e due (lezione
  // della v6.101, pagata su "Non ha numero").
  const _inEntrambe = frontChangeTypes.filter(f =>
    retroChangeTypes.some(r => r.toLowerCase().trim() === f.toLowerCase().trim()));
  if (_inEntrambe.length) {
    toast((currentLang === 'it'
      ? 'Questi tipi sono in tutte e due le liste, e un change non puo’ essere frontale e di retro insieme: ' + _inEntrambe.join(', ') + '. Lascialo in una sola.'
      : 'These types are in both lists, and a change cannot be front and back at once: ' + _inEntrambe.join(', ') + '. Keep it in one only.'),
      'error', null, 7000);
    return;
  }
  // v6.188 (Franco: "ho creato una serie dimenticandomi di mettere il nome corto e la ha creata")
  // - il NOME CORTO entra fra gli obbligatori. Fino alla v6.187 il vuoto era uno stato ammesso e
  // documentato ("Vuoto = nome per esteso"), quindi questa release non chiude un buco: CAMBIA UNA
  // REGOLA, e il campo che la diceva - il suggerimento sotto la casella - e' stato cambiato
  // insieme, nella stessa passata. Un vincolo nuovo con accanto la vecchia frase che lo smentisce
  // e' peggio di nessuno dei due.
  // ⚠️ VALE ANCHE IN MODIFICA, ed e' una conseguenza da conoscere e non da scoprire: una serie
  // nata senza nome corto non si salva piu' - nemmeno per cambiarle il nome - finche' non gliene
  // si da' uno. E' voluto: se valesse solo in creazione, quelle vecchie resterebbero senza per
  // sempre e il vincolo sarebbe vero solo per meta' dei dati.
  // 📌 Il ripiego in `_nomeSerieCard` (`corto ? corto : s.name`) RESTA, e non e' una svista: i
  // record gia' su Firestore il nome corto non ce l'hanno ancora, e la card si disegna prima che
  // qualcuno abbia riaperto quella serie. Una regola sulla form non e' una garanzia sul dato -
  // scambiare le due cose e' come dare per scritto cio' che si e' solo reso obbligatorio.
  if (!name || !year || !nomeCorto) {
    // v6.220 - "nome corto" -> "nome breve" anche qui: e' l'altra scritta visibile di quel campo,
    // e un messaggio che nomina un campo con un nome che sulla form non c'e' piu' manda a
    // cercarlo.
    toast((currentLang === 'it' ? 'Nome, nome breve e anno sono obbligatori' : 'Name, short name and year are required'), 'error');
    return;
  }
  const fb = document.getElementById('series-save-feedback');
  const btn = document.querySelector('#add-series-modal .btn-primary');
  if (fb) { fb.style.display = ''; fb.textContent = (currentLang === 'it' ? '⏳ Salvataggio in corso...' : '⏳ Saving...'); }
  if (btn) btn.disabled = true;
  // v6.190 - armato PRIMA del caricamento immagine, che sulla rete lenta e' il pezzo piu' lungo.
  const _stopAvviso = _avvisaScritturaLenta(() => { if (fb) fb.textContent = _TESTO_SCRITTURA_LENTA(); });
  // Rimette la form nello stato di riposo. Serve su ogni uscita che NON e' la riuscita.
  const _fineAttesa = () => {
    _stopAvviso();
    if (btn) btn.disabled = false;
    if (fb) { fb.style.display = 'none'; fb.textContent = ''; }
  };
  let imgUrl = editingSeriesImg || null;
  if (editingSeriesImgFile) {
    try { imgUrl = await uploadToCloudinary(editingSeriesImgFile); }
    // 🔴 v6.190 - QUESTO `return` LASCIAVA LA FORM MORTA. Il pulsante era gia' stato spento due
    // righe sopra e qui non lo riaccendeva nessuno: dopo un errore di caricamento immagine
    // restavano "Salvataggio in corso" e il tasto Salva spento, per sempre, e l'unico modo di
    // uscirne era chiudere la finestra. Non e' un difetto di questa release: e' un'uscita
    // anticipata che non rimetteva a posto quello che l'ingresso aveva toccato - la ragione per
    // cui la v6.052 aveva messo un `finally` nell'altra form.
    catch(e) { _fineAttesa(); toast((currentLang === 'it' ? 'Errore nel caricamento immagine' : 'Image upload error'), 'error'); return; }
  }
  let series = getData('series', []);
  const editId = document.getElementById('edit-series-id').value;
  try {
    if (editId) {
      const idx = series.findIndex(x => x.id === editId);
      if (idx >= 0) {
        series[idx] = { ...series[idx], colonne, name, year: +year, count: +count, firstNumber: firstNumber || series[idx].firstNumber || null, lastNumber: lastNumber || series[idx].lastNumber || null, albumCount: albumCount ?? series[idx].albumCount ?? null, desc, descIt, img: imgUrl || series[idx].img, hasSizes, hasSubseries, hasVariations, hasUnofficialVariations, hasChange, hasRetroChange /* v6.170 */, hasPrintError /* v6.219 */, hasFreeVersion, hasRetroFreeVersion /* v6.248 */, nomeCorto, controlliSospesi, noNumbers, noRetro, noAlbums /* v6.194 */, serieContenitore /* v6.204 */, articoliNascosti /* v6.216 */, countVariations: countVariations ?? series[idx].countVariations ?? null, countUnofficialVariations: countUnofficialVariations ?? series[idx].countUnofficialVariations ?? null, countChange: countChange ?? series[idx].countChange ?? null, countRetroChange: countRetroChange ?? series[idx].countRetroChange ?? null /* v6.170 */, countPrintError: countPrintError ?? series[idx].countPrintError ?? null /* v6.219 */, countFreeVersion: countFreeVersion ?? series[idx].countFreeVersion ?? null, countRetroFreeVersion: countRetroFreeVersion ?? series[idx].countRetroFreeVersion ?? null /* v6.248 */, retroChangeTypes, frontChangeTypes /* v6.102 */, retroFreeVersionTypes, frontFreeVersionTypes /* v6.246 */ };
        // 🔴 v6.172 - IL PAYLOAD NON PORTA PIU' `items`. Vedi `_serieSenzaItems`: qui cambiano
        // nome, anno, spunte e conteggi — campi di livello serie — e il documento intero partiva
        // lo stesso, 521 KB per Serie 3, perche' lo spread qui sopra si porta dietro gli oggetti.
        await fsSave('series', _serieSenzaItems(series[idx]));
        _cache.series = series;   // la CACHE tiene gli items: si strippa solo cio' che parte
      }
    } else {
      const newS = { colonne, name, year: +year, count: +count||0, firstNumber: firstNumber || null, lastNumber: lastNumber || null, albumCount: albumCount ?? null, desc, descIt, img: imgUrl, hasSizes, hasSubseries, hasVariations, hasUnofficialVariations, hasChange, hasRetroChange /* v6.170 */, hasPrintError /* v6.219 */, hasFreeVersion, hasRetroFreeVersion /* v6.248 */, nomeCorto, controlliSospesi, noNumbers, noRetro, noAlbums /* v6.194 */, serieContenitore /* v6.204 */, articoliNascosti /* v6.216 */, countVariations: countVariations ?? null, countUnofficialVariations: countUnofficialVariations ?? null, countChange: countChange ?? null, countRetroChange: countRetroChange ?? null /* v6.170 */, countPrintError: countPrintError ?? null /* v6.219 */, countFreeVersion: countFreeVersion ?? null, countRetroFreeVersion: countRetroFreeVersion ?? null /* v6.248 */, retroChangeTypes, frontChangeTypes /* v6.102 */, retroFreeVersionTypes, frontFreeVersionTypes /* v6.246 */, created: new Date().toISOString() };
      const saved = await fsSave('series', newS);
      _cache.series.push(saved);
    }
  } catch(e) {
    console.error('saveSeries', e);
    _fineAttesa();   // v6.190
    toast((currentLang === 'it' ? '❌ Salvataggio fallito: ' + (e?.code || e?.name || 'errore') + ' — riprova' : '❌ Save failed: ' + (e?.code || e?.name || 'error') + ' — please retry'), 'error');
    return;
  }
  _stopAvviso();   // v6.190 - riuscito: l'avviso non deve comparire un istante dopo il "salvata!"
  editingSeriesImgFile = null;
  if (fb) { fb.textContent = (currentLang === 'it' ? '✅ Serie salvata!' : '✅ Series saved!'); }
  if (btn) btn.disabled = false;
  setTimeout(() => {
    closeModal('add-series-modal');
    if (fb) { fb.style.display = 'none'; fb.textContent = ''; }
  }, 1000);
  renderCatalog(); renderHomeSeries(); renderHomeStats(); renderAdminSeries();
}
// ============================================================
// v6.171 (Franco) — IL PULSANTE ELIMINA DELLA SCHEDA SERIE.
// ------------------------------------------------------------
// Grigiato finche' la serie ha almeno un prodotto collegato. "Prodotto" e' qualunque cosa stia
// nella collezione `figurines`: figurine, retro, album, bustine e altri oggetti stanno tutti li',
// distinti dal campo `section`. Quindi il conteggio copre gia' tutti e cinque i tipi, e NON va
// filtrato per sezione — un filtro qui direbbe "si puo' cancellare" a una serie che ha ancora i
// retro dentro.
// ⚠️ CON LA FORM IN CREAZIONE il pulsante sparisce del tutto invece di grigiarsi: il documento su
// Firestore non esiste ancora, non c'e' niente da cancellare, e un comando disabilitato per una
// cosa che non esiste fa cercare la condizione che lo accende.
// 📌 "In creazione" vuol dire `seriesId` assente — la form aperta da "Aggiungi serie" — e NON
// "serie creata di recente". La distinzione non e' pedanteria: la prima stesura di questo commento
// diceva "serie NUOVA", e Franco ha chiesto cosa intendessi. Una parola che regge due letture, in
// un commento, resta li' per anni e la lettura sbagliata sembra sensata quanto quella giusta.
// ============================================================
function _aggiornaPulsanteEliminaSerie(seriesId) {
  const btn = document.getElementById('series-delete-btn');
  const hint = document.getElementById('series-delete-hint');
  const box = btn && btn.parentElement;
  if (!btn || !box) return;
  const it = currentLang === 'it';
  if (!seriesId) { box.style.display = 'none'; return; }
  box.style.display = '';
  const n = _prodottiDellaSerie(seriesId);
  // v6.175 - basta `disabled`: l'aspetto da spento lo mette `.btn-danger:disabled` nel CSS
  // (opacita' e cursore). Le due righe che lo facevano a mano sono state tolte — erano in linea,
  // quindi avrebbero pure VINTO sulla regola del CSS, tenendo in vita una seconda verita' sullo
  // stesso aspetto.
  btn.disabled = n > 0;
  if (hint) hint.textContent = n > 0
    ? (it ? `Non si può eliminare: la serie ha ancora ${n} prodotti collegati (figurine, retro, album, bustine, altri oggetti). Svuotala prima.`
          : `Cannot delete: the series still has ${n} linked products. Empty it first.`)
    : (it ? 'La serie è vuota: si può eliminare.' : 'The series is empty: it can be deleted.');
}

// La stessa domanda in un posto solo, letta dal pulsante E dal controllo dentro `deleteSeries`.
function _prodottiDellaSerie(seriesId) {
  return (_cache.figurines || getData('figurines', [])).filter(f => f.seriesId === seriesId).length;
}

async function deleteSeries(id) {
  // 🔴 v6.171 — IL CONTROLLO STA QUI, non solo sul pulsante. Fino alla v6.170 l'unica difesa era
  // che in tabella il cestino NON VENISSE DISEGNATO quando la serie aveva dei prodotti: la
  // funzione, se chiamata, cancellava serie e contenuto senza guardare niente.
  // Spostando il comando nella scheda e grigiandolo, la difesa sarebbe diventata un attributo
  // `disabled` — cioe' la cosa piu' facile da perdere in un ritocco al markup. Il controllo va
  // dove sta il danno, non dove sta il clic: e' la scelta della v6.143 (la rete in `saveBulkCell`
  // per chiamate che oggi non esistono).
  if (!id) return;
  const n = _prodottiDellaSerie(id);
  if (n > 0) {
    toast(currentLang === 'it'
      ? `❌ La serie ha ancora ${n} prodotti collegati: svuotala prima di eliminarla`
      : `❌ The series still has ${n} linked products: empty it first`, 'error');
    return;
  }
  if (!confirm('Delete this series and all its figurines?')) return;
  try {
    // Cancellare il documento della serie cancella già tutte le sue
    // figurine, che ora vivono incorporate al suo interno (non serve più
    // un ciclo di cancellazione separato, anzi sarebbe controproducente:
    // ricreerebbe il documento appena cancellato)
    await fsDelete('series', id);
  } catch(e) {
    console.error('deleteSeries', e);
    toast((currentLang === 'it' ? '❌ Eliminazione fallita, riprova' : '❌ Delete failed, please retry'), 'error');
    return;
  }
  _cache.series = _cache.series.filter(x => x.id !== id);
  _cache.figurines = _cache.figurines.filter(x => x.seriesId !== id);
  renderCatalog(); renderHomeSeries(); renderHomeStats(); renderAdminSeries();
  toast((currentLang === 'it' ? 'Serie eliminata' : 'Series deleted'), 'success');
}

// Pulsante "X" per svuotare un campo di ricerca in un click, invece di
// doverlo selezionare e cancellare a mano
// Mostra quanti oggetti risultano dai filtri/ricerca attivi, sia in vista
// a griglia sia in Vista tabellare — prima non veniva mostrato da nessuna
// parte, né con né senza filtri applicati
// Riceve ora l'ELENCO degli oggetti filtrati, non piu' soltanto quanti sono:
// serve per contare quanti di essi siano gia' nella lista dell'utente.
//
// E' il SECONDO dei due contatori che Franco ha distinto, ed e' bene tenerli
// separati in testa:
//   · quello nella riga della serie  → cosa ho RISPETTO ALLA SERIE. Non si muove
//     mai: e' un traguardo, e un traguardo che balla non misura niente.
//   · questo                          → cosa ho RISPETTO A CIO' CHE STO GUARDANDO.
//     Cambia a ogni filtro, ed e' giusto cosi'.
// Questo secondo numero ha un valore che va oltre l'informazione: e' l'ANTEPRIMA
// ESATTA dei due pulsanti. Dalla v5.670 "Aggiungi/Rimuovi tutti gli oggetti
// visualizzati" agisce su questo identico insieme. Leggere "96 trovati · 3 nella
// tua lista" significa sapere in anticipo che "Aggiungi" ne aggiungera' 93 e
// "Rimuovi" ne togliera' 3. Il pulsante smette di essere un salto nel buio.
//
// NON si festeggia qui con il 🎉 delle categorie: "le hai tutte" riferito a un
// insieme che l'utente si e' appena ritagliato con un filtro sarebbe un traguardo
// finto — e un complimento facile svaluta quello vero.
function updateItemsCountDisplay(items) {
  const el = document.getElementById('items-count-display');
  if (!el) return;
  const elenco = Array.isArray(items) ? items : [];
  const count = elenco.length;
  const it = currentLang === 'it';

  // v5.795 — numeri dei risultati più grandi ed evidenziati, etichette invariate.
  // v5.797 — Franco: colorare SOLO il numero (non l'intera frase). Il numero degli
  //          oggetti nella "tua lista" usa il BLU dei toggle aggiungi/rimuovi lista
  //          (var(--action)), non l'accent.
  const numBase = 'font-size:1.5rem;font-weight:700;';
  const num = v => `<span style="${numBase}color:var(--accent);">${v}</span>`;
  const numBlue = v => `<span style="${numBase}color:var(--action);">${v}</span>`;
  const cfmt = count.toLocaleString(it ? 'it-IT' : 'en-US');
  // v5.850 — su telefono le due frasi vanno tenute su UNA riga: alla larghezza di un telefono
  // "N oggetti trovati" + "N fanno parte della tua lista" non ci stanno a un corpo leggibile.
  // Non si rimpicciolisce oltre: si accorcia il testo, che e' la cosa giusta da comprimere.
  const _mobileCount = _isMobileViewport();
  const trovati = _mobileCount
    ? (it ? `${num(cfmt)} trovati` : `${num(cfmt)} found`)
    : (count === 1
        ? (it ? `${num('1')} oggetto trovato` : `${num('1')} item found`)
        : (it ? `${num(cfmt)} oggetti trovati` : `${num(cfmt)} items found`));

  let html = `<span>${trovati}</span>`;

  if (currentUser && count) {
    const ownedIds = getOwned();
    const n = elenco.filter(f => ownedIds.includes(f.id)).length;
    const nfmt = n.toLocaleString(it ? 'it-IT' : 'en-US');
    // Singolare e plurale: "1 FA parte", non "1 fanno parte". Idem in inglese
    // ("is part" / "are part"). E' il dettaglio che, sbagliato, fa sembrare
    // scritto male tutto il resto — anche quando il resto e' giusto.
    const frase = _mobileCount
      ? (it ? 'in lista' : 'in list')
      : (it
          ? (n === 1 ? 'fa parte della tua lista' : 'fanno parte della tua lista')
          : (n === 1 ? 'is part of your list' : 'are part of your list'));
    // Solo il numero è colorato (blu lista); l'etichetta resta nel colore testo.
    html += `<span>${numBlue(nfmt)} ${frase}</span>`;
  }

  el.innerHTML = `<div style="display:flex;flex-direction:column;gap:1px;"><div style="font-size:0.95rem;font-weight:600;color:var(--text);margin-bottom:0.35rem;">${it ? 'I risultati della tua ricerca' : 'Your search results'}</div>${html}</div>`;
}

function clearSearchField(inputId, renderFn) {
  const input = document.getElementById(inputId);
  if (!input) return;
  input.value = '';
  toggleSearchClearBtn(inputId);
  if (renderFn) renderFn();
  input.focus();
}

function toggleSearchClearBtn(inputId) {
  const input = document.getElementById(inputId);
  const btn = document.getElementById(inputId + '-clear');
  if (!input || !btn) return;
  btn.style.display = input.value ? '' : 'none';
}

// ============================================================
//  L'INVENTARIO A DUE TAGLI (v6.073, Franco)
// ============================================================
// Il taglio per SERIE e' quello di sempre. Quello per PRODOTTI e' il suo trasposto: gli stessi
// oggetti, ordinati per tipo invece che per serie. Serviva perche' esistono oggetti Sgorbions
// senza serie, e su un sito organizzato per serie non c'e' un posto dove metterli; su questo asse
// la domanda "di che serie e'?" non viene mai posta, quindi il problema non nasce.
// ============================================================
// v6.214 (Franco) - IL DESCRITTORE DEGLI ARTICOLI. UNA VOCE PER ARTICOLO, E BASTA.
// ------------------------------------------------------------
// Fino alla v6.213 le proprieta' dei sei articoli di codice stavano in DIECI elenchi paralleli,
// tutti chiavati sugli stessi sei nomi: `PRODOTTI_INVENTARIO` (quali sono e in che ordine),
// `COLONNE_DEFAULT`, `SECTION_ICONS`, `SECTION_IMAGES`, `getSectionLabel`,
// `getSectionLabelSingular`, `_numeroEOrdinamento`, `_mostraCampoNumero`, `SEZIONI_NASCONDIBILI`.
// Per sapere tutto di `albums` bisognava leggerne dieci, e **nessuno sapeva dell'esistenza degli
// altri**.
//
// \uD83D\uDD34 NON E' UNA QUESTIONE DI ELEGANZA: DUE DI QUEGLI ELENCHI HANNO GIA' FALLITO. La v6.195, che
// ha aggiunto la sesta sezione, ha trovato `updateSectionCounts` e `_applicaFotoSezioni` con dentro
// una lista CABLATA di cinque nomi. Nessuna delle due dava errore: il contatore della sezione nuova
// sarebbe rimasto su "caricamento..." per sempre e la sua foto non sarebbe comparsa.
//
// \u2705 QUESTA RELEASE NON CAMBIA NESSUN COMPORTAMENTO. I dieci lettori non vengono toccati: gli
// elenchi che leggevano continuano a esistere con lo stesso nome e lo stesso contenuto, solo che
// ora si RICAVANO da qui invece di essere scritti a mano. La prova e' che i valori derivati
// coincidono con i letterali di prima, uno per uno.
//
// \uD83D\uDCCC LA STESSA FORMA CHE HANNO GIA' I TIPI DI ARTICOLO. Un tipo (Cartoncini) ha la sua scheda
// con nome, singolare, ha retro, ha taglia, ordinamento, colonne. I sei di codice non ce l'avevano.
// Da qui in avanti si descrivono allo stesso modo, ed e' cio' che rende possibile la sezione
// "Tipo di articolo" in console: un posto solo dove un articolo si guarda, quale che sia la sua
// natura.
//
// ------------------------------------------------------------
// COSA VUOL DIRE OGNI CAMPO, e sono tutti fatti misurati sul codice del 17 agosto, non intenzioni:
//
//   pos           l'ordine dei box nel taglio Articoli. ⚠️ L'hub della serie ha le sue card
//                 scritte a mano nell'index e va tenuto d'accordo con questa riga (v6.195).
//   numero        COSA SIGNIFICA il campo Numero per questo articolo. Tre valori, e non sono
//                 sfumature - decidono se il campo si vede e se si eredita:
//                   'inventario'  identifica il SOGGETTO: la #214, la sua variazione e il suo
//                                 change sono tutti #214. Il campo si nasconde quando il tipo e'
//                                 ereditato, perche' li' il numero viene dalla base.
//                   'ordinamento' e' la POSIZIONE in elenco. Ogni oggetto ha la sua, e due oggetti
//                                 diversi hanno numeri diversi. Il campo si vede sempre.
//                   'nessuno'     l'articolo non ha numero: il campo non compare mai.
//   ordina        COME si ordina. Anche qui tre meccanismi, tutti gia' esistenti:
//                   'codice'  una regola scritta a mano, non esprimibile come stringa
//                   'campo'   comanda il numero scritto sull'oggetto
//                   'criterio' una stringa di criteri (oggi solo i tipi di articolo la usano)
//   nomeCompleto  COME si compone il Nome completo. 'retro' = `_retroFullName`, che ha una regola
//                 sua con categoria e sottocategoria; 'codice' = i rami di `computeFullName`.
//   ordinaDove       v6.221 - DOVE: la funzione se `ordina` e' 'codice', il campo del record se e'
//   nomeCompletoDove 'campo'. Erano commenti accanto al valore; sono diventati dati perche' la
//                    sezione di console li STAMPA, e un commento non si stampa.
//   colonne       le colonne di partenza della griglia, desktop e telefono.
//
// 🔴 v6.223 - QUI C'ERA `nascondibile` ("il flag di serie che fa sparire il box, oppure null"), ed
// e' stato tolto insieme al campo. Franco l'ha visto nella tabella appena stampata: *"perche'
// Album ha ancora il flag associato (noAlbums)?"*.
// Due fatti, misurati e non ricordati:
//   1. **NESSUNO LO LEGGEVA.** Cercato `nascondibile` in tutto il file: sei dichiarazioni, una
//      etichetta nella tabella, zero letture. Chi nasconde i box guarda `noRetro`/`noAlbums`
//      (`_serieSenzaRetro`, `_serieSenzaAlbum`) e, dalla v6.216, `articoliNascosti`.
//   2. **E DICEVA UNA COSA FALSA.** Solo `albums` dichiarava il suo flag; `retros` aveva
//      `nascondibile: null` pur avendo `noRetro` da sempre (v6.098). Cioe' la tabella insegnava
//      che gli album si possono nascondere e i retro no, e sono nascondibili tutti e sei.
// 📌 E' il primo guadagno vero della sezione: un campo morto e sbagliato stava li' da due release
// senza che nessuno lo vedesse, ed e' bastato stamparlo per farlo notare al primo sguardo.
// ⚠️ Il campo NON serve nemmeno ai passi che restano: al passo 3 i lettori passano ad
// `articoliNascosti`, e le caselle della scheda serie si generano gia' da `PRODOTTI_INVENTARIO`.
//
// \uD83D\uDD34 UNA DISCORDANZA CHE QUESTA TABELLA RENDE VISIBILE, ed e' il primo guadagno concreto:
// `attaccare` ha `numero: 'ordinamento'`, perche' e' cio' che il codice fa OGGI - cade nel ramo
// "tutto cio' che non e' figurines ne' retros". Ma Franco ha deciso che una figurina da attaccare
// porta il numero d'INVENTARIO, come la sua con velina, con cui sta 1:1. **Il valore qui e'
// sbagliato di proposito**: questa release non cambia comportamenti, e correggerlo qui li
// cambierebbe. Si corregge nella release che tocca il Numero - e adesso la discordanza si LEGGE,
// invece di stare nascosta dentro una condizione a tre rami.
// ============================================================
const ARTICOLI = {
  figurines: {
    pos: 1,
    it: 'Figurine con velina',   en: 'Stickers with tissue',
    itSing: 'figurina con velina', enSing: 'sticker with tissue',
    genere: 'f',
    icona: '&#129535;',
    colonne: { d: 7, m: 4 },
    numero: 'inventario',
    ordina: 'codice',
    // 🆕 v6.221 - IL "DOVE" ERA UN COMMENTO, ORA E' UN VALORE. La sezione di console deve
    // STAMPARE dove si ordina e dove si compone il nome: un commento non si stampa, quindi
    // sarebbe stato ricopiato a mano nella pagina - cioe' documentazione, che comincia a mentire
    // il giorno che qualcuno cambia la funzione e non la pagina.
    // Regola: se `ordina` e' 'codice' qui c'e' la FUNZIONE; se e' 'campo', il CAMPO del record.
    ordinaDove: '_chiaviOrdinamentoFigurine',  // i figli sotto il numero del capogruppo
    nomeCompleto: 'codice',
    nomeCompletoDove: 'computeFullName'       // rami variazione/change/errore/base
  },
  // 🆕 v6.224 (Franco) — IL SETTIMO ARTICOLO: le CARTE. *"le carte sono come le figurine; hanno un
  // retro che non va censito. per il resto sono come le figurine"*, e *"non ci saranno
  // variazioni-change per le carte"*.
  //
  // 📌 `pos: 1` A PARI MERITO CON LE FIGURINE, ed e' la scelta di Franco: *"una serie ha le card o
  // ha le figurine"*. Non e' un numero storto — dice una cosa vera che nessun altro campo diceva:
  // i due articoli sono ALTERNATIVI, non consecutivi. A pari punteggio l'ordine lo decide l'ordine
  // di dichiarazione (`Array.prototype.sort` e' stabile per specifica dal 2019), quindi le figurine
  // restano prima: e' l'unica cosa da sapere se un giorno si sposta questa voce piu' in su nel
  // file. L'alternativa era rinumerare gli altri cinque per far posto a un 2.
  //
  // ⚠️ `ordina: 'campo'` E NON 'codice', anche se "sono come le figurine". Il raggruppamento dei
  // figli sotto il capogruppo (`_chiaviOrdinamentoFigurine`) e' dentro un `if (currentSection ===
  // 'figurines')` scritto a mano: le carte non ci passano. E non e' un ripiego: senza variazioni
  // ne' change non c'e' NIENTE da raggruppare, quindi ordinare per il campo `number` da' lo stesso
  // ordine visibile. Il descrittore dice cio' che il codice fa - se un domani le carte avessero
  // dei figli, questa riga sarebbe il posto dove si vede che non li ordina nessuno.
  //
  // 📌 IL RETRO NON SI CENSISCE, e infatti qui non c'e' nessun campo che lo dica: il descrittore
  // non descrive i retro (ne' le taglie). Va bene cosi' finche' e' vero per costruzione - le carte
  // semplicemente non avranno record nella sezione Retro. Se un giorno servisse dichiararlo, si
  // aggiunge un campo e lo si misura su tutti e sette, non si scrive a memoria sui sei vecchi.
  carte: {
    pos: 1,
    it: 'Carte',   en: 'Cards',
    itSing: 'carta', enSing: 'card',
    genere: 'f',
    icona: '&#127183;',
    colonne: { d: 7, m: 4 },              // come le figurine
    numero: 'inventario',                 // identifica il soggetto, come le figurine
    ordina: 'campo',
    ordinaDove: 'number',
    nomeCompleto: 'codice',
    nomeCompletoDove: 'computeFullName'
  },
  albums: {
    pos: 2,
    it: 'Album',   en: 'Albums',
    itSing: 'album', enSing: 'album',
    genere: 'm',
    icona: '&#128210;',
    colonne: { d: 4, m: 3 },
    numero: 'ordinamento',
    ordina: 'campo',
    ordinaDove: 'number',                 // v6.221 - diventera' `ordine` col passo 2 della scaletta
    nomeCompleto: 'codice',
    nomeCompletoDove: 'computeFullName'  // v6.221
  },
  attaccare: {
    pos: 3,
    it: 'Figurine da attaccare', en: 'Stickers to stick',
    itSing: 'figurina da attaccare', enSing: 'sticker to stick',
    genere: 'f',
    icona: '&#128204;',
    colonne: { d: 7, m: 4 },
    numero: 'ordinamento',   // \uD83D\uDD34 da correggere in 'inventario': vedi il riquadro qui sopra
    ordina: 'campo',
    ordinaDove: 'number',                 // v6.221
    nomeCompleto: 'codice',
    nomeCompletoDove: 'computeFullName'  // v6.221
  },
  retros: {
    pos: 4,
    it: 'Retro',   en: 'Retros',
    itSing: 'retro', enSing: 'retro',
    genere: 'm',
    icona: '&#128257;',
    colonne: { d: 5, m: 4 },
    numero: 'nessuno',
    ordina: 'codice',
    ordinaDove: 'cmpVistaTabellare',     // categoria, sottocategoria, nome, tipo
    nomeCompleto: 'retro',
    nomeCompletoDove: '_retroFullName'  // v6.221
  },
  bustine: {
    pos: 5,
    it: 'Bustine', en: 'Wrappers',
    itSing: 'bustina', enSing: 'wrapper',
    genere: 'f',
    icona: '&#128230;',
    colonne: { d: 4, m: 3 },
    numero: 'ordinamento',
    ordina: 'campo',
    ordinaDove: 'number',                 // v6.221
    nomeCompleto: 'codice',
    nomeCompletoDove: 'computeFullName'  // v6.221
  },
  extras: {
    pos: 6,
    it: 'Altri oggetti', en: 'Other Items',
    itSing: 'oggetto', enSing: 'item',
    genere: 'm',
    icona: '&#127873;',
    colonne: { d: 4, m: 3 },
    numero: 'ordinamento',
    ordina: 'campo',
    ordinaDove: 'number',                 // v6.221
    nomeCompleto: 'codice',
    nomeCompletoDove: 'computeFullName'  // v6.221
  }
};

// La voce di un articolo, con ripiego sulle figurine come fa gia' `_colonneGriglia`: una sezione
// sconosciuta non deve far esplodere il disegno di una pagina.
function _art(sez) { return ARTICOLI[sez] || ARTICOLI.figurines; }

// ============================================================
// 🆕 v6.221 (Franco: "devi creare la tabella del tipo di articolo") — LA SEZIONE DI CONSOLE.
// ------------------------------------------------------------
// 📌 NON E' DOCUMENTAZIONE: E' IL DESCRITTORE STAMPATO. Una pagina scritta a mano comincia a
// mentire il giorno dopo — e' successo a `procedura-deploy.md` con *"le etichette in un posto solo:
// due righe"*, che erano 72 stringhe.
//
// 🔴 LE COLONNE SONO L'UNIONE DELLE CHIAVI DI TUTTE LE VOCI, non le chiavi della prima. La
// differenza si vede solo il giorno che un articolo dichiara un campo che gli altri non hanno:
// leggendo la prima voce quel campo sparirebbe dalla tabella **in silenzio**, ed e' proprio il caso
// in cui la tabella servirebbe. E' la stessa famiglia del difetto della v6.215 - un elenco scritto
// su una fonte piu' stretta di quella vera, che salta le righe senza dare errore.
//
// ⚠️ E se un articolo dice `ordina: 'codice'` senza dire DOVE, la tabella lo scrive
// ("non dichiarato") invece di lasciare una cella vuota: una cella vuota si legge come "niente da
// dire", e qui vorrebbe dire "nessuno sa piu' quale funzione lo ordina".
const _ETICHETTE_DESCRITTORE = {
  pos: 'Pos.', it: 'Nome (IT)', en: 'Nome (EN)', itSing: 'Singolare (IT)', enSing: 'Singolare (EN)',
  icona: 'Icona', colonne: 'Colonne d/m', numero: 'Numero', ordina: 'Ordinamento',
  ordinaDove: 'Ordina dove', nomeCompleto: 'Nome completo', nomeCompletoDove: 'Nome completo dove'
};

function _cellaDescrittore(chiave, voce) {
  const v = voce[chiave];
  const muto = t => '<span style="color:var(--muted);">' + t + '</span>';
  // Il "dove" mancante dove servirebbe: si dice, non si lascia in bianco.
  if ((chiave === 'ordinaDove' && voce.ordina === 'codice' && !v) ||
      (chiave === 'nomeCompletoDove' && !v && voce.nomeCompleto)) {
    return '<span style="color:var(--danger);">⚠️ non dichiarato</span>';
  }
  if (v === null || v === undefined || v === '') return muto('—');
  if (chiave === 'icona') return v;                       // e' un'entita' HTML: va resa, non scritta
  if (chiave === 'colonne') return esc(v.d + ' / ' + v.m); // l'unico campo composto, oggi
  if (typeof v === 'object') return esc(JSON.stringify(v));
  if (chiave === 'ordinaDove' || chiave === 'nomeCompletoDove')
    return '<code style="font-size:0.78rem;color:var(--accent);">' + esc(String(v)) + '</code>';
  return esc(String(v));
}

// 🆕 v6.228 (Franco) — ANCHE QUESTA TABELLA SI ORDINA A CLIC. Stesso meccanismo della tabella
// delle serie (v6.226) e delle altre tre del sito.
// 📌 Qui non c'e' nessun ordine manuale da proteggere - niente frecce, nessun `order` scritto sul
// dato - quindi non serve nessuno stato "torna com'era": l'ordine di partenza e' `pos`, e
// cliccando **Pos.** ci si torna, perche' ordinare per `pos` E' l'ordine naturale.
// ⚠️ Il valore su cui si ordina si ricava dalla CELLA, non da un elenco scritto a parte: le
// colonne di questa tabella nascono dalle chiavi del descrittore, e un elenco separato di chiavi
// di ordinamento sarebbe la seconda lista da tenere allineata - cioe' quella che si dimentica.
// `colonne` e' l'unico campo composto e si ordina per desktop e poi mobile; i vuoti stanno insieme.
let _tipoArtSort = { col: null, dir: 1 };
function sortAdminTipoArticolo(col) {
  if (_tipoArtSort.col === col) _tipoArtSort.dir *= -1;
  else _tipoArtSort = { col, dir: 1 };
  renderAdminTipoArticolo();
}
function _valoreOrdinamentoDescrittore(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'object') return (v.d ?? 0) * 100 + (v.m ?? 0);
  return v;
}

function renderAdminTipoArticolo() {
  const box = document.getElementById('admin-tipo-articolo-tabella');
  if (!box) return;
  const chiavi = [];
  PRODOTTI_INVENTARIO.forEach(sez =>
    Object.keys(ARTICOLI[sez]).forEach(k => { if (!chiavi.includes(k)) chiavi.push(k); }));
  // v6.228 - l'elenco delle righe, ordinato se c'e' una colonna attiva. `pos` e' l'ordine
  // naturale, quindi cliccarlo riporta esattamente com'era.
  let _sezioniOrdinate = PRODOTTI_INVENTARIO;
  if (_tipoArtSort.col) {
    const k = _tipoArtSort.col;
    _sezioniOrdinate = [...PRODOTTI_INVENTARIO].sort((a, b) => {
      const va = _valoreOrdinamentoDescrittore(ARTICOLI[a][k]);
      const vb = _valoreOrdinamentoDescrittore(ARTICOLI[b][k]);
      const cmp = (typeof va === 'number' && typeof vb === 'number')
        ? va - vb
        : String(va).localeCompare(String(vb), 'it');
      return cmp * _tipoArtSort.dir;
    });
  }
  const th = 'padding:5px 8px;font-size:0.76rem;color:var(--muted);text-align:left;white-space:nowrap;border-bottom:1px solid var(--border);';
  const td = 'padding:5px 8px;font-size:0.82rem;color:var(--text);white-space:nowrap;border-bottom:1px solid var(--border);';
  box.innerHTML =
    '<p style="font-size:0.85rem;color:var(--muted);margin-bottom:0.9rem;line-height:1.5;">' +
      'Questa tabella <strong>stampa il descrittore</strong> <code>ARTICOLI</code> di <code>app.js</code>: ' +
      'righe e colonne si ricavano da lì. Un articolo nuovo compare da sé, e un campo nuovo si porta ' +
      'dietro la sua colonna. Se una cosa che ti aspetti non è una colonna, vuol dire che ' +
      '<strong>nessun articolo la dichiara</strong> — non che la tabella se l\'è dimenticata.' +
    '</p>' +
    '<div style="overflow-x:auto;">' +
    '<table style="border-collapse:collapse;min-width:100%;">' +
    // v6.222 (Franco: "la colonna chiave, ti ringrazio ma non mi è utile") - VIA LA PRIMA
    // COLONNA, che portava il nome interno della sezione (`figurines`, `albums`...). Non e' un
    // campo del descrittore: era la sua CHIAVE, cioe' l'unica colonna scritta a mano di una
    // tabella che per il resto si ricava. La riga si riconosce dal Nome (IT), che e' li' accanto.
    '<tr>' +
      // v6.283 - la colonna dell'ORDINE non si puo' ordinare: e' l'ordine.
      '<th style="' + th + '">' + (currentLang === 'it' ? 'Ordine' : 'Order') + '</th>' +
      chiavi.map(k => {
        const attiva = _tipoArtSort.col === k || (!_tipoArtSort.col && k === 'pos');
        const freccia = attiva ? (_tipoArtSort.col === k ? (_tipoArtSort.dir === 1 ? ' \u25B2' : ' \u25BC') : ' \u25B2') : '';
        return '<th style="' + th + 'cursor:pointer;user-select:none;' + (attiva ? 'color:var(--accent);' : '') + '"' +
          ' onclick="sortAdminTipoArticolo(\'' + k + '\')"' +
          ' title="' + (currentLang === 'it' ? 'Ordina per questa colonna' : 'Sort by this column') + '">' +
          esc(_ETICHETTE_DESCRITTORE[k] || k) + freccia + '</th>';
      }).join('') +
    '</tr>' +
    // 🆕 v6.283 - LE FRECCE, e compaiono SOLO nell'ordine naturale. Con una colonna di
    // ordinamento accesa quello che si vede non e' l'ordine del sito, e una freccia che dice "su"
    // sposterebbe rispetto a una fila che esiste solo a schermo: e' il modo piu' rapido di far
    // spostare all'admin l'articolo sbagliato. Li' al loro posto c'e' il perche', non un buco.
    _sezioniOrdinate.map((sez, n) => {
      const _it = (currentLang === 'it');
      const _ord = PRODOTTI_INVENTARIO.indexOf(sez);
      const _bottone = (d, seg, dis, tit) =>
        '<button type="button" onclick="spostaArticolo(\'' + sez + '\', ' + d + ')"' +
        (dis ? ' disabled' : '') + ' title="' + tit + '"' +
        ' style="background:none;border:none;color:' + (dis ? 'var(--muted)' : 'var(--accent)') +
        ';cursor:' + (dis ? 'default' : 'pointer') + ';font-size:0.9rem;padding:0 0.15rem;">' + seg + '</button>';
      const celle = _tipoArtSort.col
        ? '<span style="color:var(--muted);" title="' + (_it ? 'Le frecce tornano togliendo l\'ordinamento per colonna: qui non stai guardando l\'ordine vero' : 'Arrows come back when no column sort is active') + '">\u2014</span>'
        : (_bottone(-1, '\u25B2', _ord === 0, _it ? 'Sposta su' : 'Move up')
         + _bottone(+1, '\u25BC', _ord === PRODOTTI_INVENTARIO.length - 1, _it ? 'Sposta giù' : 'Move down'));
      return '<tr>' +
        '<td style="' + td + 'white-space:nowrap;">' + celle + '</td>' +
        chiavi.map(k => '<td style="' + td + '">' + _cellaDescrittore(k, ARTICOLI[sez]) + '</td>').join('') +
        '</tr>';
    }).join('') +
    '</table></div>' +
    // La riga che dice PERCHE' e' in sola lettura, e i due numeri sono contati, non scritti.
    '<p style="font-size:0.8rem;color:var(--muted);margin-top:0.9rem;line-height:1.5;">' +
      '<span id="ordine-articoli-feedback" style="font-size:0.85rem;"></span> ' +
      '<strong>' + PRODOTTI_INVENTARIO.length + ' articoli, ' + chiavi.length + ' campi.</strong> ' +
      // v6.233 - QUESTA FRASE DICEVA "sono in sola lettura" e da questa release non e' piu' vera
      // per tutto: le VERSIONI si modificano dalla tabella qui sotto. Una pagina che si descrive
      // da se' e' utile finche' la descrizione e' esatta; il giorno che resta indietro diventa la
      // cosa piu' convincente e piu' sbagliata della pagina.
      'I campi di <strong>questa</strong> tabella sono in <strong>sola lettura</strong> perché sono ' +
      'descritti nel codice: si cambiano modificando <code>ARTICOLI</code> in <code>app.js</code>. ' +
      'Le <strong>Versioni</strong>, qui sotto, si modificano invece da questa pagina. ' +
      'La colonna <em>Ordina dove</em> ' +
      'porta il nome della funzione quando l\'ordinamento è di codice, e il campo del record quando è ' +
      'di campo.' +
    '</p>';
}

// 🆕 v6.233 — LE VERSIONI POSSIBILI, UNA TABELLA CHE SI MODIFICA.
//
// 📌 Le righe sono i sette articoli e le colonne le cinque versioni, e **nessuno dei due elenchi e'
// scritto qui**: le righe vengono da `PRODOTTI_INVENTARIO` (cioe' dal descrittore), le colonne da
// `VERSIONI_ARTICOLO`. Un articolo nuovo si porta la sua riga, una versione nuova la sua colonna.
// E' la stessa regola della tabella qui sopra, per la stessa ragione: l'elenco scritto a mano e'
// quello che un giorno resta indietro senza dare errore (v6.195, v6.214, v6.215).
//
// ⚠️ NON C'E' NESSUN "SALVA" AUTOMATICO A OGNI SPUNTA. Si spunta e poi si salva, come le griglie:
// una scrittura per clic su una tabella di 35 caselle sarebbe 35 scritture, e soprattutto non
// lascerebbe modo di cambiare idea a meta'.
function renderAdminVersioniArticolo() {
  const box = document.getElementById('admin-versioni-articolo');
  if (!box) return;
  const it = currentLang === 'it';
  const th = 'padding:5px 8px;font-size:0.76rem;color:var(--muted);text-align:left;white-space:nowrap;border-bottom:1px solid var(--border);';
  const td = 'padding:5px 8px;font-size:0.82rem;color:var(--text);white-space:nowrap;border-bottom:1px solid var(--border);';
  const seminato = _versioniArticoloSalvate();

  box.innerHTML =
    '<h4 style="font-family:var(--font-ui);margin:1.6rem 0 0.5rem;">\uD83E\uDDEC ' + (it ? 'Versioni di articolo possibili' : 'Possible article versions') + '</h4>' +
    '<p style="font-size:0.85rem;color:var(--muted);margin-bottom:0.9rem;line-height:1.5;">' +
      (it
        ? 'Le <strong>cinque versioni</strong> sono alternative alla base. Qui si dice, per ogni articolo, ' +
          '<strong>quali possono esistere</strong> — la logica è positiva: la casella spenta vuol dire ' +
          '<em>non può esistere</em>, non <em>non ce ne sono</em>. ' +
          'Le caselle sono nate accese dove i dati avevano già oggetti di quel tipo.'
        : 'The <strong>five versions</strong> are alternatives to the base. Here you declare, per article, ' +
          '<strong>which ones can exist</strong>. Positive logic: unchecked means <em>cannot exist</em>.') +
    '</p>' +
    '<div style="overflow-x:auto;"><table style="border-collapse:collapse;min-width:100%;">' +
    // 🆕 v6.251 (Franco) - UNA RIGA DI INTESTAZIONE SOPRA LE CINQUE, "Versioni speciali".
    // 📌 Le cinque colonne dicono una cosa sola in cinque modi, e senza un cappello sopra si
    // leggono come cinque attributi indipendenti dell'articolo — allo stesso livello del suo nome.
    // Un titolo di gruppo dice che appartengono insieme, e il rientro lo mostra prima ancora che si
    // legga. `colspan` sul numero VERO delle versioni, non su un 5 scritto a mano: una sesta
    // versione allargherebbe il cappello da se'.
    '<tr><th style="' + th + 'border-bottom:none;"></th>' +
      '<th colspan="' + VERSIONI_ARTICOLO.length + '" style="' + th + 'border-bottom:none;padding-left:1.4rem;'
      + 'border-left:1px solid var(--border);font-size:0.72rem;letter-spacing:0.04em;">'
      + (it ? 'VERSIONI SPECIALI' : 'SPECIAL VERSIONS') + '</th></tr>' +
    '<tr><th style="' + th + '">' + (it ? 'Articolo' : 'Article') + '</th>' +
      // v6.234 (Franco: "non e' applicato il color code") - le intestazioni portano il colore
      // della loro versione, come ogni altro posto del sito che nomina un tipo. Il colore viene
      // da `v.colore`, cioe' dallo stesso elenco: non e' una seconda mappa da tenere allineata.
      // ⚠️ `th` dichiara gia' `color:var(--muted)`; questa arriva DOPO nella stessa stringa,
      // quindi vince — e' l'ordine, non la specificita'.
      VERSIONI_ARTICOLO.map((v, iv) =>
        // v6.251 - il bordo e il rientro solo sulla PRIMA: e' li' che comincia il gruppo, e
        // ripeterli su tutte e cinque avrebbe disegnato una griglia invece di un raggruppamento.
        '<th style="' + th + 'text-align:center;color:' + (v.colore || 'var(--muted)') + ';'
        + (iv === 0 ? 'padding-left:1.4rem;border-left:1px solid var(--border);' : '') + '">' + esc(it ? v.it : v.en) +
        '</th>').join('') +
    '</tr>' +
    PRODOTTI_INVENTARIO.map(sez => {
      const attive = _versioniDi(sez);
      return '<tr><td style="' + td + '">' + esc(getSectionLabel(sez)) + '</td>' +
        VERSIONI_ARTICOLO.map((v, iv) =>
          '<td style="' + td + 'text-align:center;'
          + (iv === 0 ? 'padding-left:1.4rem;border-left:1px solid var(--border);' : '') + '">' +
          '<input type="checkbox" id="ver-' + sez + '-' + v.campo + '"' +
          (attive.includes(v.campo) ? ' checked' : '') + '>' +
          '</td>').join('') + '</tr>';
    }).join('') +
    '</table></div>' +
    '<div style="display:flex;align-items:center;gap:0.9rem;margin-top:0.9rem;">' +
      '<button class="btn-primary btn-admin" onclick="salvaVersioniArticolo()">' + (it ? 'Salva le versioni' : 'Save versions') + '</button>' +
      '<span id="versioni-articolo-feedback" style="font-size:0.85rem;color:var(--muted);"></span>' +
    '</div>' +
    '<p style="font-size:0.8rem;color:var(--muted);margin-top:0.9rem;line-height:1.5;">' +
      (it
        ? '⚠️ <strong>In questa versione del sito queste spunte non comandano ancora niente</strong>: ' +
          'la scheda oggetto continua a decidere come prima. Servono a essere compilate e controllate ora, ' +
          'così quando comanderanno (v6.234) partiranno già giuste.' +
          (seminato ? '' : ' <strong>Non risultano ancora seminate</strong>: riapri la pagina da admin.')
        : '⚠️ <strong>These checkboxes do not drive anything yet</strong> in this release.') +
    '</p>';
}

// 🆕 v6.234 — DA CHI PUO' NASCERE OGNI VERSIONE, IN SOLA LETTURA (chiesta da Franco).
//
// 📌 SOLA LETTURA E' LA SCELTA GIUSTA, e non per prudenza: la partenza ammessa non e' una
// preferenza, e' la forma del modello. Le spunte qui sopra dicono *cosa esiste in questa
// collezione* e cambiano da collezione a collezione; questa tabella dice *come sono fatte le
// versioni*, ed e' la stessa per chiunque. Renderla modificabile inviterebbe a cambiarla, e ogni
// riga cambiata sarebbe codice che smette di valere.
//
// ⚠️ E' il descrittore STAMPATO, non una pagina scritta a mano: righe e celle vengono da
// `VERSIONI_ARTICOLO`. Se un giorno l'omaggio potra' nascere anche da una variazione non
// ufficiale, si cambia una riga nel codice e questa tabella lo dice da se'. Una pagina scritta a
// mano comincerebbe a mentire quel giorno.
function renderAdminPartenzeVersione() {
  const box = document.getElementById('admin-partenze-versione');
  if (!box) return;
  const it = currentLang === 'it';
  const th = 'padding:5px 8px;font-size:0.76rem;color:var(--muted);text-align:left;white-space:nowrap;border-bottom:1px solid var(--border);';
  const td = 'padding:5px 8px;font-size:0.82rem;color:var(--text);border-bottom:1px solid var(--border);';
  // Le colonne: la base piu' le versioni che qualcuno ammette come partenza. Non un elenco
  // scritto: chi non compare in nessuna riga non ha colonna, ed e' l'informazione stessa.
  const colonne = ['base'].concat(VERSIONI_ARTICOLO.filter(v => _puoEsserePartenza(v.chiave)).map(v => v.chiave));
  const foglie = VERSIONI_ARTICOLO.filter(v => !_puoEsserePartenza(v.chiave));

  box.innerHTML =
    '<h4 style="font-family:var(--font-ui);margin:1.6rem 0 0.5rem;">\uD83D\uDD17 ' +
      (it ? 'Da chi pu\u00F2 nascere ogni versione' : 'Allowed starting points') + '</h4>' +
    '<p style="font-size:0.85rem;color:var(--muted);margin-bottom:0.9rem;line-height:1.5;">' +
      (it
        ? 'Ogni versione \u00E8 collegata a un <strong>articolo di partenza</strong>. Qui c\'\u00E8 chi pu\u00F2 farlo, ' +
          'versione per versione. \u00C8 in <strong>sola lettura</strong>: descrive com\'\u00E8 fatto il modello, ' +
          'non cosa contiene questa collezione \u2014 quello lo dice la tabella qui sopra.'
        : 'Each version is linked to a <strong>starting item</strong>. Read-only: this describes the model.') +
    '</p>' +
    '<div style="overflow-x:auto;"><table style="border-collapse:collapse;min-width:100%;">' +
    '<tr><th style="' + th + '">' + (it ? 'Versione' : 'Version') + '</th>' +
      colonne.map(c => '<th style="' + th + 'text-align:center;">' + esc(_etichettaChiaveTipo(c)) + '</th>').join('') +
    '</tr>' +
    VERSIONI_ARTICOLO.map(v => {
      const amm = _partenzeDi(v.chiave);
      return '<tr><td style="' + td + 'white-space:nowrap;"><span style="color:' + (v.colore || 'var(--text)') + ';font-weight:600;">' +
        esc(it ? v.it : v.en) + '</span></td>' +
        colonne.map(c => '<td style="' + td + 'text-align:center;">' +
          (amm.includes(c) ? '<span style="color:var(--success);">\u2713</span>' : '<span style="color:var(--muted);">\u2014</span>') +
          '</td>').join('') + '</tr>';
    }).join('') +
    '</table></div>' +
    '<p style="font-size:0.8rem;color:var(--muted);margin-top:0.9rem;line-height:1.5;">' +
      (it
        ? '\uD83D\uDCCC <strong>Chi pu\u00F2 fare da partenza non \u00E8 dichiarato da nessuna parte: si ricava.</strong> ' +
          'Una versione compare come colonna solo se almeno un\'altra riga la ammette. ' +
          (foglie.length
            ? 'Oggi <strong>' + foglie.map(v => esc(v.it)).join(', ') + '</strong> non compare in nessuna riga: \u00E8 una <em>foglia</em>, ci si appende e basta. '
            : 'Oggi ogni versione pu\u00F2 fare da partenza per qualcun\'altra. ') +
          '<br>⚠️ In questa versione del sito <strong>nessuno legge ancora questa tabella</strong>: la tendina ' +
          '\u201Cfigurina di partenza\u201D filtra come ha sempre fatto. Serve a controllare le regole <em>prima</em> ' +
          'che comincino a comandare.'
        : '\uD83D\uDCCC Derived, not declared. Not yet enforced anywhere.') +
    '</p>';
}

// Salva le spunte. Legge TUTTE le caselle prima di scrivere: un salvataggio a meta' su una tabella
// che dice "cosa puo' esistere" lascerebbe il sito in uno stato che nessuno ha voluto.
async function salvaVersioniArticolo() {
  const it = currentLang === 'it';
  const fb = document.getElementById('versioni-articolo-feedback');
  const per = {};
  for (const sez of PRODOTTI_INVENTARIO) {
    per[sez] = VERSIONI_ARTICOLO
      .filter(v => document.getElementById('ver-' + sez + '-' + v.campo)?.checked)
      .map(v => v.campo);
  }
  if (fb) { fb.style.color = 'var(--muted)'; fb.textContent = it ? 'Salvataggio\u2026' : 'Saving\u2026'; }
  try {
    await fsSave('settings', { id: 'versioni_articolo', perArticolo: per });
    LOCAL.set('versioniArticolo', JSON.stringify(per));
    if (fb) { fb.style.color = 'var(--success)'; fb.textContent = it ? '\u2705 Versioni salvate!' : '\u2705 Versions saved!'; }
  } catch (e) {
    // v6.232 - adesso un salvataggio che non puo' scrivere FALLISCE, e questo ramo lo mostra.
    console.error('salvaVersioniArticolo', e);
    if (fb) { fb.style.color = 'var(--danger)'; fb.textContent = (it ? '\u274C Salvataggio fallito: ' : '\u274C Save failed: ') + (e?.code || e?.name || 'errore'); }
  }
}

// ------------------------------------------------------------
// DA QUI IN GIU' GLI ELENCHI DI PRIMA, che ora si RICAVANO. Stessi nomi, stessi valori: i dieci
// punti che li leggono non sono stati toccati, ed e' cio' che rende questa release verificabile -
// se un valore derivato non coincidesse con quello di prima, si vedrebbe subito.
// L'ordine DICHIARATO, da `pos`. Dalla v6.283 non e' piu' l'ordine in uso ma il suo RIPIEGO: e'
// quello che vede chi non ha mai salvato niente, ed e' la base su cui si valida quello salvato.
const ARTICOLI_ORDINE_DICHIARATO = Object.keys(ARTICOLI).sort((a, b) => ARTICOLI[a].pos - ARTICOLI[b].pos);

// 🆕 v6.283 - L'ORDINE SALVATO SI VALIDA SEMPRE, e la ragione non e' la prudenza: quel documento
// vive su Firestore mentre il codice cambia sotto. Un elenco salvato PRIMA che nascesse un articolo
// nuovo, preso alla lettera, lo farebbe **sparire dal sito** — nessun errore, solo un box che non
// c'e' piu' e nessuno che sappia perche'.
// La regola, in due mosse: si tengono le chiavi salvate che il codice conosce ancora (una tolta dal
// codice cade da se'), e in coda si aggiunge tutto quello che il codice ha e l'elenco non nomina.
// Un articolo nuovo compare quindi ULTIMO invece di non comparire: e' l'unica delle due assenze che
// si nota.
function _ordineArticoliValido(salvato) {
  if (!Array.isArray(salvato)) return null;
  const noti = salvato.filter(k => ARTICOLI[k]);
  if (!noti.length) return null;
  return noti.concat(ARTICOLI_ORDINE_DICHIARATO.filter(k => !noti.includes(k)));
}
function _ordineArticoliSalvato() {
  try { return _ordineArticoliValido(JSON.parse(LOCAL.get('ordineArticoli') || 'null')); }
  catch (e) { return null; }
}

// 🆕 v6.283 - `let`, non piu' `const`: questo elenco adesso puo' cambiare mentre il sito e' aperto.
// ⚠️ Lo leggono quattordici punti, tutti per NOME (`PRODOTTI_INVENTARIO.map(...)`) e nessuno
// copiandoselo: per questo riassegnarlo li aggiorna tutti. Chi un domani ne tenesse una copia
// avrebbe in mano un ordine che non e' piu' quello del sito, e non se ne accorgerebbe.
let PRODOTTI_INVENTARIO = _ordineArticoliSalvato() || ARTICOLI_ORDINE_DICHIARATO;

// Il salvataggio. Si scrive PRIMA in memoria e in `LOCAL` e poi su Firestore: la freccia deve
// muovere il box subito, e se la rete fallisce lo dice il messaggio, non un box che non si muove.
async function _salvaOrdineArticoli(ordine) {
  const prima = PRODOTTI_INVENTARIO;
  PRODOTTI_INVENTARIO = ordine;
  LOCAL.set('ordineArticoli', JSON.stringify(ordine));
  try {
    await fsSave('settings', { id: 'articoli', ordine });
  } catch (e) {
    // 🔴 SE NON SI E' SALVATO, NON SI E' MOSSO. Lasciare l'ordine nuovo a schermo dopo una
    // scrittura fallita sarebbe la bugia della v6.232: si vedrebbe la freccia funzionare, e
    // l'ordine tornerebbe quello di prima al ricaricamento, senza che nessuno colleghi le due cose.
    PRODOTTI_INVENTARIO = prima;
    LOCAL.set('ordineArticoli', JSON.stringify(prima));
    throw e;
  }
}

// 🆕 v6.283 - LA FRECCIA. Sposta di UNO, salva, e ridisegna sia la tabella sia i box della
// pagina serie (che potrebbero essere sotto, gia' disegnati).
async function spostaArticolo(sez, dir) {
  const i = PRODOTTI_INVENTARIO.indexOf(sez);
  const j = i + dir;
  if (i < 0 || j < 0 || j >= PRODOTTI_INVENTARIO.length) return;
  const nuovo = PRODOTTI_INVENTARIO.slice();
  nuovo[i] = nuovo[j]; nuovo[j] = sez;
  const fb = document.getElementById('ordine-articoli-feedback');
  const it = (currentLang === 'it');
  try {
    await _salvaOrdineArticoli(nuovo);
    if (fb) { fb.style.color = 'var(--success)'; fb.textContent = it ? '\u2705 Ordine salvato' : '\u2705 Order saved'; }
  } catch (e) {
    console.error('spostaArticolo', e);
    if (fb) { fb.style.color = 'var(--danger)'; fb.textContent = (it ? '\u274C Salvataggio fallito: ' : '\u274C Save failed: ') + (e?.code || e?.name || e?.message || ''); }
  }
  try { renderAdminTipoArticolo(); } catch (e) { console.error('renderAdminTipoArticolo', e); }
  try { _riordinaBoxSezioni(); } catch (e) { console.error('_riordinaBoxSezioni', e); }
}

// Rilettura da Firestore dopo un caricamento riuscito. Silenziosa come quella del timeout
// (`_aggiornaTimeoutDaConfigurazione`) e per la stessa ragione: se fallisce, resta l'ordine di
// prima — che e' un ordine buono, non un buco.
async function _aggiornaOrdineArticoliDaConfigurazione() {
  try {
    const docs = await fsGetAll('settings');
    const ord = _ordineArticoliValido(docs.find(d => d.id === 'articoli')?.ordine);
    if (!ord) return;
    LOCAL.set('ordineArticoli', JSON.stringify(ord));
    if (ord.join('|') === PRODOTTI_INVENTARIO.join('|')) return;   // niente da ridisegnare
    PRODOTTI_INVENTARIO = ord;
    try { _riordinaBoxSezioni(); } catch (e) { console.error('riordino box', e); }
  } catch (e) { /* silenzio voluto: e' una rifinitura per il giro dopo */ }
}


// ============================================================
// 🆕 v6.233 (Franco) — LE CINQUE VERSIONI, E QUALI SONO POSSIBILI PER OGNI ARTICOLO.
// ------------------------------------------------------------
// Franco: *"per ogni tipologia di articolo prevedi le seguenti tipologie di entita'... 5 diverse
// VERSIONI alternative alla base... qui la logica e' positiva: diciamo cosa PUO' esistere, non
// cosa non puo'"*.
//
// 📌 LA PAROLA E' **VERSIONE**, non "variante" e non "variazione". Serviva un nome per l'insieme,
// e "variante" era il candidato ovvio: e' stato scartato da Franco proprio perche' si confonde
// con la *Variazione*, che e' UNA delle cinque. Due parole che si somigliano per una cosa e per
// una sua parte sono il tipo di ambiguita' che poi nessuno riesce piu' a togliere.
//
// 📌 SONO CINQUE E STANNO TUTTE ALLO STESSO LIVELLO, tutte **alternative alla base**. Da cui una
// conseguenza che non e' un dettaglio: `_eBase` dovra' negarne CINQUE, non quattro (v6.235).
// Oggi non e' ancora cosi', e finche' non lo e' una Versione omaggio conterebbe come base.
//
// 🔴 IL POSITIVO QUI E' GIUSTO, MA PER UNA RAGIONE DIVERSA DA `articoliNascosti` — e va scritto,
// o le due decisioni sembreranno contraddirsi a chi legge il documento. `articoliNascosti` sta
// **sui dati** (una serie per record): al positivo, "vuoto" avrebbe voluto dire compilare tutte
// le serie, cioe' una migrazione travestita da etichetta. Questo elenco sta su UN documento solo
// di impostazioni, e non c'e' nessun record da riempire. Il vuoto non e' un debito.
//
// ⚠️ MA IL POSITIVO HA UNA TRAPPOLA SUA, ed e' il motivo per cui esiste `_seminaVersioniArticolo`:
// se le spunte nascessero VUOTE e i lettori le usassero subito, al primo caricamento nessun
// articolo potrebbe avere nessuna versione — e le caselle sparirebbero dalla scheda oggetto
// **anche dagli oggetti che quel flag ce l'hanno gia' scritto sopra**. Migliaia di variazioni e
// change diventerebbero cose impossibili che pero' esistono, senza che niente dia errore, e la
// casella per toglierle non ci sarebbe piu'. E' la famiglia del ripiego muto.
// Quindi le spunte **nascono seminate dai dati veri**: Franco, *"all'avvio mettiamo gia' a true i
// flag per cui ci sono dati"*. Una volta sola, non a ogni avvio (vedi la funzione).
//
// ⚠️ IN QUESTA RELEASE **NESSUN LETTORE USA QUESTO ELENCO**. La scheda oggetto continua a decidere
// con le due condizioni cablate di sempre (`section === 'retros'` e "ha un tipoProdotto"), quindi
// il comportamento del sito e' identico a prima. E' il passo **espandi** della sequenza che Franco
// ha usato per `articoliNascosti`: nasce il campo, si popola, i lettori si spostano DOPO (v6.234).
// Il collaudo di questa release e' percio' che **non si veda niente di diverso**.
//
// ⚠️ `isFreeVersion` E' UN NOME SCELTO, NON CONFERMATO. Segue le altre quattro, che sono inglesi.
// Finche' la v6.235 non lo scrive sui record costa una riga cambiarlo; dopo sarebbe una
// migrazione. Se il nome non va bene, e' ADESSO il momento di dirlo.
// ============================================================
// 🆕 v6.234 — L'ELENCO E' DIVENTATO L'UNICA FONTE, e non solo per la form della v6.233.
// Ogni voce porta adesso anche la CHIAVE del tipo, il COLORE, il marcatore eBay e la forma breve:
// da qui si ricavano `_COLORE_TIPO`, `_chiaveTipo`, `_etichettaTipo` e `ebayMarcatore`, che fino
// alla v6.233 erano quattro elenchi paralleli scritti a mano.
// ⚠️ L'ORDINE DELLE RIGHE E' L'ORDINE DI PRECEDENZA. Era implicito in ogni catena di `if`, e in
// tre catene su cinque era DIVERSO (vedi il CHANGELOG). Adesso e' un fatto scritto in un posto.
const VERSIONI_ARTICOLO = [
  { chiave: 'variation',           campo: 'isVariation',           it: 'Variazione ufficiale',     en: 'Official variation',
    badgeIt: 'Variazione<br>ufficiale', badgeEn: 'Official<br>variation',
    itBreve: 'Variazione', enBreve: 'Variation', livello: 'capo', partenza: ['base'],
    // v6.284 - come si nomina questa versione dopo "Includi": articolo compreso, perche' le
    // cinque frasi non hanno lo stesso articolo e da `it` non ci si arriva.
    esportaIt: 'Variazioni ufficiali', esportaEn: 'official variations',
    // v6.286 - la sola parola che prende il colore della versione: la sua posizione nella
    // frase cambia da riga a riga, quindi si dichiara invece di cercarla per regola.
    esportaParolaIt: 'Variazioni ufficiali', esportaParolaEn: 'official variations',
    colore: 'var(--type-official)',    badge: 'fig-badge-official',    marcatoreEbay: 'VARIAZIONE' },
  { chiave: 'unofficialVariation', campo: 'isUnofficialVariation', it: 'Variazione non ufficiale', en: 'Unofficial variation',
    badgeIt: 'Variazione<br>non ufficiale', badgeEn: 'Unofficial<br>variation',
    itBreve: 'Var. non ufficiale', enBreve: 'Unofficial var.', livello: 'capo', partenza: ['base'],
    // v6.284 - come si nomina questa versione dopo "Includi": articolo compreso, perche' le
    // cinque frasi non hanno lo stesso articolo e da `it` non ci si arriva.
    esportaIt: 'Variazioni non ufficiali', esportaEn: 'unofficial variations',
    // v6.286 - la sola parola che prende il colore della versione: la sua posizione nella
    // frase cambia da riga a riga, quindi si dichiara invece di cercarla per regola.
    esportaParolaIt: 'Variazioni non ufficiali', esportaParolaEn: 'unofficial variations',
    colore: 'var(--type-unofficial)',  badge: 'fig-badge-unofficial',  marcatoreEbay: 'VARIAZIONE NON UFFICIALE' },
  { chiave: 'change',              campo: 'isChange',              it: 'Change',                   en: 'Change',
    badgeIt: 'Change', badgeEn: 'Change',
    livello: 'figlio', partenza: ['base', 'variation', 'unofficialVariation'],
    campoTipo: 'changeType', opzioniTipo: '_opzioniTipoChange',
    // v6.266 - il PLURALE del titolo fisso del riquadro. Vedi la riga dell'omaggio.
    pluraleIt: 'Change', pluraleEn: 'Changes',
    // v6.267 - la coda della dicitura del raggruppamento, dettata da Franco. Vedi l'omaggio.
    codaRaggrIt: 'TIPO DI CHANGE', codaRaggrEn: 'CHANGE TYPE',
    // v6.284 - come si nomina questa versione dopo "Includi": articolo compreso, perche' le
    // cinque frasi non hanno lo stesso articolo e da `it` non ci si arriva.
    esportaIt: 'Change', esportaEn: 'changes',
    // v6.286 - la sola parola che prende il colore della versione: la sua posizione nella
    // frase cambia da riga a riga, quindi si dichiara invece di cercarla per regola.
    esportaParolaIt: 'Change', esportaParolaEn: 'changes',
    colore: 'var(--type-change)',      badge: 'fig-badge-change',      marcatoreEbay: 'CHANGE' },
  // ⚠️ v6.234 (Franco: "togliere nuova") — `nuova: true` RESTA, ma non si vede piu' da nessuna
  // parte. Non e' un'etichetta per l'utente: e' l'interruttore che tiene questa versione fuori da
  // `_VERSIONI_VIVE` finche' non arriva la v6.235. Scriverlo a schermo raccontava un dettaglio di
  // avanzamento del lavoro dentro una tabella che descrive il modello — due cose diverse.
  // 🔴 L'OMAGGIO STA QUI, FRA CHANGE ED ERRORE DI STAMPA, ed e' una decisione di Franco:
  // *"tutto come e' oggi, ma infila omaggio prima di errore di stampa"*. Vale sia come ordine di
  // ORDINAMENTO dentro il numero, sia come precedenza — che da questa release sono la stessa cosa,
  // letta da una riga sola invece che da tre catene di `if` che dicevano tre ordini diversi.
  // ⚠️ `nuova: true` la tiene fuori da `_chiaveTipo` e compagnia finche' non arriva la v6.235:
  // dichiarata, non ancora viva. Vedi `_VERSIONI_VIVE`.
  // 🆕 v6.240 (Franco) - SI CHIAMA "OMAGGIO", non "Versione omaggio". Il nome nasceva dall'elenco
  // che Franco aveva dettato (*"5. Versione omaggio"*), quando "versione" era ancora la parola da
  // introdurre. Adesso che il campo, la colonna e il selettore si chiamano tutti VERSIONE, un
  // valore che comincia con "Versione" ripeteva il nome della categoria — e gli altri quattro no.
  // E' la stessa ambiguita' tolta ai retro nella v6.237 con "Tipo" / "Tipo di change".
  // 📌 Cambiata UNA riga e cambiano tutti e otto i punti in cui il nome compare: badge, colonna,
  // casella, selettore, le due tabelle della console, la tendina dei valori. E' esattamente cio'
  // per cui la v6.234 ha reso tutto derivato — la prova si vede meglio qui che altrove.
  // ⚠️ Il CAMPO su Firestore resta `isFreeVersion`. Come `nomeCorto`, `forSale` e `tipoProdotto`:
  // *si cambia cio' che si LEGGE, non cio' che si CHIAMA* — rinominarlo sarebbe una migrazione su
  // ogni record per cambiare una parola che nessuno vede.
  { chiave: 'free',                campo: 'isFreeVersion',         it: 'Omaggio',                  en: 'Free',
    badgeIt: 'Omaggio', badgeEn: 'Free',
    // 🆕 v6.235 - VIVA. Tolto `nuova: true`, ed e' l'unica riga che serviva: da qui la Versione
    // omaggio entra in `_VERSIONI_VIVE` e compare DA SE' nel colore, nell'etichetta, in `_eBase`,
    // nei due ranghi dell'ordinamento, nella priorita' della ricerca e nel marcatore eBay. Tutto
    // cio' che la v6.234 aveva reso derivato non e' stato toccato in questa release: e' la prova
    // che quel lavoro serviva a qualcosa.
    livello: 'figlio', partenza: ['base', 'variation'],
    campoTipo: 'freeVersionType', opzioniTipo: '_opzioniTipoOmaggio',
    // 🆕 v6.266 - IL PLURALE, e non si deriva da `it`: il titolo fisso del riquadro dice
    // "Omaggi per tipo", e da "Omaggio" non si arriva a "Omaggi" senza inventare una regola di
    // grammatica italiana - che su "Errore di stampa" -> "Errori di stampa" sbaglierebbe subito.
    // Stessa ragione di `prefissoTipo` (v6.257): un'etichetta e un plurale sono due mestieri.
    // ⚠️ `pluraleEn: 'Free items'` e' l'unica parola NUOVA di questa release: "Frees" non esiste
    // e "Free by type" si legge come un prezzo. Da confermare guardandola.
    pluraleIt: 'Omaggi', pluraleEn: 'Free items',
    // 🆕 v6.267 - LA CODA DELLA DICITURA DEL RAGGRUPPAMENTO, e le tre code NON sono uniformi:
    // qui "TIPOLOGIA DI OMAGGIO", sull'errore di stampa "TIPOLOGIA ERRORE DI STAMPA" (senza DI),
    // sul change "TIPO DI CHANGE". Sono le parole di Franco, confermate chiedendo prima di
    // scrivere proprio perche' la differenza sembra una svista e non lo e'.
    // ⚠️ E' la ragione per cui questo campo esiste: la v6.266 ricavava la frase da `it`, e una
    // derivazione non puo' produrre tre forme diverse. Quando il testo non e' una funzione
    // dell'etichetta, si dichiara — come `prefissoTipo` (v6.257) e i plurali (v6.266).
    codaRaggrIt: 'TIPOLOGIA DI OMAGGIO', codaRaggrEn: 'FREE TYPE',
    // 🆕 v6.257 - LA PAROLA CHE PRECEDE IL TIPO NEL NOME COMPLETO (Franco).
    // ⚠️ NON e' `it`, ed e' il punto: `it` e' un'etichetta DA MOSTRARE, e stanotte e' stata
    // rinominata (v6.240, "Versione omaggio" -> "Omaggio"). Il Nome completo e' un campo SALVATO:
    // se derivasse dall'etichetta, ogni rinomino cambierebbe in silenzio i nomi calcolati DOPO,
    // facendoli divergere da quelli gia' scritti — e nessuno se ne accorgerebbe.
    // Sono due mestieri diversi e ora hanno due campi diversi. Le altre versioni non lo
    // dichiarano, quindi non prefissano niente: e' cio' che decisero la v5.755 e la v5.774.
    prefissoTipo: 'OMAGGIO',
    // v6.284 - come si nomina questa versione dopo "Includi": articolo compreso, perche' le
    // cinque frasi non hanno lo stesso articolo e da `it` non ci si arriva.
    esportaIt: 'versioni Omaggio', esportaEn: 'free versions',
    // v6.286 - la sola parola che prende il colore della versione: la sua posizione nella
    // frase cambia da riga a riga, quindi si dichiara invece di cercarla per regola.
    esportaParolaIt: 'Omaggio', esportaParolaEn: 'free versions',
    colore: 'var(--type-free)',        badge: 'fig-badge-free',        marcatoreEbay: null },
  { chiave: 'printError',          campo: 'isPrintError',          it: 'Errore di stampa',         en: 'Print error',
    badgeIt: 'Errore<br>di stampa', badgeEn: 'Print<br>error',
    livello: 'figlio', partenza: ['base', 'variation', 'unofficialVariation'],
    // ⚠️ `opzioniTipo: null` non e' una dimenticanza: il Tipo di errore di stampa e' l'unico dei tre
    // a ELENCO APERTO (testo libero). E' la differenza che rende la cella della Tipologia un
    // controllo diverso riga per riga, e sta scritta qui invece che in un `if` sparso.
    campoTipo: 'printErrorType', opzioniTipo: null,
    pluraleIt: 'Errori di stampa', pluraleEn: 'Print errors',
    codaRaggrIt: 'TIPOLOGIA ERRORE DI STAMPA', codaRaggrEn: 'PRINT ERROR TYPE',
    // v6.284 - come si nomina questa versione dopo "Includi": articolo compreso, perche' le
    // cinque frasi non hanno lo stesso articolo e da `it` non ci si arriva.
    esportaIt: 'Errori di stampa', esportaEn: 'print errors',
    // v6.286 - la sola parola che prende il colore della versione: la sua posizione nella
    // frase cambia da riga a riga, quindi si dichiara invece di cercarla per regola.
    esportaParolaIt: 'Errori di stampa', esportaParolaEn: 'print errors',
    colore: 'var(--type-printerror)',  badge: 'fig-badge-printerror',  marcatoreEbay: 'ERRORE DI STAMPA' }
];

// Le versioni che il codice riconosce OGGI. La quinta entrera' qui con la v6.235, e in quel
// momento comparira' da se' in tutti i posti che derivano da questo elenco: e' esattamente cio'
// che questa release compra.
const _VERSIONI_VIVE = VERSIONI_ARTICOLO.filter(v => !v.nuova);

// 🆕 v6.266 - LE VERSIONI CHE HANNO UN TIPO, e che quindi si possono raggruppare nei risultati.
// Non e' un elenco nuovo: e' una domanda a quello che c'e' gia'. `campoTipo` sta su change, omaggio
// ed errore di stampa e non sta sulle due variazioni - che un tipo non ce l'hanno - quindi la
// risposta e' gia' scritta sopra e non va tenuta allineata a mano da nessuna parte.
const _VERSIONI_CON_TIPO = _VERSIONI_VIVE.filter(v => v.campoTipo);
const _versioneDiChiave = c => VERSIONI_ARTICOLO.find(v => v.chiave === c) || null;

// 🆕 v6.234 — I DUE LIVELLI DELL'ORDINAMENTO DELLE FIGURINE, ricavati dall'elenco.
//
// L'ordine dentro un numero NON e' una lista piatta di cinque, ed e' la cosa da capire prima di
// toccarlo: base e variazioni sono CAPIGRUPPO, change ed errori di stampa sono FIGLI appesi sotto
// un capogruppo (v6.088). Erano due catene separate — `rangoFiglio` e `rankCapo` dentro
// `_chiaviOrdinamentoFigurine` — e nessuna delle due sapeva dell'altra.
//
// 📌 Franco, sull'omaggio: *"numero, e poi dentro (variazione uff, variazione non uff, change,
// omaggio, errore di stampa)... tutto come e' oggi, ma infila omaggio prima di errore di stampa"*.
// Fra change ed errore di stampa ci sono i FIGLI: quindi la Versione omaggio e' un figlio, appeso
// alla sua base come lo e' un change — non un capogruppo come le variazioni.
//
// I due ranghi sono la POSIZIONE nell'elenco, quindi l'ordine di dichiarazione e' l'unico posto
// dove si decide. ⚠️ Oggi i valori coincidono uno per uno con quelli scritti a mano prima
// (variazione 1, non ufficiale 2; change 1, errore di stampa 2), perche' `_VERSIONI_VIVE` tiene
// fuori l'omaggio: quando la v6.235 lo fara' vivere, l'errore di stampa slittera' da 2 a 3 **da
// se'**, senza che nessuno debba ricordarsene. E' cio' che questa release compra.
const _CAPI_VERSIONE   = _VERSIONI_VIVE.filter(v => v.livello === 'capo');
const _FIGLI_VERSIONE  = _VERSIONI_VIVE.filter(v => v.livello === 'figlio');
const _rangoFiglio = f => { const i = _FIGLI_VERSIONE.findIndex(v => f && f[v.campo]); return i < 0 ? 0 : i + 1; };
const _rangoCapo   = f => { const i = _CAPI_VERSIONE.findIndex(v => f && f[v.campo]);  return i < 0 ? 0 : i + 1; };

// La priorita' piatta, per chi ordina senza i due livelli (la ricerca globale). Base = 0.
const _prioritaTipo = f => { const i = _VERSIONI_VIVE.findIndex(v => f && f[v.campo]); return i < 0 ? 0 : i + 1; };

// 🆕 v6.234 — DA CHI PUO' NASCERE OGNI VERSIONE. Franco, sull'omaggio: *"un articolo omaggio e'
// sempre collegato a un articolo di partenza, e questo puo' essere 2 cose: una versione base, una
// versione ufficiale. Mai un change, mai un errore di stampa, mai una variazione non ufficiale."*
//
// 🔴 PERCHE' SERVE UN CAMPO NUOVO invece di riusare quello che c'era. Fino a qui "chi e'
// CAPOGRUPPO" e "da chi si puo' DISCENDERE" erano scritti con la stessa espressione — *"non e'
// change ne' errore di stampa"* — e davano la stessa risposta per pura coincidenza. La regola
// dell'omaggio la rompe: le partenze sono due su tre, non tre su tre. Da qui in avanti sono due
// domande distinte, e questa ha una risposta sua, riga per riga.
//
// ⚠️ PER LE ALTRE QUATTRO E' DICHIARATO CIO' CHE IL CODICE FA OGGI, non cio' che sarebbe giusto:
// change ed errore di stampa possono nascere anche da una variazione non ufficiale. Non l'ho
// ristretto perche' Franco non l'ha chiesto, e una regola nuova nascosta in una release che dice
// "non cambia niente" sarebbe la cosa peggiore da cercare fra sei mesi.
//
// 📌 «CHI PUO' FARE DA PARTENZA» NON E' UN CAMPO: si ricava. Una versione puo' fare da partenza se
// compare nell'elenco di qualcun altro — e la Versione omaggio non compare in nessuno, quindi e'
// una foglia (Franco: *"no, mai"*). Il giorno che dovesse diventare padre, la si aggiunge a una
// riga: non c'e' un secondo posto da tenere allineato.
//
// ⚠️ IN QUESTA RELEASE NESSUNO LEGGE ANCORA QUESTO CAMPO. La tendina "figurina di partenza" filtra
// come sempre. E' una dichiarazione, e la tabella in console serve a controllarla PRIMA che
// cominci a comandare.
const _partenzeDi = chiave => (_versioneDiChiave(chiave)?.partenza) || [];

// 🆕 v6.242 — LA TIPOLOGIA: quale campo porta il "tipo di..." di questa versione.
//
// 📌 Change, errore di stampa e omaggio hanno ciascuno il proprio campo — `changeType`,
// `printErrorType`, `freeVersionType` — e sono MUTUAMENTE ESCLUSIVI per costruzione, perche' lo
// sono le versioni. Su una riga qualunque al massimo uno dei tre e' pieno: e' la ragione per cui
// nelle tabelle basta UNA colonna, e non e' un compromesso per far stare tutto — tre colonne
// sarebbero tre colonne di cui due sempre vuote, cioe' la tabella che mente sulla forma del dato.
// Base e variazioni non ne dichiarano nessuno: cella vuota, ed e' l'informazione giusta.
//
// ⚠️ `opzioniTipo` e' il NOME della funzione, non la funzione: le due (`_opzioniTipoChange`,
// `_opzioniTipoOmaggio`) sono dichiarate molto piu' sotto in questo file. Le dichiarazioni di
// funzione sono sollevate, quindi un riferimento diretto funzionerebbe — ma smetterebbe di
// funzionare il giorno che qualcuno le riscrive come `const`, e senza dare errore qui: darebbe una
// pagina bianca al caricamento (v6.117/140/151/195). Col nome, il legame si risolve quando serve.
const _FUNZIONI_OPZIONI_TIPO = {
  _opzioniTipoChange:  (seriesId, sel) => _opzioniTipoChange(seriesId, sel),
  // v6.253 - l'omaggio riceve anche la SEZIONE. ⚠️ Il change no, di proposito: li' i due elenchi
  // distinguono i change che hanno un retro PROPRIO da quelli che usano il retro della base
  // (v6.102) — una distinzione che NON coincide con la sezione. Restringerli "per simmetria"
  // toglierebbe scelte legittime, e non e' stato chiesto.
  _opzioniTipoOmaggio: (seriesId, sel, sezione) => _opzioniTipoOmaggio(seriesId, sel, sezione)
};
// Il campo della tipologia di un oggetto, o null se la sua versione non ne ha una.
const _campoTipoDi = f => (_versioneDiChiave(_chiaveTipo(f))?.campoTipo) || null;
// Tutti i campi-tipologia esistenti: serve a chi deve sapere "questo campo e' una tipologia?"
// senza riscrivere l'elenco (per esempio il ricalcolo del Nome completo in `saveBulkCell`).
const _CAMPI_TIPOLOGIA = VERSIONI_ARTICOLO.map(v => v.campoTipo).filter(Boolean);

// 🆕 v6.235 (Franco: "verifica che la query combaci con la tabellina") — IL CONTROLLO SUI DATI VERI.
//
// Da questa release la tendina "figurina di partenza" filtra leggendo `partenza`, quindi query e
// tabella non possono piu' divergere: sono la stessa riga. Ma questo dice solo che d'ora in avanti
// non si creeranno legami illegali — non dice niente sui legami GIA' SCRITTI, che sono nati sotto
// la regola vecchia (*"tutto tranne change ed errori di stampa"*), piu' larga.
//
// 🔴 E la differenza non e' teorica, ce n'e' almeno una certa: la tabella dichiara che una
// VARIAZIONE nasce solo da una base, mentre il filtro di prima ammetteva anche le variazioni fra i
// candidati. Quella riga della tabella l'ho scritta io nella v6.234 presentandola come una
// descrizione di cio' che il codice faceva: era una restrizione. Se nei dati c'e' una variazione
// appesa a un'altra variazione, la sua tendina da oggi non mostra piu' la sua partenza — il
// collegamento resta scritto sul record ma diventa invisibile e non piu' riselezionabile.
//
// 📌 Percio' il controllo guarda i DATI, non il codice: per ogni oggetto con una partenza, la
// versione del padre e' fra quelle ammesse? Gira in console da admin, una volta, e stampa il conto
// per tipo di violazione. **Silenzio = la tabella descrive davvero i dati.**
// ⚠️ Non corregge niente e non blocca niente: dice. Cosa farne — allargare la tabella o sistemare i
// record — e' una decisione di Franco, e i due rimedi non sono equivalenti.
let _partenzeVerificate = false;
function verificaPartenzeSuiDati(silenzioSeOk) {
  const items = getData('figurines', []) || [];
  if (!items.length) return null;
  const idx = new Map(items.map(f => [f.id, f]));
  const violazioni = [];
  for (const f of items) {
    if (!f.baseFigurineId) continue;
    const mia = _chiaveTipo(f);
    if (mia === 'base') continue;                 // una base non dovrebbe avere una partenza
    const padre = idx.get(f.baseFigurineId);
    if (!padre) continue;                         // legame rotto: e' un'altra diagnosi (_diagnosiErrori)
    const suo = _chiaveTipo(padre);
    if (_partenzeDi(mia).includes(suo)) continue;
    violazioni.push({ figlio: f, tipoFiglio: mia, padre, tipoPadre: suo });
  }
  if (!violazioni.length) {
    if (!silenzioSeOk) console.log('[v6.235] \u2705 partenze: nessuna violazione. La tabella descrive i dati.');
    return violazioni;
  }
  console.warn('[v6.235] \uD83D\uDD34 ' + violazioni.length + ' oggetti hanno una partenza che la tabella '
    + '\u00ABDa chi pu\u00F2 nascere ogni versione\u00BB non ammette. Sono nati sotto la regola vecchia, '
    + 'piu\' larga. Da oggi la loro tendina non offre piu\' quella partenza.');
  const perCoppia = new Map();
  violazioni.forEach(v => {
    const k = v.tipoFiglio + ' \u2190 ' + v.tipoPadre;
    perCoppia.set(k, (perCoppia.get(k) || 0) + 1);
  });
  [...perCoppia.entries()].sort((a, b) => b[1] - a[1]).forEach(([k, n]) => {
    const [figlio, padre] = k.split(' \u2190 ');
    console.warn('   \u2022 ' + n + '  \u00D7  ' + _etichettaChiaveTipo(figlio) + '  con partenza  ' + _etichettaChiaveTipo(padre));
  });
  console.warn('   I due rimedi NON sono equivalenti: allargare la tabella cambia il modello, '
    + 'sistemare i record cambia i dati. Decide Franco.');
  console.warn('   Elenco completo:', violazioni.map(v => (v.figlio.name || v.figlio.id) + ' \u2190 ' + (v.padre.name || v.padre.id)));
  return violazioni;
}
const _puoEsserePartenza = chiave =>
  chiave === 'base' || VERSIONI_ARTICOLO.some(v => (v.partenza || []).includes(chiave));
// 🆕 v6.236 (Franco) — L'ETICHETTA DELLA CASELLA PORTA IL COLORE DELLA SUA VERSIONE.
//
// 📌 Le cinque caselle della scheda oggetto dicono la stessa cosa che dicono il badge sulla card,
// la colonna Tipo e il selettore della ricerca — e quelle tre sono colorate da sempre. La casella
// no: era l'unico punto in cui il nome di una versione compariva in grigio come tutte le altre
// etichette della form. Franco: *"sarebbe carino che i campi flag associati alle versioni avessero
// la etichetta conforme al color code"*.
//
// ⚠️ Vale per TUTTI E SETTE gli articoli, e non perche' l'abbia scritto sette volte: la scheda
// oggetto e' UNA funzione sola (`switchToEditMode`), quindi il colore arriva ovunque da se'. La
// stessa ragione per cui, se domani nasce una sesta versione, la sua casella nasce gia' colorata.
//
// 📌 Il testo NON e' un parametro: viene da `VERSIONI_ARTICOLO` come il colore. Passandolo a mano
// si sarebbero potuti scrivere due nomi diversi per la stessa versione — l'etichetta della casella
// e quella del badge — che e' il difetto che questa release sta chiudendo, non uno da aprire.
function _labelVersione(chiave) {
  const v = _versioneDiChiave(chiave);
  const testo = v ? (currentLang === 'it' ? v.it : v.en) : chiave;
  const col = (v && v.colore) || 'var(--text)';
  return '<span class="detail-label" style="color:' + col + ';">' + esc(testo) + '</span>';
}

const _etichettaChiaveTipo = chiave => {
  if (chiave === 'base') return currentLang === 'it' ? 'Base' : 'Base';
  const v = _versioneDiChiave(chiave);
  return v ? (currentLang === 'it' ? v.it : v.en) : chiave;
};

// 🆕 v6.234 — UN OGGETTO BASE: quello che non porta NESSUNA versione. Era la quaterna di negazioni
// scritta a mano, e diventera' cinque senza che nessuno la riscriva.
// I contatori del taglio Prodotti contano questi (scelta di Franco). Il numero che ne esce e' la
// dimensione del set — Serie 1: 160, Serie 2 e 3: 256 — mentre il totale (368, 257, 799) e'
// un'altra cosa. ⚠️ Quei tre numeri sono anche il collaudo: se cambiassero in questa release,
// qualcosa non ha ricavato cio' che c'era prima.
const _eBase = f => !!f && !_VERSIONI_VIVE.some(v => f[v.campo]);
const _diTipo = (tutti, sec) => tutti.filter(f => (f.section || 'figurines') === sec);

// La copia locale, per non aspettare la rete a ogni disegno: stesso schema di `_colonneDefault`
// (v6.197) e del tetto d'attesa (v6.173).
function _versioniArticoloSalvate() {
  try { return JSON.parse(LOCAL.get('versioniArticolo') || 'null') || null; } catch (e) { return null; }
}

// Le versioni possibili per un articolo. ⚠️ Il ripiego quando non si sa ancora niente e' **tutte
// e quattro le vecchie**, non l'elenco vuoto: un lettore futuro che trovasse vuoto perche' la
// semina non e' ancora passata toglierebbe caselle che devono esserci. Il vuoto voluto da Franco
// e il vuoto "non lo so ancora" sono due cose diverse e qui vanno distinte.
function _versioniDi(sez) {
  const salvate = _versioniArticoloSalvate();
  const v = salvate && salvate[sez];
  if (Array.isArray(v)) return v;
  return VERSIONI_ARTICOLO.filter(x => !x.nuova).map(x => x.campo);
}

// 🆕 v6.233 — LA SEMINA, UNA VOLTA SOLA.
//
// 🔴 PERCHE' NON A OGNI AVVIO, che era la lettura possibile di "all'avvio": se rileggesse i dati
// ogni volta, una spunta che Franco TOGLIE a mano si riaccenderebbe al ricaricamento successivo
// finche' resta anche un solo oggetto con quel flag — cioe' la pagina disferebbe la sua decisione
// senza dirglielo. Seminare e' un gesto iniziale; tenere allineato sarebbe un'altra cosa, e non e'
// quella chiesta.
//
// ⚠️ SOLO DA ADMIN. Le regole di Firestore riservano la scrittura su `settings` all'admin: se la
// chiamasse un visitatore qualunque, sarebbe una scrittura rifiutata ad ogni caricamento del sito.
//
// 📌 SE FALLISCE SI VEDE. Niente `catch` muto: il documento non viene scritto, la prossima apertura
// da admin ci riprova, e intanto la causa vera finisce in console. E' la lezione della v6.232 —
// un controllo spento in silenzio e' peggio di uno che segnala il falso.
async function _seminaVersioniArticolo() {
  if (!currentUser?.isAdmin) return;
  try {
    const docs = await fsGetAll('settings');
    const gia = docs.find(d => d.id === 'versioni_articolo');
    if (gia && gia.perArticolo) {
      LOCAL.set('versioniArticolo', JSON.stringify(gia.perArticolo));
      return;                                  // c'e' gia': non si semina due volte
    }
    const items = getData('figurines', []) || [];
    if (!items.length) return;                 // senza oggetti il seme direbbe "niente e' possibile"
    const per = {};
    for (const sez of PRODOTTI_INVENTARIO) {
      const suoi = items.filter(f => (f.section || 'figurines') === sez);
      per[sez] = VERSIONI_ARTICOLO
        .filter(v => !v.nuova && suoi.some(f => f[v.campo] === true))
        .map(v => v.campo);
    }
    await fsSave('settings', { id: 'versioni_articolo', perArticolo: per, seminato: new Date().toISOString() });
    LOCAL.set('versioniArticolo', JSON.stringify(per));
    console.log('[v6.233] versioni per articolo seminate dai dati:', per);
  } catch (e) {
    console.error('[v6.233] semina delle versioni NON riuscita (si riprovera\' alla prossima apertura da admin):', e.message || e);
  }
}

// L'ultima scelta si ricorda. Un bivio che si ripresenta identico ad ogni visita diventa un
// casello: alla terza volta uno sa gia' dove vuole andare, e la domanda e' solo un clic in piu'.
let _taglioInventario = 'serie';
try { if (localStorage.getItem('sgb_taglio') === 'prodotti') _taglioInventario = 'prodotti'; } catch (e) {}

function impostaTaglioInventario(taglio) {
  _taglioInventario = (taglio === 'prodotti') ? 'prodotti' : 'serie';
  try { localStorage.setItem('sgb_taglio', _taglioInventario); } catch (e) {}
  _aggiornaBivioInventario();
  renderCatalog();
}

// ============================================================
// v6.174 (Franco) — IL RIEPILOGO DI TUTTE LE SERIE, per gli utenti.
// ------------------------------------------------------------
// E' un SOTTOINSIEME della vista tabellare admin, non una tabella nuova: gli stessi numeri, presi
// dalla stessa `_conteggiSerie`. Se un domani cambia la definizione di "figurina base", cambia in
// tutti e tre i posti insieme — scheda, tabella admin e questa.
// ⚠️ Qui NON compaiono le colonne che descrivono come e' fatto il sito (colonne della griglia,
// flag, azioni): a un visitatore direbbero come e' costruito il catalogo, non cosa contiene.
// ⚠️ E le serie senza prodotti CI SONO lo stesso, con le celle vuote: sono censite, e un elenco che
// le nasconde farebbe credere che non esistano. Se non le vuoi, e' una riga di filtro.
// ============================================================
function apriInfoTutteLeSerie() {
  const el = document.getElementById('info-serie-contenuto');
  if (!el) return;
  const it = currentLang === 'it';
  // v6.177 - su telefono la tabella si asciuga: la foto si porta il nome sotto (una colonna invece
  // di due), il nome e' quello CORTO e le intestazioni sono quelle della tabella admin, che sono
  // brevi proprio perche' nate dove lo spazio manca. Sul desktop resta tutto per esteso.
  const mobile = _isMobileViewport();
  const figs = getData('figurines', []);
  // v6.177 (Franco) - FUORI LE SERIE SENZA FIGURINE, cioe' quelle con N. FIGURINE a zero. Nasce da
  // "Extra serie", che non e' una serie ma il contenitore dei prodotti extra serie (v6.144): ha 8
  // Cartoncini e zero figurine, e in un riepilogo delle serie non ci deve stare.
  // ⚠️ SI E' SCELTO IL CRITERIO, NON IL CASO. Un flag "serie fittizia" sarebbe stato un campo nuovo
  // per una sola serie accesa (Franco: "non voglio un flag per un solo caso"), e cablare il nome
  // avrebbe smesso di funzionare in silenzio al primo rinomina. Cosi' invece la regola si legge
  // dalla tabella stessa: sparisce cio' che avrebbe la prima colonna numerica vuota.
  // 📌 Il conteggio e' `base` di `_conteggiSerie`, quindi le sole figurine del set base — senza
  // variazioni, change ed errori di stampa. Oggi escono: Extra serie, Kakkones, Weird Ball,
  // I Mitici Sgorbions - Stamps.
  const series = getData('series', [])
    .filter(s => _conteggiSerie(figs.filter(f => f.seriesId === s.id)).base > 0)
    .sort((a, b) => (a.order ?? 9999) - (b.order ?? 9999));

  // v6.175 (Franco) - I NOMI DELLE COLONNE SONO QUELLI CHE HA SCRITTO LUI, alla lettera. Nella
  // v6.174 avevo ripreso quelli della tabella admin, che sono abbreviati — ma la' lo sono perche'
  // c'e' poco spazio, e in una finestra larga quell'abbreviazione non ha nessuna ragione di essere.
  // Copiare un'etichetta senza il vincolo che l'aveva prodotta e' copiare la conseguenza e lasciare
  // indietro la causa.
  // 📌 Unico scostamento, e va detto: Franco aveva scritto "ULTIMA GIF." — refuso per "FIG.".
  // La prima colonna non ha intestazione: e' la miniatura, e un titolo sopra una foto direbbe una
  // cosa che si vede da se'.
  const intestazioni = mobile
    // v6.179 (Franco) - SU TELEFONO "DA" E "A" SPARISCONO: il loro contenuto entra sotto il conteggio
    // delle figurine, nella forma  60 / (1/160). Due colonne strette che portavano un numero
    // ciascuna diventano due righe di una colonna sola, e la tabella perde due colonne su nove.
    // v6.180 (Franco) - le due colonne delle variazioni diventano UNA, chiamata VAR, con dentro due
    // righe etichettate. Stessa idea della v6.179 su DA/A: due colonne strette che portano un numero
    // ciascuna occupano piu' larghezza delle due righe che le sostituiscono, e su telefono la
    // larghezza e' l'unica risorsa scarsa. Il riepilogo passa da sette colonne a sei.
    // v6.182 (Franco) - le intestazioni di telefono scendono dal tutto-maiuscolo a "N. figurine",
    // "Change figurine", "Change retro". A parita' di larghezza il minuscolo si legge prima: le
    // maiuscole hanno tutte lo stesso ingombro verticale e tolgono alla parola il profilo da cui la
    // si riconosce senza compitarla. Le spezzature restano dov'erano.
    // v6.208 (Franco) - "N. FIG", con FIG a capo. ⚠️ Va contro la v6.182, che su telefono
    // aveva portato queste intestazioni al minuscolo perche' *"a parita' di larghezza il minuscolo
    // si legge prima"*. Vale ancora per le parole INTERE - `Change figurine` resta com'e' - ma non
    // per una sigla: `FIG` non e' una parola da riconoscere a colpo d'occhio, e' un'abbreviazione,
    // e le maiuscole la fanno leggere come tale invece che come un troncamento. E' anche cio' che
    // la mette in riga con `VAR`, che era gia' maiuscola dalla v6.180.
    // \uD83D\uDCCC L'inglese NON diventa FIG: li' vuol dire "figura", non "figurina". Resta `stickers`.
    // \uD83C\uDD95 v6.209 (Franco) - QUATTRO COLONNE DIVENTANO UNA, chiamata SPECIALI. Le due variazioni
    // e i due change portavano un numero ciascuno; ora stanno in una cella sola su quattro righe
    // etichettate. Il riepilogo passa da SEI colonne a QUATTRO.
    // \uD83D\uDCCC E' la terza volta che questa tabella fa la stessa mossa, ed e' la piu' ampia: la v6.179
    // aveva fuso DA e A dentro il conteggio, la v6.180 le due variazioni in VAR. Ogni volta il
    // guadagno e' lo stesso e vale la pena scriverlo come regola: **su telefono due colonne strette
    // che portano un numero ciascuna occupano piu' larghezza delle due righe che le sostituiscono**,
    // perche' ogni colonna paga l'intestazione, i due margini e il bordo, mentre una riga in piu'
    // dentro una cella paga solo la sua altezza - e l'altezza, in verticale, non e' scarsa.
    // ⚠️ L'inglese SPECIALS e' una scelta mia: Franco ha dato le quattro etichette inglesi ma
    // non il nome della colonna. Da confermare.
    // v6.210 (Franco) - VIA LA COLONNA ANNO: l'anno scende sotto la foto, accanto al nome, e senza
    // etichetta - quattro cifre fra il 1985 e il 2010 si riconoscono da sole, e "ANNO: 1991" spende
    // una parola per dire una cosa che il numero dice da se'.
    // \uD83D\uDCCC Terza colonna che sparisce cosi': il NOME era gia' finito sotto la foto con la v6.177,
    // per la stessa ragione. La prima cella non e' piu' "la miniatura": e' l'identita' della serie -
    // foto, nome, anno - e le altre tre colonne portano solo numeri.
    // v6.211 (Franco) - la colonna RETRO anche su telefono, fra il conteggio delle figurine e
    // SPECIALI. ⚠️ E' una COLONNA e non una riga dentro SPECIALI: la regola della v6.209 dice
    // che due colonne strette costano piu' delle due righe che le sostituiscono, ma vale per numeri
    // che si LEGGONO INSIEME - le variazioni fra loro, i change fra loro. Il conto dei retro invece
    // sta accanto a quello delle figurine: sono le due quantita' che descrivono la serie, e si
    // guardano affiancate. Metterlo dentro SPECIALI l'avrebbe sepolto fra i contrassegni.
    ? (it ? ['', 'N.<br>FIG', 'RETRO', 'SPECIALI']
          : ['', 'N.<br>stickers', 'BACKS', 'SPECIALS'])
    // v6.177 (Franco) - via il prefisso "N." / "NUMERO": la colonna dice gia' di essere un conteggio
    // perche' sotto ci sono dei numeri, e cinque prefissi uguali allungano le intestazioni senza
    // aggiungere niente. Stessa idea del "SI" tolto nella v6.166 e del `#` tolto nella v6.115.
    // 📌 Due delle cinque righe che Franco ha mandato dicevano "VARIAZIONI UFFICIALI" al posto di
    // "NON UFFICIALI" e "CHANGE DI FIGURINA" al posto di "DI RETRO": refusi confermati da lui, non
    // applicati alla lettera. Alla lettera avrebbero prodotto due coppie di colonne OMONIME - cioe'
    // il difetto che la v6.174 aveva appena tolto alla colonna "Change" della console admin.
    // v6.178 (Franco) - le intestazioni lunghe vanno a capo dove lo dice lui, con un `<br>` scritto
    // e non lasciato all'a-capo automatico. La differenza non e' estetica: l'a-capo automatico
    // spezza dove capita a seconda della larghezza della colonna, quindi "VARIAZIONI NON UFFICIALI"
    // poteva diventare "VARIAZIONI / NON UFFICIALI" su uno schermo e "VARIAZIONI NON / UFFICIALI"
    // su un altro. Scritto, si spezza sempre allo stesso punto.
    // 📌 Le abbreviazioni "PRIMA FIG." / "ULTIMA FIG." spariscono: su due righe c'e' posto per la
    // parola intera, e un'abbreviazione senza il vincolo che la giustificava e' solo una parola
    // tagliata (e' la stessa correzione della v6.175, applicata a due colonne rimaste indietro).
    // v6.211 - la colonna RETRO anche su desktop: e' un dato della serie, e mostrarlo su telefono
    // e non sullo schermo largo sarebbe l'unico caso in cui il telefono dice di piu'.
    : (it ? ['', 'NOME', 'ANNO', 'FIGURINE', 'PRIMA<br>FIGURINA', 'ULTIMA<br>FIGURINA', 'VARIAZIONI<br>UFFICIALI', 'VARIAZIONI NON<br>UFFICIALI', 'CHANGE<br>DI FIGURINA', 'RETRO', 'CHANGE<br>DI RETRO', 'OMAGGIO']
          : ['', 'NAME', 'YEAR', 'STICKERS', 'FIRST<br>STICKER', 'LAST<br>STICKER', 'OFFICIAL<br>VARIATIONS', 'UNOFFICIAL<br>VARIATIONS', 'STICKER<br>CHANGE', 'BACKS', 'BACK<br>CHANGE', 'FREE']);

  // Tutto centrato tranne una colonna per variante, e per lo stesso motivo: quando una cella
  // contiene TESTO di lunghezza diversa riga per riga, centrarla toglie il bordo da cui l'occhio
  // riparte.
  //   desktop -> il NOME (indice 1).
  //   mobile  -> la colonna VAR (indice 3), che dalla v6.181 contiene due righe etichettate
  //              "UFF: n" e "NON UFF: m": centrate, le due etichette non si incolonnano fra loro
  //              ne' fra una riga e l'altra della tabella.
  // ⚠️ Gli indici sono DUE perche' le due varianti hanno colonne diverse: sul mobile il nome non ha
  // una colonna sua (sta sotto la foto) e VAR e' la quarta. Un indice solo avrebbe allineato la
  // colonna sbagliata su una delle due.
  // \uD83D\uDD34 v6.210 - L'INDICE DI TELEFONO PASSA DA 3 A 2, perche' togliendo ANNO la colonna
  // SPECIALI scala di un posto. La v6.209 aveva scritto proprio questo avvertimento - *"e' scritto
  // a mano ed e' l'unico punto di questa tabella che non si ricava dagli array"* - e una release
  // dopo e' servito. \uD83D\uDCCC Sbagliarlo non da' nessun errore: allinea a sinistra una colonna di
  // numeri e lascia centrata quella di testo, e la tabella continua a sembrare giusta.
  // \uD83D\uDD34 v6.211 - L'INDICE NON SI SCRIVE PIU' A MANO, SI RICAVA. Era un numero letterale, ed e'
  // scalato DUE volte in due release: 3 -> 2 quando la v6.210 ha tolto la colonna ANNO, e sarebbe
  // scalato di nuovo adesso aggiungendo N. RETRO. La v6.209 l'aveva scritto come avvertimento e la
  // v6.210 l'ha dovuto correggere: due volte e' abbastanza per smettere di ricordarselo.
  // \uD83D\uDCCC Sbagliarlo non da' NESSUN errore - allinea a sinistra una colonna di numeri e lascia
  // centrata quella di testo, e la tabella continua a sembrare giusta. E' la stessa forma dei
  // difetti muti chiusi in questi due giorni, e la contromisura e' la stessa: si CALCOLA invece di
  // ricordarselo, esattamente come l'arretrato delle cartelle e l'ordine delle dichiarazioni.
  // La colonna da allineare a sinistra e' quella che contiene TESTO: su telefono SPECIALI, su
  // desktop il NOME. Si trovano per contenuto, non per posizione.
  const _iSinistra = intestazioni.findIndex(h => mobile ? /SPECIAL/i.test(h) : /^(NOME|NAME)$/i.test(h));
  const aSinistra = i => i === _iSinistra;

  const righe = series.map(s => {
    const c = _conteggiSerie(figs.filter(f => f.seriesId === s.id));
    // v6.175 - la miniatura della foto della serie. Se la foto non c'e' la cella resta vuota: un
    // segnaposto grigio direbbe "manca qualcosa" a un visitatore che non puo' farci niente.
    const miniatura = s.img
      ? `<img src="${s.img}" alt="" loading="lazy" style="width:44px;height:44px;object-fit:cover;border-radius:8px;display:block;margin:0 auto;">`
      : '';
    // v6.177 (Franco) - SU TELEFONO IL NOME STA SOTTO LA FOTO, non in una colonna sua: due colonne
    // strette per due cose che si leggono insieme sprecavano la larghezza che serve ai numeri.
    // ⚠️ Ed e' il nome CORTO, preso da `_nomeSerieCard` - la funzione che esiste dalla v6.080
    // apposta e che sceglie da se' fra corto e lungo secondo lo schermo. Riscrivere qui quel `if`
    // avrebbe fatto la sesta copia di una regola che quel commento dice di tenere in un posto solo.
    // v6.210 - e sotto il nome l'ANNO, in grigio e piu' piccolo: e' un dato secondario, e messo
    // con lo stesso peso del nome se lo contenderebbe.
    const primaCella = mobile
      ? miniatura + `<div style="font-size:0.75rem;line-height:1.2;margin-top:0.25rem;">${_nomeSerieCard(s)}</div>`
                  + (s.year ? `<div style="font-size:0.7rem;line-height:1.1;color:var(--muted);">${s.year}</div>` : '')
      : miniatura;
    // Lo zero resta vuoto, come nella tabella admin (v6.166): una parete di zeri nasconde i numeri
    // veri esattamente come la parete di NO nascondeva i SI. Nome e anno no: quelli ci sono sempre.
    // v6.179 (Franco) - su telefono il primo e l'ultimo numero entrano SOTTO il conteggio, nella
    // forma  60 / (1/160), e le colonne DA e A spariscono.
    // ⚠️ La parentesi compare solo se ci sono TUTTI E DUE i numeri. Una serie senza numerazione
    // (`noNumbers`) o con un estremo solo mostra il conteggio nudo: scrivere "(1/)" o "(/160)"
    // darebbe l'idea di un dato rotto invece che di un dato assente.
    const _intervallo = (s.firstNumber != null && s.lastNumber != null)
      ? `<div style="font-size:0.72rem;color:var(--muted);line-height:1.25;">(${s.firstNumber}/${s.lastNumber})</div>`
      : '';
    // v6.180 (Franco) - la colonna VAR di telefono: due righe etichettate invece di due colonne.
    // ⚠️ Le righe con zero NON si scrivono, e la cella con entrambi a zero resta vuota: e' la regola
    // che Franco ha confermato per l'intervallo ("no dati -> non mostrare nulla"), la stessa del
    // vuoto-vale-zero della v6.166. Scrivere "UFF: 0 / NON UFF: 0" riempirebbe di zeri proprio la
    // colonna che si sta stringendo.
    // v6.182 (Franco) - "NON UFF" va su due righe, e il numero si CENTRA VERTICALMENTE rispetto alle
    // due. Non e' una rifinitura: con il numero appoggiato alla prima riga, "NON / UFF: 12" fa
    // sembrare il 12 riferito alla sola parola "UFF" — cioe' all'etichetta sbagliata, che qui e'
    // pure il suo contrario. `align-items:center` lo tiene in mezzo a qualunque numero di righe,
    // quindi vale anche se un domani un'etichetta ne prendesse tre.
    // v6.210 (Franco) - IL NUMERO SEMPRE A DESTRA e l'etichetta SENZA a capo.
    // \uD83D\uDCCC `space-between` invece che il solo `gap`: cosi' i numeri delle quattro righe si
    // incolonnano sul bordo destro della cella. Con il `gap` ogni numero partiva dove finiva la sua
    // etichetta, e siccome le etichette sono lunghe diverse i quattro numeri stavano su quattro
    // ascisse diverse - cioe' proprio i valori che si e' venuti a confrontare.
    // \uD83D\uDCCC `white-space:nowrap` sull'etichetta: dalla v6.209 le etichette sono per esteso, e un
    // a capo dentro "CHANGE RETRO" spezzerebbe la riga in due lasciando il numero appeso. E' anche
    // cio' che rende inutile il `<br>` scritto a mano che la v6.209 aveva tolto: qui non si spezza
    // per scelta e non si spezza per caso.
    // ⚠️ `min-width:0` sull'etichetta: senza, una riga `nowrap` puo' allargare la cella oltre
    // la colonna invece di lasciar decidere alla tabella - il difetto piu' comune del flex, e non
    // da' errore: si vede solo che una colonna si mangia le altre.
    const _rigaVar = (etichetta, n) => n
      ? `<div style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;font-size:0.75rem;line-height:1.15;margin:0.1rem 0;">`
        // v6.213 (Franco) - via `nowrap`: le etichette tornano su due righe. Resta `min-width:0`,
        // che serve a permettere all'etichetta di STRINGERSI invece di allargare la cella.
        + `<span style="color:var(--muted);min-width:0;">${etichetta}:</span>`
        + `<span style="font-variant-numeric:tabular-nums;">${n}</span></div>`
      : '';
    // v6.209 (Franco) - le QUATTRO righe della colonna SPECIALI, con le etichette che ha scritto
    // lui. Nascono da `_rigaVar`, la stessa della v6.180: la regola "riga con zero non si scrive"
    // arriva gratis, ed e' quella che tiene la cella corta - una serie con solo change di retro
    // mostra UNA riga, non quattro di cui tre a zero.
    // ⚠️ Via il `<br>` dentro "NON UFF" che la v6.182 aveva messo: serviva a spezzare
    // un'etichetta in una colonna larga tre caratteri. Qui la colonna e' una sola e larga, e un a
    // capo forzato dentro una riga che ci sta comoda spezzerebbe dove non serve. La ragione della
    // v6.182 - il numero centrato verticalmente su piu' righe - resta valida e non si tocca:
    // `align-items:center` regge qualunque numero di righe, comprese quelle che l'a-capo automatico
    // dovesse produrre su uno schermo stretto.
    // v6.213 (Franco) - le etichette tornano su DUE RIGHE, e l'a capo e' SCRITTO, non lasciato
    // all'automatico. E' la regola della v6.178: *"l'a-capo automatico spezza dove capita a seconda
    // della larghezza della colonna"* - la stessa etichetta si romperebbe in un punto su un telefono
    // e in un altro su quello accanto. Scritto, si spezza sempre allo stesso posto.
    // \uD83D\uDCCC E il punto scelto non e' a meta' parola: la prima riga dice la FAMIGLIA (VAR, CHANGE),
    // la seconda QUALE (UFF, NON UFF, FIG, RETRO). Cosi' le cinque righe si leggono in colonna -
    // VAR/VAR/CHANGE/RETRO/CHANGE - e la seconda parola distingue dentro la famiglia.
    // ⚠️ "NON UFF" resta INTERO sulla seconda riga: spezzarlo in "VAR NON" + "UFF" farebbe
    // leggere "UFF" - cioe' il suo contrario - come l'etichetta del numero. E' il rischio che la
    // v6.182 aveva gia' visto e risolto centrando il numero; qui si evita a monte.
    const _speciali = _rigaVar(it ? 'VAR<br>UFF'      : 'OFFICIAL<br>VAR',    c.variazioni)
                    + _rigaVar(it ? 'VAR<br>NON UFF'  : 'UNOFFICIAL<br>VAR',  c.nonUfficiali)
                    + _rigaVar(it ? 'CHANGE<br>FIG'   : 'STICKER<br>CHANGES', c.changeFigurine)
                    + _rigaVar(it ? 'CHANGE<br>RETRO' : 'BACK<br>CHANGES',    c.changeRetro)
                    // 🆕 v6.235 (Franco: "per la sua mobile version aggiungi riga sotto a CHANGE").
                    // Su telefono e' una RIGA dentro SPECIALI e non una colonna, ed e' la regola
                    // della v6.209: due colonne strette costano piu' delle due righe che le
                    // sostituiscono. Vale qui perche' l'omaggio si legge INSIEME agli altri
                    // contrassegni — a differenza del conto dei retro, che sta accanto a quello
                    // delle figurine perche' e' una quantita' della serie, non un contrassegno.
                    // La regola "riga con zero non si scrive" arriva gratis da `_rigaVar`: finche'
                    // non sposti niente su omaggio, questa riga non compare.
                    + _rigaVar(it ? 'OMAGGIO' : 'FREE', c.omaggi);   // v6.240
    const celle = mobile
      ? [primaCella, (c.base || '') + _intervallo, c.retro || '', _speciali]
      // v6.211 - `c.retro` sta PRIMA di `c.changeRetro` (Franco): i due numeri dei retro si leggono
      // affiancati, come le due colonne dei change lo erano gia'.
      : [primaCella, s.name || '', s.year ?? '', c.base || '', s.firstNumber ?? '', s.lastNumber ?? '',
         // v6.235 - VERSIONI OMAGGIO, in coda come chiesto da Franco (dopo CHANGE DI RETRO).
         c.variazioni || '', c.nonUfficiali || '', c.changeFigurine || '', c.retro || '', c.changeRetro || '', c.omaggi || ''];
    return '<tr>' + celle.map((v, i) =>
      // v6.208 (Franco) - su TELEFONO: celle piu' strette e griglia visibile.
      // \uD83D\uDCCC Lo spazio orizzontale scende da 0,7rem a 0,3rem per lato. In una tabella a sei
      // colonne quel margine si paga **dieci volte** (due lati per cinque confini), ed e'
      // larghezza sottratta ai numeri, che sono l'unica cosa che si e' venuti a leggere.
      // \uD83D\uDCCC E i bordi: `.data-table td` ha solo un `border-bottom` a opacita' 0.04, cioe'
      // quasi invisibile. Bastava su una tabella larga con poche colonne; con sei colonne strette
      // e celle che dentro hanno due righe (VAR, e il conteggio col suo (1/160) sotto) senza una
      // griglia non si capisce piu' quale numero appartiene a quale colonna. Il bordo pieno non
      // e' decorazione: e' cio' che tiene insieme la lettura quando le celle diventano piccole.
      // ⚠️ Su DESKTOP non cambia niente: li' lo spazio non manca e la riga sottile basta.
      `<td style="padding:${mobile ? '0.3rem 0.3rem' : '0.4rem 0.7rem'};font-size:0.85rem;${mobile ? 'border:1px solid rgba(255,255,255,0.16);' : ''}text-align:${aSinistra(i) ? 'left' : 'center'};">${v}</td>`
    ).join('') + '</tr>';
  }).join('');

  // 🧪 Intestazioni e celle si costruiscono dallo STESSO array di dieci voci e con la STESSA
  // funzione di allineamento: non possono disallinearsi ne' in numero ne' in incolonnamento. E' il
  // controllo che nella v6.166 e nella v6.168 e' servito di piu' — in una tabella fatta di stringhe
  // una colonna in piu' da una parte sola non da' nessun errore, sposta i dati sotto l'intestazione
  // sbagliata e la tabella continua a sembrare giusta.
  el.innerHTML = `<table class="data-table compact" style="width:100%;"><thead><tr>${
    // 🔴 v6.183 - `text-transform:none` E' LA RIGA CHE MANCAVA ALLA v6.182.
    // Quella release aveva portato le intestazioni di telefono in minuscolo — "N. figurine",
    // "Change figurine" — e a schermo restavano MAIUSCOLE, perche' `.data-table th` in style.css
    // ha `text-transform: uppercase`. Il testo era cambiato davvero; a non cambiare era cio' che si
    // vedeva.
    // ⚠️ Ed e' il difetto della v6.157 per la quarta volta in due giorni: **avevo verificato che il
    // codice fosse cambiato, non che il cambiamento avesse un effetto**. Il controllo che avevo
    // fatto — stampare l'array delle intestazioni — non poteva accorgersene per costruzione:
    // guardava la sorgente, e il colpevole stava nel foglio di stile. L'ha trovato Franco guardando
    // il sito, come le tre volte precedenti.
    // Si mette `none` per TUTTE e due le varianti, non solo per il telefono: le due liste portano
    // gia' le maiuscole dove le vogliamo, quindi da qui in avanti **cio' che e' scritto e' cio' che
    // si legge**, senza una trasformazione invisibile in mezzo.
    // v6.208 - le intestazioni prendono lo stesso trattamento delle celle, se no la griglia
    // comincerebbe dalla seconda riga e la prima sembrerebbe staccata dalla tabella.
    intestazioni.map((h, i) => `<th style="line-height:1.2;vertical-align:bottom;white-space:normal;text-transform:none;${mobile ? 'padding:0.3rem 0.3rem;border:1px solid rgba(255,255,255,0.16);' : ''}text-align:${aSinistra(i) ? 'left' : 'center'};">${h}</th>`).join('')
  }</tr></thead><tbody>${righe}</tbody></table>`;
  // 🔴 v6.179 - QUI SOTTO C'ERA UNA NOTA CHE NON MI ERA STATA CHIESTA, e l'ho tolta.
  // Diceva "Le celle vuote valgono zero. «FIGURINE» conta le figurine del set base, senza
  // variazioni, change ed errori di stampa. Le serie senza figurine non compaiono."
  // Franco: **"non dimenticarti che questa tabella e' per gli UTENTI -> non mettere contenuti senza
  // chiedermi prima"**. Ed e' una regola di sostanza, non di forma: quella nota spiegava a un
  // visitatore le convenzioni INTERNE del catalogo — set base, change, errori di stampa — cioe'
  // come e' costruito il sito invece di cosa contiene. E' lo stesso criterio con cui, in questa
  // stessa tabella, sono state tenute fuori le colonne dei flag e delle colonne della griglia.
  // 📌 Da qui in avanti: nessun testo rivolto agli utenti si aggiunge senza che lo abbia approvato
  // Franco. Non e' un dettaglio di stile — le parole del sito sono sue.

  document.getElementById('info-serie-modal').classList.remove('hidden');
}

// Il sottotitolo NON si scrive a mano: applyI18n() riscrive tutto cio' che ha un data-i18n ad ogni
// avvio e ad ogni cambio lingua, quindi un textContent messo qui sparirebbe da solo alla prima
// occasione. Si cambia la CHIAVE e si lascia fare a lui — cosi' la frase vale anche in inglese
// senza una seconda regola da mantenere.
function _aggiornaBivioInventario() {
  ['serie', 'prodotti'].forEach(k => {
    const b = document.getElementById('taglio-' + k);
    if (b) {
      const acceso = (k === _taglioInventario);
      b.style.background = acceso ? 'var(--action)' : 'transparent';
      b.style.color = acceso ? '#ffffff' : 'var(--muted)';
    }
  });
  const sub = document.getElementById('catalog-sub');
  if (sub) {
    const chiave = (_taglioInventario === 'prodotti') ? 'catalog.subProducts' : 'catalog.sub';
    sub.setAttribute('data-i18n', chiave);
    sub.textContent = t(chiave);
  }
  // v6.144 - IL PULSANTE CHE AGGIUNGE SEGUE IL TAGLIO. Nel taglio Serie si aggiunge una serie, nel
  // taglio Prodotti un tipo di prodotto: stessa posizione, mai insieme. Sta qui e non in
  // `updateNavUser` perche' e' il TAGLIO a deciderlo, e il taglio cambia senza che l'utente cambi:
  // lasciarlo la' avrebbe voluto dire due punti che accendono lo stesso pulsante con due regole
  // diverse, ed e' il difetto chiuso ieri con la v6.139.
  const _admin = !!currentUser?.isAdmin;
  const _bSerie = document.getElementById('admin-add-series-btn');
  const _bTipo = document.getElementById('admin-add-tipo-prodotto-btn');
  if (_bSerie) _bSerie.style.display = (_admin && _taglioInventario !== 'prodotti') ? '' : 'none';
  if (_bTipo)  _bTipo.style.display  = (_admin && _taglioInventario === 'prodotti') ? '' : 'none';
  // v6.174 - il riepilogo delle serie: solo nel taglio Serie, ma per CHIUNQUE. Non c'e' `_admin`
  // nella condizione, e non e' una dimenticanza: e' un riepilogo del catalogo, non uno strumento.
  const _bInfo = document.getElementById('btn-info-tutte-serie');
  if (_bInfo) {
    _bInfo.style.display = (_taglioInventario !== 'prodotti') ? '' : 'none';
    // v6.177 (Franco) - su telefono l'etichetta si accorcia. Si cambia l'ATTRIBUTO `data-i18n` e poi
    // il testo, come fa questa stessa funzione due righe sopra per `catalog.sub`: scrivere solo il
    // testo lo farebbe riallungare al primo `applyI18n()`, che rilegge l'attributo.
    const chiave = _isMobileViewport() ? 'catalog.allSeriesInfoShort' : 'catalog.allSeriesInfo';
    _bInfo.setAttribute('data-i18n', chiave);
    _bInfo.textContent = t(chiave);
  }
}

// ---- PRIMO LIVELLO DEL TAGLIO PRODOTTI ----
// Stesso guscio della card di una serie: cambiano il nome e la foto. Anno e punteggio modale non
// esistono per un prodotto e i due slot restano vuoti, invece di riempirsi con qualcosa di
// inventato. Sotto, TUTTE le serie in colonna — nello stesso ordine del taglio Serie, comprese
// quelle a zero: un elenco che cambia lunghezza da una card all'altra non si legge in colonna.
// v6.073 (Franco) — la foto di un prodotto e' LA STESSA che quel prodotto ha nell'hub di una serie.
// Non la si ricopia: si legge dal DOM il riquadro immagine della card corrispondente in
// #section-selector e lo si riusa. Retro e Bustine non stanno in SECTION_IMAGES — il primo ha lo
// sfondo scritto nell'index, la seconda e' un SVG disegnato a mano — quindi copiarli avrebbe
// voluto dire due sorgenti per la stessa immagine, destinate a divergere alla prima modifica
// (e' lo stesso motivo per cui i due caroselli condividono la card, v6.071).
// #section-selector e' markup statico dell'index: c'e' sempre, anche quando la sua pagina e'
// nascosta, quindi leggerlo non dipende da dove ci si trova.
function _fotoProdotto(sec) {
  // v6.145 - se l'admin ha scelto una foto per questo box, e' quella e non si clona niente: il
  // clone del DOM esisteva per non tenere due copie della stessa immagine, ma con una foto propria
  // le copie sono gia' una sola. In piu' non dipende piu' dal fatto che il selettore delle sezioni
  // sia in pagina, che era il punto fragile di questa funzione.
  // v6.159 (Franco) - stessa misura delle foto dei box SERIE. Non e' il contenitore a essere
  // diverso — e' lo stesso `.card-img-placeholder` — ma come la foto ci sta dentro: le serie usano
  // `contain` con un padding (la foto si vede tutta, un po' piu' piccola), i prodotti usavano
  // `cover`, che riempie e taglia facendola sembrare piu' grande. Ora sono la stessa cosa.
  const _url = _fotoBoxUrl(sec);
  if (_url) return '<img src="' + cloudinaryUrl(_url, 'w_400,h_400,c_fit,q_auto,f_auto') +
    '" alt="" style="width:100%;height:100%;object-fit:contain;position:absolute;top:0;left:0;padding:8px;">';
  const cards = Array.from(document.querySelectorAll('#section-selector .section-choice-card'));
  const card = cards.find(c => (c.getAttribute('onclick') || '').indexOf("'" + sec + "'") >= 0);
  const blocco = card && card.firstElementChild;
  if (blocco) {
    const c = blocco.cloneNode(true);
    // Nell'hub il riquadro si da' l'altezza da solo con aspect-ratio; qui deve riempire
    // .card-img-placeholder, che l'altezza ce l'ha gia'. Due contesti, due modi di misurare.
    c.style.position = 'absolute'; c.style.top = '0'; c.style.left = '0';
    c.style.width = '100%'; c.style.height = '100%'; c.style.aspectRatio = 'auto';
    // v6.159 - anche la foto clonata si comporta come quella di una serie: la card della sezione la
    // mostra a pieno riquadro, qui deve stare nella stessa misura delle altre card dell'Inventario.
    const _im = c.querySelector('img');
    if (_im) { _im.style.objectFit = 'contain'; _im.style.padding = '8px'; }
    return c.outerHTML;
  }
  // Ripiego, se un domani quel markup cambiasse nome: meglio l'icona di un buco.
  return SECTION_IMAGES[sec]
    ? '<img src="' + SECTION_IMAGES[sec] + '" alt="" style="width:100%;height:100%;object-fit:contain;position:absolute;top:0;left:0;padding:8px;">'
    : SECTION_ICONS[sec];
}

// v6.073 (Franco) — il titolo della card di un prodotto. Non e' l'etichetta della sezione
// ("Figurine"): e' il nome della cosa ("Le Figurine Sgorbions"). L'articolo cambia col genere e col
// numero, quindi si scrive, non si compone: "Le Figurine", "I Retro", "Gli Album". Comporlo da
// getSectionLabel avrebbe voluto dire una regola grammaticale italiana dentro il codice.
function _titoloProdotto(sec) {
  const it = {
    figurines: 'Le Figurine Sgorbions', retros: 'I Retro Sgorbions', bustine: 'Le Bustine Sgorbions',
    albums: 'Gli Album Sgorbions',      extras: 'Gli Altri oggetti Sgorbions'
  };
  const en = {
    figurines: 'The Sgorbions Stickers', retros: 'The Sgorbions Retros', bustine: 'The Sgorbions Wrappers',
    albums: 'The Sgorbions Albums',      extras: 'The Other Sgorbions Items'
  };
  return (currentLang === 'it' ? it : en)[sec] || getSectionLabel(sec);
}

// La scomposizione per tipologia, COI COLORI del codice tipologie (v5.703): base, variazione
// ufficiale, non ufficiale, change, errore di stampa. I colori non si scrivono qui: si puntano le
// variabili --type-*, che stanno in un posto solo proprio perche' se un domani il rosa diventa
// viola cambi una riga e cambia dappertutto.
// Le tipologie a ZERO non si mostrano, come le serie a zero: un album non ha Change, e dirlo
// occuperebbe una riga per non dire niente.
function _contiTipologie(oggetti) {
  const conta = f => oggetti.filter(f).length;
  return [
    { n: conta(_eBase),                     col: 'var(--type-base)',       it: ['base', 'base'],                                     en: ['base', 'base'] },
    { n: conta(f => f.isVariation),         col: 'var(--type-official)',   it: ['variazione ufficiale', 'variazioni ufficiali'],     en: ['official variation', 'official variations'] },
    { n: conta(f => f.isUnofficialVariation), col: 'var(--type-unofficial)', it: ['variazione non ufficiale', 'variazioni non ufficiali'], en: ['unofficial variation', 'unofficial variations'] },
    { n: conta(f => f.isChange),            col: 'var(--type-change)',     it: ['change', 'change'],                                 en: ['change', 'changes'] },
    { n: conta(f => f.isPrintError),        col: 'var(--type-printerror)', it: ['errore di stampa', 'errori di stampa'],             en: ['print error', 'print errors'] }
  ].filter(v => v.n > 0);
}
const _paroleTipologia = v => (currentLang === 'it' ? v.it : v.en)[v.n === 1 ? 0 : 1];

// Numero + etichetta, ognuno nel colore della sua tipologia. Due DISPOSIZIONI, non due funzioni:
//  - 'riga'    -> tutte di seguito, separate da ';'. Va nella testata della pagina, che e' larga.
//  - 'colonna' -> una per riga. Va nei box delle serie, dove in orizzontale non ci starebbero ma
//                 in verticale lo spazio c'e'.
// L'etichetta c'e' in tutti e due i casi: il colore da solo va ricordato, la parola no.
function _righeTipologie(oggetti, modo) {
  const voci = _contiTipologie(oggetti);
  // v6.080 (Franco) - modo 'pillole': gli stessi conti, ma nella forma delle card dell'Inventario
  // - allineate a sinistra, ognuna nella sua cornicetta, che vanno a capo quando lo spazio finisce.
  // Franco preferisce quella lettura, e riusarla vuol dire che le due griglie delle serie ora si
  // somigliano invece di essere due dialetti della stessa informazione.
  // Il COLORE per tipologia resta (v6.073, "il colore fa da etichetta"): sta sul testo dentro la
  // pillola, non al posto della cornice. Le due cose non erano in conflitto, erano solo separate.
  if (modo === 'pillole') {
    // Su TELEFONO la pillola puo' andare a capo: "Variazioni non ufficiali" in due colonne non ci
    // sta su una riga e veniva troncata. Sul desktop resta `nowrap`, dove lo spazio c'e' e una
    // pillola spezzata sarebbe solo piu' brutta. Il numero resta comunque attaccato alla prima riga.
    const _mobPil = _isMobileViewport();
    return '<div class="card-meta" style="display:flex;flex-wrap:wrap;justify-content:flex-start;gap:0.3rem;margin-top:0.45rem;padding-top:0.45rem;">' +
      voci.map(v => '<span class="card-badge" style="color:' + v.col + ';'
        + (_mobPil ? 'white-space:normal;line-height:1.25;text-align:left;' : 'white-space:nowrap;') + '">' +
        '<b style="font-variant-numeric:tabular-nums;">' + v.n + '</b> ' + esc(_paroleTipologia(v)) + '</span>').join('') +
      '</div>';
  }
  if (modo === 'colonna') {
    return voci.map(v =>
      '<div style="display:flex;align-items:baseline;gap:0.4rem;color:' + v.col + ';line-height:1.45;">' +
        '<span style="font-weight:800;font-variant-numeric:tabular-nums;min-width:2.6em;text-align:right;">' + v.n + '</span>' +
        '<span>' + esc(_paroleTipologia(v)) + '</span>' +
      '</div>'
    ).join('');
  }
  return voci.map(v =>
    '<span style="color:' + v.col + ';white-space:nowrap;"><b>' + v.n + '</b> ' + esc(_paroleTipologia(v)) + '</span>'
  ).join('<span style="color:var(--muted);">; </span>');
}

function prodottoCardHTML(sec, tutti, serieOrdinate) {
  const miei = _diTipo(tutti, sec);
  const basi = miei.filter(_eBase);
  // v6.156 - `serieConRoba` e' sparita con la scritta che la usava: un conto calcolato per una riga che non c'e' piu'.
  // v6.156 (Franco) - resta il solo riepilogo: il numero delle serie se ne va. Sotto c'e' gia'
  // l'elenco delle serie con i loro numeri, quindi dirne il conto qui era ripetere in cifre una
  // cosa che si legge per esteso due righe piu' sotto.
  const desc = basi.length + ' base';
  // v6.073 (Franco) — le serie che di quel prodotto non hanno NIENTE non si mostrano affatto.
  // Uno zero occupa una riga per dire che non c'e' niente da dire: l'elenco cambia lunghezza da
  // una card all'altra, ma dice solo cose vere.
  const righe = serieOrdinate.map(s => {
    const n = basi.filter(f => f.seriesId === s.id).length;
    if (!n) return '';
    // v6.206 - via `width:100%`: dentro una griglia la larghezza la da' la colonna, e un 100%
    // cablato la scavalcherebbe.
    return '<span style="display:flex;align-items:center;gap:0.5rem;min-width:0;padding:4px 10px 4px 4px;border-radius:20px;font-size:0.78rem;font-family:var(--font-ui);' +
      'background:rgba(181,255,46,0.08);border:1px solid rgba(181,255,46,0.18);color:var(--text);">' +
      (s.img
        ? '<img src="' + cloudinaryUrl(s.img, 'w_80,h_80,c_fit,q_auto,f_auto') + '" loading="lazy" alt="" style="width:22px;height:22px;object-fit:contain;border-radius:50%;background:var(--bg3);flex:0 0 auto;">'
        : '<span style="width:22px;height:22px;flex:0 0 auto;"></span>') +
      // v6.206 - NOME CORTO anche su desktop: in due colonne lo spazio e' quello del telefono,
      // ed e' esattamente il problema per cui il nome corto e' stato creato (v6.080).
      '<span style="flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + esc(_nomeSerieCard(s, true)) + '</span>' +
      '<span style="font-weight:800;font-variant-numeric:tabular-nums;flex:0 0 auto;">' + n + '</span>' +
    '</span>';
  }).join('');
  const foto = _fotoProdotto(sec);
  return '<div class="card" style="position:relative;" onclick="openProdottoDetail(\'' + sec + '\')">' +
    _matitaBox(sec) +   // v6.145
    '<div class="card-img-placeholder">' + foto + '</div>' +
    '<div class="card-body">' +
      // v6.157 (Franco) - IL TOTALE VA SOTTO L'ELENCO, non sopra. Sopra era una premessa; sotto
      // e' la riga che tira le somme, che e' il mestiere che ha. La v6.156 l'aveva solo ripulito
      // dal conto delle serie e lasciato dov'era: avevo letto "mettila sola" dove c'era scritto
      // "mettila sotto".
      '<div class="card-title" style="margin-bottom:0.5rem;">' + esc(getSectionLabel(sec)) + '</div>' +
      // \uD83C\uDD95 v6.206 (Franco) - L'ELENCO SU DUE COLONNE, e la decisione la prende lo SPAZIO.
      // `auto-fill` con un minimo di 130px: dove ci stanno due colonne ne fa due, dove non ci
      // stanno ne fa una. Non c'e' nessun "se desktop" scritto da noi - che sarebbe un numero da
      // indovinare e da rincorrere ad ogni cambio di larghezza della card.
      // \uD83D\uDCCC Il conto che ha deciso il 130: con il nome CORTO una riga e' foto 22px + nome
      // (~8 caratteri a 0,78rem) + conteggio, cioe' ~120px. Col nome LUNGO servivano ~240px, e in
      // una card larga ~320px due colonne non ci stavano: quasi tutte le serie sarebbero finite a
      // puntini. E' per questo che le due cose - due colonne e nome corto - sono una sola
      // modifica e non due.
      '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:0.35rem;padding-top:0.2rem;">' + righe + '</div>' +
      '<div class="card-desc" style="margin-top:0.45rem;padding-top:0.45rem;border-top:1px solid rgba(255,255,255,0.06);">' + esc(desc) + '</div>' +
    '</div>' +
  '</div>';
}

function renderCatalogProdotti(grid) {
  // v6.080 (Franco) - anche il PRIMO livello dell'hub va a due colonne su telefono. Usa la stessa
  // griglia dell'Inventario (#catalog-grid), che di colonne ne ha tre per via della media query
  // sull'ID (v5.823/835): le card dei prodotti sono pero' piu' cariche di quelle delle serie -
  // copertina, titolo e l'elenco delle serie con le miniature - e in un terzo di schermo si
  // spezzano. Stile inline perche' quella regola sta nel CSS e non si puo' scavalcare da qui
  // senza toccare un file che le cartelle _upload_ non contengono nemmeno (§5).
  // Lo pulisce renderCatalog() tornando al taglio per Serie: la griglia e' la stessa, e uno stile
  // lasciato acceso si porterebbe dietro le due colonne anche dove ne servono tre.
  if (grid && _isMobileViewport()) grid.style.gridTemplateColumns = 'repeat(' + HUB_COLONNE_MOBILE + ', 1fr)';
  const tutti = getData('figurines', []);
  const serieOrdinate = getData('series', []).slice().sort((a, b) => (a.order ?? 9999) - (b.order ?? 9999));
  // v6.144 - i cinque di sempre, poi i tipi censiti dall'admin. In coda e non mescolati: i primi
  // cinque sono TAGLI sugli item delle serie, questi sono CONTENITORI di oggetti senza serie, e
  // ordinarli insieme farebbe sembrare che siano la stessa cosa.
  grid.innerHTML = PRODOTTI_INVENTARIO.map(sec => prodottoCardHTML(sec, tutti, serieOrdinate)).join('')
    + _tipiProdotto().map(t => tipoProdottoCardHTML(t, tutti)).join('');
}

// ============================================================
//  v6.144 (Franco) - I TIPI DI PRODOTTO SENZA SERIE
// ============================================================
// LA DOMANDA DI FRANCO: come si censiscono oggetti Sgorbions che NON hanno una serie di
// riferimento, ma valgono per il concetto in generale? Il primo si chiama "Cartoncini".
//
// ⚠️ LA DECISIONE CHE REGGE TUTTO IL RESTO: un tipo aggiunto dall'admin e' un CONTENITORE, non una
// SEZIONE. `section` sembra un'etichetta ed e' un COMPORTAMENTO, scritto in una dozzina di punti —
// `_campiEreditatiDaBase` (quattro campi per i retro, uno per tutti gli altri), il ramo dedicato di
// `computeFullName`, Categoria/Sottocategoria mostrate solo ai retro, `_mostraCampoNumero`,
// l'aspect eBay `Tipo` mappato dalla sezione, le etichette, i filtri.
// Una SESTA sezione cadrebbe in ogni `else` di quei punti senza che nessuno l'abbia deciso:
// erediterebbe per silenzio comportamenti scritti per altri cinque. E' la stessa forma dei difetti
// chiusi dalle v6.129/133/142 — codice che da' per scontato un presupposto che non vale piu'.
// Quindi: i cinque di `PRODOTTI_INVENTARIO` restano codice, i tipi nuovi sono DATO.
//
// COME SONO FATTI: gli oggetti di un tipo sono item NORMALI, nella serie "Extra serie", sezione
// `extras` (decisione di Franco: "si comportano come gli Altri oggetti"), piu' un campo
// `tipoProdotto` che dice a quale box appartengono. Da li' viene gratis tutto — la scheda, la vista
// tabellare, i filtri, la ricerca globale, il punteggio, la wishlist, il blocco eBay, il Nome
// completo, la propagazione padre-figlio della v6.143.
//
// 📌 TENUTO A MENTE E NON COSTRUITO (Franco, 14 agosto): questi prodotti potrebbero un domani
// essere messi in relazione con gli ALBUM. Non c'e' niente nel codice che lo prepari, ed e' voluto:
// un campo aggiunto "per quando servira'" e' un campo che nessuno riempie e che intanto racconta
// una decisione mai presa.
// ============================================================
//  v6.145 (Franco) - LE FOTO DEI BOX LE CAMBIA L'ADMIN
// ============================================================
// Franco: "rendimi autonomo nel cambiare la foto di tutti i box del sito".
//
// COM'ERA, e spiega perche' la richiesta vale piu' di una comodita': le foto dei box stanno DENTRO
// IL CODICE. `SECTION_IMAGES` e' una costante di ~276 KB di base64 con tre immagini (Figurine,
// Album, Altri oggetti); Retro e Bustine hanno la loro nel markup dell'index; e `_fotoProdotto()`
// non ha una foto propria — CLONA IL DOM del box della sezione per riusarne l'immagine. Cambiarne
// una voleva dire una release, e quelle immagini viaggiano dentro un file da 2,4 MB che il browser
// riscarica ad ogni versione.
//
// COM'E' ORA: un documento solo, `settings/immagini_box`, con una voce per box -> l'URL Cloudinary,
// cioe' la stessa strada di TUTTE le altre foto del sito. Chi non ha una voce continua a usare la
// foto di oggi: nessuna migrazione, e finche' non si tocca niente non cambia niente.
//
// ⚠️ `SECTION_IMAGES` NON viene tolta ora, ed e' deliberato: e' il ripiego. Si potra' cancellare —
// recuperando i 276 KB — solo quando tutti e cinque i box avranno una foto scelta da Franco, e
// sara' una release a se' con una misura davanti (quanto pesa `app.js` prima e dopo). Toglierla
// adesso vorrebbe dire lasciare cinque buchi in attesa che qualcuno li riempia.
//
// LE CHIAVI sono quelle che il sito gia' usa: le cinque sezioni (`figurines`, `retros`, `bustine`,
// `albums`, `extras`) e l'id di un tipo di prodotto (`tp_...`). Non un elenco nuovo da tenere
// allineato a mano.
async function getImmaginiBox() {
  if (_cache.immaginiBox !== undefined) return _cache.immaginiBox;
  try {
    const docs = await fsGetAll('settings');
    const found = docs.find(d => d.id === 'immagini_box');
    _cache.immaginiBox = (found && typeof found.box === 'object' && found.box) ? found.box : {};
  } catch (e) { _cache.immaginiBox = {}; }
  return _cache.immaginiBox;
}

// Lettura sincrona per chi disegna, con la stessa regola di `_tipiProdotto`: se la cache non c'e'
// ancora la carica e poi ridisegna, invece di far aspettare la prima pittura.
function _immaginiBox() {
  if (_cache.immaginiBox === undefined) {
    getImmaginiBox().then(() => { try { _ridisegnaBox(); } catch (e) {} });
    return {};
  }
  return _cache.immaginiBox;
}
function _fotoBoxUrl(chiave) { return _immaginiBox()[chiave] || ''; }

// Ridisegna i punti in cui una foto di box si vede. Sono due e stanno in due pagine diverse, quindi
// si chiamano tutti e due e ognuno si arrangia se non e' in pagina: cercare di indovinare dove ci
// si trova vorrebbe dire una terza regola da tenere allineata alle prime due.
function _ridisegnaBox() {
  try { _riordinaBoxSezioni(); } catch (e) { console.error('_riordinaBoxSezioni', e); }   // v6.283
  try { _applicaFotoSezioni(); } catch (e) {}
  try { _applicaSezioniNascoste(); } catch (e) {}   // v6.194
  try { renderCatalog(); } catch (e) {}
}

// La matitina. `stopPropagation` non e' un dettaglio: la matita sta DENTRO la card, e la card ha il
// suo `onclick` che porta da un'altra parte — senza, cambiare la foto aprirebbe anche il box.
function _matitaBox(chiave) {
  if (!currentUser?.isAdmin) return '';
  return '<button type="button" title="Cambia la foto di questo box" ' +
    'onclick="event.stopPropagation();cambiaFotoBox(\'' + chiave + '\')" ' +
    'style="position:absolute;top:6px;right:6px;z-index:3;border:none;border-radius:999px;' +
    'width:30px;height:30px;line-height:1;cursor:pointer;font-size:0.95rem;' +
    'background:rgba(0,0,0,0.6);color:#fff;">&#9998;</button>';
}

let _boxFotoInCorso = null;

// Una sola `<input type=file>` per tutte le matite: crearne una per box vorrebbe dire N elementi
// nascosti che fanno la stessa cosa, e la prima modifica li farebbe divergere.
function cambiaFotoBox(chiave) {
  if (!currentUser?.isAdmin) { toast((currentLang === 'it' ? 'Solo per admin' : 'Admin only'), 'error'); return; }
  _boxFotoInCorso = chiave;
  let inp = document.getElementById('box-foto-input');
  if (!inp) {
    inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'image/*'; inp.id = 'box-foto-input';
    inp.style.display = 'none';
    inp.addEventListener('change', _caricaFotoBox);
    document.body.appendChild(inp);
  }
  inp.value = '';   // se no riscegliendo LO STESSO file l'evento `change` non parte
  inp.click();
}

async function _caricaFotoBox(ev) {
  const it = currentLang === 'it';
  const file = ev.target.files && ev.target.files[0];
  const chiave = _boxFotoInCorso;
  if (!file || !chiave) return;
  // v6.191 - prima si guarda, poi si carica. Fino alla v6.190 il file partiva subito e non c'era
  // nessun momento in cui offrire "Rimuovi sfondo".
  const scelto = await _scegliFoto(file, it ? 'Foto del box' : 'Box photo');
  if (!scelto) { _boxFotoInCorso = null; return; }   // annullato
  toast(it ? 'Carico la foto…' : 'Uploading…', 'info');
  let url;
  try {
    url = await uploadToCloudinary(scelto);
  } catch (e) {
    console.error('_caricaFotoBox/upload', e);
    toast(it ? '❌ Caricamento fallito — riprova' : '❌ Upload failed — retry', 'error');
    return;
  }
  // Si scrive PRIMA su Firestore e solo dopo si aggiorna la cache: se la scrittura fallisce, la
  // foto nuova non deve restare a schermo dando l'impressione di essere salvata. E' la stessa
  // regola della v6.101 sul salvataggio con la rete staccata.
  const box = { ..._immaginiBox(), [chiave]: url };
  try {
    await fsSave('settings', { id: 'immagini_box', box });
  } catch (e) {
    console.error('_caricaFotoBox/salva', e);
    toast(it ? '❌ Salvataggio fallito: la foto non è stata cambiata' : '❌ Save failed: photo unchanged', 'error');
    return;
  }
  _cache.immaginiBox = box;
  _boxFotoInCorso = null;
  _ridisegnaBox();
  toast(it ? '✅ Foto del box aggiornata' : '✅ Box photo updated', 'success');
}

// Le foto dei box SEZIONE, dentro l'hub di una serie. Il markup di quelle card sta nell'index e non
// si genera qui, quindi la foto e la matita si applicano al DOM gia' disegnato.
// v6.194 (Franco: "ci sono serie senza album; mi serve un flag Senza album che mi permetta di
// nascondere dall'hub il box Album").
// La domanda vive in un posto solo, come `_serieSenzaRetro` (v6.098) che ha la stessa forma: e'
// una proprieta' della SERIE, e chi la legge non deve sapere come si chiama il campo.
function _serieSenzaAlbum(seriesId) {
  const s = getData('series', []).find(x => x.id === seriesId);
  return !!(s && s.noAlbums);
}

// La card di una sezione dentro l'hub. Estratta perche' ora la cercano in DUE: la foto (v6.145) e
// la sparizione del box (v6.194). Due copie della stessa ricerca sarebbero due punti da correggere
// il giorno che il markup cambia - ed e' appena successo, con la v6.191.
function _cardSezione(sel, sec) {
  return Array.from(sel.querySelectorAll('.section-choice-card'))
    .find(c => (c.getAttribute('onclick') || '').indexOf("'" + sec + "'") >= 0) || null;
}

// v6.194 - i box che questa serie non ha. Oggi ce n'e' uno solo, e si scrive comunque come tabella:
// il giorno che ne servira' un secondo (una serie senza bustine, mettiamo) si aggiunge una riga
// invece di ricopiare l'`if`. E' la forma che la v6.186 e la v6.191 hanno gia' pagato due volte.
// ============================================================
// \uD83C\uDD95 v6.216 (Franco: "non tutte le serie hanno tutti i tipi di articolo") - GLI ARTICOLI CHE
// UNA SERIE NON HA, IN UN CAMPO SOLO. **PASSO 1 DI 4.**
// ------------------------------------------------------------
// La serie porta `articoliNascosti`, un elenco: `['albums', 'retros']`. Tutti e sei gli articoli
// possono starci, e le caselle nella scheda serie si GENERANO dal descrittore - un articolo nuovo
// porta la sua da se'.
//
// \uD83D\uDCCC PERCHE' UN ELENCO E NON SEI FLAG. Sei booleani con sei nomi diversi (`noAlbums`,
// `noBustine`, ...) sarebbero sei righe in `_ripristinaFlagSerie`, sei nel payload, sei caselle
// scritte a mano nell'index: **sei occasioni di dimenticarne una**. E' il difetto che ha morso tre
// volte in due giorni - v6.186 (flag ripristinati in un ramo solo), v6.195 (due elenchi cablati a
// cinque nomi), v6.215 (la riga di tabella che non c'era).
//
// \uD83D\uDCCC E `noRetro` ENTRA NELL'ELENCO. Avevo proposto di tenerlo fuori sostenendo che dicesse
// un'altra cosa - *"le figurine non hanno retro"* contro *"nascondi il box"*. Franco: **"il
// significato e' lo stesso: figurine senza retro significa che la serie non ha i retro"**. Ha
// ragione: erano la stessa frase detta due volte in due posti, ed e' proprio il genere di doppione
// che questa release toglie.
//
// ⚠️ QUESTO E' IL PASSO 1 DI QUATTRO, e l'ordine e' di Franco:
//   1. (qui) nasce il campo unico. Il salvataggio scrive l'elenco **E TIENE ALLINEATI** i due
//      vecchi flag. I lettori non si toccano: continuano a leggere `noRetro` / `noAlbums`.
//   2. la MIGRAZIONE dei dati dai flag all'elenco, con anteprima e numero atteso.
//   3. i lettori passano all'elenco; si smette di scrivere i vecchi.
//   4. i due campi si CANCELLANO da Firestore.
// \uD83D\uDD34 Il punto delicato e' il "tiene allineati" di questo passo, ed e' cio' che rende sicura
// tutta la sequenza: fra il passo 2 e il passo 3 i dati sono migrati ma i lettori guardano ancora i
// vecchi flag. Se in quella finestra si salva una serie dalle caselle nuove e i vecchi non venissero
// aggiornati, resterebbero indietro **e i lettori mostrerebbero la cosa sbagliata**. Costa una riga
// e chiude la finestra.
// \uD83D\uDCCC Franco aveva scartato il ripiego-in-lettura che avevo proposto - *"non mi piace molto...
// cosi' si che e' pulito: no campi che sono superflui"* - e la sequenza espandi/migra/sposta/contrai
// e' effettivamente piu' pulita: alla fine non resta niente di morto.
function _articoliNascosti(seriesId) {
  const s = getData('series', []).find(x => x.id === seriesId);
  if (!s) return [];
  if (Array.isArray(s.articoliNascosti)) return s.articoliNascosti;
  // ⚠️ Finche' il passo 2 non e' stato lanciato, la verita' sta ancora nei due flag: qui si
  // ricostruisce l'elenco da loro, cosi' le caselle si aprono gia' giuste. Questa ricostruzione
  // sparisce al passo 3, quando i dati saranno migrati.
  const da = [];
  if (s.noAlbums) da.push('albums');
  if (s.noRetro)  da.push('retros');
  return da;
}
function _articoloNascosto(sez, seriesId) { return _articoliNascosti(seriesId).includes(sez); }

// 🆕 v6.283 - I SETTE BOX DELLA PAGINA SERIE, RIMESSI IN FILA. Sono markup fisso di
// `index.html` (dentro ci stanno le loro foto in base64), quindi non si rigenerano: si spostano.
// `appendChild` su un nodo gia' presente nel documento lo SPOSTA — e' la stessa proprieta' che
// rende questa funzione tre righe invece di una riscrittura.
// 📌 I box che questa serie non ha (v6.194) si riordinano insieme agli altri: sono `display:none`,
// non assenti, e il giorno che riappaiono devono trovarsi al loro posto.
// 📌 Un box che l'elenco non nomina non viene toccato e resta in testa: non si perde niente.
function _riordinaBoxSezioni() {
  const sel = document.getElementById('section-selector');
  const griglia = sel && sel.querySelector('.sec-grid');
  if (!griglia) return;
  for (const sez of PRODOTTI_INVENTARIO) {
    const card = _cardSezione(sel, sez);
    if (card) griglia.appendChild(card);
  }
}

function _applicaSezioniNascoste() {
  const sel = document.getElementById('section-selector');
  if (!sel || !currentSeriesId) return;
  // v6.216 - si guardano TUTTI gli articoli, non piu' solo quelli di una tabella a parte.
  const nascosti = _articoliNascosti(currentSeriesId);
  PRODOTTI_INVENTARIO.forEach(sez => {
    const card = _cardSezione(sel, sez);
    if (!card) {
      // Stessa scelta della v6.191: se il markup cambia lo si sente, non si tira dritto.
      console.warn('v6.216 _applicaSezioniNascoste: card', sez, 'non trovata nel selettore.');
      return;
    }
    card.style.display = nascosti.includes(sez) ? 'none' : '';
  });
}

// \uD83D\uDD34 v6.216 (Franco: "la foto si vede 3 volte; le 3 ripetizioni sono tra loro impilate").
// LA FUNZIONE CHE METTE UN'IMMAGINE DEVE IMPOSTARE TUTTO CIO' CHE QUELL'IMMAGINE RICHIEDE.
// La v6.191 scriveva `background-image` e `background-size` e lasciava il RIPETERSI al markup - che
// non e' uniforme: delle sei card dell'hub, `retros` e `bustine` non hanno
// `background-repeat:no-repeat` scritto inline (e `bustine` non ha nemmeno `background-size`).
// Con `contain` l'immagine non riempie il riquadro, lo spazio che avanza viene PIASTRELLATO, e
// siccome avanza in verticale le ripetizioni si impilano.
// \uD83D\uDCCC La lezione non e' "mancava una riga nel markup": e' che una funzione non deve dipendere da
// cio' che il markup si porta dietro per caso. Quattro card su sei funzionavano e le altre due non
// davano nessun errore - solo un'immagine ripetuta, che sembra un problema della foto.
function _sfondoUnaVoltaSola(el) {
  el.style.backgroundRepeat = 'no-repeat';
  el.style.backgroundPosition = 'center';
}

function _applicaFotoSezioni() {
  const sel = document.getElementById('section-selector');
  if (!sel) return;
  PRODOTTI_INVENTARIO.forEach(sec => {   // v6.195 - stesso motivo di `updateSectionCounts`
    // 🔴 v6.191 (Franco: "la matita che permette di cambiare la foto ai box dell'hub non funziona;
    // cambiando la foto, al salvataggio, la foto poi rimane quella di prima").
    // QUI STAVA IL GUASTO, e non era nel salvataggio: era che questa funzione parlava a un elemento
    // CHE NON ESISTE. Cercava `sec-img-<sezione>`, e di `sec-img` nell'index ci sono ZERO
    // occorrenze — in tutto il progetto quella stringa compariva una volta sola, nella riga che la
    // cercava. Quindi ENTRAMBI i rami (foto scelta e ripiego `SECTION_IMAGES`) erano codice morto:
    // il file partiva, Cloudinary rispondeva, Firestore veniva scritto, e non si vedeva niente.
    // 📌 E' la famiglia della v6.157 ("avevo modificato `categoryHTML`, che dalla v6.037 non legge
    // piu' nessuno"), e la regola scritta li' lo trovava in dieci secondi: *grep del nome; se torna
    // una riga sola, quella riga e' morta*.
    // Le card dell'hub hanno il markup FISSO nell'index e non mostrano un `<img>`: mostrano un
    // `background-image` sul primo div interno. E' quello che va scritto.
    const url = _fotoBoxUrl(sec);
    // la matita: una sola per card, e si rimette solo se non c'e' gia'
    const card = _cardSezione(sel, sec);   // v6.194 - la ricerca e' passata in un posto solo
    if (!card) return;
    // v6.191 - il riquadro della foto e' il primo figlio della card (la matita si appende in coda,
    // quindi non lo scalza). `c_fit` + `contain` come `_fotoProdotto`: stessa misura nei due posti,
    // che e' la decisione della v6.159.
    const riquadro = card.firstElementChild;
    if (!riquadro) {
      // ⚠️ NON in silenzio. Il guasto che questa release chiude e' durato perche' non falliva:
      // non trovava l'elemento e tirava dritto. Se il markup dell'index cambia ancora, questo
      // avviso e' l'unica cosa che lo dira'.
      console.warn('v6.191 _applicaFotoSezioni: nessun riquadro foto nella card di', sec,
                   '- il markup dell\'index e\' cambiato e la foto del box non si vedra\'.');
    } else if (url) {
      riquadro.style.backgroundImage = 'url(\'' + cloudinaryUrl(url, 'w_600,h_600,c_fit,q_auto,f_auto') + '\')';
      riquadro.style.backgroundSize = 'contain';
      _sfondoUnaVoltaSola(riquadro);   // v6.216
    } else if (SECTION_IMAGES[sec]) {
      // Il ripiego: si rimette il segnaposto com'e' nell'index, misura compresa.
      riquadro.style.backgroundImage = 'url(\'' + SECTION_IMAGES[sec] + '\')';
      riquadro.style.backgroundSize = '60%';
      _sfondoUnaVoltaSola(riquadro);   // v6.216
    }
    const vecchia = card.querySelector('[data-matita-box]');
    if (vecchia) vecchia.remove();
    if (!currentUser?.isAdmin) return;
    if (getComputedStyle(card).position === 'static') card.style.position = 'relative';
    const holder = document.createElement('div');
    holder.setAttribute('data-matita-box', sec);
    holder.innerHTML = _matitaBox(sec);
    const b = holder.firstElementChild;
    if (b) card.appendChild(b);
  });
}

const NOME_SERIE_SENZA_SERIE = 'Extra serie';

// \uD83D\uDD34 v6.204 (Franco: "il click sul box dei Cartoncini si e' rotto... a causa della rinomina
// che io avevo fatto della categoria fittizia") - LA SERIE CONTENITORE SI RICONOSCE DA UN FLAG.
//
// Qui c'era scritto: *"Si cerca per NOME e non per id: l'id non e' scritto da nessuna parte e
// inchiodarlo qui vorrebbe dire avere una costante che nessuno puo' verificare leggendola."*
// L'obiezione all'id era giusta; la conclusione no. Il rimedio a un identificatore illeggibile non
// e' il NOME - il nome e' precisamente la cosa che un utente puo' cambiare, e infatti l'ha
// cambiata, e i Cartoncini sono diventati irraggiungibili. **Un identificatore non deve essere una
// cosa che si legge e si modifica.**
// \uD83D\uDCCC E' la stessa decisione che questa notte ha tenuto `tipoProdotto` e `forSale` come sono su
// Firestore: il dato non si chiama come l'etichetta che gli sta sopra.
//
// ⚠️ IL NOME RESTA COME RIPIEGO, e non e' pigrizia: finche' nessuno ha spuntato il flag su
// nessuna serie, il sito deve continuare a funzionare esattamente come prima. Chi aggiorna non deve
// trovare i Cartoncini rotti in attesa di una spunta che non sa di dover mettere. Quando il flag
// c'e', comanda lui e la serie si puo' chiamare come si vuole.
function _serieSenzaSerie() {
  const tutte = getData('series', []) || [];
  const conFlag = tutte.filter(s => s.serieContenitore);
  if (conFlag.length > 1) {
    // Due contenitori sono una contraddizione: si prende il primo e LO SI DICE, invece di
    // sceglierne uno in silenzio (lezione della v6.101 sui due dati che si contraddicono).
    console.warn('v6.204: piu\' di una serie ha il flag "serie contenitore":',
                 conFlag.map(s => s.name), '- uso la prima.');
  }
  if (conFlag.length) return conFlag[0];
  const n = NOME_SERIE_SENZA_SERIE.trim().toLowerCase();
  return tutte.find(s => (s.name || '').trim().toLowerCase() === n) || null;
}

// I tipi vivono in UN documento solo, `settings/tipi_prodotto`: sono pochi e cambiano di rado.
// Una collezione a se' costerebbe una lettura in piu' ad ogni avvio per lo stesso risultato.
async function getTipiProdotto() {
  if (_cache.tipiProdotto !== undefined) return _cache.tipiProdotto;
  try {
    const docs = await fsGetAll('settings');
    const found = docs.find(d => d.id === 'tipi_prodotto');
    _cache.tipiProdotto = Array.isArray(found?.tipi) ? found.tipi : [];
  } catch (e) { _cache.tipiProdotto = []; }
  return _cache.tipiProdotto;
}

// Lettura sincrona per chi disegna. Se la cache non c'e' ancora torna un elenco vuoto E se la
// carica, poi ridisegna: cosi' il primo giro mostra i cinque di sempre invece di aspettare la rete,
// e i box compaiono da soli un istante dopo. Un elenco vuoto perche' "non e' ancora arrivato" e uno
// vuoto perche' "non ce ne sono" si distinguono solo qui, ed e' per questo che il caricamento parte
// da questa funzione e non da chi la chiama.
function _tipiProdotto() {
  if (_cache.tipiProdotto === undefined) {
    getTipiProdotto().then(() => { try { renderCatalog(); } catch (e) {} });
    return [];
  }
  // v6.167 - i box si ordinano per NOME. Il campo "Ordine" e' stato tolto perche' non lo usava
  // nessuno, e con esso il criterio che lo leggeva: lasciarlo nel confronto avrebbe fatto decidere
  // la posizione dei box a un numero che nessuno puo' piu' vedere ne' cambiare — il caso peggiore,
  // perche' l'effetto resta e la causa diventa invisibile.
  return _cache.tipiProdotto.slice().sort((a, b) =>
    (a.nome || '').localeCompare(b.nome || '', 'it', { numeric: true }));
}

async function _salvaTipiProdotto(tipi) {
  _cache.tipiProdotto = tipi;
  await fsSave('settings', { id: 'tipi_prodotto', tipi });
}

// Il box di un tipo nel primo livello dell'hub. Stessa forma delle card dei cinque prodotti, meno
// l'elenco delle serie: un tipo senza serie non ha righe da mostrare li' dentro, e un riquadro
// vuoto sotto una linea di separazione direbbe che manca qualcosa.
// 🆕 v6.305 - IL NOME DI UN TIPO NELLA LINGUA CORRENTE. Il ripiego e' l'italiano: un tipo senza
// traduzione si legge in italiano, non sparisce. Un nome vuoto renderebbe il suo box irraggiungibile
// — e' successo davvero con la v6.204, per un'altra ragione, e non va rifatto per questa.
function _nomeTipo(t) {
  if (!t) return '';
  return ((currentLang === 'it' ? t.nome : (t.nomeEn || t.nome)) || '').trim();
}
// Il singolare ha gia' un suo ripiego (il plurale, v6.148): qui se ne aggiunge uno prima, la lingua.
// L'ordine e' quello che si legge: inglese singolare, inglese plurale, italiano singolare, italiano
// plurale. Si scende finche' si trova qualcosa da scrivere.
function _singolareTipo(t) {
  if (!t) return '';
  const cand = (currentLang === 'it')
    ? [t.singolare, t.nome]
    : [t.singolareEn, t.nomeEn, t.singolare, t.nome];
  for (const c of cand) if ((c || '').trim()) return c.trim();
  return '';
}

function tipoProdottoCardHTML(t, tutti) {
  const suoi = tutti.filter(f => (f.tipoProdotto || '') === t.id);
  const quanti = suoi.filter(_eBase).length;
  const desc = currentLang === 'it'
    ? (quanti === 1 ? '1 oggetto' : quanti + ' oggetti')
    : (quanti === 1 ? '1 item' : quanti + ' items');
  const _url = _fotoBoxUrl(t.id);   // v6.145
  const _foto = _url
    ? '<img src="' + cloudinaryUrl(_url, 'w_400,h_400,c_fit,q_auto,f_auto') +
      '" alt="" style="width:100%;height:100%;object-fit:contain;position:absolute;top:0;left:0;padding:8px;">'
    : '<span style="font-size:3rem;">&#128230;</span>';
  // v6.149 - due matite: quella della FOTO (v6.145, a destra) e quella del NOME, spostata a
  // sinistra. Due mestieri diversi sullo stesso box, e distinguerli per posizione costa meno di
  // un menu.
  const _matitaNome = currentUser?.isAdmin
    ? '<button type="button" title="Modifica questo tipo di articolo" ' +
      'onclick="event.stopPropagation();openAddTipoProdottoModal(\'' + t.id + '\')" ' +
      'style="position:absolute;top:6px;right:42px;z-index:3;border:none;border-radius:999px;' +
      'width:30px;height:30px;line-height:1;cursor:pointer;font-size:0.9rem;' +
      'background:rgba(0,0,0,0.6);color:#fff;">&#9881;</button>'
    : '';
  return '<div class="card" style="position:relative;" onclick="openTipoProdotto(\'' + t.id + '\')">' +
    _matitaBox(t.id) + _matitaNome +
    '<div class="card-img-placeholder">' + _foto + '</div>' +
    '<div class="card-body">' +
      '<div class="card-title" style="margin-bottom:0.5rem;">' + esc(_nomeTipo(t)) + '</div>' +
      '<div class="card-desc">' + esc(desc) + '</div>' +
    '</div>' +
  '</div>';
}

// Quale tipo si sta guardando. Vive accanto a `currentSeriesId`/`currentSection` perche' e' la
// stessa cosa: dice cosa c'e' nella griglia. Torna a null uscendo, come tutti gli altri filtri —
// un filtro acceso che non si vede svuota la griglia senza dire perche' (v6.095, v6.134, v6.140).
let _tipoProdottoCorrente = null;

// Entrando in un box non ci sono i box delle SERIE: ce n'e' una sola, e sarebbe un passaggio a
// vuoto. Si va dritti alla vista degli oggetti, che e' quella di sempre — quindi arrivano gratis
// ricerca, filtri, vista tabellare e il "+ Aggiungi".
function openTipoProdotto(id) {
  // `tipo` e non `t`: `t()` e' la funzione delle traduzioni, e ombreggiarla dentro una funzione
  // significa che la prima riga tradotta che qualcuno aggiungera' qui dentro non funzionera', con
  // un errore che parla di tutt'altro.
  const tipo = _tipiProdotto().find(x => x.id === id);
  if (!tipo) return;
  const serie = _serieSenzaSerie();
  if (!serie) {
    // Senza il contenitore non si puo' entrare, e va detto con il nome esatto che manca: un
    // "errore" generico qui manderebbe a cercare nel posto sbagliato.
    // v6.204 - il messaggio non nomina piu' UNA serie che potrebbe chiamarsi in mille modi: dice
    // cosa manca e come si mette. Prima diceva 'Manca la serie "Extra serie"' anche quando la serie
    // c'era e si chiamava soltanto in un altro modo - cioe' mandava a cercare esattamente nel posto
    // sbagliato, che e' il difetto che quel messaggio diceva di voler evitare.
    toast((currentLang === 'it'
      ? 'Nessuna serie e\' marcata come contenitore degli articoli senza serie. Aprine una dalla console e spunta "Serie contenitore".'
      : 'No series is marked as the container for items without a series. Open one from the console and tick "Container series".'), 'error', null, 9000);
    return;
  }
  const d = document.getElementById('prodotto-detail');
  if (d) d.style.display = 'none';
  openSeriesDetail(serie.id);
  _tipoProdottoCorrente = id;   // DOPO: `openSeriesDetail` azzera, e deve azzerare
  openSeriesSection('extras');  // e questa ridisegna la griglia, quindi il filtro e' gia' acceso
  const titolo = document.getElementById('items-section-title');
  if (titolo) titolo.textContent = _nomeTipo(tipo) || titolo.textContent;
}

// ---- LA FORM DEL TIPO: due campi, e non e' una form di prodotti ----
// Il PRODOTTO si crea dalla scheda, che dal §12.1 e' l'unica form del sito. Qui si crea il BOX che
// lo conterra': sono due mestieri diversi, e tenerli separati e' cio' che evita di scrivere una
// seconda scheda gemella — la cosa che il §12.1 ha passato otto release a smontare.
// v6.149 (Franco) - LA STESSA FORM CREA E MODIFICA. Con `id` vuoto crea, con un id riapre quel tipo
// e salva sopra. Una seconda form gemella per la modifica sarebbe la cosa che il §12.1 ha passato
// otto release a smontare — e qui costerebbe ancora meno accorgersene, visto che i campi sono
// quattro.
// Nasce perche' la v6.148 ha consegnato un campo (il singolare) che non si poteva raggiungere: il
// tipo esisteva gia' e non c'era modo di riaprirlo. Un campo irraggiungibile e' peggio di un campo
// che manca — sembra che si possa fare, e non si puo'.
function openAddTipoProdottoModal(idDaModificare) {
  if (!currentUser?.isAdmin) { toast((currentLang === 'it' ? 'Solo per admin' : 'Admin only'), 'error'); return; }
  const it = currentLang === 'it';
  const t = idDaModificare ? _tipiProdotto().find(x => x.id === idDaModificare) : null;
  const g = id => document.getElementById(id);
  if (g('tipo-prodotto-id')) g('tipo-prodotto-id').value = t ? t.id : '';
  if (g('tipo-prodotto-nome')) g('tipo-prodotto-nome').value = t ? (t.nome || '') : '';
  if (g('tipo-prodotto-singolare')) g('tipo-prodotto-singolare').value = t ? (t.singolare || '') : '';
  if (g('tipo-prodotto-nome-en')) g('tipo-prodotto-nome-en').value = t ? (t.nomeEn || '') : '';
  if (g('tipo-prodotto-singolare-en')) g('tipo-prodotto-singolare-en').value = t ? (t.singolareEn || '') : '';

  if (g('tipo-prodotto-haretro')) g('tipo-prodotto-haretro').checked = !!(t && t.haRetro);
  if (g('tipo-prodotto-ordina')) g('tipo-prodotto-ordina').value = t ? (t.ordina || '') : '';   // v6.155
  if (g('tipo-prodotto-hataglia')) g('tipo-prodotto-hataglia').checked = !!(t && t.haTaglia);  // v6.160
  if (g('tipo-prodotto-colonne-desktop')) g('tipo-prodotto-colonne-desktop').value = (t && _colClamp(t.colonneDesktop)) || COLONNE_DEFAULT.extras.d;  // v6.163
  if (g('tipo-prodotto-colonne-mobile'))  g('tipo-prodotto-colonne-mobile').value  = (t && _colClamp(t.colonneMobile))  || COLONNE_DEFAULT.extras.m;  // v6.163
  const tit = g('tipo-prodotto-modal-title');
  if (tit) tit.textContent = t ? (it ? 'Modifica tipo di articolo' : 'Edit item type')
                               : (it ? 'Aggiungi tipo di articolo' : 'Add item type');
  // v6.151 (Franco) - ELIMINA GRIGIATO finche' quel tipo ha dei prodotti dentro. La v6.149 lo
  // lasciava premibile e spiegava nella conferma che gli oggetti sarebbero rimasti orfani di box:
  // una spiegazione dopo il clic e' un avviso, un pulsante spento e' una regola. E qui la regola
  // c'e' — un box con roba dentro non si butta — quindi tanto vale dirla prima.
  // Il motivo sta nel `title`, se no un pulsante spento e' un vicolo cieco senza spiegazione: chi
  // ci passa sopra legge quanti oggetti lo trattengono e sa cosa deve fare per poterlo premere.
  const del = g('tipo-prodotto-elimina');
  if (del) {
    const _dentro = t ? (getData('figurines', []) || []).filter(x => (x.tipoProdotto || '') === t.id).length : 0;
    del.style.display = t ? '' : 'none';
    del.disabled = _dentro > 0;
    del.style.opacity = _dentro > 0 ? '0.45' : '';
    del.style.cursor = _dentro > 0 ? 'not-allowed' : '';
    del.title = _dentro > 0
      ? (it ? 'Non si può eliminare: contiene ' + _dentro + (_dentro === 1 ? ' oggetto.' : ' oggetti.') +
              ' Spostali o cancellali prima.'
            : 'Cannot delete: it holds ' + _dentro + ' item(s).')
      : (it ? 'Elimina questo tipo di articolo' : 'Delete this item type');
  }
  document.getElementById('add-tipo-prodotto-modal')?.classList.remove('hidden');
  setTimeout(() => g('tipo-prodotto-nome')?.focus(), 50);
}

// v6.149 - la cancellazione NOMINA QUANTI OGGETTI restano dentro. "Sei sicuro?" senza un numero non
// e' una domanda, e' un ostacolo (§14, punto 2). E gli oggetti NON si cancellano: restano in Extra
// serie, raggiungibili dalla serie, invece di sparire insieme al box che li mostrava.
async function eliminaTipoProdotto() {
  if (!currentUser?.isAdmin) return;
  const it = currentLang === 'it';
  const id = (document.getElementById('tipo-prodotto-id')?.value || '').trim();
  if (!id) return;
  const t = _tipiProdotto().find(x => x.id === id);
  if (!t) return;
  const dentro = (getData('figurines', []) || []).filter(f => (f.tipoProdotto || '') === id).length;
  // v6.151 - il rifiuto sta anche QUI, dove si scrive, e non solo sul pulsante: il pulsante puo'
  // essere stato disegnato prima che qualcuno aggiungesse un oggetto, e un controllo accanto alla
  // scrittura e' l'unico che non si puo' scavalcare. Stessa forma della v6.143/B.
  if (dentro > 0) {
    toast((it ? 'Non si può eliminare "' + _nomeTipo(t) + '": contiene ' + dentro +
                (dentro === 1 ? ' oggetto.' : ' oggetti.')
              : 'Cannot delete "' + _nomeTipo(t) + '": it holds ' + dentro + ' item(s).'), 'error', null, 6000);
    return;
  }
  const msg = it
    ? 'Elimino il tipo di articolo "' + _nomeTipo(t) + '"?\n\nNon contiene nessun oggetto.'
    : 'Delete item type "' + _nomeTipo(t) + '"?\n\nIt holds no items.';
  if (!confirm(msg)) return;
  try {
    await _salvaTipiProdotto(_tipiProdotto().filter(x => x.id !== id));
  } catch (e) {
    console.error('eliminaTipoProdotto', e);
    toast(it ? '❌ Eliminazione fallita' : '❌ Delete failed', 'error');
    return;
  }
  closeModal('add-tipo-prodotto-modal');
  toast(it ? '✅ Tipo di articolo eliminato' : '✅ Item type deleted', 'success');
  try { renderCatalog(); } catch (e) {}
}

async function salvaTipoProdotto() {
  if (!currentUser?.isAdmin) return;
  const it = currentLang === 'it';
  const nome = (document.getElementById('tipo-prodotto-nome')?.value || '').trim();
  const singolare = (document.getElementById('tipo-prodotto-singolare')?.value || '').trim();
  // v6.305 - le due caselle inglesi. Possono restare vuote: il ripiego e' l'italiano.
  const nomeEn = (document.getElementById('tipo-prodotto-nome-en')?.value || '').trim();
  const singolareEn = (document.getElementById('tipo-prodotto-singolare-en')?.value || '').trim();
  // v6.167 - il campo "Ordine" non c'e' piu': non lo usava nessuno (Franco). I box si ordinano per
  // NOME, che e' l'unico criterio rimasto e non ha bisogno di essere scritto da qualcuno.
  const ordina = (document.getElementById('tipo-prodotto-ordina')?.value || '').trim();   // v6.155
  if (!nome) { toast(it ? 'Il nome è obbligatorio' : 'Name is required', 'error'); return; }
  // v6.155 - UN NOME STORTO FERMA IL SALVATAGGIO e viene nominato. Ignorarlo produrrebbe un
  // ordinamento diverso da quello scritto, senza che niente lo dica: la stessa famiglia dei filtri
  // invisibili e dei controlli spenti in silenzio chiusa tre volte in questi due giorni.
  const _ord = _passiOrdinamento(ordina);
  // v6.167 (Franco) - OBBLIGATORIO. Prima vuoto voleva dire "l'ordinamento di sempre", cioe' uno
  // stato in piu' che significava qualcosa: chi creava un tipo poteva lasciarlo in bianco senza
  // accorgersi di aver deciso. Ora si dichiara, e il messaggio dice con cosa si compila — un campo
  // obbligatorio che non spiega cosa vuole e' un ostacolo, non una regola.
  if (!_ord.passi.length) {
    toast((it ? 'L\u2019ordinamento degli oggetti è obbligatorio. Ammessi: '
                + Object.keys(CAMPI_ORDINAMENTO_TIPO).join(', ') + '.'
              : 'The sort order is required.'), 'error', null, 9000);
    return;
  }
  if (_ord.sconosciuti.length) {
    toast((it ? 'Ordinamento: non conosco ' + _ord.sconosciuti.map(x => '"' + x + '"').join(', ') +
                '. Ammessi: ' + Object.keys(CAMPI_ORDINAMENTO_TIPO).join(', ') + '.'
              : 'Sort order: unknown ' + _ord.sconosciuti.join(', ')), 'error', null, 9000);
    return;
  }
  const idEsistente = (document.getElementById('tipo-prodotto-id')?.value || '').trim();   // v6.149
  const haRetro = !!document.getElementById('tipo-prodotto-haretro')?.checked;             // v6.149
  const haTaglia = !!document.getElementById('tipo-prodotto-hataglia')?.checked;           // v6.160
  // v6.163 - obbligatori anche qui: vuoto -> il default della sezione `extras`, che e' quella in cui
  // questi oggetti vivono.
  const colonneDesktop = _colClamp(document.getElementById('tipo-prodotto-colonne-desktop')?.value) || COLONNE_DEFAULT.extras.d;
  const colonneMobile  = _colClamp(document.getElementById('tipo-prodotto-colonne-mobile')?.value)  || COLONNE_DEFAULT.extras.m;
  const tipi = (_cache.tipiProdotto || []).slice();
  // Due box con lo stesso nome non si distinguono a colpo d'occhio, ed e' esattamente l'incidente
  // dei due `index.html` in coda al deploy: davanti a due omonimi non si sceglie.
  // v6.149 - in modifica il confronto SALTA SE STESSO, se no rinominare un tipo lasciandogli il
  // nome che ha gia' verrebbe rifiutato per omonimia con se' stesso.
  if (tipi.some(x => x.id !== idEsistente && (x.nome || '').trim().toLowerCase() === nome.toLowerCase())) {
    toast(it ? 'Esiste già un tipo di articolo con questo nome.' : 'An item type with that name already exists.', 'error');
    return;
  }
  if (idEsistente) {
    const k = tipi.findIndex(x => x.id === idEsistente);
    if (k < 0) { toast(it ? 'Quel tipo di articolo non esiste più.' : 'That item type no longer exists.', 'error'); return; }
    // Si riscrive il record intero a partire da quello che c'e': cosi' un campo aggiunto in futuro
    // non viene perso da un salvataggio scritto oggi.
    tipi[k] = { ...tipi[k], nome, singolare, nomeEn, singolareEn, haRetro, haTaglia, ordina, colonneDesktop, colonneMobile };
  } else {
    // L'id si genera e non si scrive: e' un riferimento, e un riferimento battuto a mano e' un id
    // storto che non si vede (la lezione della v6.119 sul `baseFigurineId`).
    const id = 'tp_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
    tipi.push({ id, nome, singolare, nomeEn, singolareEn, haRetro, haTaglia, ordina, colonneDesktop, colonneMobile });
  }
  try {
    await _salvaTipiProdotto(tipi);
  } catch (e) {
    console.error('salvaTipoProdotto', e);
    toast(it ? '❌ Salvataggio fallito: ' + (e?.code || e?.message || 'errore') : '❌ Save failed', 'error');
    return;
  }
  closeModal('add-tipo-prodotto-modal');
  // v6.161 - se si stava guardando QUEL box, il titolo della sezione segue il nome nuovo. Senza,
  // rinominare un tipo lasciava a schermo il nome vecchio fino al giro dopo — e chi l'ha appena
  // cambiato conclude che non si e' salvato.
  if (idEsistente && _tipoProdottoCorrente === idEsistente) {
    const _t = _tipiProdotto().find(x => x.id === idEsistente);
    const _titolo = document.getElementById('items-section-title');
    if (_t && _titolo) _titolo.textContent = _t.nome || _titolo.textContent;
    try { renderItems(); } catch (e) {}   // l'ordinamento del tipo puo' essere cambiato
  }
  toast(it ? (idEsistente ? '✅ Tipo di articolo aggiornato' : '✅ Tipo di articolo creato')
           : (idEsistente ? '✅ Item type updated' : '✅ Item type created'), 'success');
  try { renderCatalog(); } catch (e) {}
}

// ---- SECONDO LIVELLO: L'HUB DI UN PRODOTTO ----
// Stessa impostazione dell'hub di una serie, con i box delle SERIE al posto dei box dei prodotti.
// Il contenitore si crea una volta sola e poi si riusa.
let _prodottoCorrente = null;
// Da dove si e' arrivati in una sezione: se dall'hub di un prodotto, il tasto indietro torna LI'.
// Stessa idea di _elencoNav della v6.033 — ricordare la provenienza invece di darla per scontata.
let _sezioneApertaDaProdotto = null;

function _creaProdottoDetail() {
  let d = document.getElementById('prodotto-detail');
  if (d) return d;
  d = document.createElement('div');
  d.id = 'prodotto-detail';
  d.style.cssText = 'display:none;padding-top:64px;min-height:100vh;position:relative;z-index:1;';
  d.innerHTML =
    '<div class="series-hero"><div class="series-hero-inner">' +
      '<button class="back-btn" onclick="closeProdottoDetail()">&#8592; <span data-i18n="back">Inventario</span></button>' +
      '<h1 class="series-name" id="prodotto-detail-name" style="margin:0.4rem 0 0;"></h1>' +
      // v6.156 - meno aria fra il titolo e le numeriche: erano due blocchi separati da uno spazio
      // che li faceva sembrare due cose, e sono la stessa.
      '<div id="prodotto-detail-meta" style="font-size:0.85rem;color:var(--muted);margin:0.1rem 0 0;"></div>' +
      '<div id="prodotto-carosello-sez" style="display:none;width:100%;position:relative;margin-top:0.6rem;">' +
        '<button type="button" id="prodotto-carosello-prec" aria-label="Precedente" style="position:absolute;left:-6px;top:42%;transform:translateY(-50%);z-index:2;border:none;background:rgba(0,0,0,0.55);color:var(--text);font-size:1.3rem;line-height:1;padding:0.4rem 0.55rem;border-radius:999px;cursor:pointer;">&#8249;</button>' +
        '<div id="prodotto-carosello" style="display:flex;gap:0.9rem;overflow-x:auto;scroll-behavior:smooth;scroll-snap-type:x mandatory;padding:0.2rem 0.4rem 0.6rem;"></div>' +
        '<button type="button" id="prodotto-carosello-succ" aria-label="Successivo" style="position:absolute;right:-6px;top:42%;transform:translateY(-50%);z-index:2;border:none;background:rgba(0,0,0,0.55);color:var(--text);font-size:1.3rem;line-height:1;padding:0.4rem 0.55rem;border-radius:999px;cursor:pointer;">&#8250;</button>' +
      '</div>' +
    '</div></div>' +
    '<div style="max-width:1100px;margin:0 auto;padding:2rem;">' +
      // v6.080 (Franco) - la griglia delle serie dell'hub usa la STESSA classe dell'Inventario.
      // Prima aveva un `grid-template-columns: repeat(auto-fit, minmax(240px,1fr))` scritto a mano:
      // su un telefono da 390px due colonne da 240 non ci stanno, quindi ne restava UNA - non una
      // scelta per il telefono, l'aritmetica di quel 240. L'Inventario per Serie invece usa
      // `grid-3`, che una sua regola per il telefono ce l'ha gia' (tre colonne).
      // Due griglie che mostrano le stesse serie devono comportarsi allo stesso modo, e il modo
      // di ottenerlo non e' ritoccare il 240: e' usare la stessa classe.
      '<div class="grid-3" id="prodotto-serie-grid"></div>' +
    '</div>';
  // v6.073 (Franco) — BACO: l'hub partiva piu' in basso di quello di una serie. Con
  // body.appendChild finiva IN FONDO al body, cioe' DOPO il <footer>, che sta al primo livello:
  // il footer restava sopra e lo spingeva giu'. Va messo dove sta il suo gemello, subito dopo
  // #series-detail, cosi' i due occupano lo stesso posto nel flusso e non c'e' niente da
  // compensare con margini o padding — che avrebbero curato il sintomo lasciando la causa.
  const gemello = document.getElementById('series-detail');
  if (gemello && gemello.parentNode) gemello.parentNode.insertBefore(d, gemello.nextSibling);
  else document.body.appendChild(d);
  return d;
}

function openProdottoDetail(sec) {
  _prodottoCorrente = sec;
  _creaProdottoDetail();
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('series-detail').style.display = 'none';
  document.getElementById('prodotto-detail').style.display = 'block';
  _caroselloSpegni('home'); _caroselloSpegni('serie');

  const tutti = getData('figurines', []);
  const miei = _diTipo(tutti, sec);
  const basi = miei.filter(_eBase);
  const serieOrdinate = getData('series', []).slice().sort((a, b) => (a.order ?? 9999) - (b.order ?? 9999));
  // v6.073 (Franco) — la testata dell'hub dice le stesse cose della card da cui ci si e' arrivati,
  // e le dice con le stesse funzioni: titolo, "N Serie:", scomposizione per tipologia coi colori.
  // Se fossero due testi diversi, la card e la pagina che apre finirebbero per non combaciare —
  // ed e' il tipo di divergenza che nessuno nota, perche' le due non si vedono mai insieme.
  // v6.156 - anche qui `serieConRoba` se n'e' andata con la riga che la usava.
  document.getElementById('prodotto-detail-name').textContent = _titoloProdotto(sec);
  // v6.156 (Franco) - resta il solo riepilogo. Il conto delle serie se ne va da qui come dalla
  // card: sotto c'e' gia' un box per ogni serie, quindi dirne il numero era ripetere in cifre una
  // cosa che si legge per esteso due centimetri piu' giu'.
  document.getElementById('prodotto-detail-meta').innerHTML =
    '<div style="font-size:0.86rem;line-height:1.7;">' + _righeTipologie(miei) + '</div>';
  const griglia = document.getElementById('prodotto-serie-grid');
  // v6.080 (Franco) - TRE SERIE PER RIGA ANCHE QUI SU TELEFONO, come nell'Inventario.
  // Perche' dal JS e non dal CSS: le tre colonne dell'Inventario non vengono da `.grid-3` (che e'
  // auto-fill minmax(300px,1fr) e su un telefono cade a una colonna sola) ma da una media query
  // agganciata all'ID #catalog-grid - scritta nella v5.823/835 con la nota "le altre .grid-3 del
  // sito non cambiano". Dare la stessa classe non bastava, e una media query gemella nell'index
  // non funziona: il CSS inline di quel file ha le graffe sbilanciate (una in eccesso verso riga
  // 106), quindi una regola aggiunta in fondo finisce annidata in un blocco che non e' quello che
  // sembra leggendolo. Uno stile inline non dipende da quella struttura e vince comunque.
  const _mobHub = _isMobileViewport();
  if (griglia) {
    griglia.style.gridTemplateColumns = _mobHub ? 'repeat(' + HUB_COLONNE_MOBILE + ', 1fr)' : '';
    griglia.style.gap = _mobHub ? '0.45rem' : '';
  }
  // Le serie che di quel prodotto non hanno NIENTE non si mostrano: un box che apre una griglia
  // vuota e' un vicolo cieco. Nella colonna del primo livello invece restano, perche' li' servono
  // a tenere l'elenco della stessa lunghezza in tutte le card — sono due mestieri diversi.
  const conRoba = serieOrdinate.filter(s => miei.some(f => f.seriesId === s.id));
  griglia.innerHTML = conRoba.map(s => {
    // v6.073 (Franco) - nel box di una serie ci vanno TUTTI i numeri, ognuno nel colore della sua
    // tipologia, non piu' il solo "N base, M in tutto". Il colore fa da etichetta - e' il mestiere
    // per cui il codice della v5.703 esiste - e il nome per esteso resta nel passaggio del mouse.
    const suoi = miei.filter(f => f.seriesId === s.id);
    const etichetta = _righeTipologie(suoi, 'pillole'); // v6.080 - come le card dell'Inventario
    return '<div class="section-choice-card" onclick="apriSerieDaProdotto(\'' + s.id + '\')" style="padding:0;overflow:hidden;">' +
      '<div style="width:100%;aspect-ratio:var(--hub-box-ratio);background:var(--bg3);overflow:hidden;display:flex;align-items:center;justify-content:center;">' +
        (s.img ? '<img src="' + cloudinaryUrl(s.img, 'w_400,h_400,c_fit,q_auto,f_auto') + '" loading="lazy" alt="" style="width:100%;height:100%;object-fit:contain;">' : '<span style="font-size:3rem;">&#127924;</span>') +
      '</div>' +
      '<div class="card-body prodotto-serie-testo" style="padding:' + (_mobHub ? '0.5rem 0.5rem 0.6rem' : '1.25rem 1.5rem') + ';text-align:left;">' + // v6.080 - su telefono il riquadro si stringe con la colonna
        '<div class="card-title" style="margin-bottom:0;' + (_mobHub ? 'font-size:0.88rem;line-height:1.2;' : '') + '">' + esc(_nomeSerieCard(s)) + '</div>' +
        etichetta +
      '</div>' +
    '</div>';
  }).join('');

  try { renderCaroselloProdotto(); } catch (e) { console.error('renderCaroselloProdotto', e); }
  try { _aggiornaLogoNavbar(); } catch (e) {}
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function closeProdottoDetail() {
  _caroselloSpegni('prodotto');
  const d = document.getElementById('prodotto-detail');
  if (d) d.style.display = 'none';
  _prodottoCorrente = null;
  _sezioneApertaDaProdotto = null;
  document.getElementById('page-catalog').classList.add('active');
  renderCatalog();
}

// Il terzo livello e' la griglia che esiste gia': stessa destinazione, altra strada.
function apriSerieDaProdotto(seriesId) {
  const sec = _prodottoCorrente;
  _caroselloSpegni('prodotto');
  const d = document.getElementById('prodotto-detail');
  if (d) d.style.display = 'none';
  openSeriesDetail(seriesId);
  openSeriesSection(sec);
  _sezioneApertaDaProdotto = sec;  // dopo openSeriesSection, che non lo sa
}

function renderCatalog() {
  const q = (document.getElementById('series-search')?.value || '').trim();
  if (q) { renderCatalogSearch(q); return; }
  // Nessuna query: ripristina vista normale
  const resultsEl = document.getElementById('catalog-search-results');
  const grid = document.getElementById('catalog-grid');
  if (resultsEl) resultsEl.style.display = 'none';
  if (grid) grid.style.display = '';
  _aggiornaBivioInventario();
  if (_taglioInventario === 'prodotti') { if (grid) renderCatalogProdotti(grid); return; }
  // v6.080 - tornando al taglio per SERIE la griglia riprende le sue colonne: e' lo stesso
  // elemento, e lo stile inline messo dal taglio Prodotti gli resterebbe addosso.
  if (grid) grid.style.gridTemplateColumns = '';
  let series = getData('series', []);
  series = series.sort((a,b) => (a.order ?? 9999) - (b.order ?? 9999));
  if (!series.length) {
    grid.innerHTML = `<div class="empty-state"><div class="empty-icon">🎴</div><p class="empty-title">${t('catalog.empty')}</p></div>`;
    return;
  }
  grid.innerHTML = series.map(s => seriesCardHTML(s)).join('');
}

// v6.093 (Franco) - LA RICERCA NON DEVE CHIEDERE L'ACCENTO ESATTO.
// Segnalato da Franco cercando PIE-DINO, che non trovava PIÈ-DINO. Nei nomi Sgorbions gli accenti
// sono dappertutto (PIÈ-DINO, PUBBLICITÀ PROGRESSO, L'ALFABETO) e chi cerca non sa - e non deve
// sapere - se nel dato la lettera e' accentata.
// COME: la normalizzazione Unicode NFD separa la lettera dal segno diacritico, e il segno si butta.
// Vale per QUALUNQUE accento, mentre una lista di lettere scritta a mano dimentica sempre la È
// maiuscola o la ù. Stesso trattamento per i tre apostrofi (dritto, tipografico, accento grave):
// nei dati convivono e a occhio non si distinguono, quindi chi cerca non puo' indovinare quale sia.
// DOVE: in TUTTI i punti che cercano - le due ricerche, i quattro menu a tendina dei collegamenti,
// il selettore del paese - e su ENTRAMBI i lati del confronto. Una funzione sola, non nove copie:
// e' la stessa lezione di _dueFacce() e _changeConRetroErrato().
// ⚠️ NON va usata per le CHIAVI DI UNICITA' (controllo duplicati, riconoscimento in import): li'
// due nomi che differiscono per un accento sono due nomi diversi, e confonderli produrrebbe
// doppioni inventati - cioe' il difetto opposto, su dati veri.
// 🔴 v6.263 (Franco) - GLI SPAZI TORNANO. QUESTA FUNZIONE LI TOGLIEVA, E NON ERA MAI STATO
// CHIESTO. Franco: *"non ho mai detto di fare una stringa unica di tutto il testo di un oggetto;
// dissi una volta solo di non contare i '-'"*.
//
// IL DANNO, misurato su dati veri: `fullName` NON e' un campo, e' una stringa COMPOSTA da piu'
// campi uniti da " - " (nome, categoria, sottocategoria, tipologia). Togliendo gli spazi
// sparivano i confini fra quei pezzi, e la ricerca trovava parole a cavallo di due campi diversi:
//     "PERMESSO DI SCROCCONE - ROSSO"      -> permessodiscrocco NERO sso
//     "PERMESSO DI SBOCCATAGGINE - ROSSO"  -> permessodisboccataggi NERO sso
// Cercando "nero" uscivano retro ROSSI, e a schermo la parola non c'era da nessuna parte.
// Trovato da Franco su due casi veri; io avevo dato la spiegazione giusta per il sintomo ma
// sbagliata per la causa — davo per buona una regola che nessuno aveva chiesto.
//
// 📌 COSA RESTA COME PRIMA, ed e' cio' che la v6.093 voleva davvero: via gli accenti (PIE-DINO
// trova PIÈ-DINO), via i tre apostrofi, e VIA I TRATTINI — che erano l'unica cosa richiesta.
// Gli spazi ora si NORMALIZZANO invece di sparire: piu' spazi diventano uno, e i bordi restano.
// ⚠️ "GROSSO" continua a contenere "ROSSO", e non e' un difetto: e' una sottostringa dentro UNA
// parola, non a cavallo di due campi. Una ricerca per sottostringa fa questo, e Franco l'ha
// accettato esplicitamente.
// ⚠️ TOCCA TUTTI I PUNTI CHE CERCANO — le due ricerche, i quattro menu dei collegamenti, il
// selettore del paese. Conseguenza da sapere: "sanmarino" scritto tutto attaccato non trova piu'
// "San Marino". E' il prezzo della correzione, ed e' piccolo rispetto ai falsi positivi che toglie.
function _perRicerca(s) {
  return String(s == null ? '' : s)
    .normalize('NFD').replace(/\p{M}/gu, '')
    .replace(/[’‘‛`´']/g, '')
    .replace(/[\-‐-―_]+/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

// 🆕 v6.264 (Franco: "le approssimazioni della ricerca devono avere senso") — SI CERCA
// DALL'INIZIO DI UNA PAROLA, NON IN MEZZO.
//
// Il caso che ha aperto la questione: cercando "rosso" usciva "PREMIO DI G-ROSSO IPOCRITA", perche'
// `includes` trova la sottostringa ovunque, anche incastrata dentro un'altra parola. Franco:
// *"uno mica ci arriva"*. Ed e' vero — la v6.263 aveva tolto i falsi positivi FRA campi diversi
// (gli spazi cancellati), ma restavano quelli DENTRO una parola, che a chi guarda sono
// indistinguibili: in entrambi i casi la parola cercata a schermo non c'e'.
//
// 📌 LA REGOLA NUOVA E' QUELLA CHE UNO SI ASPETTA SENZA DOVERLA IMPARARE: quello che scrivi e'
// l'INIZIO di una parola. "rosso" trova ROSSO e ROSSOBLU, non GROSSO. "perm" trova PERMESSO.
// Vale anche per le richieste di piu' parole: "permesso di" combacia perche' comincia su un
// confine di parola, e da li' prosegue com'e' scritto.
// ⚠️ Non e' una ricerca "per parola intera": "perm" deve continuare a funzionare, perche' scrivere
// meno e' il modo normale di cercare. Il vincolo e' solo sull'INIZIO.
//
// ⚠️ DOVE SI APPLICA: le due ricerche degli oggetti e quella delle serie. NON i quattro menu a
// tendina dei collegamenti ne' il selettore del paese: li' si sta scegliendo da un elenco corto e
// gia' visibile, e restringere il modo di filtrare toglierebbe piu' di quanto dia. Se un giorno
// dovessero allinearsi, e' questa la funzione da chiamare.
function _matchRicerca(testo, qn) {
  if (!qn) return true;
  const t = _perRicerca(testo);
  if (!t) return false;
  let i = t.indexOf(qn);
  while (i >= 0) {
    if (i === 0 || t.charAt(i - 1) === ' ') return true;   // inizio stringa o inizio parola
    i = t.indexOf(qn, i + 1);
  }
  return false;
}

// v6.096 (Franco) - LE DUE RICERCHE GUARDANO LO STESSO INSIEME DI CAMPI, e ora lo guardano
// perche' lo chiedono alla stessa funzione, non perche' due elenchi sono stati scritti uguali.
// La v6.049/050 li aveva gia' allineati una volta, campo per campo. Sono tornati a divergere lo
// stesso: `desc` era finito nella ricerca GLOBALE e non in quella di SEZIONE, e la differenza non
// si vedeva da nessuna parte - cercando una parola della descrizione dalla griglia di una serie
// non si trovava niente, e sembrava che quella parola non ci fosse.
// Due elenchi copiati restano uguali finche' qualcuno non ne tocca uno: allinearli di nuovo a mano
// avrebbe solo rimandato la prossima divergenza. Da qui in poi il campo si aggiunge in UN posto.
// Il NUMERO resta fuori dalla normalizzazione: si confronta grezzo, perche' _perRicerca toglie
// trattini e spazi e su una cifra non c'e' niente da normalizzare.
// Le NOTE ci sono solo per l'admin: per chiunque altro il campo non esiste sul sito, e renderlo
// cercabile lo farebbe esistere - un oggetto comparirebbe fra i risultati per una parola che chi
// cerca non puo' vedere da nessuna parte.
// 🆕 v6.247 (Franco: "la parola ricercata non viene usata per cercare nei campi Versione, Tipo di
// change, Tipo di omaggio, tipo di errore di stampa") — CI ENTRANO TUTTI E QUATTRO.
//
// 📌 I TRE TIPI SI TROVAVANO GIA', MA DI RIFLESSO: finiscono dentro il Nome completo
// ("NomeBase - TIPO"), che e' fra i campi cercati. E' esattamente la situazione del SOTTONOME
// prima della v6.049, e la ragione per cui fu aggiunto direttamente vale identica qui: il Nome
// completo e' un campo SALVATO, che puo' restare indietro (§13). Cercare il tipo di riflesso
// funziona finche' quel campo e' aggiornato — cioe' dipende da una cosa che puo' rompersi.
// Cercarlo direttamente non dipende da niente.
//
// 🔴 LA VERSIONE E' UN CASO DIVERSO, ed e' l'unica che non si trovava per niente: non e' un campo
// del record, e' un'etichetta CALCOLATA dai cinque flag. Non sta nel Nome completo e non sta da
// nessun'altra parte, quindi cercare "omaggio" non trovava nulla — nemmeno di riflesso.
// ⚠️ `_etichettaTipo(f, false)` e non `true`: col `true` un oggetto BASE restituirebbe "Base", e
// cercare quella parola tirerebbe su l'intero set base della serie (160 oggetti su Serie 1). "Base"
// non e' un contrassegno scritto sull'oggetto: e' l'assenza di contrassegni, e non si cerca.
// 📌 L'etichetta e' nella lingua corrente, quindi si cerca nella lingua che si sta leggendo — che e'
// l'unica cosa che chi cerca puo' aspettarsi.
function _campiRicercaFigurina(f) {
  const campi = [f.name, f.subseries, f.desc, f.category, f.subcategory, f.subname, f.fullName,
                 f.changeType, f.printErrorType, f.freeVersionType,   // v6.247
                 _etichettaTipo(f, false)];                           // v6.247 - la Versione
  if (currentUser?.isAdmin) campi.push(f.note);
  return campi;
}

function _figMatchRicerca(f, qn) {
  if (!qn) return true;
  if (String(f.number || '').includes(qn)) return true;
  return _campiRicercaFigurina(f).some(v => _matchRicerca(v, qn));   // v6.264
}

// v6.093 (Franco) - IL ROSSO DI "INVISIBILE" SEGUE LA SPUNTA, nelle due form.
// Togliendo la scritta "la vede solo l'admin" il rosso restava senza un posto dove stare: e'
// passato sull'etichetta. Una funzione sola per entrambe le form - sono due punti che devono dire
// la stessa cosa, ed e' esattamente il doppione del §12.1: scriverlo due volte significa che il
// giorno che uno cambia, l'altro no, e nessuno se ne accorge.
// `coloreSpento` cambia perche' i due contesti partono da colori diversi: nella finestra il testo
// e' grigio spento, nella scheda l'etichetta ha il colore suo del CSS (stringa vuota = lo riprende).
function _dipingiInvisibile(idInput, idLabel, coloreSpento) {
  const chk = document.getElementById(idInput);
  const lab = document.getElementById(idLabel);
  if (chk && lab) lab.style.color = chk.checked ? 'var(--danger)' : coloreSpento;
}

// v6.097 (Franco) - L'ELENCO SU CUI SCORRONO LE FRECCE DALLA RICERCA GLOBALE.
// Non e' l'ordine della griglia e non e' l'ordine di `results`: e' l'ordine in cui le card
// COMPAIONO A SCHERMO, che nasce da tre annidamenti (serie -> sezione -> dentro le figurine il
// gruppo base+variazioni+change). Per questo si riempie DENTRO il map che disegna le card e non
// si ricalcola dopo: un secondo calcolo sarebbe una copia della stessa verita', e le due copie
// divergono alla prima modifica dell'ordinamento - com'e' gia' successo altrove in questo file.
let _elencoRicercaGlobale = [];

function renderCatalogSearch(q) {
  // v6.097 - si azzera SUBITO, prima di ogni ritorno anticipato. I due `return` qui sotto (query
  // vuota, query fatta di soli separatori) e quello del "nessun risultato" lasciavano altrimenti
  // in giro l'elenco della ricerca precedente, e le frecce avrebbero scorso dei risultati che a
  // schermo non c'erano piu'.
  _elencoRicercaGlobale = [];
  // v6.093 - `q` resta il testo COME L'HA SCRITTO Franco, perche' finisce nel messaggio
  // "Nessun risultato per ...": mostrargli la versione senza accenti sarebbe rispondere a una
  // domanda che non ha fatto. A confrontare ci pensa `qn`.
  q = (q || document.getElementById('series-search')?.value || '').trim();
  const qn = _perRicerca(q);
  // v6.093 - se dopo la normalizzazione non resta NIENTE (si e' cercato "-", o dei soli spazi),
  // `includes('')` sarebbe vero per ogni campo di ogni oggetto: la ricerca risponderebbe con
  // l'intero catalogo, cioe' il contrario di quello che chiede chi ha scritto qualcosa. Un testo
  // fatto di soli separatori non e' una domanda: si torna al catalogo, come a campo vuoto.
  if (!qn) { renderCatalog(); return; }
  const resultsEl = document.getElementById('catalog-search-results');
  const grid = document.getElementById('catalog-grid');
  if (!q) { renderCatalog(); return; }
  if (resultsEl) resultsEl.style.display = '';
  if (grid) grid.style.display = 'none';

  const allSeries = getData('series', []).sort((a,b) => (a.order??9999)-(b.order??9999));
  const allFigs = getData('figurines', []);

  // Cerca in serie (nome, descrizione) e negli oggetti.
  // v6.049 (Franco) - LE DUE RICERCHE CERCAVANO IN CAMPI DIVERSI. Quella dentro una sezione aveva
  // categoria, sottocategoria e Nome completo dalla v5.763; questa qui, la ricerca globale, no -
  // era rimasta ai quattro campi del 2024. Effetto misurato sui dati veri: dei 1017 retro con una
  // categoria, 621 non si trovavano cercando la loro categoria; e TUTTI e 148 quelli con un
  // sottonome non si trovavano cercando il sottonome. Da qui la domanda di Franco.
  // Ora i campi sono gli stessi nelle due ricerche, piu' `subname` in ENTRAMBE: il sottonome
  // finiva dentro il Nome completo, quindi si trovava di riflesso - ma solo finche' il Nome
  // completo e' aggiornato, ed e' un campo SALVATO che puo' restare indietro (vedi §13). Cercarlo
  // anche direttamente non dipende da niente.
  const results = [];
  allSeries.forEach(s => {
    const desc = (currentLang === 'it' ? (s.descIt || s.desc) : (s.desc || s.descIt)) || '';
    const seriesMatch = _matchRicerca(s.name, qn) || _matchRicerca(desc, qn);   // v6.264
    // v6.096 - l'elenco dei campi sta in _campiRicercaFigurina, condiviso con la ricerca di sezione
    const matchingFigs = allFigs.filter(f => f.seriesId === s.id && _figMatchRicerca(f, qn));
    if (seriesMatch || matchingFigs.length) {
      results.push({ series: s, seriesMatch, figs: matchingFigs });
    }
  });

  if (!results.length) {
    resultsEl.innerHTML = `<div class="empty-state"><div class="empty-icon">🔍</div><p class="empty-title">${currentLang === 'it' ? 'Nessun risultato per "' + q + '"' : 'No results for "' + q + '"'}</p></div>`;
    return;
  }

  const totalFigs = results.reduce((n, r) => n + r.figs.length, 0);
  const totalSeries = results.filter(r => r.seriesMatch).length;
  // v6.097 (Franco) - "1 serie TROVATE" e "1 oggetti TROVATI". Il riepilogo era scritto al plurale
  // fisso, e con un risultato solo - il caso piu' comune quando si cerca un nome preciso - sbagliava
  // l'accordo due volte nella stessa riga.
  // v6.103 (Franco) - UNA FRASE SOLA invece di due conteggi separati da un punto: "Trovati 6 oggetti
  // in 1 serie". Prima erano due misure affiancate e toccava a chi legge metterle in relazione;
  // adesso la relazione e' scritta - gli oggetti sono il risultato, le serie sono dove stanno.
  // Gli accordi restano due, e sono gli stessi di prima spostati di posto:
  //   · il PARTICIPIO passa in testa e si accorda con gli OGGETTI, non piu' con le serie
  //     (Trovato 1 oggetto / Trovati 6 oggetti);
  //   · `serie` in italiano e' invariabile (1 serie / 2 serie), quindi in coda non c'e' niente da
  //     accordare - ed e' il motivo per cui la frase regge senza un terzo caso.
  // In inglese `series` e `found` sono invariabili: l'unica voce che si accorda resta `item(s)`.
  const summary = currentLang === 'it'
    ? `<p style="color:var(--muted);font-size:0.88rem;margin-bottom:1rem;">Trovat${totalFigs === 1 ? 'o' : 'i'} ${totalFigs} ${totalFigs === 1 ? 'oggetto' : 'oggetti'} in ${results.length} serie</p>`
    : `<p style="color:var(--muted);font-size:0.88rem;margin-bottom:1rem;">Found ${totalFigs} ${totalFigs === 1 ? 'item' : 'items'} in ${results.length} series</p>`;

  resultsEl.innerHTML = summary + results.map(r => {
    const s = r.series;
    const desc = (currentLang === 'it' ? (s.descIt || s.desc) : (s.desc || s.descIt)) || '';
    // Nome serie sempre in cima, cliccabile per aprire la serie
    // Prima riga: nome serie a sx + conteggio oggetti a dx
    const seriesHeader = `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:0.4rem;">
        <div onclick="openSeriesDetail('${s.id}')" style="cursor:pointer;display:flex;align-items:center;gap:0.5rem;flex:1;min-width:0;">
          ${s.img ? `<img src="${cloudinaryUrl(s.img,'w_40,h_40,c_fit,q_auto,f_auto')}" style="width:28px;height:28px;object-fit:contain;border-radius:4px;background:var(--card2);flex-shrink:0;">` : '<span style="font-size:1rem;flex-shrink:0;">🎴</span>'}
          <span style="font-family:var(--font-display);font-size:0.95rem;font-weight:600;color:var(--accent);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${s.name}</span>
          ${r.seriesMatch ? `<span style="font-size:0.65rem;color:var(--muted);border:1px solid var(--border);border-radius:6px;padding:1px 5px;flex-shrink:0;">${currentLang==='it'?'serie':'series'}</span>` : ''}
        </div>
        ${r.figs.length ? `<span style="font-size:0.7rem;color:var(--muted);white-space:nowrap;margin-left:0.5rem;flex-shrink:0;">${r.figs.length} ${currentLang==='it'?(r.figs.length===1?'trovato':'trovati'):'found'}</span>` : ''}
      </div>`;
    const sectionLabels = { figurines: currentLang === 'it' ? 'Figurine' : 'Stickers', retros: 'Retro', albums: currentLang === 'it' ? 'Album' : 'Albums', extras: currentLang === 'it' ? 'Altri oggetti' : 'Other items', bustine: currentLang === 'it' ? 'Bustine' : 'Wrappers' };
    const sectionOrder = ['figurines', 'retros', 'albums', 'extras', 'bustine'];
    const figsHTML = r.figs.length
      // v6.050 (Franco) - NEI RISULTATI I RETRO SI MOSTRANO COL NOME COMPLETO.
      // Prima si mostrava il nome LUNGO (nome + sottonome), che non contiene categoria e
      // sottocategoria. Con la v6.049 la ricerca ha iniziato a trovare anche per quei due campi, e
      // il risultato era un elenco che non spiegava perche' fosse li': cercando "privacy" uscivano
      // DUE righe con la STESSA identica etichetta - "RICERCATA PER INVASIONE DELLA PRIVACY -
      // VICINA" - mentre i due oggetti differiscono per sottocategoria e tipo, che il Nome completo
      // dice ("... - ROSSO" e "... - ROSSO - OMAGGIO NERO").
      // Due risultati indistinguibili sono peggio di nessun risultato: uno costringe a aprirli
      // entrambi per capire quale sia quale.
      // Il Nome completo e' anche cio' che si legge nella scheda e nella colonna della vista
      // tabellare: la ricerca ora chiama le cose con lo stesso nome del resto del sito.
      // La scritta "Change: <tipo>" diventa il solo marcatore "Change": il tipo e' gia' in fondo al
      // Nome completo, e ripeterlo era la stessa parola due volte nella stessa riga.
      ? sectionOrder.map(sec => {
          let inSection = r.figs.filter(f => (f.section || 'figurines') === sec);
          // v6.103 (Franco) - I RISULTATI DELLA STESSA FIGURINA STANNO INSIEME.
          // Prima le pillole erano un elenco piatto che andava a capo dove capitava: cercando
          // "cerino" i due #537 CE-RINO finivano su due righe diverse, e sembravano due cose
          // scollegate invece che la stessa figurina vista da due angoli.
          //
          // IL COLLANTE E' IL NUMERO, non la figurina base — e la scelta e' di Franco, con una
          // ragione che il codice da solo non poteva sapere: "a seconda della ricerca fatta potrebbe
          // non esserci la figurina base ma solo sue variazioni-change-errori stampa". Raggruppare
          // sulla base voleva dire dipendere da un record che i risultati possono non contenere.
          // Il numero c'e' sempre, e per una variazione E' quello della base (lo eredita al
          // salvataggio), quindi lega senza bisogno che la base sia li'.
          // Dove il numero non c'e' (serie senza numeri, `noNumber`) il collante e' il nome, che in
          // quel caso e' l'unica cosa che quegli oggetti condividono.
          //
          // Questo sostituisce il vecchio `groupNumber`, che il numero della base andava a cercarlo
          // con una find() su ~3300 oggetti per ogni confronto dell'ordinamento.
          const chiaveGruppo = f => String((f.number ?? '') !== '' ? f.number : (f.name || ''));
          if (sec === 'figurines') {
            // v6.103 - gli errori di stampa avevano priorita' 0, cioe' si ordinavano come se fossero
            // la figurina BASE e finivano davanti alle variazioni della stessa. Ora chiudono la fila.
            // v6.234 - sesta catena a mano, con gli stessi numeri: ora e' `_prioritaTipo`.
            const priority = _prioritaTipo;
            inSection = [...inSection].sort((a, b) => {
              const g = chiaveGruppo(a).localeCompare(chiaveGruppo(b), undefined, { numeric: true });
              if (g !== 0) return g;
              return priority(a) - priority(b);
            });
          }
          if (!inSection.length) return '';
          // I gruppi, nell'ordine appena stabilito. Le altre sezioni restano UN gruppo solo, cioe'
          // esattamente com'erano: raggruppare i Retro per numero non vorrebbe dire niente, e
          // spezzarli in gruppi da uno cambierebbe le spaziature senza motivo.
          const gruppi = [];
          if (sec !== 'figurines') {
            gruppi.push({ k: '*', items: inSection });
          } else {
            inSection.forEach(f => {
              const k = chiaveGruppo(f);
              const ultimo = gruppi[gruppi.length - 1];
              if (ultimo && ultimo.k === k) ultimo.items.push(f); else gruppi.push({ k, items: [f] });
            });
          }
          // Due contenitori annidati, e il trucco sta tutto li': il gruppo e' un elemento SOLO per
          // chi va a capo fuori, quindi resta intero finche' ci sta. Se non ci sta, va a capo al suo
          // interno - che e' quello che Franco ha chiesto ("ovviamente se non c'e' spazio si va a
          // capo") e che una riga forzata con `flex-wrap:nowrap` avrebbe impedito, mandando le
          // pillole fuori dallo schermo.
          // Lo stacco fra gruppi e' piu' largo di quello dentro un gruppo (0.7 contro 0.3): e' cosi'
          // che si vede DOVE finisce una figurina e ne comincia un'altra, senza cornici ne' righelli.
          return `<div style="margin-bottom:0.4rem;">
            <div style="font-size:0.9rem;color:#ff9d3d;font-weight:600;margin-bottom:0.25rem;">${sectionLabels[sec]}:</div>
            <div style="display:flex;flex-wrap:wrap;gap:0.7rem;">
              ${gruppi.map(gruppo => '<div style="display:inline-flex;flex-wrap:wrap;gap:0.3rem;">' + gruppo.items.map(f => {
                _elencoRicercaGlobale.push(f.id); // v6.097 - l'ordine e' questo, perche' e' qui che si disegna
                // v6.103 (Franco) - GLI ERRORI DI STAMPA ENTRANO NEL CONTO. Prima restavano fuori e
                // nei risultati sembravano figurine normali: nessuna etichetta, nessun tipo. Erano
                // l'unico dei quattro tipi a non comparire.
                // ⚠️ EFFETTO COLLATERALE VOLUTO, ma da sapere: questa variabile decide anche il
                // ripiego della FOTO (riga piu' sotto). Da ora un errore di stampa senza foto propria
                // mostra quella della sua base, come gia' fanno variazioni e change; prima non
                // mostrava niente. E' coerente con gli altri tre tipi e meglio di un buco, ma resta
                // un ripiego: se un errore di stampa e' visibile nel fronte, la foto della base non
                // lo fa vedere. Se dà fastidio, e' una condizione da separare, non da togliere.
                const isVarOrChange = sec === 'figurines' && (f.isVariation || f.isUnofficialVariation || f.isChange || f.isPrintError);
                const baseFig = (isVarOrChange && f.baseFigurineId) ? getData('figurines', []).find(x => x.id === f.baseFigurineId) : null;
                // v6.103 (Franco) - LA MINIATURA DEL RETRO VALE ANCHE PER LE FIGURINE BASE.
                // La condizione chiedeva `isVarOrChange`, quindi una figurina base col suo retro
                // collegato non lo mostrava: nei risultati aveva una foto sola mentre le sue
                // variazioni ne avevano due, e sembrava che il retro ce l'avessero solo loro.
                // NOTA: la miniatura si mostra sempre, il NOME del retro no - quello resta dentro il
                // ramo `isVarOrChange` piu' sotto. Per una variazione il retro e' cio' che la
                // distingue dalle sorelle e va scritto; per una base e' solo il suo dietro, e
                // ripeterne il nome accanto a quello della figurina allungherebbe ogni pillola
                // senza distinguere niente.
                const retroFig = f.retroId ? getData('figurines', []).find(x => x.id === f.retroId) : null;
                // v6.234 - era la quinta catena a mano, con gli stessi identici quattro testi.
                const varLabel = _etichettaTipo(f, false);
                // v6.103 (Franco) - IL TIPO TORNA NEI RISULTATI, per i soli Change ed errori di stampa.
                // Era stato tolto con la nota "il tipo e' gia' in fondo al Nome completo, ripeterlo
                // era la stessa parola due volte". Vero per i RETRO, che qui mostrano
                // `_retroNomeCompleto(f)`; falso per le FIGURINE, che mostrano `f.name` — e per un
                // Change il `name` e' quello EREDITATO DALLA BASE (§13.1). Conseguenza: due Change
                // della stessa base ma di tipo diverso risultavano identici, stesso nome e stesso
                // numero (ereditato anche quello). Una giustificazione buona per un ramo applicata a
                // tutti e due, e invisibile perche' guardando un elenco non si vede cio' che manca.
                // Le VARIAZIONI restano fuori di proposito: il loro suffisso e' il nome del retro, e
                // la riga piu' sotto lo aggiunge gia' per conto suo. Metterlo qui lo stamperebbe due
                // volte — che e' poi il difetto vero denunciato dalla nota originale.
                const tipoLabel = f.isChange ? (f.changeType || '')
                  : f.isPrintError ? (f.printErrorType || '') : '';
                // v6.103 (Franco) - IL RETRO DI UNA VARIAZIONE SI SCRIVE PER INTERO: sequenza
                // N.; Nome; Categoria retro; Sottocategoria retro; Nome retro.
                // Qui si chiamava `_retroNomeLungo()`, che da' solo *nome + sottonome*: categoria e
                // sottocategoria non comparivano, e due variazioni collegate a retro omonimi di
                // categorie diverse erano indistinguibili.
                // La funzione giusta esisteva gia' ed e' `_retroNomeCompleto()`, che porta dentro la
                // regola delle categorie di sempre - "CATEGORIA - SOTTOCATEGORIA - Nome", oppure
                // "Nome - SOTTOCATEGORIA" quando il Nome comincia gia' per la categoria
                // (`_retroNameStartsWithCategory`, tolleranza di genere inclusa: RICERCATO combacia
                // con RICERCATA). Un identificatore cambiato invece di una regola riscritta: era la
                // quinta volta che quella regola poteva nascere in copia, e non e' nata.
                // E' anche la stessa funzione che questa riga usa gia' per la sezione Retro, quindi
                // ora i due rami dei risultati chiamano il nome allo stesso modo.
                // v6.103 (Franco) - MINIATURE AL DOPPIO: 22px -> 44px, "troppo piccole".
                // Raddoppia anche cio' che si CHIEDE a Cloudinary (32 -> 64): lasciare w_32 avrebbe
                // fatto ingrandire al browser un'immagine da 32px, cioe' la stessa foto sgranata ma
                // piu' grande. E 64 non e' un lusso: su uno schermo a densita' doppia 44 CSS-pixel
                // sono 88 fisici, quindi anche cosi' si sta chiedendo il minimo, non il massimo.
                //
                // ⚠️ E LE DUE MINIATURE DIVENTANO UNA FUNZIONE SOLA. Qui c'erano gli stessi identici
                // numeri scritti due volte - in `smallImg` e, venti caratteri piu' in la', nell'IIFE
                // del fronte - che differivano per due dettagli: il `title` e il bordo. Ridimensionarne
                // una e non l'altra era il difetto piu' facile del mondo da introdurre oggi, e
                // nessuno se ne sarebbe accorto finche' non fossero finite affiancate. Ora il bordo
                // e' un parametro e la misura sta in un posto solo.
                const _MINI = 44;
                const smallImg = (url, title, bordo = true) => url
                  ? `<img src="${cloudinaryUrl(url,'w_64,h_64,c_fit,q_auto,f_auto')}"${title ? ` title="${esc(title)}"` : ''} style="width:${_MINI}px;height:${_MINI}px;object-fit:contain;border-radius:4px;background:var(--card);${bordo ? 'border:1px solid var(--border);' : ''}">`
                  : '';
                return `<span onclick="openFigFromSearch('${f.id}','${s.id}','${f.section||'figurines'}')" style="cursor:pointer;background:var(--card2);border:1px solid var(--border);color:var(--text);font-size:0.75rem;padding:2px 6px 2px 3px;border-radius:8px;display:inline-flex;align-items:center;gap:4px;">
                ${(() => { const front = isVarOrChange ? (f.img || (baseFig && baseFig.img) || null) : f.img; return smallImg(front, '', false); })()}
                ${retroFig ? smallImg(retroFig.img, currentLang === 'it' ? 'Retro associato' : 'Associated retro') : ''}
                <span>${f.number ? '<span style="color:var(--muted);font-size:0.68rem;">'+f.number+'</span> ' : ''}${sec === 'retros' ? esc(_retroNomeCompleto(f)) : f.name}${(sec === 'retros' && f.changeType) ? ' <span style="font-size:0.68rem;color:#ffd84d;">Change</span>' : ''}${isVarOrChange ? ' <span style="font-size:0.68rem;"><span style="color:#ffd84d;">' + varLabel + '</span>' + (tipoLabel ? ' <span style="color:#ffd84d;">' + esc(tipoLabel) + '</span>' : '') + (retroFig ? ' - <span style="color:var(--info);">' + esc(_retroNomeCompleto(retroFig)) + '</span>' : '') + '</span>' : ''}</span>
              </span>`;
              }).join('') + '</div>').join('')}
            </div>
          </div>`;
        }).join('') : '';
    return `<div style="background:var(--card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:0.6rem 0.75rem;margin-bottom:0.6rem;">
      ${seriesHeader}
      ${figsHTML}
    </div>`;
  }).join('');
}

function openFigFromSearch(figId, seriesId, section) {
  // Imposta il contesto senza navigare via dai risultati di ricerca
  currentSeriesId = seriesId;
  currentSection = section || 'figurines';
  // Apre direttamente la modal di dettaglio, i risultati rimangono visibili
  // v6.097 (Franco) - LE FRECCE SCORRONO TUTTI I RISULTATI, anche passando da una serie all'altra.
  // Il meccanismo c'era gia' dalla v6.033 (_elencoNav): alla ricerca globale non era mai stato
  // collegato, e per vedere il risultato successivo bisognava chiudere la scheda e cliccare a mano.
  openFigDetail(figId, _elencoRicercaGlobale);
}

// v6.080 (Franco) - IL NOME DA METTERE SULLE CARD. Su telefono, se la serie ha un "Nome corto",
// si usa quello: nelle griglie a due o tre colonne il nome per esteso non ci sta e viene troncato,
// e un nome troncato non identifica niente. Sul desktop e nella SCHEDA della serie resta sempre il
// nome vero - li' lo spazio c'e', ed e' il posto dove il nome si legge per intero.
// Una funzione sola: i punti che elencano serie sono cinque, e cinque copie di questo `if`
// sarebbero cinque occasioni di dimenticarne una.
// v6.206 - il secondo parametro. La regola NON si duplica: chi ha bisogno del nome corto anche
// su desktop lo CHIEDE a questa funzione, che resta l'unico posto dove sta scritto cos'e' il nome
// da mettere su una card. Il commento della v6.080 qui sopra dice il motivo: *"cinque copie di
// questo `if` sarebbero cinque occasioni di dimenticarne una"* - e cinque copie sono la stessa cosa
// di due funzioni gemelle.
// \uD83D\uDCCC `sempreCorto` non e' "preferisci il corto": e' "qui lo spazio e' quello del telefono anche
// se siamo su un desktop". La condizione vera resta una sola - lo spazio - e chi chiama la conosce
// meglio di questa funzione.
function _nomeSerieCard(s, sempreCorto) {
  if (!s) return '';
  const corto = (s.nomeCorto || '').trim();
  return ((sempreCorto || _isMobileViewport()) && corto) ? corto : (s.name || '');
}

function seriesCardHTML(s) {
  const allItems = getData('figurines', []).filter(f => f.seriesId === s.id);
  const retros = allItems.filter(f => f.section === 'retros');
  const albums = allItems.filter(f => f.section === 'albums');
  const extras = allItems.filter(f => f.section === 'extras');
  const bustine = allItems.filter(f => f.section === 'bustine');
  const figs = allItems.filter(f => f.section !== 'retros' && f.section !== 'albums' && f.section !== 'extras' && f.section !== 'bustine');
  const desc = currentLang === 'it' ? (s.descIt || s.desc) : (s.desc || s.descIt);
  // Calculate mode score (most common score > 0)
  let modeScoreHTML = '';
  const scoredFigs = figs.filter(f => f.score && f.score > 0);
  if (scoredFigs.length) {
    const freq = {};
    scoredFigs.forEach(f => { freq[f.score] = (freq[f.score] || 0) + 1; });
    const modeScore = Object.entries(freq).sort((a,b) => b[1]-a[1])[0][0];
    modeScoreHTML = `<span style="font-size:0.78rem;color:var(--accent);font-family:var(--font-ui);">⭐ ${modeScore} pt</span>`;
  }
  return `<div class="card" onclick="openSeriesDetail('${s.id}')">
    <div class="card-img-placeholder">
      ${s.img ? `<img src="${cloudinaryUrl(s.img, 'w_400,h_400,c_fit,q_auto,f_auto')}" style="width:100%;height:100%;object-fit:contain;position:absolute;top:0;left:0;padding:8px;">` : '🎴'}
    </div>
    <div class="card-body">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;flex-wrap:wrap;margin-bottom:0.5rem;">
        <div class="card-title" style="display:flex;align-items:baseline;gap:0.5rem;flex-wrap:wrap;margin-bottom:0;"><span>${esc(_nomeSerieCard(s))}</span>${s.year ? `<span class="card-tag" style="display:inline;margin-bottom:0;">${s.year}</span>` : ''}</div>
        ${modeScoreHTML || ''}
      </div>
      <div class="card-desc">${(desc||'').substring(0,90)}${(desc||'').length>90?'…':''}</div>
      <div class="card-meta">
        <span class="card-badge">${figs.length} ${currentLang === 'it' ? 'figurine' : 'stickers'}</span>
        ${retros.length ? `<span class="card-badge">${retros.length} ${currentLang === 'it' ? 'retro' : 'retros'}</span>` : ''}
        ${bustine.length ? `<span class="card-badge">${bustine.length} ${currentLang === 'it' ? (bustine.length === 1 ? 'bustina' : 'bustine') : 'wrappers'}</span>` : ''}
        ${albums.length ? `<span class="card-badge">${albums.length} ${currentLang === 'it' ? 'album' : 'albums'}</span>` : ''}
        ${extras.length ? `<span class="card-badge">${extras.length} ${currentLang === 'it' ? 'Altro' : 'Other'}</span>` : ''}
      </div>
    </div>
  </div>`;
}

function renderHomeSeries() {
  const grid = document.getElementById('home-series-grid');
  if (!grid) return;
  const series = getData('series', []).slice(0, 3);
  if (!series.length) {
    grid.innerHTML = `<div class="empty-state"><div class="empty-icon">🎴</div><p class="empty-title">${t('catalog.empty')}</p></div>`;
    return;
  }
  grid.innerHTML = series.map(s => seriesCardHTML(s)).join('');
}

// ============================================================
//  SERIES DETAIL
// ============================================================
let currentSection = null; // 'figurines' | 'albums' | 'extras'
let currentItemPage = 1;
let _gridOrderedIds = []; // elenco ordinato completo (tutte le pagine) per navigazione avanti/indietro nel dettaglio
let _currentDetailFigId = null;

// v6.033 (Franco) - SU COSA SCORRONO LE FRECCE del dettaglio.
// Di norma sull'elenco della GRIGLIA. Ma aprendo un oggetto da uno dei tab dei collegati - i
// Change di un retro, le variazioni di una figurina, le figurine che usano un retro - quasi mai
// quell'oggetto sta in griglia: la griglia mostra i retro, non i loro Change. Li' l'indice usciva
// -1 e le frecce sparivano, proprio dove servivano.
// Ora l'elenco di navigazione e' un parametro di openFigDetail: chi apre da un tab passa gli id di
// QUEL tab, e finche' si resta dentro le frecce scorrono quello. Chi apre da una card non passa
// niente e torna alla griglia - il reset e' automatico, non c'e' uno stato da ricordarsi di
// azzerare, che e' il modo in cui questa roba si rompe.
let _elencoNav = null;
function _navIdsCorrenti(figId) {
  return (_elencoNav && _elencoNav.includes(figId)) ? _elencoNav : _gridOrderedIds;
}

function navigateFigDetail(direction) {
  if (!_currentDetailFigId) return;
  const ids = _navIdsCorrenti(_currentDetailFigId);
  const idx = ids.indexOf(_currentDetailFigId);
  if (idx === -1) return;
  const newIdx = idx + direction;
  if (newIdx < 0 || newIdx >= ids.length) return;
  // v6.097 (Franco) - IL CONTESTO SEGUE L'OGGETTO CHE SI APRE.
  // Serve per la ricerca globale, dove le frecce attraversano serie diverse: senza, chiudendo la
  // scheda si tornava nel posto sbagliato, e gia' dentro la scheda i campi mostrati dipendono
  // dalla sezione (vedi _mostraCampoNumero). openFigFromSearch faceva gia' esattamente questo
  // all'APERTURA; qui si limita a continuare a farlo a ogni passo.
  // ⚠️ Decisione consapevole di Franco (11 agosto 2026): si allinea SEMPRE, non solo venendo dalla
  // ricerca. Quindi tocca anche i tab dei collegati - scorrendo da un retro a un suo Change,
  // `currentSection` passa da 'retros' a 'figurines'. E' scritto qui perche' se un giorno la
  // griglia sotto cambia da sola dopo aver chiuso una scheda aperta da un tab, questa riga e' il
  // primo posto dove guardare: l'alternativa scartata era allineare solo per _elencoRicercaGlobale.
  const _nuovo = getData('figurines', []).find(x => x.id === ids[newIdx]);
  if (_nuovo) {
    currentSeriesId = _nuovo.seriesId;
    currentSection = _nuovo.section || 'figurines';
  }
  openFigDetail(ids[newIdx], _elencoNav); // v6.033 - restando nello stesso elenco
}
const ROWS_PER_PAGE = 7;

// Indice id -> oggetto, costruito UNA VOLTA per render e passato a chi serve. Prima ogni
// confronto dell'ordinamento cercava la figurina base e il retro con allFigs.find(...), cioe' una
// scansione lineare di ~3300 oggetti fino a tre volte per confronto: 163 ms per ordinare 800
// figurine, e l'ordinamento gira ad OGNI cambio pagina. Con la Map: 1,4 ms, a ordine identico
// (verificato confrontando le due sequenze di id carattere per carattere). Non si conserva fra
// una chiamata e l'altra di proposito: costa 0,6 ms rifarla, e una Map tenuta in giro andrebbe
// invalidata ad ogni scrittura sui dati — le cache mal invalidate sono il bug che poi si
// manifesta come "la modifica non c'e'".
function _figIndex(allFigs) {
  const m = new Map();
  for (let i = 0; i < allFigs.length; i++) m.set(allFigs[i].id, allFigs[i]);
  return m;
}

// Una figurina mostrera' nella griglia la card LARGA (350px) invece di quella normale (247px)?
// v5.978 — questa funzione ora ricalca ESATTAMENTE il ramo di renderItems() che accende
// hasWidePair. Prima divergeva in due punti, e la paginazione partiva quindi da larghezze
// sbagliate: (1) ignorava i CHANGE, che nel renderer sono larghi quando hanno un retro proprio
// o ereditato dalla base (_effRetroId, v5.786); (2) ignorava _soloFronte, cioe' che su telefono
// col filtro "Figurine set base" il retro non si affianca affatto (v5.853). Aggiunto anche il
// controllo sulla modalita': la card larga esiste solo in 'destra-piena'.
// Se un giorno cambia il ramo in renderItems, va cambiato qui: sono due copie della stessa
// verita', e l'unica difesa e' che questo commento lo dica.
// v6.020 — del "solo fronte" non e' piu' una copia: chiama _soloFronteMobile(), la stessa
// funzione che usa renderItems. Restano copie i controlli su modalita' e coppia fronte/retro.
// v6.099 (§12.8) - LA COPPIA FRONTE/RETRO DI UNA CARD, DECISA IN UN POSTO SOLO.
// Prima questa condizione stava scritta DUE volte: in `renderItems`, che disegna la card, e qui,
// che la ricalcola per sapere quante card stanno in una pagina. Il commento della v5.978 avvertiva
// gia' di tenerle allineate, ed e' stato fatto due volte a mano - v5.978 e v6.094. **Due volte sono
// tornate a divergere**, e l'11 agosto se n'e' aggiunta una terza col caso C. Quel conto e' la
// prova che il problema non era la disattenzione: era la duplicazione. Quindi ora la verita' e' una
// sola e i due chiamanti la leggono.
//
// Le due divergenze che c'erano al momento dell'unificazione, e come sono state risolte - **in
// entrambi i casi vince il RENDERER**, perche' e' quello che si vede: se i due non concordano, e'
// il conteggio a essere sbagliato, non il disegno.
//   1. IL FRONTE. Il renderer usa `_fotoFigurina(f, allFigs)` dalla v6.080 - la foto DELL'OGGETTO,
//      con la base come ripiego solo dove il fronte coincide davvero. Il contatore era rimasto a
//      `baseFigDual?.img`, cioe' sempre la foto della base. Divergevano su variazioni e change con
//      foto propria. Ora si usa `_fotoFigurina` per entrambi.
//   2. IL RETRO BIANCO. Il renderer lo tratta come un retro vero dalla v6.006 (un oggetto finto con
//      la sola immagine, cosi' le cinque disposizioni non devono sapere che il caso esiste). Il
//      contatore non lo nominava affatto: una figurina con retro bianco era larga da disegnare e
//      stretta da contare. Ora il finto record si costruisce qui, una volta, per tutti e due.
// Il sintomo di entrambe era lo stesso, ed e' la ragione per cui non erano mai state notate: le
// card traboccano dalla pagina o lasciano un buco, ma solo sulle righe che contengono uno di quei
// casi - quindi in modo intermittente e mai riproducibile a comando.
//
// Nota: si guarda `f.section` e non `currentSection`. In griglia coincidono (gli item sono filtrati
// per sezione), ma dipendere dall'oggetto invece che da una variabile globale rende la funzione
// chiamabile da qualunque punto senza doversi chiedere "dove mi trovo?" - ed e' cio' che ha reso
// possibile fonderle: le due copie partivano proprio da qui, una con `currentSection` e una con
// `f.section`.
function _coppiaFronteRetro(f, allFigs, idx) {
  const vuoto = { mostra: false, larga: false, fronte: null, retroImg: null, retroVuoto: false };
  if (!f || f.section !== 'figurines') return vuoto;
  if (_soloFronteMobile()) return vuoto; // v5.853 — su telefono col filtro "set base", solo il fronte
  const get = id => (idx ? idx.get(id) : allFigs.find(x => x.id === id));
  const isBaseFig = !f.isVariation && !f.isUnofficialVariation && !f.isChange;
  const baseForChange = (f.isChange && f.baseFigurineId) ? get(f.baseFigurineId) : null;
  const effRetroId = f.isChange ? (f.retroId || baseForChange?.retroId || null) : f.retroId;
  const retroBianco = !!f.retroBianco && !f.retroId; // v6.006
  // v6.098 caso C: la figurina che un retro dovrebbe averlo e non e' collegata entra comunque, e al
  // posto del retro va il riquadro vuoto. Caso B: tranne dove i retro non esistono proprio.
  const retroDaCollegare = !effRetroId && !retroBianco && !_serieSenzaRetro(f.seriesId);
  const entra = ((f.isVariation || f.isUnofficialVariation) && f.baseFigurineId && (f.retroId || retroBianco))
    || (f.isChange && f.baseFigurineId && effRetroId)
    || (isBaseFig && (f.retroId || retroBianco))
    || retroDaCollegare;
  if (!entra) return vuoto;
  const fronte = _fotoFigurina(f, allFigs); // divergenza 1, risolta a favore del renderer
  if (!fronte) return vuoto;                // senza fronte la card cade nel ramo a foto singola
  const retroRec = retroBianco ? { img: RETRO_BIANCO_IMG, name: '' } : get(effRetroId); // divergenza 2
  return {
    mostra: true,
    // la card larga esiste SOLO in 'destra-piena': nelle altre quattro disposizioni la coppia si
    // disegna dentro una card di larghezza normale.
    larga: _retroViewMode === 'destra-piena',
    fronte,
    // v6.094 - basta che il retro ESISTA: se la foto manca, al suo posto va il segnaposto, e la
    // card resta larga lo stesso.
    retroImg: retroRec ? retroRec.img : null,
    retroVuoto: !retroRec, // v6.098 - il terzo stato: la faccia non esiste, non e' una foto mancante
  };
}

function _itemHasWidePair(f, allFigs, idx) {
  return _coppiaFronteRetro(f, allFigs, idx).larga; // v6.099 - non piu' una copia, vedi sopra
}

// Geometria REALE della griglia. Nessun numero di colonne assunto: si LEGGE quello che c'e'.
// Questo sostituisce _estimateWideModeCols(), che assumeva un contenitore di 1800px (il
// max-width della griglia) e ne ricavava 5 colonne con un margine di 2 pixel:
// 5x350 + 4x12 = 1798 <= 1800. Su una finestra da 1536px CSS il contenitore vero e' 1475px, dove
// entrano 4 card, non 5 — ed e' da qui che veniva il tetto di 30 (ROWS_PER_PAGE 6 x 5) e le due
// celle orfane in fondo ad ogni pagina, segnalate da Franco in v5.336, in v5.564 e di nuovo oggi.
// Le prime due volte una stima e' stata sostituita da un'altra stima; questa volta si misura.
// Si decide dallo stile CALCOLATO, non da _retroViewMode: sotto gli 860px il CSS riporta la
// griglia a 4 colonne con !important anche in 'destra-piena' (v5.821), e leggendo la modalita'
// si crederebbe di essere in flex mentre il browser sta impaginando a griglia.
// UNA sola lettura di layout per render: leggere clientWidth/getComputedStyle forza il calcolo
// del layout, e farlo dentro un ciclo sarebbe il modo classico di rendere lento tutto.
// Quante colonne dice il valore CALCOLATO di grid-template-columns. Non e' banale: a griglia
// VISIBILE il browser lo restituisce risolto in pixel ("285.3px 285.3px ..." — cinque token per
// cinque colonne) e basta contarli; a griglia NASCOSTA lo restituisce NON risolto, cosi' com'e'
// scritto ("repeat(7, 1fr)"), e contare i token a spazi darebbe 2. Verificato sul sito in entrambi
// gli stati: e' un errore che sarebbe passato inosservato, perche' 2 colonne non fanno eccezione,
// fanno solo pagine sbagliate.
function _colsFromTracks(tracks, fallback) {
  if (!tracks || tracks === 'none') return fallback;
  const tok = tracks.trim().split(/\s+/);
  if (tok.length && tok.every(t => t.endsWith('px'))) return tok.length;
  const m = tracks.match(/repeat\(\s*(\d+)/);
  if (m) return parseInt(m[1], 10);
  return fallback;
}

function _gridGeometry() {
  const fallbackCols = currentSection === 'retros' ? 5 : 7;
  const grid = document.getElementById('items-grid');
  if (!grid) return { kind: 'grid', cols: fallbackCols };
  const cs = getComputedStyle(grid);
  if (cs.display !== 'flex') {
    return { kind: 'grid', cols: Math.max(1, _colsFromTracks(cs.gridTemplateColumns, fallbackCols)) };
  }
  // Griglia in flex (modalita' 'destra-piena'): le card hanno due larghezze, quindi il numero di
  // card per riga NON e' costante e va simulato riga per riga. Se la sezione e' nascosta
  // clientWidth vale 0: si ripiega sulla stessa formula che renderItems scrive su grid.style.width.
  const width = grid.clientWidth || Math.min(1800, Math.round(window.innerWidth * 0.96));
  const gap = parseFloat(cs.columnGap) || parseFloat(cs.gap) || 12;
  return { kind: 'flex', width, gap };
}

// Chiave di FAMIGLIA: un oggetto base e tutto cio' che vi si aggancia (variazioni ufficiali e non,
// Change, errori di stampa) portano la stessa chiave. Il legame e' sempre baseFigurineId — vale
// identico per Figurine e Retro (i Retro non hanno variazioni, ma hanno Change ed errori di stampa).
function _familyKey(f) { return f.baseFigurineId || f.id; }

// Confini delle pagine, sull'elenco GIA' ORDINATO e GIA' FILTRATO. Due regole, in quest'ordine:
//   1. una FAMIGLIA non viene mai spezzata fra due pagine;
//   2. la pagina si misura in RIGHE (ROWS_PER_PAGE), non in un numero di card.
// Si aggiungono famiglie intere finche' ci si sta dentro. La 2 e' il punto che elimina le celle
// orfane: un tetto contato in card (30) diviso per le colonne reali (4) lasciava un resto di 2 e
// quel resto era il buco, sempre, anche col filtro "solo carte base" dove di famiglie non ce n'e'
// nessuna da rispettare. Contando in righe il resto non esiste piu'.
// Cosa NON si puo' garantire, e perche': quando in pagina ci sono anche variazioni, Change ed
// errori di stampa, le famiglie sono blocchi indivisibili da 1 a 5 e le righe buche da 1 a 3. Se
// la famiglia che segue e' piu' grande del buco, il buco resta. Nella Serie 1, 124 famiglie su 160
// hanno dimensione PARI (2 o 4): un buco dispari non potra' mai essere colmato da loro. Le
// alternative sono peggio: arretrare a una riga tonda produce pagine da una riga sola, crescere
// fino a chiuderla fa ballare la pagina fra 28 e 36 card. Col filtro base ogni famiglia vale 1 e
// il buco non si presenta mai.
// Caso limite: una famiglia piu' alta di una pagina intera non ha collocazione possibile, e
// arretrare darebbe una pagina vuota, cioe' un ciclo che non termina. Allora la si prende intera
// sforando le righe. Oggi la famiglia piu' grande e' di 5 card contro 7 righe, quindi il ramo non
// scatta: c'e' perche' un ciclo che puo' non terminare non si lascia in piedi per fiducia.
function buildItemPages(allItems) {
  const geo = _gridGeometry();
  const allFigs = getData('figurines', []);
  const idx = _figIndex(allFigs);
  const famEnd = i => { let j = i + 1; const k = _familyKey(allItems[i]);
                        while (j < allItems.length && _familyKey(allItems[j]) === k) j++; return j; };
  const pages = [];
  let start = 0;
  while (start < allItems.length) {
    let end = start, x = 0, rows = 1; // x = larghezza occupata (flex) o card nella riga (grid)
    while (end < allItems.length) {
      const fe = famEnd(end);
      let xx = x, rr = rows, entra = true;
      for (let i = end; i < fe; i++) {
        if (geo.kind === 'flex') {
          const w = _itemHasWidePair(allItems[i], allFigs, idx) ? 350 : 247;
          if (xx > 0 && xx + geo.gap + w > geo.width) { rr++; xx = w; } else { xx = xx > 0 ? xx + geo.gap + w : w; }
        } else {
          xx++; if (xx > geo.cols) { rr++; xx = 1; }
        }
        if (rr > ROWS_PER_PAGE) { entra = false; break; }
      }
      if (!entra) break;          // la famiglia sfonderebbe le righe: slitta alla pagina dopo
      x = xx; rows = rr; end = fe;
    }
    if (end === start) end = famEnd(start); // famiglia piu' alta della pagina (vedi sopra)
    pages.push({ start, end });
    start = end;
  }
  return pages;
}

// Confini dell'ultimo render, per changeItemPage: il numero di pagine dipende dai confini reali
